# -- Price cache (CoinGecko) ------------------------------------------------
_PRICE_CACHE: dict[str, tuple[float, float]] = {}  # coin_id -> (price_usd, timestamp)
_PRICE_CACHE_TTL = 300  # 5 minutes
_PAIR_TOKEN_CACHE: dict[tuple[str, str], tuple[str, str, str]] = {}
_POOL_RESERVE_SNAPSHOT_CACHE: dict[tuple[str, str, int], tuple[float, dict[str, Any]]] = {}
_POOL_RESERVE_SNAPSHOT_CACHE_TTL = 300
_POOL_RESERVE_SNAPSHOT_CACHE_MAX = 256
_VENUE_MAPPING_CACHE: dict[tuple[str, str], tuple[float, dict[str, Any] | None]] = {}
_VENUE_MAPPING_CACHE_TTL = 60

def _get_native_price_usd(chain: str) -> float:
    coin_id = _NATIVE_COIN_IDS.get(_normalize_chain(chain))
    if not coin_id:
        return 0.0
    return float(_get_coin_prices({coin_id}).get(coin_id) or 0.0)


def get_evm_code(chain: str, address: str) -> str:
    chain = _normalize_chain(chain)
    result, _ = _rpc_evm_chain(chain, "eth_getCode", [address, "latest"])
    return result or "0x"


def _get_coin_prices(coin_ids: set[str]) -> dict[str, float]:
    """Fetch USD prices from CoinGecko."""
    if not coin_ids:
        return {}
    now = time.time()
    result: dict[str, float] = {}
    missing: list[str] = []
    for cid in coin_ids:
        if cid in _PRICE_CACHE:
            price, ts = _PRICE_CACHE[cid]
            if now - ts < _PRICE_CACHE_TTL:
                result[cid] = price
            else:
                missing.append(cid)
        else:
            missing.append(cid)
    if missing:
        try:
            ids_param = ",".join(missing)
            url = f"https://api.coingecko.com/api/v3/simple/price?ids={ids_param}&vs_currencies=usd"
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read().decode())
                for cid in missing:
                    price = data.get(cid, {}).get("usd", 0.0)
                    result[cid] = price
                    _PRICE_CACHE[cid] = (price, now)
        except Exception:
            pass
    return result


def get_token_balance(chain: str, wallet: str, token: str) -> float:
    """Get ERC20/BEP20 token balance."""
    data = "0x70a08231" + "0" * 24 + wallet[2:]
    chain = _normalize_chain(chain)
    token_meta = _MAJOR_TOKENS.get(chain, {}).get(token.lower(), {})
    decimals = int(token_meta.get("decimals") or 18)
    result, _ = _rpc_evm_chain(chain, "eth_call", [{"to": token, "data": data}, "latest"])
    if result and result != "0x":
        return int(result, 16) / (10 ** decimals)
    return 0.0


def get_token_balances(chain: str, wallet: str) -> list[dict[str, Any]]:
    """Get all major token balances for a wallet."""
    chain = _normalize_chain(chain)
    tokens = _MAJOR_TOKENS.get(chain, {})
    results = []
    for addr, meta in tokens.items():
        bal = get_token_balance(chain, wallet, addr)
        if bal > 0:
            results.append({
                "chain": chain,
                "token_address": addr,
                "coin_id": meta.get("coin_id"),
                "symbol": meta.get("symbol") or meta.get("coin_id"),
                "balance": bal,
                "decimals": meta.get("decimals"),
            })
    return results



# Cache
_CACHE: dict[str, tuple[float, Any]] = {}
_CACHE_TTL = 60


def _cached(key: str, fn: Any, *args: Any) -> Any:
    now = time.time()
    if key in _CACHE:
        ts, val = _CACHE[key]
        if now - ts < _CACHE_TTL:
            return val
    val = fn(*args)
    _CACHE[key] = (now, val)
    return val


# DB
def _get_db() -> sqlite3.Connection:
    conn = sqlite3.connect(str(DB_PATH), check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA busy_timeout=5000")
    return conn


def _backup_onchain_db(reason: str) -> str:
    """Create a consistent SQLite backup, including committed WAL state."""
    _init_db()
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    safe_reason = "".join(ch if ch.isalnum() or ch in {"_", "-"} else "_" for ch in reason).strip("_")
    safe_reason = safe_reason or "backup"
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    backup_path = BACKUP_DIR / f"onchain_{safe_reason}_{stamp}.db"
    source = sqlite3.connect(str(DB_PATH))
    target = sqlite3.connect(str(backup_path))
    try:
        source.backup(target)
    finally:
        target.close()
        source.close()
    return str(backup_path)


def _init_db() -> None:
    conn = _get_db()
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS blocks (
            chain TEXT,
            block_number INTEGER,
            block_hash TEXT,
            timestamp INTEGER,
            tx_count INTEGER,
            PRIMARY KEY (chain, block_number)
        );
        CREATE TABLE IF NOT EXISTS transactions (
            tx_hash TEXT PRIMARY KEY,
            chain TEXT,
            block_number INTEGER,
            from_addr TEXT,
            to_addr TEXT,
            value REAL,
            timestamp INTEGER
        );
        CREATE TABLE IF NOT EXISTS swaps (
            tx_hash TEXT,
            chain TEXT,
            block_number INTEGER,
            timestamp INTEGER,
            wallet TEXT,
            dex TEXT,
            token_in TEXT,
            token_out TEXT,
            amount_in REAL,
            amount_out REAL,
            amount_usd REAL,
            pool TEXT,
            token_identity_quality TEXT DEFAULT 'unknown',
            pair_rpc_source TEXT,
            router_addr TEXT,
            venue_source TEXT,
            venue_confidence REAL DEFAULT 0,
            PRIMARY KEY (tx_hash, token_in, token_out)
        );
        CREATE TABLE IF NOT EXISTS token_transfers (
            tx_hash TEXT,
            log_index INTEGER,
            chain TEXT,
            block_number INTEGER,
            timestamp INTEGER,
            token TEXT,
            from_addr TEXT,
            to_addr TEXT,
            value_raw TEXT,
            source TEXT DEFAULT 'erc20_transfer_log',
            PRIMARY KEY (tx_hash, log_index)
        );
        CREATE TABLE IF NOT EXISTS pair_tokens (
            chain TEXT,
            pool TEXT,
            token0 TEXT,
            token1 TEXT,
            rpc_source TEXT,
            observed_at INTEGER,
            PRIMARY KEY (chain, pool)
        );
        CREATE TABLE IF NOT EXISTS token_metadata (
            chain TEXT NOT NULL,
            token_address TEXT NOT NULL,
            symbol TEXT,
            name TEXT,
            decimals INTEGER,
            rpc_source TEXT,
            observed_at INTEGER NOT NULL,
            status TEXT NOT NULL DEFAULT 'resolved',
            error TEXT,
            PRIMARY KEY (chain, token_address)
        );
        CREATE TABLE IF NOT EXISTS wallets (
            wallet TEXT PRIMARY KEY,
            chain TEXT,
            first_seen INTEGER,
            last_seen INTEGER,
            total_tx INTEGER DEFAULT 0,
            total_swaps INTEGER DEFAULT 0,
            total_volume REAL DEFAULT 0,
            native_balance REAL DEFAULT 0,
            labels TEXT
        );
        CREATE TABLE IF NOT EXISTS wallet_chain_state (
            chain TEXT NOT NULL,
            address TEXT NOT NULL,
            native_balance REAL DEFAULT 0,
            tx_count INTEGER DEFAULT 0,
            token_balances_json TEXT NOT NULL DEFAULT '[]',
            rpc_source TEXT,
            label TEXT,
            entity TEXT,
            confidence TEXT,
            address_kind TEXT DEFAULT 'wallet',
            is_contract INTEGER DEFAULT 0,
            native_value_usd REAL DEFAULT 0,
            activity_tier TEXT DEFAULT 'unknown',
            risk_flags_json TEXT NOT NULL DEFAULT '[]',
            data_quality_score INTEGER DEFAULT 0,
            label_sources_json TEXT NOT NULL DEFAULT '[]',
            source_attribution_json TEXT NOT NULL DEFAULT '{}',
            observed_at INTEGER NOT NULL,
            PRIMARY KEY (chain, address)
        );
        CREATE TABLE IF NOT EXISTS data_jobs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            job_type TEXT NOT NULL,
            status TEXT NOT NULL,
            started_at INTEGER NOT NULL,
            finished_at INTEGER,
            params_json TEXT NOT NULL DEFAULT '{}',
            result_json TEXT NOT NULL DEFAULT '{}',
            error TEXT
        );
        CREATE TABLE IF NOT EXISTS dex_venue_mappings (
            chain TEXT NOT NULL,
            router_addr TEXT NOT NULL,
            venue TEXT NOT NULL,
            source_url TEXT NOT NULL,
            evidence_json TEXT NOT NULL DEFAULT '{}',
            confidence REAL NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'active',
            created_at INTEGER NOT NULL,
            updated_at INTEGER NOT NULL,
            created_by TEXT,
            PRIMARY KEY (chain, router_addr)
        );
        CREATE INDEX IF NOT EXISTS idx_tx_from ON transactions(from_addr);
        CREATE INDEX IF NOT EXISTS idx_tx_to ON transactions(to_addr);
        CREATE INDEX IF NOT EXISTS idx_swap_wallet ON swaps(wallet);
        CREATE INDEX IF NOT EXISTS idx_token_transfers_chain_from ON token_transfers(chain, from_addr, timestamp);
        CREATE INDEX IF NOT EXISTS idx_token_transfers_chain_to ON token_transfers(chain, to_addr, timestamp);
        CREATE INDEX IF NOT EXISTS idx_token_transfers_chain_token ON token_transfers(chain, token, timestamp);
        CREATE INDEX IF NOT EXISTS idx_token_metadata_status ON token_metadata(status);
        CREATE INDEX IF NOT EXISTS idx_token_metadata_symbol ON token_metadata(symbol);
        CREATE INDEX IF NOT EXISTS idx_wallet_chain ON wallets(chain);
        CREATE INDEX IF NOT EXISTS idx_wallet_state_entity ON wallet_chain_state(entity);
        CREATE INDEX IF NOT EXISTS idx_data_jobs_type ON data_jobs(job_type);
        CREATE INDEX IF NOT EXISTS idx_data_jobs_started ON data_jobs(started_at);
        CREATE INDEX IF NOT EXISTS idx_dex_venue_mappings_status ON dex_venue_mappings(status);
    """)
    existing_columns = {
        row[1]
        for row in conn.execute("PRAGMA table_info(wallet_chain_state)").fetchall()
    }
    for column, ddl in {
        "address_kind": "ALTER TABLE wallet_chain_state ADD COLUMN address_kind TEXT DEFAULT 'wallet'",
        "is_contract": "ALTER TABLE wallet_chain_state ADD COLUMN is_contract INTEGER DEFAULT 0",
        "native_value_usd": "ALTER TABLE wallet_chain_state ADD COLUMN native_value_usd REAL DEFAULT 0",
        "activity_tier": "ALTER TABLE wallet_chain_state ADD COLUMN activity_tier TEXT DEFAULT 'unknown'",
        "risk_flags_json": "ALTER TABLE wallet_chain_state ADD COLUMN risk_flags_json TEXT NOT NULL DEFAULT '[]'",
        "data_quality_score": "ALTER TABLE wallet_chain_state ADD COLUMN data_quality_score INTEGER DEFAULT 0",
        "label_sources_json": "ALTER TABLE wallet_chain_state ADD COLUMN label_sources_json TEXT NOT NULL DEFAULT '[]'",
        "source_attribution_json": "ALTER TABLE wallet_chain_state ADD COLUMN source_attribution_json TEXT NOT NULL DEFAULT '{}'",
    }.items():
        if column not in existing_columns:
            conn.execute(ddl)
    swap_columns = {
        row[1]
        for row in conn.execute("PRAGMA table_info(swaps)").fetchall()
    }
    for column, ddl in {
        "token_identity_quality": "ALTER TABLE swaps ADD COLUMN token_identity_quality TEXT DEFAULT 'unknown'",
        "pair_rpc_source": "ALTER TABLE swaps ADD COLUMN pair_rpc_source TEXT",
        "router_addr": "ALTER TABLE swaps ADD COLUMN router_addr TEXT",
        "venue_source": "ALTER TABLE swaps ADD COLUMN venue_source TEXT",
        "venue_confidence": "ALTER TABLE swaps ADD COLUMN venue_confidence REAL DEFAULT 0",
    }.items():
        if column not in swap_columns:
            conn.execute(ddl)
    conn.commit()
    conn.close()


def _start_data_job(job_type: str, params: dict[str, Any]) -> int:
    _init_db()
    conn = _get_db()
    try:
        cur = conn.execute(
            "INSERT INTO data_jobs (job_type, status, started_at, params_json) VALUES (?, ?, ?, ?)",
            (job_type, "running", int(time.time()), json.dumps(params, default=str)),
        )
        conn.commit()
        return int(cur.lastrowid)
    finally:
        conn.close()


def _finish_data_job(job_id: int, status: str, result: dict[str, Any] | None = None, error: str | None = None) -> None:
    conn = _get_db()
    try:
        conn.execute(
            """
            UPDATE data_jobs
            SET status = ?, finished_at = ?, result_json = ?, error = ?
            WHERE id = ?
            """,
            (status, int(time.time()), json.dumps(result or {}, default=str), error, job_id),
        )
        conn.commit()
    finally:
        conn.close()


def get_data_jobs(limit: int = 20, job_type: str | None = None) -> dict[str, Any]:
    _init_db()
    where = ""
    params: list[Any] = []
    if job_type:
        where = "WHERE job_type = ?"
        params.append(job_type)
    conn = _get_db()
    try:
        rows = conn.execute(
            f"""
            SELECT id, job_type, status, started_at, finished_at, params_json, result_json, error
            FROM data_jobs
            {where}
            ORDER BY started_at DESC, id DESC
            LIMIT ?
            """,
            [*params, max(1, min(int(limit or 20), 100))],
        ).fetchall()
    finally:
        conn.close()
    return {
        "ok": True,
        "rows": [
            {
                "id": row[0],
                "job_type": row[1],
                "status": row[2],
                "started_at": row[3],
                "finished_at": row[4],
                "params": json.loads(row[5] or "{}"),
                "result": json.loads(row[6] or "{}"),
                "error": row[7],
            }
            for row in rows
        ],
    }


def _latest_data_job(job_types: list[str] | tuple[str, ...]) -> dict[str, Any] | None:
    _init_db()
    clean_types = [job_type for job_type in job_types if job_type]
    if not clean_types:
        return None
    placeholders = ",".join("?" for _ in clean_types)
    conn = _get_db()
    try:
        row = conn.execute(
            f"""
            SELECT id, job_type, status, started_at, finished_at, params_json, result_json, error
            FROM data_jobs
            WHERE job_type IN ({placeholders})
            ORDER BY started_at DESC, id DESC
            LIMIT 1
            """,
            clean_types,
        ).fetchone()
    finally:
        conn.close()
    if not row:
        return None
    return {
        "id": row[0],
        "job_type": row[1],
        "status": row[2],
        "started_at": row[3],
        "finished_at": row[4],
        "params": json.loads(row[5] or "{}"),
        "result": json.loads(row[6] or "{}"),
        "error": row[7],
        "age_seconds": max(0, int(time.time()) - int(row[3] or 0)),
    }


def build_label_ledger_job(limit_files: int | None = None) -> dict[str, Any]:
    """Rebuild the local label ledger with the same audit trail as RPC enrichment."""
    params = {"limit_files": limit_files}
    job_id = _start_data_job("label_ledger_build", params)
    try:
        from services.label_ledger import build_label_ledger

        result = build_label_ledger(limit_files)
        _finish_data_job(job_id, "ok", result=result)
        return {"ok": True, "job_id": job_id, "result": result}
    except Exception as exc:
        _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


