def get_dex_router_venue_mapping_final_safety_review(
    evidence_id: int | None,
    venue_name: str | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Final read-only safety review before designing any future DEX mapping write."""
    plan = get_dex_router_venue_mapping_sql_plan(evidence_id, venue_name, dry_run=True)
    audit = get_dex_router_venue_mapping_prewrite_audit(evidence_id, venue_name, dry_run=True)
    duplicate_check = audit.get("duplicate_mapping_check") or {}
    blockers = list(dict.fromkeys([
        *(plan.get("blockers") or []),
        *(audit.get("blockers") or []),
        *(["dry_run_required"] if not dry_run else []),
    ]))
    missing_proofs = list(dict.fromkeys([
        *(plan.get("missing_proofs") or []),
        *(audit.get("missing_proofs") or []),
    ]))

    plan_ready = plan.get("plan_status") == "ready_but_disabled"
    prewrite_ready = bool(audit.get("prewrite_ready"))
    duplicate_check_ready = bool(duplicate_check.get("checked")) and not bool(duplicate_check.get("duplicate_present"))
    rollback_ready = bool(plan.get("rollback_steps")) and plan.get("expected_rows_affected") == 1
    rollback_artifact_ready = bool(plan.get("rollback_artifact_ready"))
    plan_digest_bound = bool(plan.get("plan_digest_bound"))
    rollback_artifact_guard = plan.get("rollback_artifact_guard") or {}
    rollback_artifact_summary = plan.get("rollback_artifact_summary") or {}
    rollback_artifact_guard_ready = (
        rollback_artifact_ready
        and plan_digest_bound
        and bool(rollback_artifact_guard.get("rollback_artifact_exists"))
        and bool(rollback_artifact_guard.get("rollback_plan_digest_bound"))
    )
    expected_rows_affected = int(plan.get("expected_rows_affected") or 0)
    if not plan_ready:
        blockers.append("sql_plan_not_ready")
    if not prewrite_ready:
        blockers.append("prewrite_not_ready")
    if not duplicate_check_ready:
        blockers.append("duplicate_check_not_ready")
    if not rollback_ready:
        blockers.append("rollback_not_ready")
    if not rollback_artifact_ready:
        blockers.append("rollback_artifact_not_ready")
    if not plan_digest_bound:
        blockers.append("rollback_artifact_plan_digest_mismatch")
    if expected_rows_affected != 1:
        blockers.append("expected_rows_affected_must_equal_1")
    blockers = list(dict.fromkeys(blockers))
    ready = (
        plan_ready
        and prewrite_ready
        and duplicate_check_ready
        and rollback_ready
        and rollback_artifact_ready
        and plan_digest_bound
        and rollback_artifact_guard_ready
        and expected_rows_affected == 1
        and not blockers
    )

    return {
        "ok": True,
        "safety_status": "ready_for_write_design_only" if ready else "blocked",
        "evidence_id": plan.get("evidence_id"),
        "venue_name": plan.get("venue_name"),
        "chain": plan.get("chain"),
        "router_address": plan.get("router_address"),
        "plan_ready": plan_ready,
        "prewrite_ready": prewrite_ready,
        "duplicate_check_ready": duplicate_check_ready,
        "rollback_ready": rollback_ready,
        "rollback_artifact_ready": rollback_artifact_ready,
        "plan_digest_bound": plan_digest_bound,
        "rollback_artifact_guard_ready": rollback_artifact_guard_ready,
        "rollback_artifact_guard": rollback_artifact_guard,
        "rollback_artifact_summary": rollback_artifact_summary,
        "expected_rows_affected": expected_rows_affected,
        "write_preconditions": [
            "admin_token_valid",
            "sql_plan_ready",
            "prewrite_audit_ready",
            "evidence_row_still_pending",
            "router_still_in_source_map",
            "source_url_still_present",
            "no_existing_mapping_for_chain_router",
            "rollback_artifact_valid",
            "rollback_plan_digest_bound",
            "expected_rows_affected_equals_1",
        ],
        "rollback_preconditions": [
            "rollback_artifact_row_exists",
            "rollback_digest_matches_current_plan",
            "inserted_mapping_identified_by_chain_router_source_evidence",
            "rollback_deletes_only_inserted_mapping",
            "rollback_expected_rows_affected_equals_1",
        ],
        "remaining_risks": [
            "official_evidence_could_still_be_wrong_or_stale",
            "plan_digest_can_drift_before_actual_write",
            "real_write_must_recheck_inside_transaction",
            "duplicate_mapping_must_be_rechecked_inside_future_write_transaction",
            "rollback_only_covers_mapping_insert_not_external_interpretation",
            "mapping_router_to_venue_is_not_a_trade_signal",
            "no_client_signal_generated",
            "alpha_lab_client_ui_remains_frozen",
        ],
        "future_write_recommendation": "prepare_confirmed_write_endpoint_later" if ready else "resolve_blockers_before_write_design",
        "write_enabled_now": False,
        "mapping_allowed_now": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "blockers": blockers,
        "missing_proofs": missing_proofs,
        "source_policy": (
            "admin-only DEX venue mapping final safety review; read-only gate over SQL plan and prewrite audit, "
            "no DB writes, no provider calls, no scraping, no router labels, no venue mappings, no swap changes, "
            "no wallet rows and no Alpha Lab changes"
        ),
    }


