def get_dex_router_venue_mapping_real_write_go_nogo(
    evidence_id: int | None,
    venue_name: str | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only go/no-go review before designing any real confirmed DEX mapping write."""
    required_rechecks = [
        "evidence_row_still_pending",
        "router_still_in_source_map",
        "source_url_still_present",
        "no_existing_mapping_for_chain_router",
        "rollback_artifact_row_still_exists",
        "rollback_artifact_plan_digest_still_matches_current_plan",
        "expected_rows_affected_exactly_1",
        "recheck_inside_same_db_transaction",
    ]
    confirm = "APPLY_DEX_ROUTER_VENUE_MAPPING CONFIRM_DEX_VENUE_MAPPING_WRITE CONFIRM_ROLLBACK_ARTIFACT_BOUND"
    apply = get_dex_router_venue_mapping_apply_confirmed_design(evidence_id, venue_name, dry_run=True, confirm=confirm)
    safety = get_dex_router_venue_mapping_final_safety_review(evidence_id, venue_name, dry_run=True)
    rechecks = set(apply.get("transaction_rechecks_required") or [])
    missing_rechecks = [item for item in required_rechecks if item not in rechecks]
    blockers = list(dict.fromkeys([
        *(apply.get("blockers") or []),
        *(safety.get("blockers") or []),
        *(["dry_run_required"] if not dry_run else []),
        *(["missing_transaction_rechecks"] if missing_rechecks else []),
    ]))
    missing_proofs = list(dict.fromkeys([
        *(apply.get("missing_proofs") or []),
        *(safety.get("missing_proofs") or []),
        *missing_rechecks,
    ]))
    apply_contract_ready = apply.get("apply_status") == "ready_for_future_confirm" and bool(apply.get("would_write"))
    safety_ready = safety.get("safety_status") == "ready_for_write_design_only"
    write_preview_ready = bool(apply.get("write_preview"))
    rollback_preview_ready = bool(apply.get("rollback_preview"))
    rollback_artifact_ready = bool(apply.get("rollback_artifact_ready")) and bool(safety.get("rollback_artifact_ready"))
    plan_digest_bound = bool(apply.get("plan_digest_bound")) and bool(safety.get("plan_digest_bound"))
    transaction_rechecks_ready = not missing_rechecks
    if not rollback_artifact_ready:
        blockers.append("rollback_artifact_not_ready")
    if not plan_digest_bound:
        blockers.append("rollback_artifact_plan_digest_mismatch")
    blockers = list(dict.fromkeys(blockers))
    pipeline_ready = (
        apply_contract_ready
        and safety_ready
        and write_preview_ready
        and rollback_preview_ready
        and rollback_artifact_ready
        and plan_digest_bound
        and transaction_rechecks_ready
        and not blockers
    )

    return {
        "ok": True,
        "decision": "go_for_write_design" if pipeline_ready else "no_go",
        "evidence_id": safety.get("evidence_id") if safety.get("evidence_id") is not None else apply.get("evidence_id"),
        "venue_name": safety.get("venue_name") or apply.get("venue_name"),
        "chain": safety.get("chain") or apply.get("chain"),
        "router_address": safety.get("router_address") or apply.get("router_address"),
        "pipeline_ready": pipeline_ready,
        "apply_contract_ready": apply_contract_ready,
        "safety_ready": safety_ready,
        "write_preview_ready": write_preview_ready,
        "rollback_preview_ready": rollback_preview_ready,
        "rollback_artifact_ready": rollback_artifact_ready,
        "plan_digest_bound": plan_digest_bound,
        "rollback_artifact_guard": apply.get("rollback_artifact_guard") or safety.get("rollback_artifact_guard") or {},
        "rollback_artifact_summary": apply.get("rollback_artifact_summary") or safety.get("rollback_artifact_summary") or {},
        "required_transaction_rechecks": required_rechecks,
        "transaction_rechecks_ready": transaction_rechecks_ready,
        "go_reasons": [
            "apply_contract_ready",
            "safety_review_ready",
            "write_preview_available",
            "rollback_preview_available",
            "rollback_artifact_ready",
            "rollback_plan_digest_bound",
            "transaction_rechecks_complete",
        ] if pipeline_ready else [],
        "no_go_reasons": blockers,
        "required_next_goal": "design_real_confirmed_transactional_write_endpoint" if pipeline_ready else "resolve_go_nogo_blockers",
        "must_remain_disabled": [
            "real_write_enabled",
            "mapping_allowed_now",
            "dex_venue_mapping_write",
            "wallet_chain_state_changes",
            "swap_changes",
            "alpha_lab_ui_changes",
            "client_trade_signal",
        ],
        "mapping_allowed_now": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": (
            "admin-only DEX venue mapping real-write go/no-go review; read-only synthesis, no DB writes, "
            "no provider calls, no scraping, no router labels, no venue mappings, no swap changes, "
            "no wallet rows and no Alpha Lab changes"
        ),
    }


