def get_dex_router_venue_mapping_multi_router_validation_scan(
    limit: int = 20,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only scan for additional DEX routers before any first real mapping write."""
    safe_limit = max(1, min(int(limit or 20), 50))
    review = get_dex_router_official_evidence_review_queue(status="pending_admin_review", limit=safe_limit)
    source_map = get_dex_router_source_map(limit=50, include_public_evidence=False)
    router_rows = {
        (str(row.get("chain") or ""), str(row.get("router_address") or "").lower()): row
        for row in source_map.get("rows", [])
    }
    evidence_rows = sorted(
        review.get("rows") or [],
        key=lambda row: (
            str(row.get("chain") or ""),
            str(row.get("router_address") or "").lower(),
            int(row.get("evidence_id") or 0),
        ),
    )[:safe_limit]

    mapping_lookup: dict[tuple[str, str], dict[str, Any]] = {}
    artifact_lookup: set[int] = set()
    conn = _get_db()
    try:
        mapping_table_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                ("dex_venue_mappings",),
            ).fetchone()
        )
        if mapping_table_exists:
            for row in conn.execute(
                "SELECT chain, LOWER(router_addr), venue, source_url, confidence, status FROM dex_venue_mappings"
            ).fetchall():
                mapping_lookup[(str(row[0] or ""), str(row[1] or ""))] = {
                    "venue": row[2],
                    "source_url": row[3],
                    "confidence": float(row[4] or 0),
                    "status": row[5],
                }
        artifact_table_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                ("dex_venue_mapping_rollback_artifacts",),
            ).fetchone()
        )
        if artifact_table_exists:
            artifact_lookup = {
                int(row[0])
                for row in conn.execute(
                    "SELECT DISTINCT evidence_id FROM dex_venue_mapping_rollback_artifacts"
                ).fetchall()
                if row[0] is not None
            }
    finally:
        conn.close()

    rows: list[dict[str, Any]] = []
    ready_count = 0
    existing_mappings = 0
    rollback_artifacts_existing = 0
    routers_still_unknown = 0
    accepted_types = set(DEX_ROUTER_ACCEPTED_EVIDENCE_TYPES)
    for evidence in evidence_rows:
        evidence_id = int(evidence.get("evidence_id") or 0)
        chain = str(evidence.get("chain") or "")
        router_address = str(evidence.get("router_address") or "").lower()
        source_url = str(evidence.get("source_url") or "").strip()
        evidence_type = str(evidence.get("evidence_type") or "")
        evidence_status = str(evidence.get("status") or "")
        key = (chain, router_address)
        router_row = router_rows.get(key)
        existing_mapping = mapping_lookup.get(key)
        artifact_present = evidence_id in artifact_lookup
        blockers: list[str] = []
        if evidence_status != "pending_admin_review":
            blockers.append("evidence_not_pending")
        if evidence_type not in accepted_types:
            blockers.append("evidence_type_not_accepted")
        if not router_row:
            blockers.append("router_not_in_current_source_map")
        if not source_url:
            blockers.append("source_url_missing")
        if existing_mapping:
            blockers.append("existing_mapping_present")
        readiness = "ready_for_pipeline_replay" if not blockers else "blocked"
        if readiness == "ready_for_pipeline_replay":
            ready_count += 1
        if existing_mapping:
            existing_mappings += 1
        if artifact_present:
            rollback_artifacts_existing += 1
        if router_row:
            routers_still_unknown += 1
        suggested_venue_name = str((router_row or {}).get("candidate_venue_hint") or "").strip() or None
        rows.append({
            "evidence_id": evidence_id,
            "chain": chain,
            "router_address": router_address,
            "source_url": source_url or None,
            "evidence_type": evidence_type,
            "evidence_status": evidence_status,
            "router_still_unknown": bool(router_row),
            "router_unknown_swaps": int((router_row or {}).get("unknown_swaps") or 0),
            "router_tx_count": int((router_row or {}).get("tx_count") or 0),
            "existing_mapping_present": bool(existing_mapping),
            "rollback_artifact_present": artifact_present,
            "readiness": readiness,
            "blockers": list(dict.fromkeys(blockers)),
            "suggested_venue_name": suggested_venue_name,
            "next_pipeline_step": (
                "run_mapping_preview_with_admin_venue_name"
                if readiness == "ready_for_pipeline_replay" and suggested_venue_name
                else "needs_admin_venue_name"
                if readiness == "ready_for_pipeline_replay"
                else "resolve_blockers_before_pipeline_replay"
            ),
            "would_create_mapping": False,
            "would_write": False,
        })

    blocked_count = len(rows) - ready_count
    blockers = [] if dry_run else ["dry_run_required"]
    return {
        "ok": True,
        "scan_status": "blocked" if blockers else "ready" if rows else "empty",
        "summary": {
            "total_evidence_rows": int((review.get("summary") or {}).get("total_evidence_rows") or len(rows)),
            "rows_scanned": len(rows),
            "ready_for_pipeline_replay": ready_count,
            "blocked_rows": blocked_count,
            "existing_mappings": existing_mappings,
            "rollback_artifacts_existing": rollback_artifacts_existing,
            "routers_still_unknown": routers_still_unknown,
            "recommended_sample_size": 3 if ready_count >= 3 else 2,
            "dry_run": bool(dry_run),
        },
        "rows": rows,
        "recommended_next_action": (
            "rerun_with_dry_run_true"
            if blockers
            else
            "validate_2_or_3_ready_routers_before_first_real_write"
            if ready_count
            else "collect_more_source_backed_dex_router_evidence"
        ),
        "blockers": blockers,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": (
            "admin-only read-only DEX multi-router validation scan from local evidence, source-map, mapping and artifact tables; "
            "dry-run only, no DB writes, no files, no provider calls, no scraping, no router labels, no venue mappings, "
            "no rollback artifact creation, no swap changes, no wallet rows and no Alpha Lab or client signal changes"
        ),
    }


def get_dex_router_venue_mapping_additional_router_evidence_plan(
    needed: int = 2,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only plan for adding more DEX router evidence before a first real mapping write."""
    safe_needed = max(1, min(int(needed or 2), 5))
    source_queue = get_dex_router_official_source_queue(limit=50)
    replay_scan = get_dex_router_venue_mapping_multi_router_validation_scan(limit=20, dry_run=True)
    source_map = get_dex_router_source_map(limit=50, include_public_evidence=False)
    source_map_rows = {
        (str(row.get("chain") or ""), str(row.get("router_address") or "").lower()): row
        for row in source_map.get("rows", [])
    }

    evidence_keys: set[tuple[str, str]] = set()
    mapping_keys: set[tuple[str, str]] = set()
    conn = _get_db()
    try:
        evidence_table_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                ("dex_router_official_evidence_queue",),
            ).fetchone()
        )
        if evidence_table_exists:
            evidence_keys = {
                (str(row[0] or ""), str(row[1] or "").lower())
                for row in conn.execute(
                    "SELECT chain, router_address FROM dex_router_official_evidence_queue"
                ).fetchall()
            }
        mapping_table_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                ("dex_venue_mappings",),
            ).fetchone()
        )
        if mapping_table_exists:
            mapping_keys = {
                (str(row[0] or ""), str(row[1] or "").lower())
                for row in conn.execute(
                    "SELECT chain, router_addr FROM dex_venue_mappings"
                ).fetchall()
            }
    finally:
        conn.close()

    candidate_rows: list[dict[str, Any]] = []
    excluded_evidence = 0
    excluded_mapping = 0
    for row in source_queue.get("rows") or []:
        chain = str(row.get("chain") or "")
        router_address = str(row.get("router_address") or "").lower()
        key = (chain, router_address)
        evidence_present = key in evidence_keys
        mapping_present = key in mapping_keys
        if evidence_present:
            excluded_evidence += 1
            continue
        if mapping_present:
            excluded_mapping += 1
            continue
        source_row = source_map_rows.get(key) or {}
        sample_tokens = row.get("sample_tokens") or []
        unknown_swaps = int(row.get("unknown_swaps") or 0)
        tx_count = int(row.get("tx_count") or 0)
        has_wallet_state = bool(source_row.get("has_wallet_state"))
        is_contract = bool(source_row.get("is_contract"))
        priority_score = (
            unknown_swaps * 100
            + tx_count * 5
            + (20 if has_wallet_state else 0)
            + (10 if is_contract else 0)
            + min(len(sample_tokens), 10)
        )
        candidate_rows.append({
            "chain": chain,
            "router_address": router_address,
            "unknown_swaps": unknown_swaps,
            "tx_count": tx_count,
            "sample_tokens": sample_tokens,
            "candidate_venue_hint": row.get("candidate_venue_hint"),
            "evidence_already_present": False,
            "existing_mapping_present": False,
            "priority_score": priority_score,
            "recommended_evidence_type": "official_protocol_docs",
            "required_admin_inputs": [
                "chain",
                "router_address",
                "evidence_type",
                "source_url",
                "notes",
                "confirm=INSERT_DEX_ROUTER_OFFICIAL_EVIDENCE",
            ],
            "next_pipeline_step": "collect_official_source_url_then_run_confirmed_evidence_insert",
            "would_insert_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
        })

    candidate_rows.sort(
        key=lambda row: (
            -int(row.get("priority_score") or 0),
            str(row.get("chain") or ""),
            str(row.get("router_address") or ""),
        )
    )
    selected_rows = candidate_rows[:safe_needed] if dry_run else []
    blockers = [] if dry_run else ["dry_run_required"]
    return {
        "ok": True,
        "plan_status": "blocked" if blockers else "ready" if selected_rows else "empty",
        "summary": {
            "needed": safe_needed,
            "source_queue_rows": int((source_queue.get("summary") or {}).get("queue_rows") or len(source_queue.get("rows") or [])),
            "current_ready_for_pipeline_replay": int((replay_scan.get("summary") or {}).get("ready_for_pipeline_replay") or 0),
            "candidate_rows_available": len(candidate_rows),
            "proposed_rows": len(selected_rows),
            "excluded_evidence_already_present": excluded_evidence,
            "excluded_existing_mapping": excluded_mapping,
            "dry_run": bool(dry_run),
        },
        "rows": selected_rows,
        "required_admin_inputs": [
            "chain",
            "router_address",
            "evidence_type",
            "source_url",
            "notes",
            "confirm=INSERT_DEX_ROUTER_OFFICIAL_EVIDENCE",
        ],
        "accepted_evidence_types": sorted(DEX_ROUTER_ACCEPTED_EVIDENCE_TYPES),
        "rejected_evidence_types": sorted(DEX_ROUTER_REJECTED_EVIDENCE_TYPES),
        "next_admin_action": (
            "collect_official_sources_for_selected_routers_then_run_future_confirmed_evidence_insert"
            if selected_rows
            else "collect_more_unknown_router_candidates_or_resolve_blockers"
        ),
        "real_write_enabled": False,
        "writes_performed": 0,
        "blockers": blockers,
        "source_policy": (
            "admin-only read-only DEX additional router evidence plan from local source queue and DB tables; "
            "dry-run only, no DB writes, no files, no provider calls, no web search, no scraping, no evidence insert, "
            "no rollback artifacts, no venue mappings, no swap changes, no wallet rows and no Alpha Lab or client signal changes"
        ),
    }


