def repair_dex_trades_amount_decode_token_metadata(
    limit: int = 50,
    expected_token_count: int | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
    max_seconds: int = 45,
) -> dict[str, Any]:
    """Confirmed bounded ERC20 metadata repair for raw Swap amount-decode blockers."""
    clean_limit = max(1, min(int(limit or 50), 100))
    safe_seconds = max(5, min(int(max_seconds or 45), 180))
    plan = get_dex_trades_amount_decode_metadata_repair_plan(limit=clean_limit, dry_run=True)
    selected = list(plan.get("selected_for_metadata_repair") or [])
    before_counts = _onchain_table_counts()
    before_label_counts = _label_ledger_guard_counts()
    blockers: list[str] = []
    if not selected:
        blockers.append("no_decode_blocked_tokens_missing_decimals")
    if expected_token_count is None:
        blockers.append("expected_token_count_required")
    elif int(expected_token_count) != len(selected):
        blockers.append("expected_token_count_mismatch")
    if not dry_run and confirm != DEX_TRADES_AMOUNT_DECODE_METADATA_REPAIR_CONFIRM:
        blockers.append("confirm_required")

    common = {
        "ok": not blockers,
        "dry_run": bool(dry_run),
        "limit": clean_limit,
        "max_seconds": safe_seconds,
        "confirm_required": DEX_TRADES_AMOUNT_DECODE_METADATA_REPAIR_CONFIRM,
        "expected_token_count": expected_token_count,
        "selected_for_metadata_repair": selected,
        "before_counts": before_counts,
        "before_label_counts": before_label_counts,
        "amount_usd_decision_enabled": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "source_policy": (
            "bounded ERC20 metadata repair for tokens blocking raw Swap amount decode only; writes token_metadata "
            "and data_jobs only when confirmed; no labels, mappings, trades, wallet orders, client signals or opt-ins"
        ),
    }
    if dry_run or blockers:
        return {
            **common,
            "repair_status": "ready_but_disabled" if selected and not blockers else "blocked",
            "would_query_rpc_metadata": bool(selected and not blockers),
            "would_enrich_metadata": bool(selected and not blockers),
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "blockers": list(dict.fromkeys(blockers)),
        }

    backup_path = _backup_onchain_db("before_dex_trades_amount_decode_metadata_repair")
    job_id = _start_data_job(
        "dex_trades_amount_decode_metadata_repair",
        {"limit": clean_limit, "max_seconds": safe_seconds, "selected": selected},
    )
    metadata_rows: list[dict[str, Any]] = []
    started_at = time.monotonic()
    try:
        conn = _get_db()
        try:
            for row in selected:
                if time.monotonic() - started_at >= safe_seconds:
                    blockers.append("time_budget_reached")
                    break
                metadata = _rpc_erc20_metadata(str(row.get("chain") or ""), str(row.get("token_address") or ""))
                metadata["blocking_raw_provenance_ids"] = row.get("blocking_raw_provenance_ids") or []
                metadata["blocking_pools"] = row.get("blocking_pools") or []
                metadata["token_roles"] = row.get("token_roles") or []
                metadata["persisted"] = False
                conn.execute(
                    """
                    INSERT INTO token_metadata (
                        chain, token_address, symbol, name, decimals, rpc_source,
                        observed_at, status, error
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(chain, token_address) DO UPDATE SET
                        symbol = excluded.symbol,
                        name = excluded.name,
                        decimals = excluded.decimals,
                        rpc_source = excluded.rpc_source,
                        observed_at = excluded.observed_at,
                        status = excluded.status,
                        error = excluded.error
                    """,
                    (
                        metadata.get("chain"),
                        metadata.get("token_address"),
                        metadata.get("symbol"),
                        metadata.get("name"),
                        metadata.get("decimals"),
                        metadata.get("rpc_source"),
                        int(time.time()),
                        metadata.get("status") or "unresolved",
                        metadata.get("error"),
                    ),
                )
                metadata["persisted"] = True
                metadata_rows.append(metadata)
            conn.commit()
        finally:
            conn.close()

        after_counts = _onchain_table_counts()
        after_label_counts = _label_ledger_guard_counts()
        table_deltas = {
            table: int(after_counts.get(table, 0)) - int(before_counts.get(table, 0))
            for table in sorted(set(before_counts) | set(after_counts))
        }
        changed_tables = {table: delta for table, delta in table_deltas.items() if delta != 0}
        disallowed_table_deltas = {
            table: delta
            for table, delta in changed_tables.items()
            if table not in _TOKEN_METADATA_ALLOWED_TABLES
        }
        label_count_deltas = {
            key: int(after_label_counts.get(key, 0)) - int(before_label_counts.get(key, 0))
            for key in sorted(set(before_label_counts) | set(after_label_counts))
        }
        labels_changed = any(delta != 0 for delta in label_count_deltas.values())
        if disallowed_table_deltas:
            blockers.append("disallowed_onchain_table_changed")
        if labels_changed:
            blockers.append("label_ledger_changed")
        payload = {
            **common,
            "ok": not blockers,
            "dry_run": False,
            "backup_path": backup_path,
            "job_id": job_id,
            "repair_status": "completed" if not blockers else "completed_with_guard_blockers",
            "metadata_rows": metadata_rows,
            "resolved": sum(1 for row in metadata_rows if row.get("status") == "resolved"),
            "unresolved": sum(1 for row in metadata_rows if row.get("status") != "resolved"),
            "after_counts": after_counts,
            "after_label_counts": after_label_counts,
            "table_deltas": table_deltas,
            "changed_tables": changed_tables,
            "disallowed_table_deltas": disallowed_table_deltas,
            "label_count_deltas": label_count_deltas,
            "labels_changed": labels_changed,
            "would_query_rpc_metadata": False,
            "would_enrich_metadata": False,
            "would_write": False,
            "real_write_enabled": True,
            "writes_performed": sum(max(0, int(delta)) for delta in changed_tables.values()),
            "blockers": list(dict.fromkeys(blockers)),
        }
        _finish_data_job(job_id, "ok" if not blockers else "failed", result=payload)
        return payload
    except Exception as exc:
        _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


