def create_token_market_discovery_candidates(
    token_symbol: str | None,
    chain: str | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Create token market discovery candidate storage with explicit DDL-only confirmation."""
    plan = get_token_market_discovery_candidates_schema_plan(token_symbol, chain, dry_run=True)
    if dry_run:
        return {
            **plan,
            "dry_run": True,
            "would_create_table": bool(plan.get("migration_required")),
            "would_write": False,
            "writes_performed": 0,
            "source_policy": (
                "admin-only dry-run token market discovery candidates migration; no table creation, "
                "no DB writes, no provider calls, no scraping, no labels, no venue mappings, "
                "no rollback artifacts, no swaps, no wallet rows and no Alpha Lab changes"
            ),
        }
    if confirm != "CREATE_TOKEN_MARKET_DISCOVERY_CANDIDATES_TABLE":
        return {
            **plan,
            "dry_run": False,
            "ok": False,
            "blocked": True,
            "blockers": ["confirm_CREATE_TOKEN_MARKET_DISCOVERY_CANDIDATES_TABLE_required"],
            "would_create_table": False,
            "would_write": False,
            "writes_performed": 0,
        }

    target_table = "token_market_discovery_candidates"
    index_names = [
        "token_market_discovery_candidates_dedupe_key_uq",
        "token_market_discovery_candidates_token_symbol_idx",
        "token_market_discovery_candidates_token_chain_idx",
        "token_market_discovery_candidates_market_type_idx",
        "token_market_discovery_candidates_venue_key_idx",
        "token_market_discovery_candidates_status_idx",
        "token_market_discovery_candidates_chain_token_contract_idx",
        "token_market_discovery_candidates_chain_pool_idx",
    ]
    conn = _get_db()
    try:
        before_objects = {
            "table": bool(
                conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                    (target_table,),
                ).fetchone()
            )
        }
        for index_name in index_names:
            before_objects[index_name] = bool(
                conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type = 'index' AND name = ? LIMIT 1",
                    (index_name,),
                ).fetchone()
            )

        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS token_market_discovery_candidates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                token_symbol TEXT NOT NULL,
                chain TEXT,
                market_type TEXT NOT NULL,
                venue_name TEXT,
                venue_key TEXT,
                pair TEXT,
                base_asset TEXT,
                quote_asset TEXT,
                token_contract TEXT,
                pool_or_pair_address TEXT,
                router_or_factory_address TEXT,
                source_url TEXT NOT NULL,
                source_tier TEXT NOT NULL,
                evidence_type TEXT NOT NULL,
                observed_volume_24h REAL,
                observed_liquidity REAL,
                observed_at TEXT,
                status TEXT NOT NULL DEFAULT 'pending_admin_review',
                dedupe_key TEXT NOT NULL UNIQUE,
                source_policy TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE UNIQUE INDEX IF NOT EXISTS token_market_discovery_candidates_dedupe_key_uq
            ON token_market_discovery_candidates(dedupe_key)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_token_symbol_idx
            ON token_market_discovery_candidates(token_symbol)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_token_chain_idx
            ON token_market_discovery_candidates(token_symbol, chain)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_market_type_idx
            ON token_market_discovery_candidates(market_type)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_venue_key_idx
            ON token_market_discovery_candidates(venue_key)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_status_idx
            ON token_market_discovery_candidates(status)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_chain_token_contract_idx
            ON token_market_discovery_candidates(chain, token_contract)
            """
        )
        conn.execute(
            """
            CREATE INDEX IF NOT EXISTS token_market_discovery_candidates_chain_pool_idx
            ON token_market_discovery_candidates(chain, pool_or_pair_address)
            """
        )
        conn.commit()

        after_objects = {
            "table": bool(
                conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                    (target_table,),
                ).fetchone()
            )
        }
        for index_name in index_names:
            after_objects[index_name] = bool(
                conn.execute(
                    "SELECT 1 FROM sqlite_master WHERE type = 'index' AND name = ? LIMIT 1",
                    (index_name,),
                ).fetchone()
            )
        candidate_rows = int(conn.execute(f"SELECT COUNT(*) FROM {target_table}").fetchone()[0]) if after_objects["table"] else 0
    finally:
        conn.close()

    refreshed = get_token_market_discovery_candidates_schema_plan(token_symbol, chain, dry_run=True)
    writes_performed = sum(1 for key, exists_after in after_objects.items() if exists_after and not before_objects.get(key))
    return {
        **refreshed,
        "dry_run": False,
        "table_created": bool(not before_objects["table"] and after_objects["table"]),
        "idempotent": True,
        "candidate_rows": candidate_rows,
        "would_create_table": False,
        "would_write": False,
        "writes_performed": writes_performed,
        "source_policy": (
            "admin-confirmed token market discovery candidates DDL migration only; creates table/indexes if absent, "
            "inserts no rows, does not call providers or scraping, and does not change labels, venue mappings, "
            "rollback artifacts, swaps, wallet rows, Alpha Lab or client signals"
        ),
    }


_TOKEN_MARKET_DISCOVERY_MARKET_TYPES = {"cex", "dex", "hybrid_or_unclear", "aggregator_or_perp", "unknown"}
_TOKEN_MARKET_DISCOVERY_SOURCE_TIERS = {"tier_1", "tier_2", "tier_3"}


def _token_market_discovery_slug(value: str | None) -> str | None:
    clean = str(value or "").strip().lower()
    if not clean:
        return None
    slug = re.sub(r"[^a-z0-9]+", "_", clean).strip("_")
    return slug or None


def _token_market_discovery_pair(pair: str | None, base_asset: str | None, quote_asset: str | None) -> str | None:
    clean_pair = str(pair or "").strip().upper().replace("-", "/").replace("_", "/")
    if clean_pair:
        parts = [part for part in clean_pair.split("/") if part]
        if len(parts) >= 2:
            return f"{parts[0]}/{parts[1]}"
        return clean_pair
    clean_base = str(base_asset or "").strip().upper()
    clean_quote = str(quote_asset or "").strip().upper()
    if clean_base and clean_quote:
        return f"{clean_base}/{clean_quote}"
    return None


def _token_market_discovery_addr(value: str | None) -> str | None:
    clean = str(value or "").strip().lower()
    return clean or None


