        "INDEX token_market_controlled_promotion_queue_future_target_queue_idx ON future_target_queue",
        "INDEX token_market_controlled_promotion_queue_status_idx ON status",
        "INDEX token_market_controlled_promotion_queue_chain_venue_idx ON chain, venue_key",
