def create_token_market_downstream_business_handoff_queue(
    downstream_id: int | None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Confirmed DDL-only creation of the downstream business handoff queue."""
    plan = get_token_market_downstream_business_handoff_queue_schema_plan(
        downstream_id=downstream_id,
        dry_run=True,
    )
    blockers = list(plan.get("blockers") or [])
    if downstream_id is None:
        blockers.append("downstream_id_required")
