def get_token_market_post_apply_execution_apply_queue_schema_plan(
    post_apply_execution_id: int | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only schema plan for a future token market post-apply execution apply queue."""
    target_table = "token_market_post_apply_execution_apply_queue"
    contract = get_token_market_post_apply_execution_apply_contract(
        post_apply_execution_id=post_apply_execution_id,
        dry_run=True,
    )
    blockers = list(contract.get("blockers") or [])
    if not dry_run:
        blockers.append("dry_run_required")
    if post_apply_execution_id is None:
        blockers.append("post_apply_execution_id_required")
    if contract.get("contract_status") != "ready_but_disabled":
        blockers.append("post_apply_execution_apply_contract_not_ready")

    conn = _get_db()
    try:
        table_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                (target_table,),
            ).fetchone()
        )
    finally:
        conn.close()

    schema_preview = [
        "id INTEGER PRIMARY KEY AUTOINCREMENT",
        "post_apply_execution_id INTEGER NOT NULL",
        "post_apply_insert_id INTEGER NOT NULL",
        "post_apply_id INTEGER NOT NULL",
        "business_apply_id INTEGER NOT NULL",
        "business_execution_id INTEGER NOT NULL",
        "business_insert_id INTEGER NOT NULL",
        "business_handoff_id INTEGER NOT NULL",
        "downstream_id INTEGER NOT NULL",
        "promotion_id INTEGER NOT NULL",
        "evidence_id INTEGER NOT NULL",
        "candidate_id INTEGER NOT NULL",
        "token_symbol TEXT NOT NULL",
        "market_type TEXT NOT NULL",
        "final_apply_target TEXT NOT NULL",
        "execution_target TEXT NOT NULL",
        "apply_target TEXT NOT NULL",
        "insert_target TEXT NOT NULL",
        "post_apply_target TEXT NOT NULL",
        "business_target TEXT NOT NULL",
        "promotion_target TEXT NOT NULL",
        "downstream_target TEXT NOT NULL",
        "future_target_queue TEXT NOT NULL",
        "source_url TEXT NOT NULL",
        "source_tier TEXT NOT NULL",
        "evidence_type TEXT NOT NULL",
        "evidence_preview_digest TEXT NOT NULL",
        "post_apply_insert_dedupe_key TEXT NOT NULL",
        "post_apply_execution_dedupe_key TEXT NOT NULL",
        "post_apply_execution_apply_dedupe_key TEXT NOT NULL UNIQUE",
        "apply_contract_json TEXT NOT NULL",
        "status TEXT NOT NULL DEFAULT 'pending_admin_review'",
        "created_at TEXT NOT NULL",
        "source_policy TEXT NOT NULL",
    ]
    indexes_preview = [
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_dedupe ON token_market_post_apply_execution_apply_queue(post_apply_execution_apply_dedupe_key)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_execution ON token_market_post_apply_execution_apply_queue(post_apply_execution_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_insert ON token_market_post_apply_execution_apply_queue(post_apply_insert_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_post_apply ON token_market_post_apply_execution_apply_queue(post_apply_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_business_apply ON token_market_post_apply_execution_apply_queue(business_apply_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_business_execution ON token_market_post_apply_execution_apply_queue(business_execution_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_business_insert ON token_market_post_apply_execution_apply_queue(business_insert_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_handoff ON token_market_post_apply_execution_apply_queue(business_handoff_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_downstream ON token_market_post_apply_execution_apply_queue(downstream_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_promotion ON token_market_post_apply_execution_apply_queue(promotion_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_evidence ON token_market_post_apply_execution_apply_queue(evidence_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_candidate ON token_market_post_apply_execution_apply_queue(candidate_id)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_token ON token_market_post_apply_execution_apply_queue(token_symbol)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_market_type ON token_market_post_apply_execution_apply_queue(market_type)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_final_target ON token_market_post_apply_execution_apply_queue(final_apply_target)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_market_final_target ON token_market_post_apply_execution_apply_queue(market_type, final_apply_target)",
        "CREATE INDEX IF NOT EXISTS idx_token_market_post_apply_execution_apply_queue_status ON token_market_post_apply_execution_apply_queue(status)",
    ]
    constraints_preview = {
        "market_type_enum": ["cex", "dex", "hybrid_or_unclear", "aggregator_or_perp", "unknown"],
        "final_apply_target_enum": [
            "cex_market_evidence_review_queue",
            "dex_router_official_evidence_queue",
            "manual_classification_queue",
        ],
        "status_enum": [
            "pending_admin_review",
            "accepted_for_future_final_apply",
            "needs_better_source",
            "rejected",
        ],
        "cex_guard": "cex final apply intent must not write direct CEX label",
        "dex_guard": "dex final apply intent must not write DEX mapping",
        "hybrid_guard": "hybrid_or_unclear remains manual review",
        "trade_guard": "no client trade execution route",
        "client_consent_guard": "no client consent or opt-in route",
    }
    dedupe_constraints = {
        "primary_unique_key": "post_apply_execution_apply_dedupe_key",
        "post_apply_execution_apply_dedupe_key": contract.get("post_apply_execution_apply_dedupe_key"),
        "post_apply_execution_dedupe_key": contract.get("dedupe_status", {}).get("post_apply_execution_dedupe_key"),
        "post_apply_insert_dedupe_key": (
            ((contract.get("apply_contract") or {}).get("payload_preview") or {}).get("post_apply_insert_dedupe_key")
        ),
        "final_apply_target": contract.get("final_apply_target"),
        "future_confirmed_insert_behavior": "duplicate_blocks_no_overwrite_no_upsert_no_silent_success",
        "future_insert_refuses_if": [
            "apply_contract_blocked",
            "dedupe_mismatch",
            "post_apply_execution_no_longer_accepted",
            "parent_chain_changed",
            "source_digest_drift",
            "route_changed_unexpectedly",
            "duplicate_post_apply_execution_apply_dedupe_key",
            "final_apply_target_changed_unexpectedly",
        ],
    }
    return {
        "ok": True,
        "plan_status": "ready" if not blockers else "blocked",
        "post_apply_execution_id": post_apply_execution_id,
        "target_table": target_table,
        "table_exists": table_exists,
        "schema_preview": schema_preview,
        "indexes_preview": indexes_preview,
        "constraints_preview": constraints_preview,
        "dedupe_constraints": dedupe_constraints,
        "migration_required": bool(not table_exists),
        "confirm_required": "CREATE_TOKEN_MARKET_POST_APPLY_EXECUTION_APPLY_QUEUE",
        "source_policy": (
            "admin-only read-only token market post-apply execution apply queue schema plan; no DDL, no DB writes, "
            "no providers, no scraping, no CEX label creation, no DEX router evidence insert, no venue mappings, "
            "no trades, no client opt-ins, no swaps, no wallet rows and no Alpha Lab or client signal changes"
        ),
        "would_create_table": False,
        "would_write": False,
        "would_execute_trade": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "blockers": list(dict.fromkeys(blockers)),
    }


