        "CREATE INDEX IF NOT EXISTS idx_cex_label_candidate_review_queue_final_handoff_target ON cex_label_candidate_review_queue(final_handoff_target_id)",
        "CREATE INDEX IF NOT EXISTS idx_cex_label_candidate_review_queue_final_handoff ON cex_label_candidate_review_queue(final_handoff_id)",
