        "CREATE INDEX IF NOT EXISTS idx_cex_label_candidate_review_queue_final_apply ON cex_label_candidate_review_queue(final_apply_id)",
        "CREATE INDEX IF NOT EXISTS idx_cex_label_candidate_review_queue_apply ON cex_label_candidate_review_queue(post_apply_execution_apply_id)",
        "CREATE INDEX IF NOT EXISTS idx_cex_label_candidate_review_queue_execution ON cex_label_candidate_review_queue(post_apply_execution_id)",
        "CREATE INDEX IF NOT EXISTS idx_cex_label_candidate_review_queue_insert ON cex_label_candidate_review_queue(post_apply_insert_id)",
