def create_unknown_dex_paircreated_evidence(
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Confirmed DDL-only creation of the PairCreated evidence table."""
    target_table = "dex_paircreated_evidence"
    plan = get_unknown_dex_paircreated_evidence_persistence_schema_plan(
        dry_run=True,
        allow_external=False,
    )
    blockers: list[str] = []
    if not dry_run and confirm != "CREATE_DEX_PAIRCREATED_EVIDENCE":
        blockers.append("confirm_CREATE_DEX_PAIRCREATED_EVIDENCE_required")

    expected_columns = [
        "id",
        "chain",
        "source_type",
        "source_label",
        "source_url",
        "source_tier",
        "official_venue",
        "factory_address",
        "pair_address",
        "token0",
        "token0_symbol",
        "token1",
        "token1_symbol",
        "tx_hash",
        "log_index",
        "block_number",
        "block_hash",
        "event_timestamp",
        "paircreated_event_topic",
        "paircreated_dedupe_key",
        "evidence_payload_digest",
        "raw_payload_json",
        "status",
        "created_at",
        "source_policy",
    ]
    index_sql = [
        "CREATE UNIQUE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_dedupe ON dex_paircreated_evidence(paircreated_dedupe_key)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_chain_factory ON dex_paircreated_evidence(chain, factory_address)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_chain_pair ON dex_paircreated_evidence(chain, pair_address)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_tx_log ON dex_paircreated_evidence(tx_hash, log_index)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_block ON dex_paircreated_evidence(block_number)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_token0 ON dex_paircreated_evidence(token0)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_token1 ON dex_paircreated_evidence(token1)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_status ON dex_paircreated_evidence(status)",
        "CREATE INDEX IF NOT EXISTS idx_dex_paircreated_evidence_source_type ON dex_paircreated_evidence(source_type)",
    ]
    table_exists = bool(plan.get("table_exists"))
    migration_required = not table_exists
    if table_exists:
        conn = _get_db()
        try:
            existing_columns = {row[1] for row in conn.execute(f"PRAGMA table_info({target_table})").fetchall()}
        finally:
            conn.close()
        if any(column not in existing_columns for column in expected_columns):
            blockers.append("schema_drift_detected")

    if dry_run or blockers:
        return {
            "ok": not blockers,
            "dry_run": bool(dry_run),
            "create_status": "ready_but_disabled" if not blockers else "blocked",
            "target_table": target_table,
            "table_exists": table_exists,
            "migration_required": migration_required,
            "confirm_required": "CREATE_DEX_PAIRCREATED_EVIDENCE",
            "would_create_table": bool(migration_required and not blockers),
            "table_created": False,
            "indexes_created": [],
            "rows_inserted": 0,
            "row_count": 0,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_cex_label": False,
            "would_execute_trade": False,
            "would_create_wallet_order": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "blockers": list(dict.fromkeys(blockers)),
            "source_policy": (
                "admin-only dry-run PairCreated evidence DDL preview; no evidence rows, no mappings, no router "
                "evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
            ),
        }

    conn = _get_db()
    try:
        before_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                (target_table,),
            ).fetchone()
        )
        before_indexes = {
            row[0]
            for row in conn.execute(
                "SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = ?",
                (target_table,),
            ).fetchall()
            if not str(row[0]).startswith("sqlite_autoindex_")
        }
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS dex_paircreated_evidence (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                chain TEXT NOT NULL,
                source_type TEXT NOT NULL,
                source_label TEXT NOT NULL,
                source_url TEXT NOT NULL,
                source_tier TEXT NOT NULL,
                official_venue TEXT,
                factory_address TEXT NOT NULL,
                pair_address TEXT NOT NULL,
                token0 TEXT NOT NULL,
                token0_symbol TEXT,
                token1 TEXT NOT NULL,
                token1_symbol TEXT,
                tx_hash TEXT NOT NULL,
                log_index INTEGER NOT NULL,
                block_number INTEGER NOT NULL,
                block_hash TEXT,
                event_timestamp INTEGER,
                paircreated_event_topic TEXT NOT NULL,
                paircreated_dedupe_key TEXT NOT NULL UNIQUE,
                evidence_payload_digest TEXT NOT NULL,
                raw_payload_json TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending_admin_review',
                created_at TEXT NOT NULL,
                source_policy TEXT NOT NULL
            )
            """
        )
        for sql in index_sql:
            conn.execute(sql)
        conn.commit()
        after_exists = bool(
            conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
                (target_table,),
            ).fetchone()
        )
        after_indexes = {
            row[0]
            for row in conn.execute(
                "SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = ?",
                (target_table,),
            ).fetchall()
            if not str(row[0]).startswith("sqlite_autoindex_")
        }
        row_count = int(conn.execute(f"SELECT COUNT(*) FROM {target_table}").fetchone()[0] or 0)
    finally:
        conn.close()

    created_indexes = sorted(after_indexes - before_indexes)
    table_created = after_exists and not before_exists
    return {
        "ok": True,
        "dry_run": False,
        "create_status": "created" if table_created else "already_exists",
        "target_table": target_table,
        "table_exists": after_exists,
        "migration_required": False,
        "confirm_required": "CREATE_DEX_PAIRCREATED_EVIDENCE",
        "would_create_table": False,
        "table_created": table_created,
        "indexes_created": created_indexes,
        "rows_inserted": 0,
        "row_count": row_count,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": (1 if table_created else 0) + len(created_indexes),
        "blockers": [],
        "source_policy": (
            "admin-confirmed DDL-only PairCreated evidence migration; created table/indexes if absent, "
            f"inserted zero rows and current row_count={row_count}; no evidence persisted, no mappings, "
            "no router evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
        ),
    }


def insert_unknown_dex_paircreated_evidence(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    allow_rpc_preflight: bool = True,
    max_indexer_calls: int = 4,
    timeout: int = 6,
    expected_paircreated_dedupe_key: str | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
    allow_external: bool = False,
    source_confirm: str | None = None,
) -> dict[str, Any]:
    """Dry-run-first insert of one evidence-only PairCreated row."""
    target_table = "dex_paircreated_evidence"
    plan = get_unknown_dex_paircreated_evidence_persistence_schema_plan(
        chain=chain,
        factory_address=factory_address,
        block_window=block_window,
        limit=limit,
        tx_transfer_limit=tx_transfer_limit,
        max_pools=max_pools,
        lookback_blocks=lookback_blocks,
        allow_rpc_preflight=allow_rpc_preflight,
        max_indexer_calls=max_indexer_calls,
        timeout=timeout,
        dry_run=True,
        allow_external=allow_external,
        confirm=source_confirm,
    )
    blockers: list[str] = []
    if plan.get("plan_status") != "ready_read_only":
        blockers.append("paircreated_evidence_schema_plan_not_ready")

    eligible_rows = list(plan.get("eligible_rows") or [])
    clean_expected_key = str(expected_paircreated_dedupe_key or "").strip()
    if not dry_run and not clean_expected_key:
        blockers.append("expected_paircreated_dedupe_key_required")

    selected_row: dict[str, Any] | None = None
    if clean_expected_key:
        selected_row = next(
            (row for row in eligible_rows if row.get("paircreated_dedupe_key") == clean_expected_key),
            None,
        )
        if eligible_rows and selected_row is None:
            blockers.append("expected_paircreated_dedupe_key_mismatch")
    elif len(eligible_rows) == 1:
        selected_row = eligible_rows[0]
    elif len(eligible_rows) > 1:
        blockers.append("expected_paircreated_dedupe_key_required_for_multiple_candidates")

    if selected_row is None:
        blockers.append("paircreated_evidence_candidate_missing")

    conn = _get_db()
    try:
        table_ready = _table_exists(conn, target_table)
        existing_row = None
        if table_ready and selected_row:
            existing_row = conn.execute(
                "SELECT id FROM dex_paircreated_evidence WHERE paircreated_dedupe_key = ? LIMIT 1",
                (selected_row.get("paircreated_dedupe_key"),),
            ).fetchone()
        row_count = (
            int(conn.execute("SELECT COUNT(*) FROM dex_paircreated_evidence").fetchone()[0] or 0)
            if table_ready else 0
        )
    finally:
        conn.close()

    if not table_ready:
        blockers.append("dex_paircreated_evidence_table_missing")
    dedupe_status = "duplicate" if existing_row else "new"
    if existing_row:
        blockers.append("duplicate_paircreated_evidence")
    if not dry_run and confirm != "INSERT_DEX_PAIRCREATED_EVIDENCE":
        blockers.append("confirm_INSERT_DEX_PAIRCREATED_EVIDENCE_required")

    would_insert = bool(table_ready and selected_row and not blockers)
    if dry_run or blockers:
        return {
            "ok": not blockers,
            "dry_run": bool(dry_run),
            "insert_status": "ready_for_insert" if would_insert else "blocked",
            "target_table": target_table,
            "table_exists": table_ready,
            "paircreated_evidence_id": None,
            "pair_address": selected_row.get("pair_address") if selected_row else None,
            "factory_address": selected_row.get("factory_address") if selected_row else None,
            "tx_hash": selected_row.get("tx_hash") if selected_row else None,
            "log_index": selected_row.get("log_index") if selected_row else None,
            "block_number": selected_row.get("block_number") if selected_row else None,
            "paircreated_dedupe_key": selected_row.get("paircreated_dedupe_key") if selected_row else clean_expected_key or None,
            "expected_paircreated_dedupe_key": clean_expected_key or None,
            "dedupe_status": dedupe_status,
            "would_insert": would_insert,
            "inserted": False,
            "row_count": row_count,
            "rows_inserted": 0,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_cex_label": False,
            "would_execute_trade": False,
            "would_create_wallet_order": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
            "source_backed_scoring": False,
            "mapping_ready_now": 0,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "blockers": list(dict.fromkeys(blockers)),
            "source_plan": plan,
            "source_policy": (
                "admin-only dry-run PairCreated evidence insert preview; no evidence row is persisted in dry-run, "
                "no mappings, no router evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
            ),
        }

    row = dict(selected_row or {})
    raw_payload_json = json.dumps(
        row.get("raw_payload_preview_not_persisted") or {},
        sort_keys=True,
        default=str,
    )
    created_at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    conn = _get_db()
    try:
        cursor = conn.execute(
            """
            INSERT INTO dex_paircreated_evidence (
                chain, source_type, source_label, source_url, source_tier, official_venue,
                factory_address, pair_address, token0, token0_symbol, token1, token1_symbol,
                tx_hash, log_index, block_number, block_hash, event_timestamp,
                paircreated_event_topic, paircreated_dedupe_key, evidence_payload_digest,
                raw_payload_json, status, created_at, source_policy
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                row.get("chain"),
                row.get("source_type"),
                row.get("source_label"),
                row.get("source_url"),
                row.get("source_tier"),
                row.get("official_venue"),
                row.get("factory_address"),
                row.get("pair_address"),
                row.get("token0"),
                row.get("token0_symbol"),
                row.get("token1"),
                row.get("token1_symbol"),
                row.get("tx_hash"),
                row.get("log_index"),
                row.get("block_number"),
                row.get("block_hash"),
                row.get("event_timestamp"),
                row.get("paircreated_event_topic"),
                row.get("paircreated_dedupe_key"),
                row.get("evidence_payload_digest"),
                raw_payload_json,
                "pending_admin_review",
                created_at,
                (
                    "admin-confirmed PairCreated evidence-only row; not a DEX mapping, not source-backed scoring, "
                    "not a client signal and not a trade trigger"
                ),
            ),
        )
        conn.commit()
        evidence_id = int(cursor.lastrowid)
        row_count_after = int(conn.execute("SELECT COUNT(*) FROM dex_paircreated_evidence").fetchone()[0] or 0)
    finally:
        conn.close()

    return {
        "ok": True,
        "dry_run": False,
        "insert_status": "inserted",
        "target_table": target_table,
        "table_exists": True,
        "paircreated_evidence_id": evidence_id,
        "pair_address": row.get("pair_address"),
        "factory_address": row.get("factory_address"),
        "tx_hash": row.get("tx_hash"),
        "log_index": row.get("log_index"),
        "block_number": row.get("block_number"),
        "paircreated_dedupe_key": row.get("paircreated_dedupe_key"),
        "expected_paircreated_dedupe_key": clean_expected_key,
        "dedupe_status": "inserted",
        "would_insert": False,
        "inserted": True,
        "row_count": row_count_after,
        "rows_inserted": 1,
        "would_persist_paircreated_evidence": False,
        "persisted_paircreated_evidence": True,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 1,
        "blockers": [],
        "source_policy": (
            "admin-confirmed PairCreated evidence-only insert; wrote one evidence row, no mappings, no router "
            "evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
        ),
    }


def _unknown_dex_paircreated_evidence_review_row(row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
    evidence = dict(row)
    blockers: list[str] = []
    chain = str(evidence.get("chain") or "").strip().lower()
    factory = str(evidence.get("factory_address") or "").strip().lower()
    pair = str(evidence.get("pair_address") or "").strip().lower()
    tx_hash = str(evidence.get("tx_hash") or "").strip().lower()
    log_index = evidence.get("log_index")
    current_dedupe = f"{chain}|{factory}|{tx_hash}|{log_index}|{pair}" if all([chain, factory, tx_hash, pair]) and log_index is not None else None
    stored_dedupe = str(evidence.get("paircreated_dedupe_key") or "").strip()
    dedupe_bound = bool(current_dedupe and stored_dedupe == current_dedupe)

    raw_payload = None
    payload_json_valid = False
    payload_digest_bound = False
    current_digest = None
    try:
        raw_payload = json.loads(evidence.get("raw_payload_json") or "")
        payload_json_valid = isinstance(raw_payload, dict)
    except (TypeError, json.JSONDecodeError):
        raw_payload = None
    if payload_json_valid:
        current_digest = hashlib.sha256(
            json.dumps(raw_payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
        ).hexdigest()
        payload_digest_bound = bool(
            evidence.get("evidence_payload_digest") and evidence.get("evidence_payload_digest") == current_digest
        )

    official_venue = str(evidence.get("official_venue") or "").strip()
    venue_rules = OFFICIAL_VENUE_SOURCE_RULES.get(official_venue) or {}
    official_factory_addresses = {
        str(addr).lower()
        for addr in ((venue_rules.get("official_factory_addresses") or {}).get(chain) or [])
    }
    official_factory_bound = bool(factory and factory in official_factory_addresses)
    topic_bound = str(evidence.get("paircreated_event_topic") or "").strip().lower() == PAIR_CREATED_TOPIC

    required_fields = [
        "chain",
        "source_type",
        "source_label",
        "source_url",
        "source_tier",
        "factory_address",
        "pair_address",
        "token0",
        "token1",
        "tx_hash",
        "log_index",
        "block_number",
        "paircreated_event_topic",
        "paircreated_dedupe_key",
        "evidence_payload_digest",
        "raw_payload_json",
        "status",
    ]
    for field in required_fields:
        if evidence.get(field) in (None, ""):
            blockers.append(f"{field}_required")
    if evidence.get("status") != "pending_admin_review":
        blockers.append("paircreated_evidence_not_pending_admin_review")
    if evidence.get("source_type") != "sqd_portal_stream_api":
        blockers.append("source_type_not_sqd_portal_stream_api")
    if evidence.get("source_tier") not in {"tier_1", "tier_2", "tier_2_indexer_corroboration"}:
        blockers.append("source_tier_not_evidence_ready")
    if not dedupe_bound:
        blockers.append("paircreated_dedupe_key_not_bound")
    if not payload_json_valid:
        blockers.append("raw_payload_json_invalid")
    if not payload_digest_bound:
        blockers.append("evidence_payload_digest_not_bound")
    if not official_factory_bound:
        blockers.append("official_factory_not_bound")
    if not topic_bound:
        blockers.append("paircreated_event_topic_not_bound")
    if not _valid_evm_address(factory):
        blockers.append("factory_address_invalid")
    if not _valid_evm_address(pair):
        blockers.append("pair_address_invalid")

    readiness = "ready_for_paircreated_evidence_decision_preview" if not blockers else "blocked"
    return {
        "paircreated_evidence_id": evidence.get("id"),
        "chain": chain,
        "source_type": evidence.get("source_type"),
        "source_label": evidence.get("source_label"),
        "source_url": evidence.get("source_url"),
        "source_tier": evidence.get("source_tier"),
        "official_venue": official_venue or None,
        "factory_address": factory or None,
        "pair_address": pair or None,
        "token0": evidence.get("token0"),
        "token0_symbol": evidence.get("token0_symbol"),
        "token1": evidence.get("token1"),
        "token1_symbol": evidence.get("token1_symbol"),
        "tx_hash": tx_hash or None,
        "log_index": log_index,
        "block_number": evidence.get("block_number"),
        "block_hash": evidence.get("block_hash"),
        "event_timestamp": evidence.get("event_timestamp"),
        "paircreated_event_topic": evidence.get("paircreated_event_topic"),
        "paircreated_dedupe_key": stored_dedupe or None,
        "current_paircreated_dedupe_key": current_dedupe,
        "dedupe_bound": dedupe_bound,
        "evidence_payload_digest": evidence.get("evidence_payload_digest"),
        "current_evidence_payload_digest": current_digest,
        "payload_json_valid": payload_json_valid,
        "payload_digest_bound": payload_digest_bound,
        "official_factory_bound": official_factory_bound,
        "paircreated_event_topic_bound": topic_bound,
        "status": evidence.get("status"),
        "review_readiness": readiness,
        "review_blockers": list(dict.fromkeys(blockers)),
        "next_admin_action": (
            "prepare_paircreated_evidence_decision_preview"
            if readiness == "ready_for_paircreated_evidence_decision_preview"
            else "repair_paircreated_evidence_binding_or_keep_research_only"
        ),
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
    }


def get_unknown_dex_paircreated_evidence_review_queue(
    status: str | None = "pending_admin_review",
    pair_address: str | None = None,
    factory_address: str | None = None,
    limit: int = 50,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only review queue for persisted PairCreated evidence rows."""
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    clean_status = str(status or "").strip() or None
    clean_pair = str(pair_address or "").strip().lower() or None
    clean_factory = str(factory_address or "").strip().lower() or None
    safe_limit = max(1, min(int(limit or 50), 100))
    target_table = "dex_paircreated_evidence"
    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        table_ready = _table_exists(conn, target_table)
        rows: list[dict[str, Any]] = []
        if not table_ready:
            blockers.append("dex_paircreated_evidence_table_missing")
        else:
            clauses: list[str] = []
            params: list[Any] = []
            if clean_status and clean_status.lower() != "all":
                clauses.append("status = ?")
                params.append(clean_status)
            if clean_pair:
                clauses.append("LOWER(pair_address) = ?")
                params.append(clean_pair)
            if clean_factory:
                clauses.append("LOWER(factory_address) = ?")
                params.append(clean_factory)
            where_sql = f"WHERE {' AND '.join(clauses)}" if clauses else ""
            db_rows = conn.execute(
                f"""
                SELECT id, chain, source_type, source_label, source_url, source_tier, official_venue,
                       factory_address, pair_address, token0, token0_symbol, token1, token1_symbol,
                       tx_hash, log_index, block_number, block_hash, event_timestamp, paircreated_event_topic,
                       paircreated_dedupe_key, evidence_payload_digest, raw_payload_json, status, created_at,
                       source_policy
                FROM dex_paircreated_evidence
                {where_sql}
                ORDER BY id ASC
                LIMIT ?
                """,
                (*params, safe_limit),
            ).fetchall()
            rows = [_unknown_dex_paircreated_evidence_review_row(row) for row in db_rows]
    finally:
        conn.close()

    summary = {
        "total_paircreated_evidence_rows": len(rows),
        "ready_for_paircreated_evidence_decision_preview": sum(
            1 for row in rows if row.get("review_readiness") == "ready_for_paircreated_evidence_decision_preview"
        ),
        "blocked": sum(1 for row in rows if row.get("review_readiness") == "blocked"),
        "dedupe_bound": sum(1 for row in rows if row.get("dedupe_bound")),
        "payload_digest_bound": sum(1 for row in rows if row.get("payload_digest_bound")),
        "official_factory_bound": sum(1 for row in rows if row.get("official_factory_bound")),
        "paircreated_event_topic_bound": sum(1 for row in rows if row.get("paircreated_event_topic_bound")),
        "known_unmatched_research_only_pools": 3,
        "source_backed_scoring_ready": 0,
        "mapping_ready_now": 0,
        "client_ready_signals": 0,
        "trade_ready": 0,
        "real_write_enabled": False,
    }
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "queue_status": "blocked" if blockers else "ready_read_only",
        "target_table": target_table,
        "summary": summary,
        "rows": rows,
        "filters": {
            "status": clean_status,
            "pair_address": clean_pair,
            "factory_address": clean_factory,
            "limit": safe_limit,
        },
        "blockers": list(dict.fromkeys(blockers)),
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": (
            "admin-only read-only PairCreated evidence review queue; no evidence writes, no status updates, "
            "no mappings, no router evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
        ),
    }


_UNKNOWN_DEX_PAIRCREATED_EVIDENCE_DECISIONS = {
    "accept_for_future_paircreated_evidence",
    "request_repair",
    "reject",
}


def get_unknown_dex_paircreated_evidence_decision_preview(
    paircreated_evidence_id: int | None,
    proposed_decision: str | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only preview of the next decision for a persisted PairCreated evidence row."""
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    clean_decision = str(proposed_decision or "").strip().lower()
    if paircreated_evidence_id is None:
        blockers.append("paircreated_evidence_id_required")
    if clean_decision not in _UNKNOWN_DEX_PAIRCREATED_EVIDENCE_DECISIONS:
        blockers.append("invalid_proposed_decision")

    review = get_unknown_dex_paircreated_evidence_review_queue(status="all", limit=100, dry_run=True)
    evidence_row = None
    if paircreated_evidence_id is not None:
        evidence_row = next(
            (row for row in review.get("rows") or [] if row.get("paircreated_evidence_id") == paircreated_evidence_id),
            None,
        )
        if evidence_row is None:
            blockers.append("paircreated_evidence_missing")

    row_review_blockers = list(evidence_row.get("review_blockers") or []) if evidence_row else []
    future_status = None
    next_step = None
    routing_safety = None
    if clean_decision == "accept_for_future_paircreated_evidence":
        future_status = "accepted_for_future_mapping_review"
        next_step = "paircreated_evidence_status_only_apply_not_mapping"
        routing_safety = "paircreated_evidence_is_not_dex_mapping_or_signal"
        if evidence_row:
            if evidence_row.get("review_readiness") != "ready_for_paircreated_evidence_decision_preview":
                blockers.append("paircreated_evidence_not_ready_for_acceptance")
            if evidence_row.get("status") != "pending_admin_review":
                blockers.append("paircreated_evidence_status_not_pending_admin_review")
            if not evidence_row.get("dedupe_bound"):
                blockers.append("paircreated_evidence_dedupe_not_bound")
            if not evidence_row.get("payload_json_valid"):
                blockers.append("paircreated_evidence_payload_json_invalid")
            if not evidence_row.get("payload_digest_bound"):
                blockers.append("paircreated_evidence_payload_digest_not_bound")
            if not evidence_row.get("official_factory_bound"):
                blockers.append("paircreated_evidence_official_factory_not_bound")
            if not evidence_row.get("paircreated_event_topic_bound"):
                blockers.append("paircreated_evidence_event_topic_not_bound")
            for field in ("factory_address", "pair_address", "tx_hash", "log_index", "block_number"):
                if evidence_row.get(field) in (None, ""):
                    blockers.append(f"paircreated_evidence_{field}_missing")
            blockers.extend(row_review_blockers)
    elif clean_decision == "request_repair":
        future_status = "needs_better_source"
        next_step = "repair_paircreated_evidence_binding_or_collect_stronger_source"
        routing_safety = "no_mapping_until_paircreated_evidence_is_repaired"
    elif clean_decision == "reject":
        future_status = "rejected"
        next_step = "keep_unknown_dex_route_research_only"
        routing_safety = "no_mapping_signal_trade_or_client_action"

    gate_clear = bool(
        evidence_row
        and clean_decision in _UNKNOWN_DEX_PAIRCREATED_EVIDENCE_DECISIONS
        and dry_run
    )
    decision_allowed = bool(gate_clear and not blockers)
    decision_preview = {
        "future_status": future_status,
        "next_step": next_step,
        "routing_safety": routing_safety,
        "review_readiness": evidence_row.get("review_readiness") if evidence_row else None,
        "review_blockers": row_review_blockers,
        "source_type": evidence_row.get("source_type") if evidence_row else None,
        "source_tier": evidence_row.get("source_tier") if evidence_row else None,
        "official_venue": evidence_row.get("official_venue") if evidence_row else None,
        "factory_address": evidence_row.get("factory_address") if evidence_row else None,
        "pair_address": evidence_row.get("pair_address") if evidence_row else None,
        "tx_hash": evidence_row.get("tx_hash") if evidence_row else None,
        "log_index": evidence_row.get("log_index") if evidence_row else None,
        "block_number": evidence_row.get("block_number") if evidence_row else None,
    }
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "preview_status": "ready_but_disabled" if decision_allowed else "blocked",
        "paircreated_evidence_id": paircreated_evidence_id,
        "proposed_decision": clean_decision,
        "decision_allowed": decision_allowed,
        "decision_preview": decision_preview,
        "required_future_confirm": "FUTURE_SEPARATE_CONFIRMED_PAIRCREATED_EVIDENCE_STATUS_ONLY_GOAL_REQUIRED",
        "blockers": list(dict.fromkeys(blockers)),
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_update_paircreated_evidence_status": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": (
            "admin-only read-only PairCreated evidence decision preview; no DB writes, no status updates, "
            "no evidence writes, no mappings, no router evidence, no labels, no trades, no wallet orders, "
            "no client signals and no opt-ins"
        ),
    }


def apply_unknown_dex_paircreated_evidence_decision(
    paircreated_evidence_id: int | None,
    proposed_decision: str | None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Apply a confirmed PairCreated evidence decision as a status-only update."""
    preview = get_unknown_dex_paircreated_evidence_decision_preview(
        paircreated_evidence_id=paircreated_evidence_id,
        proposed_decision=proposed_decision,
        dry_run=True,
    )
    blockers = list(preview.get("blockers") or [])
    clean_decision = str(proposed_decision or "").strip().lower()
    if paircreated_evidence_id is None:
        blockers.append("paircreated_evidence_id_required")
    if clean_decision != "accept_for_future_paircreated_evidence":
        blockers.append("only_accept_for_future_paircreated_evidence_can_be_applied")
    if not dry_run and confirm != "APPLY_DEX_PAIRCREATED_EVIDENCE_DECISION":
        blockers.append("confirm_APPLY_DEX_PAIRCREATED_EVIDENCE_DECISION_required")
    if not preview.get("decision_allowed"):
        blockers.append("paircreated_evidence_decision_preview_not_allowed")

    previous_status = None
    if paircreated_evidence_id is not None:
        conn = _get_db()
        try:
            row = conn.execute(
                "SELECT status FROM dex_paircreated_evidence WHERE id = ? LIMIT 1",
                (paircreated_evidence_id,),
            ).fetchone()
            if row is None:
                blockers.append("paircreated_evidence_missing")
            else:
                previous_status = row[0]
                if previous_status != "pending_admin_review":
                    blockers.append("paircreated_evidence_status_not_pending_admin_review")
        except sqlite3.OperationalError:
            blockers.append("dex_paircreated_evidence_table_missing")
        finally:
            conn.close()

    decision_preview = preview.get("decision_preview") or {}
    new_status = decision_preview.get("future_status")
    if new_status != "accepted_for_future_mapping_review":
        blockers.append("target_status_unknown")

    can_update = not blockers and previous_status == "pending_admin_review" and bool(new_status)
    response_base = {
        "ok": True,
        "dry_run": bool(dry_run),
        "paircreated_evidence_id": paircreated_evidence_id,
        "proposed_decision": clean_decision or None,
        "previous_status": previous_status,
        "new_status": new_status,
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
    }
    if dry_run or blockers:
        return {
            **response_base,
            "apply_status": "ready_but_disabled" if can_update else "blocked",
            "would_update_paircreated_evidence_status": bool(can_update),
            "updated": False,
            "writes_performed": 0,
            "blockers": list(dict.fromkeys(blockers)),
            "source_policy": (
                "admin-only PairCreated evidence status preview; no evidence writes, no mappings, no router "
                "evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
            ),
        }

    conn = _get_db()
    try:
        cur = conn.execute(
            """
            UPDATE dex_paircreated_evidence
            SET status = ?
            WHERE id = ? AND status = 'pending_admin_review'
            """,
            (new_status, paircreated_evidence_id),
        )
        if cur.rowcount != 1:
            conn.rollback()
            return {
                **response_base,
                "dry_run": False,
                "apply_status": "blocked",
                "would_update_paircreated_evidence_status": False,
                "updated": False,
                "writes_performed": 0,
                "blockers": ["paircreated_evidence_status_update_rowcount_not_one"],
                "source_policy": "PairCreated evidence status-only update blocked because rowcount was not exactly one",
            }
        conn.commit()
    finally:
        conn.close()

    return {
        **response_base,
        "dry_run": False,
        "apply_status": "updated",
        "would_update_paircreated_evidence_status": False,
        "updated": True,
        "writes_performed": 1,
        "blockers": [],
        "source_policy": (
            "admin-confirmed PairCreated evidence status-only update; changed only "
            "dex_paircreated_evidence.status, no evidence writes, no DEX mappings, no router evidence, "
            "no labels, no trades, no wallet orders, no client signals and no opt-ins"
        ),
    }


