def create_dex_local_event_reader_checkpoint_raw_tables(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Confirmed DDL-only creation of local DEX event reader checkpoint/raw tables."""
    confirm_token = "CREATE_DEX_LOCAL_EVENT_READER_CHECKPOINT_RAW_TABLES"
    plan = get_dex_local_event_reader_checkpoint_raw_schema_plan(
        chain=chain,
        factory_address=factory_address,
        dry_run=True,
    )
    blockers: list[str] = list(plan.get("blockers") or [])
    if plan.get("plan_status") != "ready_read_only":
        blockers.append("dex_local_event_reader_checkpoint_raw_schema_plan_not_ready")
    if not dry_run and confirm != confirm_token:
        blockers.append("confirm_CREATE_DEX_LOCAL_EVENT_READER_CHECKPOINT_RAW_TABLES_required")

    table_plans = plan.get("table_plans") or {}
    if not table_plans:
        blockers.append("event_reader_table_plans_missing")

    def _column_name(column_sql: str) -> str:
        return str(column_sql).strip().split()[0].strip('"`[]')

    def _index_sql(table_name: str, index_preview: str) -> str:
        preview = str(index_preview).strip()
        if preview.upper().startswith("CREATE "):
            return preview
        unique_prefix = "UNIQUE INDEX "
        index_prefix = "INDEX "
        if preview.startswith(unique_prefix):
            index_kind = "UNIQUE INDEX"
            rest = preview[len(unique_prefix):]
        elif preview.startswith(index_prefix):
            index_kind = "INDEX"
            rest = preview[len(index_prefix):]
        else:
            raise ValueError(f"unsupported_index_preview:{preview}")
        name, columns = rest.split(" ON ", 1)
        columns = columns.strip()
        if not columns.startswith("("):
            columns = f"({columns})"
        return f"CREATE {index_kind} IF NOT EXISTS {name.strip()} ON {table_name}{columns}"

    conn = _get_db()
    try:
        table_inventory: dict[str, dict[str, Any]] = {}
        for table_name, spec in table_plans.items():
            table_exists = _table_exists(conn, table_name)
            expected_columns = [_column_name(column) for column in spec.get("schema_preview") or []]
            row_count = 0
            existing_columns: set[str] = set()
            if table_exists:
                existing_columns = {row[1] for row in conn.execute(f"PRAGMA table_info({table_name})").fetchall()}
                row_count = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0)
                missing_columns = [column for column in expected_columns if column not in existing_columns]
                if missing_columns:
                    blockers.append(f"{table_name}_schema_drift_detected")
            table_inventory[table_name] = {
                "table_exists": table_exists,
                "migration_required": not table_exists,
                "row_count": row_count,
                "expected_columns": expected_columns,
                "existing_columns_count": len(existing_columns),
            }
    finally:
        conn.close()

    blockers = list(dict.fromkeys(blockers))
    migration_required = any(item.get("migration_required") for item in table_inventory.values())
    confirm_required = confirm_token if migration_required else None

    if dry_run or blockers:
        return {
            "ok": not blockers,
            "dry_run": bool(dry_run),
            "create_status": "ready_but_disabled" if not blockers else "blocked",
            "chain": plan.get("chain"),
            "venue_family": plan.get("venue_family"),
            "factory_scope": plan.get("factory_scope"),
            "target_tables": list(table_plans),
            "table_inventory": table_inventory,
            "table_count": len(table_plans),
            "tables_existing_now": sum(1 for item in table_inventory.values() if item.get("table_exists")),
            "migrations_required": sum(1 for item in table_inventory.values() if item.get("migration_required")),
            "migration_required": migration_required,
            "confirm_required": confirm_token,
            "would_create_table": bool(migration_required and not blockers),
            "tables_created": [],
            "indexes_created": [],
            "rows_inserted": 0,
            "row_counts": {table: item.get("row_count", 0) for table, item in table_inventory.items()},
            "source_backed_scoring": False,
            "mapping_ready_now": 0,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_insert_raw_event": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_cex_label": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_wallet_order": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "blockers": blockers,
            "source_policy": (
                "admin-only dry-run DEX local event reader checkpoint/raw DDL preview; no RPC calls, "
                "no raw events, no PairCreated evidence persistence, no mappings, no router evidence, "
                "no labels, no client signals, no trades, no wallet orders and no opt-ins"
            ),
        }

    conn = _get_db()
    try:
        before_exists = {table_name: _table_exists(conn, table_name) for table_name in table_plans}
        before_indexes: dict[str, set[str]] = {}
        for table_name in table_plans:
            before_indexes[table_name] = {
                row[0]
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = ?",
                    (table_name,),
                ).fetchall()
                if not str(row[0]).startswith("sqlite_autoindex_")
            }
        for table_name, spec in table_plans.items():
            columns_sql = ",\n                ".join(spec.get("schema_preview") or [])
            conn.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {table_name} (
                    {columns_sql}
                )
                """
            )
            for index_preview in spec.get("indexes_preview") or []:
                conn.execute(_index_sql(table_name, index_preview))
        conn.commit()
        after_exists = {table_name: _table_exists(conn, table_name) for table_name in table_plans}
        indexes_created: list[str] = []
        row_counts: dict[str, int] = {}
        for table_name in table_plans:
            after_indexes = {
                row[0]
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = ?",
                    (table_name,),
                ).fetchall()
                if not str(row[0]).startswith("sqlite_autoindex_")
            }
            indexes_created.extend(sorted(after_indexes - before_indexes.get(table_name, set())))
            row_counts[table_name] = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0)
    finally:
        conn.close()

    tables_created = sorted(table for table, exists_before in before_exists.items() if after_exists.get(table) and not exists_before)
    return {
        "ok": True,
        "dry_run": False,
        "create_status": "created" if tables_created else "already_exists",
        "chain": plan.get("chain"),
        "venue_family": plan.get("venue_family"),
        "factory_scope": plan.get("factory_scope"),
        "target_tables": list(table_plans),
        "table_count": len(table_plans),
        "tables_created": tables_created,
        "indexes_created": sorted(indexes_created),
        "rows_inserted": 0,
        "row_counts": row_counts,
        "migration_required": False,
        "confirm_required": confirm_required,
        "would_create_table": False,
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_insert_raw_event": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": len(tables_created) + len(indexes_created),
        "blockers": [],
        "source_policy": (
            "admin-confirmed DDL-only DEX local event reader checkpoint/raw migration; created empty "
            "checkpoint/raw/proof package tables and indexes if absent, inserted zero rows, called no RPC/provider, "
            "persisted no evidence, created no mappings/router evidence/labels, emitted no client signals, "
            "executed no trades and created no opt-ins"
        ),
    }


def get_dex_local_event_reader_run_contract(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    dex_mapping_review_id: int | None = None,
    from_block: int | None = None,
    to_block: int | None = None,
    event_names: str | None = None,
    max_block_span: int = 1_000,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only contract for one future bounded local DEX event reader run."""
    requested_chain = _normalize_chain(chain or "bsc")
    clean_factory = str(factory_address or "").strip().lower() or None
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    if clean_factory and not _valid_evm_address(clean_factory):
        blockers.append("factory_address_invalid")

    try:
        safe_max_span = max(1, min(int(max_block_span or 1_000), 5_000))
    except (TypeError, ValueError):
        safe_max_span = 1_000
        blockers.append("max_block_span_invalid")

    event_aliases = {
        "paircreated": "PairCreated",
        "pair_created": "PairCreated",
        "pair-created": "PairCreated",
        "swap": "Swap",
        "transfer": "ERC20 Transfer",
        "erc20_transfer": "ERC20 Transfer",
        "erc20 transfer": "ERC20 Transfer",
    }
    supported_events = {
        "PairCreated": {
            "contract_scope": "factory",
            "topic0": PAIR_CREATED_TOPIC,
            "target_table": "dex_raw_paircreated_events",
            "purpose": "prove official factory pool creation when collected later",
        },
        "Swap": {
            "contract_scope": "pair",
            "topic0": SWAP_TOPIC,
            "target_table": "dex_raw_swap_events",
            "purpose": "capture exact pool flow from the candidate pair when collected later",
        },
        "ERC20 Transfer": {
            "contract_scope": "token",
            "topic0": TRANSFER_TOPIC,
            "target_table": "erc20_transfer_events",
            "purpose": "capture token funding/context edges around the candidate window when collected later",
        },
    }
    if event_names:
        requested_events: list[str] = []
        for raw_event in str(event_names).split(","):
            key = raw_event.strip().lower()
            if not key:
                continue
            canonical = event_aliases.get(key)
            if not canonical:
                blockers.append(f"unsupported_event_{raw_event.strip()}")
                continue
            if canonical not in requested_events:
                requested_events.append(canonical)
    else:
        requested_events = ["PairCreated", "Swap", "ERC20 Transfer"]
    if not requested_events:
        blockers.append("event_names_required")

    plan = get_dex_local_event_reader_checkpoint_raw_schema_plan(
        chain=requested_chain,
        factory_address=clean_factory,
        dry_run=True,
    )
    if plan.get("plan_status") != "ready_read_only":
        blockers.append("dex_local_event_reader_checkpoint_raw_schema_plan_not_ready")

    required_tables = [
        "dex_event_reader_runs",
        "dex_event_reader_checkpoints",
        "dex_raw_paircreated_events",
        "dex_raw_swap_events",
        "dex_raw_sync_events",
        "dex_raw_liquidity_events",
        "erc20_transfer_events",
        "dex_event_proof_packages",
    ]
    table_status: dict[str, dict[str, Any]] = {}
    mapping_context: dict[str, Any] | None = None
    paircreated_context: dict[str, Any] | None = None
    latest_local_block: int | None = None
    duplicate_run = False
    existing_run_id = None

    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        for table_name in required_tables:
            table_exists = _table_exists(conn, table_name)
            row_count = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0) if table_exists else 0
            table_status[table_name] = {
                "exists": table_exists,
                "row_count": row_count,
            }
            if not table_exists:
                blockers.append(f"{table_name}_missing")

        if _table_exists(conn, "dex_mapping_review_queue"):
            if dex_mapping_review_id is not None:
                row = conn.execute(
                    "SELECT * FROM dex_mapping_review_queue WHERE id = ? LIMIT 1",
                    (dex_mapping_review_id,),
                ).fetchone()
            else:
                row = conn.execute(
                    "SELECT * FROM dex_mapping_review_queue ORDER BY id DESC LIMIT 1"
                ).fetchone()
            if row:
                mapping_context = dict(row)
            else:
                blockers.append("dex_mapping_review_row_missing")
        else:
            blockers.append("dex_mapping_review_queue_missing")

        if mapping_context and _table_exists(conn, "dex_paircreated_evidence"):
            evidence_id = mapping_context.get("paircreated_evidence_id")
            row = conn.execute(
                "SELECT * FROM dex_paircreated_evidence WHERE id = ? LIMIT 1",
                (evidence_id,),
            ).fetchone()
            if row:
                paircreated_context = dict(row)
            else:
                blockers.append("paircreated_evidence_missing")

        max_block_sources = [
            ("swaps", "block_number"),
            ("token_transfers", "block_number"),
            ("dex_paircreated_evidence", "block_number"),
            ("dex_mapping_review_queue", "block_number"),
            ("dex_raw_paircreated_events", "block_number"),
            ("dex_raw_swap_events", "block_number"),
            ("dex_raw_sync_events", "block_number"),
            ("dex_raw_liquidity_events", "block_number"),
            ("erc20_transfer_events", "block_number"),
        ]
        for table_name, column_name in max_block_sources:
            if not _table_exists(conn, table_name):
                continue
            columns = {row[1] for row in conn.execute(f"PRAGMA table_info({table_name})").fetchall()}
            if column_name not in columns:
                continue
            if "chain" in columns:
                row = conn.execute(
                    f"SELECT MAX({column_name}) FROM {table_name} WHERE LOWER(chain) = ?",
                    (requested_chain,),
                ).fetchone()
            else:
                row = conn.execute(f"SELECT MAX({column_name}) FROM {table_name}").fetchone()
            candidate = row[0] if row else None
            if candidate is not None:
                latest_local_block = max(int(candidate), latest_local_block or 0)
    finally:
        conn.close()

    if mapping_context:
        mapping_chain = str(mapping_context.get("chain") or "").strip().lower()
        if mapping_chain and mapping_chain != requested_chain:
            blockers.append("mapping_review_chain_mismatch")
        context_factory = str(mapping_context.get("factory_address") or "").strip().lower()
        if clean_factory and context_factory and clean_factory != context_factory:
            blockers.append("factory_address_mismatch_with_mapping_review")
        if not clean_factory:
            clean_factory = context_factory or None
        if mapping_context.get("status") not in {
            "pending_mapping_review",
            "accepted_for_future_mapping_decision",
            "accepted_for_future_mapping",
        }:
            blockers.append("mapping_review_status_not_collectable")
    else:
        context_factory = ""

    pair_address = str((mapping_context or {}).get("pair_address") or "").strip().lower()
    token0 = str((mapping_context or {}).get("token0") or "").strip().lower()
    token1 = str((mapping_context or {}).get("token1") or "").strip().lower()
    source_block = (mapping_context or {}).get("block_number") or (paircreated_context or {}).get("block_number")
    if clean_factory and not _valid_evm_address(clean_factory):
        blockers.append("factory_scope_missing_or_invalid")
    if "Swap" in requested_events and not _valid_evm_address(pair_address):
        blockers.append("pair_scope_missing_for_swap")
    if "ERC20 Transfer" in requested_events:
        if not _valid_evm_address(token0):
            blockers.append("token0_scope_missing_for_transfer")
        if not _valid_evm_address(token1):
            blockers.append("token1_scope_missing_for_transfer")

    parsed_from = None
    parsed_to = None
    block_range_source = "not_resolved"
    if from_block is None and to_block is None:
        try:
            center_block = int(source_block if source_block is not None else latest_local_block)
        except (TypeError, ValueError):
            center_block = None
        if center_block is None:
            blockers.append("block_range_required")
        else:
            half_window = safe_max_span // 2
            parsed_from = max(0, center_block - half_window)
            parsed_to = parsed_from + safe_max_span - 1
            block_range_source = "mapping_paircreated_block_centered_window"
    elif from_block is None or to_block is None:
        blockers.append("from_block_and_to_block_required_together")
        block_range_source = "invalid_partial_input"
    else:
        try:
            parsed_from = int(from_block)
            parsed_to = int(to_block)
            block_range_source = "explicit_admin_input"
        except (TypeError, ValueError):
            blockers.append("block_range_invalid")
            block_range_source = "invalid_admin_input"

    block_span = (parsed_to - parsed_from + 1) if parsed_from is not None and parsed_to is not None else None
    if parsed_from is not None and parsed_from < 0:
        blockers.append("from_block_negative")
    if parsed_from is not None and parsed_to is not None and parsed_from > parsed_to:
        blockers.append("from_block_after_to_block")
    if block_span is not None and block_span > safe_max_span:
        blockers.append("block_span_exceeds_max_block_span")

    contract_addresses: dict[str, list[str]] = {
        "factory": [clean_factory] if clean_factory else [],
        "pair": [pair_address] if _valid_evm_address(pair_address) else [],
        "token": [addr for addr in [token0, token1] if _valid_evm_address(addr)],
    }
    planned_checkpoints: list[dict[str, Any]] = []
    if parsed_from is not None and parsed_to is not None:
        for event_name in requested_events:
            event_spec = supported_events[event_name]
            for contract_address in contract_addresses.get(event_spec["contract_scope"], []):
                checkpoint_raw = "|".join([
                    requested_chain,
                    "local_event_reader",
                    clean_factory or "",
                    event_name,
                    contract_address,
                    str(parsed_from),
                    str(parsed_to),
                ])
                planned_checkpoints.append({
                    "chain": requested_chain,
                    "source_name": "local_rpc_future_bounded_reader",
                    "venue_family": "PancakeSwap V2",
                    "factory_address": clean_factory,
                    "event_name": event_name,
                    "contract_scope": event_spec["contract_scope"],
                    "contract_address": contract_address,
                    "topic0": event_spec["topic0"],
                    "target_table": event_spec["target_table"],
                    "from_block": parsed_from,
                    "to_block": parsed_to,
                    "chunk_size_blocks": min(250, safe_max_span),
                    "checkpoint_dedupe_key": checkpoint_raw,
                    "cursor_digest": hashlib.sha256(checkpoint_raw.encode("utf-8")).hexdigest(),
                    "future_status": "planned",
                    "purpose": event_spec["purpose"],
                })
    if requested_events and not planned_checkpoints and not any("scope_missing" in item for item in blockers):
        blockers.append("no_checkpoint_scope_available")

    event_scope = {
        "chain": requested_chain,
        "venue_family": "PancakeSwap V2",
        "factory_address": clean_factory,
        "dex_mapping_review_id": (mapping_context or {}).get("id"),
        "paircreated_evidence_id": (mapping_context or {}).get("paircreated_evidence_id"),
        "pair_address": pair_address or None,
        "token0": token0 or None,
        "token1": token1 or None,
        "from_block": parsed_from,
        "to_block": parsed_to,
        "event_names": requested_events,
        "checkpoint_count": len(planned_checkpoints),
    }
    event_scope_digest = hashlib.sha256(
        json.dumps(event_scope, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    ).hexdigest()
    run_dedupe_key = (
        f"{requested_chain}|local_event_reader|{clean_factory or 'no_factory'}|"
        f"{parsed_from}|{parsed_to}|{event_scope_digest}"
    )

    conn = _get_db()
    try:
        if _table_exists(conn, "dex_event_reader_runs"):
            row = conn.execute(
                "SELECT id FROM dex_event_reader_runs WHERE run_dedupe_key = ? LIMIT 1",
                (run_dedupe_key,),
            ).fetchone()
            if row:
                duplicate_run = True
                existing_run_id = row[0]
                blockers.append("duplicate_run_dedupe_key")
    finally:
        conn.close()

    blockers = list(dict.fromkeys(blockers))
    ready = bool(dry_run and not blockers)
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "contract_status": "ready_but_disabled" if ready else "blocked",
        "chain": requested_chain,
        "venue_family": "PancakeSwap V2",
        "factory_scope": [clean_factory] if clean_factory else [],
        "dex_mapping_review_id": (mapping_context or {}).get("id"),
        "paircreated_evidence_id": (mapping_context or {}).get("paircreated_evidence_id"),
        "mapping_review_status": (mapping_context or {}).get("status"),
        "paircreated_evidence_status": (paircreated_context or {}).get("status"),
        "from_block": parsed_from,
        "to_block": parsed_to,
        "block_span": block_span,
        "block_range_source": block_range_source,
        "max_block_span": safe_max_span,
        "latest_local_block": latest_local_block,
        "event_names": requested_events,
        "event_scope": event_scope,
        "run_contract": {
            "target_table": "dex_event_reader_runs",
            "run_dedupe_key": run_dedupe_key,
            "event_scope_digest": event_scope_digest,
            "future_status": "planned",
            "future_confirm_required": "FUTURE_SEPARATE_CONFIRMED_EVENT_READER_RUN_INSERT_REQUIRED",
        },
        "run_dedupe_key": run_dedupe_key,
        "run_dedupe_status": "duplicate" if duplicate_run else "new",
        "existing_run_id": existing_run_id,
        "planned_checkpoints": planned_checkpoints,
        "checkpoint_count": len(planned_checkpoints),
        "table_status": table_status,
        "mapping_context": {
            "pair_address": pair_address or None,
            "token0": token0 or None,
            "token1": token1 or None,
            "proof_type": (mapping_context or {}).get("proof_type"),
            "source_type": (mapping_context or {}).get("source_type"),
            "source_tier": (mapping_context or {}).get("source_tier"),
            "mapping_dedupe_key": (mapping_context or {}).get("mapping_dedupe_key"),
        },
        "source_evidence": {
            "source_type": (paircreated_context or {}).get("source_type"),
            "source_url": (paircreated_context or {}).get("source_url"),
            "source_tier": (paircreated_context or {}).get("source_tier"),
            "payload_digest": (paircreated_context or {}).get("evidence_payload_digest"),
            "tx_hash": (paircreated_context or {}).get("tx_hash"),
            "log_index": (paircreated_context or {}).get("log_index"),
            "block_number": (paircreated_context or {}).get("block_number"),
            "paircreated_event_topic": (paircreated_context or {}).get("paircreated_event_topic"),
        },
        "chunk_policy": {
            "max_block_span": safe_max_span,
            "default_chunk_size_blocks": min(250, safe_max_span),
            "no_unbounded_replay": True,
            "shrink_on_provider_limit": True,
            "no_silent_success": True,
        },
        "retry_policy": {
            "max_retries_per_chunk": 2,
            "stop_on_pruned_history_or_missing_trie": True,
            "record_errors_only_in_future_checkpoint_lane": True,
        },
        "digest_policy": {
            "event_scope_digest": "sha256(canonical_event_scope_json)",
            "checkpoint_cursor_digest": "sha256(chain|source|factory|event|contract|from|to)",
            "raw_event_digest": "sha256(canonical_raw_log_json) in a later confirmed collection goal",
            "no_overwrite_no_upsert": True,
        },
        "route_safety": {
            "paircreated_checkpoint_targets_official_factory_only": "PairCreated" in requested_events,
            "swap_checkpoint_targets_bound_pair_only": "Swap" in requested_events,
            "transfer_checkpoint_targets_bound_tokens_only": "ERC20 Transfer" in requested_events,
            "no_mapping_creation": True,
            "no_client_signal_route": True,
            "no_trade_route": True,
            "no_wallet_order_route": True,
        },
        "next_micro_step": "event_reader_run_insert_dry_run_first" if ready else "repair_event_reader_run_contract_blockers",
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_create_event_reader_run": False,
        "would_create_checkpoint": False,
        "would_insert_raw_event": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "blockers": blockers,
        "source_policy": (
            "admin-only read-only DEX local event reader run contract. It plans a bounded future "
            "PairCreated/Swap/ERC20 Transfer collection window from existing local proof/review context only. "
            "It does not call RPC/providers, creates no run/checkpoint/raw rows, persists no evidence, creates "
            "no mapping/router evidence/labels, emits no client signals, executes no trades and creates no opt-ins."
        ),
    }


def insert_dex_local_event_reader_run(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    dex_mapping_review_id: int | None = None,
    from_block: int | None = None,
    to_block: int | None = None,
    event_names: str | None = None,
    max_block_span: int = 1_000,
    expected_run_dedupe_key: str | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Dry-run-first insert of one future DEX event reader run and planned checkpoints."""
    confirm_token = "INSERT_DEX_LOCAL_EVENT_READER_RUN"
    contract = get_dex_local_event_reader_run_contract(
        chain=chain,
        factory_address=factory_address,
        dex_mapping_review_id=dex_mapping_review_id,
        from_block=from_block,
        to_block=to_block,
        event_names=event_names,
        max_block_span=max_block_span,
        dry_run=True,
    )
    blockers: list[str] = list(contract.get("blockers") or [])
    if contract.get("contract_status") != "ready_but_disabled":
        blockers.append("dex_local_event_reader_run_contract_not_ready")

    run_dedupe_key = str(contract.get("run_dedupe_key") or "").strip()
    clean_expected = str(expected_run_dedupe_key or "").strip()
    if not dry_run and not clean_expected:
        blockers.append("expected_run_dedupe_key_required")
    if clean_expected and run_dedupe_key and clean_expected != run_dedupe_key:
        blockers.append("expected_run_dedupe_key_mismatch")
    if not dry_run and confirm != confirm_token:
        blockers.append("confirm_INSERT_DEX_LOCAL_EVENT_READER_RUN_required")

    planned_checkpoints = list(contract.get("planned_checkpoints") or [])
    if not planned_checkpoints:
        blockers.append("planned_checkpoints_missing")

    conn = _get_db()
    try:
        run_table_exists = _table_exists(conn, "dex_event_reader_runs")
        checkpoint_table_exists = _table_exists(conn, "dex_event_reader_checkpoints")
        run_row_count = int(conn.execute("SELECT COUNT(*) FROM dex_event_reader_runs").fetchone()[0] or 0) if run_table_exists else 0
        checkpoint_row_count = (
            int(conn.execute("SELECT COUNT(*) FROM dex_event_reader_checkpoints").fetchone()[0] or 0)
            if checkpoint_table_exists else 0
        )
        existing_run = None
        existing_checkpoint_keys: list[str] = []
        if not run_table_exists:
            blockers.append("dex_event_reader_runs_table_missing")
        elif run_dedupe_key:
            existing_run = conn.execute(
                "SELECT id FROM dex_event_reader_runs WHERE run_dedupe_key = ? LIMIT 1",
                (run_dedupe_key,),
            ).fetchone()
        if not checkpoint_table_exists:
            blockers.append("dex_event_reader_checkpoints_table_missing")
        elif planned_checkpoints:
            for checkpoint in planned_checkpoints:
                checkpoint_key = str(checkpoint.get("checkpoint_dedupe_key") or "").strip()
                if not checkpoint_key:
                    blockers.append("checkpoint_dedupe_key_missing")
                    continue
                row = conn.execute(
                    "SELECT id FROM dex_event_reader_checkpoints WHERE checkpoint_dedupe_key = ? LIMIT 1",
                    (checkpoint_key,),
                ).fetchone()
                if row:
                    existing_checkpoint_keys.append(checkpoint_key)
    finally:
        conn.close()

    if existing_run:
        blockers.append("duplicate_run_dedupe_key")
    if existing_checkpoint_keys:
        blockers.append("duplicate_checkpoint_dedupe_key")

    blockers = list(dict.fromkeys(blockers))
    would_insert = bool(not blockers and run_dedupe_key and planned_checkpoints)
    if dry_run or blockers:
        return {
            "ok": not blockers,
            "dry_run": bool(dry_run),
            "insert_status": "ready_for_insert" if would_insert else "blocked",
            "chain": contract.get("chain"),
            "venue_family": contract.get("venue_family"),
            "dex_mapping_review_id": contract.get("dex_mapping_review_id"),
            "paircreated_evidence_id": contract.get("paircreated_evidence_id"),
            "from_block": contract.get("from_block"),
            "to_block": contract.get("to_block"),
            "block_span": contract.get("block_span"),
            "event_names": contract.get("event_names"),
            "run_dedupe_key": run_dedupe_key or clean_expected or None,
            "expected_run_dedupe_key": clean_expected or None,
            "run_dedupe_status": "duplicate" if existing_run else contract.get("run_dedupe_status"),
            "event_reader_run_id": None,
            "checkpoint_ids": [],
            "checkpoint_count": len(planned_checkpoints),
            "planned_checkpoints": planned_checkpoints,
            "run_row_count": run_row_count,
            "checkpoint_row_count": checkpoint_row_count,
            "would_insert": would_insert,
            "would_create_event_reader_run": would_insert,
            "would_create_checkpoint": bool(would_insert and planned_checkpoints),
            "would_create_checkpoint_count": len(planned_checkpoints) if would_insert else 0,
            "inserted": False,
            "rows_inserted": 0,
            "source_backed_scoring": False,
            "mapping_ready_now": 0,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_insert_raw_event": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_cex_label": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_wallet_order": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "blockers": blockers,
            "source_policy": (
                "admin-only dry-run DEX local event reader run/checkpoint insert preview; no RPC calls, "
                "no raw event inserts, no evidence persistence, no mappings, no router evidence, no labels, "
                "no client signals, no trades, no wallet orders and no opt-ins"
            ),
        }

    created_at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    event_scope_json = json.dumps(contract.get("event_scope") or {}, sort_keys=True, separators=(",", ":"), default=str)
    source_policy = (
        "admin-confirmed DEX local event reader run/checkpoint intent insert; wrote one planned run "
        "and bounded planned checkpoints only. It called no RPC/provider, inserted no raw events, "
        "persisted no PairCreated evidence, created no DEX mappings/router evidence/labels, emitted no "
        "client signals, executed no trades and created no opt-ins"
    )
    conn = _get_db()
    try:
        cursor = conn.execute(
            """
            INSERT INTO dex_event_reader_runs (
                chain, source_name, venue_family, factory_address, event_scope_json,
                run_dedupe_key, status, started_at, finished_at, created_at, source_policy
            )
            VALUES (?, ?, ?, ?, ?, ?, 'planned', NULL, NULL, ?, ?)
            """,
            (
                contract.get("chain"),
                "local_rpc_future_bounded_reader",
                contract.get("venue_family"),
                (contract.get("factory_scope") or [None])[0],
                event_scope_json,
                run_dedupe_key,
                created_at,
                source_policy,
            ),
        )
        event_reader_run_id = int(cursor.lastrowid)
        checkpoint_ids: list[int] = []
        for checkpoint in planned_checkpoints:
            cursor = conn.execute(
                """
                INSERT INTO dex_event_reader_checkpoints (
                    run_id, chain, source_name, venue_family, factory_address, event_name,
                    contract_address, from_block, to_block, last_success_block, last_attempted_block,
                    chunk_size_blocks, retry_count, last_error, checkpoint_dedupe_key, cursor_digest,
                    status, created_at, updated_at, source_policy
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, ?, 0, NULL, ?, ?, 'planned', ?, ?, ?)
                """,
                (
                    event_reader_run_id,
                    checkpoint.get("chain"),
                    checkpoint.get("source_name"),
                    checkpoint.get("venue_family"),
                    checkpoint.get("factory_address"),
                    checkpoint.get("event_name"),
                    checkpoint.get("contract_address"),
                    checkpoint.get("from_block"),
                    checkpoint.get("to_block"),
                    checkpoint.get("chunk_size_blocks"),
                    checkpoint.get("checkpoint_dedupe_key"),
                    checkpoint.get("cursor_digest"),
                    created_at,
                    created_at,
                    source_policy,
                ),
            )
            checkpoint_ids.append(int(cursor.lastrowid))
        conn.commit()
        run_row_count_after = int(conn.execute("SELECT COUNT(*) FROM dex_event_reader_runs").fetchone()[0] or 0)
        checkpoint_row_count_after = int(
            conn.execute("SELECT COUNT(*) FROM dex_event_reader_checkpoints").fetchone()[0] or 0
        )
    finally:
        conn.close()

    return {
        "ok": True,
        "dry_run": False,
        "insert_status": "inserted",
        "chain": contract.get("chain"),
        "venue_family": contract.get("venue_family"),
        "dex_mapping_review_id": contract.get("dex_mapping_review_id"),
        "paircreated_evidence_id": contract.get("paircreated_evidence_id"),
        "from_block": contract.get("from_block"),
        "to_block": contract.get("to_block"),
        "block_span": contract.get("block_span"),
        "event_names": contract.get("event_names"),
        "run_dedupe_key": run_dedupe_key,
        "expected_run_dedupe_key": clean_expected,
        "run_dedupe_status": "inserted",
        "event_reader_run_id": event_reader_run_id,
        "checkpoint_ids": checkpoint_ids,
        "checkpoint_count": len(checkpoint_ids),
        "run_row_count": run_row_count_after,
        "checkpoint_row_count": checkpoint_row_count_after,
        "would_insert": False,
        "would_create_event_reader_run": False,
        "would_create_checkpoint": False,
        "inserted": True,
        "rows_inserted": 1 + len(checkpoint_ids),
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_insert_raw_event": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 1 + len(checkpoint_ids),
        "blockers": [],
        "source_policy": source_policy,
    }


def get_dex_local_event_reader_execution_contract(
    event_reader_run_id: int | None,
    dry_run: bool = True,
    max_rpc_calls: int = 25,
) -> dict[str, Any]:
    """Read-only execution contract for a planned local DEX event reader run."""
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    if event_reader_run_id is None:
        blockers.append("event_reader_run_id_required")
    try:
        safe_max_rpc_calls = max(1, min(int(max_rpc_calls or 25), 100))
    except (TypeError, ValueError):
        safe_max_rpc_calls = 25
        blockers.append("max_rpc_calls_invalid")

    topic_by_event = {
        "PairCreated": PAIR_CREATED_TOPIC,
        "Swap": SWAP_TOPIC,
        "ERC20 Transfer": TRANSFER_TOPIC,
    }
    raw_table_by_event = {
        "PairCreated": "dex_raw_paircreated_events",
        "Swap": "dex_raw_swap_events",
        "ERC20 Transfer": "erc20_transfer_events",
    }

    run: dict[str, Any] | None = None
    checkpoints: list[dict[str, Any]] = []
    raw_counts_by_checkpoint: dict[int, int] = {}
    table_status: dict[str, dict[str, Any]] = {}
    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        required_tables = [
            "dex_event_reader_runs",
            "dex_event_reader_checkpoints",
            "dex_raw_paircreated_events",
            "dex_raw_swap_events",
            "erc20_transfer_events",
            "dex_paircreated_evidence",
            "dex_mapping_review_queue",
        ]
        for table_name in required_tables:
            exists = _table_exists(conn, table_name)
            row_count = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0) if exists else 0
            table_status[table_name] = {"exists": exists, "row_count": row_count}
            if not exists:
                blockers.append(f"{table_name}_missing")

        if event_reader_run_id is not None and _table_exists(conn, "dex_event_reader_runs"):
            row = conn.execute(
                "SELECT * FROM dex_event_reader_runs WHERE id = ? LIMIT 1",
                (event_reader_run_id,),
            ).fetchone()
            if row:
                run = dict(row)
            else:
                blockers.append("event_reader_run_missing")

        if run and _table_exists(conn, "dex_event_reader_checkpoints"):
            rows = conn.execute(
                "SELECT * FROM dex_event_reader_checkpoints WHERE run_id = ? ORDER BY id",
                (event_reader_run_id,),
            ).fetchall()
            checkpoints = [dict(row) for row in rows]
            if not checkpoints:
                blockers.append("event_reader_checkpoints_missing")

        for checkpoint in checkpoints:
            checkpoint_id = int(checkpoint["id"])
            raw_table = raw_table_by_event.get(str(checkpoint.get("event_name") or ""))
            if not raw_table:
                blockers.append(f"unsupported_checkpoint_event_{checkpoint.get('event_name')}")
                raw_counts_by_checkpoint[checkpoint_id] = 0
                continue
            if not _table_exists(conn, raw_table):
                blockers.append(f"{raw_table}_missing")
                raw_counts_by_checkpoint[checkpoint_id] = 0
                continue
            columns = {row[1] for row in conn.execute(f"PRAGMA table_info({raw_table})").fetchall()}
            if "checkpoint_id" in columns:
                count = int(
                    conn.execute(
                        f"SELECT COUNT(*) FROM {raw_table} WHERE checkpoint_id = ?",
                        (checkpoint_id,),
                    ).fetchone()[0]
                    or 0
                )
            else:
                count = 0
            raw_counts_by_checkpoint[checkpoint_id] = count
            if count:
                blockers.append("checkpoint_already_has_raw_events")
    finally:
        conn.close()

    event_scope_json_valid = False
    event_scope: dict[str, Any] = {}
    if run:
        if run.get("status") != "planned":
            blockers.append("event_reader_run_status_not_planned")
        try:
            parsed_scope = json.loads(run.get("event_scope_json") or "{}")
            if isinstance(parsed_scope, dict):
                event_scope = parsed_scope
                event_scope_json_valid = True
        except (TypeError, json.JSONDecodeError):
            event_scope_json_valid = False
        if not event_scope_json_valid:
            blockers.append("event_scope_json_invalid")

    checkpoint_execution_plan: list[dict[str, Any]] = []
    planned_rpc_calls: list[dict[str, Any]] = []
    total_planned_rpc_calls = 0
    def _topic_address(address: str | None) -> str | None:
        normalized = str(address or "").strip().lower()
        if not _valid_evm_address(normalized):
            return None
        return "0x" + ("0" * 24) + normalized[2:]

    for checkpoint in checkpoints:
        event_name = str(checkpoint.get("event_name") or "")
        topic0 = topic_by_event.get(event_name)
        raw_table = raw_table_by_event.get(event_name)
        checkpoint_id = int(checkpoint.get("id") or 0)
        contract_address = str(checkpoint.get("contract_address") or "").strip().lower()
        from_block = int(checkpoint.get("from_block") or 0)
        to_block = int(checkpoint.get("to_block") or 0)
        chunk_size = max(1, min(int(checkpoint.get("chunk_size_blocks") or 250), 1_000))
        checkpoint_blockers: list[str] = []
        if checkpoint.get("status") != "planned":
            checkpoint_blockers.append("checkpoint_status_not_planned")
        if not topic0:
            checkpoint_blockers.append("event_topic_not_bound")
        if not _valid_evm_address(contract_address):
            checkpoint_blockers.append("contract_address_invalid")
        pair_topic = _topic_address(event_scope.get("pair_address"))
        token0_topic = _topic_address(event_scope.get("token0"))
        token1_topic = _topic_address(event_scope.get("token1"))
        topic_sets: list[dict[str, Any]] = [{"topics": [topic0], "filter_role": "event_topic_only"}]
        if event_name == "PairCreated" and token0_topic and token1_topic:
            topic_sets = [{
                "topics": [topic0, token0_topic, token1_topic],
                "filter_role": "paircreated_token0_token1_exact",
            }]
        elif event_name == "ERC20 Transfer" and pair_topic:
            topic_sets = [
                {"topics": [topic0, pair_topic, None], "filter_role": "transfer_from_pair"},
                {"topics": [topic0, None, pair_topic], "filter_role": "transfer_to_pair"},
            ]
        elif event_name == "ERC20 Transfer":
            checkpoint_blockers.append("transfer_pair_topic_missing")
        if from_block > to_block:
            checkpoint_blockers.append("checkpoint_from_block_after_to_block")
        if (to_block - from_block + 1) > 5_000:
            checkpoint_blockers.append("checkpoint_block_span_too_large")
        if raw_counts_by_checkpoint.get(checkpoint_id, 0):
            checkpoint_blockers.append("checkpoint_already_has_raw_events")

        chunks: list[dict[str, Any]] = []
        if not checkpoint_blockers:
            chunk_from = from_block
            while chunk_from <= to_block:
                chunk_to = min(to_block, chunk_from + chunk_size - 1)
                for topic_set in topic_sets:
                    total_planned_rpc_calls += 1
                    call = {
                        "checkpoint_id": checkpoint_id,
                        "event_name": event_name,
                        "method": "eth_getLogs",
                        "address": contract_address,
                        "topics": topic_set["topics"],
                        "filter_role": topic_set["filter_role"],
                        "from_block": chunk_from,
                        "to_block": chunk_to,
                        "from_block_hex": hex(chunk_from),
                        "to_block_hex": hex(chunk_to),
                        "would_call_now": False,
                        "target_raw_table": raw_table,
                    }
                    chunks.append(call)
                    if len(planned_rpc_calls) < safe_max_rpc_calls:
                        planned_rpc_calls.append(call)
                chunk_from = chunk_to + 1

        checkpoint_execution_plan.append({
            "checkpoint_id": checkpoint_id,
            "event_name": event_name,
            "status": checkpoint.get("status"),
            "contract_address": contract_address,
            "topic0": topic0,
            "target_raw_table": raw_table,
            "from_block": from_block,
            "to_block": to_block,
            "chunk_size_blocks": chunk_size,
            "filter_roles": sorted({item["filter_role"] for item in topic_sets}),
            "raw_rows_existing": raw_counts_by_checkpoint.get(checkpoint_id, 0),
            "planned_chunk_count": len(chunks),
            "planned_chunks_preview": chunks[:safe_max_rpc_calls],
            "blockers": checkpoint_blockers,
        })
        blockers.extend(checkpoint_blockers)

    if total_planned_rpc_calls > safe_max_rpc_calls:
        blockers.append("planned_rpc_call_count_exceeds_preview_limit")
    blockers = list(dict.fromkeys(blockers))
    ready = bool(dry_run and not blockers)

    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "execution_contract_status": "ready_but_disabled" if ready else "blocked",
        "event_reader_run_id": event_reader_run_id,
        "run_status": (run or {}).get("status"),
        "chain": (run or {}).get("chain"),
        "source_name": (run or {}).get("source_name"),
        "venue_family": (run or {}).get("venue_family"),
        "factory_address": (run or {}).get("factory_address"),
        "event_scope_json_valid": event_scope_json_valid,
        "event_scope": event_scope,
        "run_dedupe_key": (run or {}).get("run_dedupe_key"),
        "checkpoint_count": len(checkpoints),
        "checkpoint_execution_plan": checkpoint_execution_plan,
        "planned_rpc_calls_preview": planned_rpc_calls,
        "planned_rpc_call_count": total_planned_rpc_calls,
        "max_rpc_calls_preview": safe_max_rpc_calls,
        "table_status": table_status,
        "required_future_confirm": "FUTURE_SEPARATE_CONFIRMED_EVENT_READER_EXECUTION_REQUIRED",
        "execution_policy": {
            "bounded_checkpoints_only": True,
            "no_unplanned_addresses": True,
            "no_unplanned_topics": True,
            "no_status_update_now": True,
            "no_raw_event_insert_now": True,
            "no_mapping_or_signal_or_trade_route": True,
        },
        "next_micro_step": "bounded_execution_dry_run_no_persistence" if ready else "repair_execution_contract_blockers",
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_execute_reader": False,
        "would_update_checkpoint": False,
        "would_insert_raw_event": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "blockers": blockers,
        "source_policy": (
            "admin-only read-only DEX local event reader execution contract. It reads the planned run and "
            "checkpoints, expands bounded future eth_getLogs calls in memory, but calls no RPC/provider, updates "
            "no checkpoint, inserts no raw event, persists no evidence, creates no mappings/router evidence/labels, "
            "emits no client signals, executes no trades and creates no opt-ins."
        ),
    }


def run_dex_local_event_reader_execution_dry_run(
    event_reader_run_id: int | None,
    dry_run: bool = True,
    allow_rpc: bool = False,
    max_rpc_calls: int = 16,
    max_logs_total: int = 2_000,
) -> dict[str, Any]:
    """Bounded no-persistence RPC dry-run for a planned DEX local event-reader run."""
    source_policy = (
        "admin-only bounded DEX local event reader execution dry-run. It can call eth_getLogs only for the "
        "already planned checkpoint chunks, parses logs in memory, and persists nothing. It does not update "
        "checkpoints, insert raw events, persist evidence, create mappings/router evidence/labels, emit client "
        "signals, execute trades, create wallet orders or opt-ins."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_insert_raw_event": False,
        "would_persist_paircreated_evidence": False,
        "would_update_checkpoint": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "execution_dry_run_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "would_call_rpc": False,
            "rpc_calls_performed": 0,
            **common_disabled,
        }
    if event_reader_run_id is None:
        return {
            "ok": True,
            "dry_run": True,
            "execution_dry_run_status": "blocked",
            "error": "event_reader_run_id_required",
            "blockers": ["event_reader_run_id_required"],
            "would_call_rpc": False,
            "rpc_calls_performed": 0,
            **common_disabled,
        }
    try:
        safe_max_rpc_calls = max(1, min(int(max_rpc_calls or 16), 100))
    except (TypeError, ValueError):
        safe_max_rpc_calls = 16
    try:
        safe_max_logs_total = max(1, min(int(max_logs_total or 2_000), 20_000))
    except (TypeError, ValueError):
        safe_max_logs_total = 2_000

    contract = get_dex_local_event_reader_execution_contract(
        event_reader_run_id=event_reader_run_id,
        dry_run=True,
        max_rpc_calls=100,
    )
    contract_blockers = list(contract.get("blockers") or [])
    if contract.get("execution_contract_status") != "ready_but_disabled" or contract_blockers:
        return {
            "ok": True,
            "dry_run": True,
            "execution_dry_run_status": "blocked",
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "contract": contract,
            "blockers": list(dict.fromkeys(["execution_contract_not_ready", *contract_blockers])),
            "would_call_rpc": False,
            "rpc_calls_performed": 0,
            **common_disabled,
        }
    planned_calls = list(contract.get("planned_rpc_calls_preview") or [])
    selected_calls = planned_calls[:safe_max_rpc_calls]
    if not allow_rpc:
        return {
            "ok": True,
            "dry_run": True,
            "execution_dry_run_status": "ready_but_rpc_disabled",
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "planned_rpc_call_count": contract.get("planned_rpc_call_count"),
            "selected_rpc_call_count": len(selected_calls),
            "required_future_allow_rpc": True,
            "blockers": ["allow_rpc_required_for_no_persistence_dry_run"],
            "would_call_rpc": False,
            "rpc_calls_performed": 0,
            "contract_summary": {
                "checkpoint_count": contract.get("checkpoint_count"),
                "run_status": contract.get("run_status"),
                "chain": contract.get("chain"),
                "factory_address": contract.get("factory_address"),
            },
            **common_disabled,
        }

    chain = str(contract.get("chain") or "bsc")
    call_results: list[dict[str, Any]] = []
    event_counts: dict[str, int] = {}
    provider_counts: dict[str, int] = {}
    errors: list[dict[str, Any]] = []
    log_previews: list[dict[str, Any]] = []
    total_logs = 0
    truncated = False

    for call in selected_calls:
        event_name = str(call.get("event_name") or "")
        params = [{
            "address": call.get("address"),
            "fromBlock": call.get("from_block_hex"),
            "toBlock": call.get("to_block_hex"),
            "topics": call.get("topics") or [],
        }]
        try:
            logs: Any = None
            provider: str | None = None
            provider_errors: list[dict[str, Any]] = []
            for url in _evm_rpc_urls(chain):
                provider_label = _rpc_source_label(url)
                try:
                    logs = _rpc_evm(url, "eth_getLogs", params)
                    provider = provider_label
                    break
                except Exception as exc:
                    provider_errors.append({
                        "provider": provider_label,
                        "error": str(exc)[:300],
                    })
            if provider is None:
                raise RuntimeError(json.dumps(provider_errors, sort_keys=True))
            if not isinstance(logs, list):
                logs = []
            provider_counts[provider] = provider_counts.get(provider, 0) + 1
            total_logs += len(logs)
            event_counts[event_name] = event_counts.get(event_name, 0) + len(logs)
            for log in logs:
                if len(log_previews) >= min(25, safe_max_logs_total):
                    break
                if isinstance(log, Mapping):
                    log_previews.append(_dex_event_reader_log_preview(event_name, log))
            call_results.append({
                "checkpoint_id": call.get("checkpoint_id"),
                "event_name": event_name,
                "address": call.get("address"),
                "from_block": call.get("from_block"),
                "to_block": call.get("to_block"),
                "provider": provider,
                "log_count": len(logs),
                "status": "ok",
            })
            if total_logs > safe_max_logs_total:
                truncated = True
                errors.append({
                    "error": "max_logs_total_exceeded",
                    "max_logs_total": safe_max_logs_total,
                    "observed_logs": total_logs,
                })
                break
        except Exception as exc:
            error_row = {
                "checkpoint_id": call.get("checkpoint_id"),
                "event_name": event_name,
                "address": call.get("address"),
                "from_block": call.get("from_block"),
                "to_block": call.get("to_block"),
                "error": str(exc)[:500],
            }
            errors.append(error_row)
            call_results.append({**error_row, "status": "error", "log_count": 0})

    rpc_calls_performed = len(call_results)
    partial = len(selected_calls) < int(contract.get("planned_rpc_call_count") or 0)
    status = "completed_no_persistence"
    if errors:
        status = "completed_with_rpc_errors_no_persistence"
    if partial:
        status = "partial_no_persistence" if not errors else "partial_with_rpc_errors_no_persistence"
    blockers = list(dict.fromkeys([
        *("rpc_errors_observed" for _ in [1] if errors),
        *("execution_truncated_by_max_logs_total" for _ in [1] if truncated),
        *("partial_execution_due_to_max_rpc_calls" for _ in [1] if partial),
    ]))

    return {
        "ok": True,
        "dry_run": True,
        "execution_dry_run_status": status,
        "event_reader_run_id": event_reader_run_id,
        "contract_status": contract.get("execution_contract_status"),
        "chain": chain,
        "run_status": contract.get("run_status"),
        "checkpoint_count": contract.get("checkpoint_count"),
        "planned_rpc_call_count": contract.get("planned_rpc_call_count"),
        "selected_rpc_call_count": len(selected_calls),
        "rpc_calls_performed": rpc_calls_performed,
        "total_logs_seen": total_logs,
        "event_counts": event_counts,
        "provider_counts": provider_counts,
        "call_results": call_results,
        "log_previews": log_previews,
        "truncated": truncated,
        "errors": errors,
        "blockers": blockers,
        "next_safe_step": (
            "event_reader_raw_persistence_schema_or_confirmed_raw_insert_plan"
            if total_logs and not errors else "repair_rpc_or_reduce_chunks_before_persistence"
        ),
        "would_call_rpc": True,
        "would_call_external": False,
        **common_disabled,
    }


def get_unknown_dex_paircreated_archive_indexer_alternative_strategy(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc_preflight: bool = True,
) -> dict[str, Any]:
    """Read-only strategy after public RPC and Blockscout fail historical PairCreated lookup."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only PairCreated archive/indexer alternative strategy. It compares future proof "
        "paths for the existing planned filters only. It does not call external indexers, persist evidence, "
        "create mappings, router evidence, labels, client signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "external_lookup": True,
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "strategy_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "would_call_external": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    plan = get_unknown_dex_paircreated_log_replay_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc_preflight),
    )
    blockscout_base = BLOCKSCOUT_API_BASE_URLS.get(requested_chain)
    scan_base = EXPLORER_ADDRESS_BASE_URLS.get(requested_chain)
    scan_key_present = bool(os.getenv("BSCSCAN_API_KEY") or os.getenv("BSC_SCAN_API_KEY")) if requested_chain == "bsc" else False
    bscscan_v2_key_present = bool(os.getenv("ETHERSCAN_API_KEY") or os.getenv("BSCSCAN_API_KEY") or os.getenv("BSC_SCAN_API_KEY"))

    rows: list[dict[str, Any]] = []
    for plan_row in plan.get("rows") or []:
        if plan_row.get("candidate_status") != "ready_for_future_paircreated_replay":
            continue
        future_filter = dict(plan_row.get("future_eth_get_logs_filter") or {})
        from_block = _hex_to_int_or_none(future_filter.get("fromBlock"))
        to_block = _hex_to_int_or_none(future_filter.get("toBlock"))
        rows.append({
            "chain": requested_chain,
            "candidate_status": "research_only_paircreated_historical_proof_missing",
            "official_venue": plan_row.get("official_venue"),
            "expected_factory_address": plan_row.get("expected_factory_address"),
            "expected_pool_address": plan_row.get("expected_pool_address"),
            "expected_token0": plan_row.get("expected_token0"),
            "expected_token0_symbol": plan_row.get("expected_token0_symbol"),
            "expected_token1": plan_row.get("expected_token1"),
            "expected_token1_symbol": plan_row.get("expected_token1_symbol"),
            "observed_swap_tx_hash": plan_row.get("observed_swap_tx_hash"),
            "observed_swap_block": plan_row.get("observed_swap_block"),
            "planned_paircreated_filter": future_filter,
            "planned_block_range": {
                "from_block": from_block,
                "to_block": to_block,
                "lookback_blocks": safe_lookback,
                "risk": "pool_creation_may_be_before_window; archive/indexer or creation-block discovery needed",
            },
            "proof_distinction": {
                "get_pair_current_state_proof": "useful preflight only; not enough for mapping or scoring",
                "paircreated_historical_event_proof": "required before future evidence persistence and any mapping",
            },
            "missing_for_source_backed_mapping": [
                "historical PairCreated log emitted by official factory",
                "emitted pair equals expected pool",
                "raw log persisted later through separate evidence-only gate",
                "policy gate after persistence before any mapping",
            ],
            "source_backed_scoring_ready": False,
            "mapping_ready_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
        })

    strategy_options = [
        {
            "option_id": "archive_rpc_eth_getLogs",
            "source_type": "archive_rpc",
            "status": "best_technical_path_not_configured_here",
            "requires": ["archive-capable BSC RPC", "bounded eth_getLogs by exact factory/topic/token topics"],
            "proof_expected": "historical PairCreated event emitted by official PancakeSwap V2 factory",
            "why_useful": "directly verifies the missing historical event instead of relying on current getPair state",
            "risks": ["paid or rate-limited provider", "wide historical ranges may still need chunking"],
            "next_step": "configure/test archive source in a separate bounded dry-run; persist nothing",
            "would_call_now": False,
        },
        {
            "option_id": "scan_logs_api_keyed",
            "source_type": "explorer_logs_api",
            "status": "blocked_without_key" if requested_chain == "bsc" and not bscscan_v2_key_present else "candidate_keyed_source",
            "base_url": scan_base,
            "api_key_present": bscscan_v2_key_present,
            "requires": ["API key", "same PairCreated topic/filter", "strict response parsing in memory"],
            "proof_expected": "historical log API result with emitted pair equal to expected pool",
            "risks": ["external dependency", "quota/rate-limit", "must not become final official proof alone"],
            "next_step": "only test under explicit external dry-run confirm if product accepts keyed explorer dependency",
            "would_call_now": False,
        },
        {
            "option_id": "blockscout_public_no_key",
            "source_type": "public_indexer",
            "status": "tested_no_match_or_endpoint_unavailable",
            "base_url": blockscout_base,
            "requires": ["public endpoint support for historical logs"],
            "proof_expected": "PairCreated log in public address/logs or legacy logs surface",
            "observed_result": "recent bounded lookup returned 0 PairCreated logs and HTTP 404 on BSC public per-instance logs endpoints",
            "risks": ["endpoint support differs by chain", "pagination without block/topic filters is weak"],
            "next_step": "do not repeat as primary path unless endpoint availability changes",
            "would_call_now": False,
        },
        {
            "option_id": "local_creation_block_discovery",
            "source_type": "local_rpc_strategy",
            "status": "candidate_strategy_read_only",
            "requires": [
                "derive tighter creation range from pool first local appearance or explorer metadata",
                "then replay exact PairCreated logs with smaller bounded windows",
                "no mapping until log is persisted through a separate evidence gate",
            ],
            "proof_expected": "same PairCreated log, but searched through a much smaller creation window",
            "risks": ["local data may only start after creation", "still needs archive-capable logs if old"],
            "next_step": "create a read-only creation-block range plan for the 4 pools",
            "would_call_now": False,
        },
        {
            "option_id": "fresh_paircreated_forward_collection",
            "source_type": "future_data_collection",
            "status": "useful_for_future_candidates_not_for_current_old_4",
            "requires": ["bounded recent factory log collection", "store raw PairCreated evidence only under separate confirmed goal"],
            "proof_expected": "newer pools with PairCreated captured close to real time",
            "risks": ["does not solve historical proof for current 4 pools"],
            "next_step": "collect recent factory events only in a separate data-quality goal if needed",
            "would_call_now": False,
        },
    ]
    recommended_options = [
        option["option_id"] for option in strategy_options
        if option["option_id"] in {"archive_rpc_eth_getLogs", "local_creation_block_discovery"}
    ]
    strategy_status = (
        "ready_read_only"
        if rows else "blocked_no_paircreated_replay_candidates"
    )
    return {
        "ok": True,
        "dry_run": True,
        "strategy_status": strategy_status,
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "plan_status": plan.get("plan_status"),
        "summary": {
            "paircreated_replay_candidates_reviewed": len(rows),
            "strategy_options_reviewed": len(strategy_options),
            "recommended_options": recommended_options,
            "blockscout_public_path_status": "tested_no_match_or_endpoint_unavailable",
            "archive_rpc_needed": bool(rows),
            "local_creation_block_plan_recommended": bool(rows),
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "proof_state": {
            "get_pair_current_state_proof": "already useful but insufficient",
            "paircreated_historical_event_proof": "missing",
            "blockscout_public_no_key": "tested_no_match_or_endpoint_unavailable",
            "source_backed_scoring": False,
            "mapping_ready_now": False,
        },
        "rows": rows,
        "strategy_options": strategy_options,
        "recommended_next_source": (
            "archive_rpc_or_local_creation_block_range_plan"
            if rows else "rerun PairCreated replay plan after repairing candidate inputs"
        ),
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_paircreated_replay_candidates" for _ in [1] if not rows),
            "paircreated_historical_event_missing",
            "blockscout_public_no_key_not_sufficient",
            *("keyed_explorer_not_configured" for _ in [1] if requested_chain == "bsc" and not bscscan_v2_key_present),
            "paircreated_evidence_not_persisted",
            "source_backed_scoring_remains_false",
            "mapping_ready_now_remains_false",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "DEX PairCreated local creation-block range plan read-only"
            if rows else "rerun PairCreated replay plan after repairing candidate inputs"
        ),
        "would_call_external": False,
        "would_call_rpc": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_paircreated_local_creation_block_range_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    creation_lookback_blocks: int = 250_000,
    max_future_replay_range_blocks: int = 250_000,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc_preflight: bool = True,
) -> dict[str, Any]:
    """Read-only local range plan to narrow future PairCreated historical log replay."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_creation_lookback = max(1_000, min(int(creation_lookback_blocks or 250_000), 2_000_000))
    safe_future_range = max(1_000, min(int(max_future_replay_range_blocks or 250_000), 2_000_000))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only local PairCreated creation-block range plan. It reads existing local swaps, "
        "pair_tokens, token_transfers and token_metadata for the already planned pools. It does not call external "
        "indexers, does not persist evidence, creates no mappings, labels, signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "external_lookup": True,
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "would_call_external": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    plan = get_unknown_dex_paircreated_log_replay_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc_preflight),
    )

    def _pool_swap_stats(conn: sqlite3.Connection, pool: str) -> dict[str, Any]:
        if not _table_exists(conn, "swaps"):
            return {"table_present": False, "rows": 0}
        row = conn.execute(
            """
            SELECT COUNT(*), COUNT(DISTINCT LOWER(tx_hash)), COUNT(DISTINCT LOWER(wallet)),
                   MIN(block_number), MAX(block_number), MIN(timestamp), MAX(timestamp)
            FROM swaps
            WHERE LOWER(chain) = ? AND LOWER(pool) = ?
            """,
            (requested_chain, pool),
        ).fetchone()
        sample = conn.execute(
            """
            SELECT tx_hash, block_number, timestamp, wallet, dex, token_in, token_out, amount_usd
            FROM swaps
            WHERE LOWER(chain) = ? AND LOWER(pool) = ?
            ORDER BY block_number ASC, tx_hash ASC
            LIMIT 3
            """,
            (requested_chain, pool),
        ).fetchall()
        return {
            "table_present": True,
            "rows": int((row or [0])[0] or 0),
            "distinct_transactions": int((row or [0, 0])[1] or 0),
            "distinct_wallets": int((row or [0, 0, 0])[2] or 0),
            "first_block": (row or [None, None, None, None])[3],
            "last_block": (row or [None, None, None, None, None])[4],
            "first_timestamp": (row or [None, None, None, None, None, None])[5],
            "last_timestamp": (row or [None, None, None, None, None, None, None])[6],
            "first_samples": [
                {
                    "tx_hash": item[0],
                    "block_number": item[1],
                    "timestamp": item[2],
                    "wallet": item[3],
                    "dex": item[4],
                    "token_in": item[5],
                    "token_out": item[6],
                    "amount_usd": item[7],
                }
                for item in sample
            ],
        }

    def _pool_transfer_stats(conn: sqlite3.Connection, pool: str, tx_hash: str | None) -> dict[str, Any]:
        if not _table_exists(conn, "token_transfers"):
            return {"table_present": False, "rows": 0}
        row = conn.execute(
            """
            SELECT COUNT(*), COUNT(DISTINCT LOWER(tx_hash)), COUNT(DISTINCT LOWER(token)),
                   MIN(block_number), MAX(block_number), MIN(timestamp), MAX(timestamp)
            FROM token_transfers
            WHERE LOWER(chain) = ? AND (LOWER(from_addr) = ? OR LOWER(to_addr) = ?)
            """,
            (requested_chain, pool, pool),
        ).fetchone()
        same_tx_rows = 0
        if tx_hash:
            same_tx_rows = int(conn.execute(
                """
                SELECT COUNT(*)
                FROM token_transfers
                WHERE LOWER(chain) = ? AND LOWER(tx_hash) = ?
                """,
                (requested_chain, tx_hash),
            ).fetchone()[0] or 0)
        sample = conn.execute(
            """
            SELECT tx_hash, log_index, block_number, timestamp, token, from_addr, to_addr
            FROM token_transfers
            WHERE LOWER(chain) = ? AND (LOWER(from_addr) = ? OR LOWER(to_addr) = ?)
            ORDER BY block_number ASC, log_index ASC
            LIMIT 5
            """,
            (requested_chain, pool, pool),
        ).fetchall()
        return {
            "table_present": True,
            "rows": int((row or [0])[0] or 0),
            "distinct_transactions": int((row or [0, 0])[1] or 0),
            "distinct_tokens": int((row or [0, 0, 0])[2] or 0),
            "first_block": (row or [None, None, None, None])[3],
            "last_block": (row or [None, None, None, None, None])[4],
            "first_timestamp": (row or [None, None, None, None, None, None])[5],
            "last_timestamp": (row or [None, None, None, None, None, None, None])[6],
            "same_tx_transfer_rows": same_tx_rows,
            "first_samples": [
                {
                    "tx_hash": item[0],
                    "log_index": item[1],
                    "block_number": item[2],
                    "timestamp": item[3],
                    "token": item[4],
                    "from_addr": item[5],
                    "to_addr": item[6],
                }
                for item in sample
            ],
        }

    def _pair_tokens_stats(conn: sqlite3.Connection, pool: str) -> dict[str, Any]:
        if not _table_exists(conn, "pair_tokens"):
            return {"table_present": False, "pair_tokens_bound": False}
        row = conn.execute(
            """
            SELECT token0, token1, rpc_source, observed_at
            FROM pair_tokens
            WHERE LOWER(chain) = ? AND LOWER(pool) = ?
            LIMIT 1
            """,
            (requested_chain, pool),
        ).fetchone()
        return {
            "table_present": True,
            "pair_tokens_bound": bool(row),
            "token0": row[0] if row else None,
            "token1": row[1] if row else None,
            "rpc_source": row[2] if row else None,
            "observed_at": row[3] if row else None,
        }

    def _token_metadata_preview(conn: sqlite3.Connection, tokens: Sequence[str | None]) -> list[dict[str, Any]]:
        if not _table_exists(conn, "token_metadata"):
            return []
        out: list[dict[str, Any]] = []
        for token in tokens:
            clean_token = str(token or "").strip().lower()
            if not _valid_evm_address(clean_token):
                continue
            row = conn.execute(
                """
                SELECT symbol, name, decimals, status, rpc_source, observed_at
                FROM token_metadata
                WHERE LOWER(chain) = ? AND LOWER(token_address) = ?
                LIMIT 1
                """,
                (requested_chain, clean_token),
            ).fetchone()
            out.append({
                "token_address": clean_token,
                "metadata_present": bool(row),
                "symbol": row[0] if row else None,
                "name": row[1] if row else None,
                "decimals": row[2] if row else None,
                "status": row[3] if row else None,
                "rpc_source": row[4] if row else None,
                "observed_at": row[5] if row else None,
            })
        return out

    rows: list[dict[str, Any]] = []
    conn = _get_db()
    try:
        for plan_row in plan.get("rows") or []:
            if plan_row.get("candidate_status") != "ready_for_future_paircreated_replay":
                continue
            pool = str(plan_row.get("expected_pool_address") or "").strip().lower()
            tx_hash = str(plan_row.get("observed_swap_tx_hash") or "").strip().lower() or None
            token0 = str(plan_row.get("expected_token0") or "").strip().lower() or None
            token1 = str(plan_row.get("expected_token1") or "").strip().lower() or None
            swap_stats = _pool_swap_stats(conn, pool)
            transfer_stats = _pool_transfer_stats(conn, pool, tx_hash)
            pair_stats = _pair_tokens_stats(conn, pool)
            metadata_preview = _token_metadata_preview(conn, [token0, token1, pair_stats.get("token0"), pair_stats.get("token1")])
            candidate_blocks = [
                int(value) for value in (
                    swap_stats.get("first_block"),
                    transfer_stats.get("first_block"),
                    plan_row.get("observed_swap_block"),
                )
                if value is not None
            ]
            first_local_block = min(candidate_blocks) if candidate_blocks else None
            range_to = first_local_block
            range_from = max(0, range_to - safe_creation_lookback + 1) if range_to is not None else None
            range_width = (range_to - range_from + 1) if range_to is not None and range_from is not None else None
            future_replay_ready = bool(range_width is not None and range_width <= safe_future_range)
            if not first_local_block:
                range_confidence = "blocked_no_local_pool_appearance"
            elif int(transfer_stats.get("rows") or 0) > 0 and int(swap_stats.get("rows") or 0) > 1:
                range_confidence = "medium_local_pool_transfer_and_swap_context"
            elif int(swap_stats.get("rows") or 0) > 0:
                range_confidence = "low_swap_only_creation_may_precede_local_history"
            else:
                range_confidence = "low_local_context_sparse"
            blockers = list(dict.fromkeys([
                *("local_pool_appearance_missing" for _ in [1] if not first_local_block),
                *("local_transfer_pool_context_missing" for _ in [1] if int(transfer_stats.get("rows") or 0) == 0),
                *("pair_tokens_missing" for _ in [1] if not pair_stats.get("pair_tokens_bound")),
                *("future_replay_range_too_wide" for _ in [1] if range_width is not None and range_width > safe_future_range),
                "paircreated_historical_event_missing",
                "paircreated_evidence_not_persisted",
                "source_backed_scoring_remains_false",
                "mapping_ready_now_remains_false",
                "client_signal_disabled",
                "trade_disabled",
            ]))
            rows.append({
                "chain": requested_chain,
                "range_plan_status": "range_candidate_read_only" if first_local_block else "blocked_no_local_range",
                "official_venue": plan_row.get("official_venue"),
                "expected_factory_address": plan_row.get("expected_factory_address"),
                "expected_pool_address": pool or None,
                "expected_token0": token0,
                "expected_token0_symbol": plan_row.get("expected_token0_symbol"),
                "expected_token1": token1,
                "expected_token1_symbol": plan_row.get("expected_token1_symbol"),
                "observed_swap_tx_hash": tx_hash,
                "observed_swap_block": plan_row.get("observed_swap_block"),
                "local_swap_context": swap_stats,
                "local_pool_transfer_context": transfer_stats,
                "local_pair_tokens_context": pair_stats,
                "token_metadata_preview": metadata_preview,
                "first_local_pool_appearance_block": first_local_block,
                "proposed_creation_search_range": {
                    "strategy": "search_backwards_from_first_local_pool_appearance",
                    "from_block": range_from,
                    "to_block": range_to,
                    "range_blocks": range_width,
                    "creation_lookback_blocks": safe_creation_lookback,
                    "max_future_replay_range_blocks": safe_future_range,
                    "range_confidence": range_confidence,
                    "future_replay_range_small_enough": future_replay_ready,
                    "risk": "PairCreated can be older than first local pool appearance; this narrows search but is not proof.",
                },
                "proof_distinction": {
                    "get_pair_current_state_proof": "already useful but insufficient",
                    "local_first_appearance": "narrows a future search window but does not prove pool creation",
                    "paircreated_historical_event_proof": "still required before evidence persistence or mapping",
                },
                "source_backed_scoring_ready": False,
                "mapping_ready_now": False,
                "safe_for_client_signal_now": False,
                "safe_for_trade_now": False,
                "blockers": blockers,
                "next_safe_step": (
                    "future bounded PairCreated replay against this reduced range; still no persistence"
                    if future_replay_ready else "use archive RPC or broader creation-block discovery before replay"
                ),
                "would_replay_paircreated_logs": False,
                "would_persist_paircreated_evidence": False,
                "would_create_mapping": False,
                "would_create_dex_router_evidence": False,
                "would_create_client_signal": False,
                "would_execute_trade": False,
                "would_create_client_opt_in": False,
                "would_write": False,
            })
    finally:
        conn.close()

    narrowed = sum(1 for row in rows if (row.get("proposed_creation_search_range") or {}).get("future_replay_range_small_enough"))
    plan_status = "ready_read_only" if rows else "blocked_no_paircreated_replay_candidates"
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": plan_status,
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "paircreated_plan_status": plan.get("plan_status"),
        "summary": {
            "paircreated_replay_candidates_reviewed": len(rows),
            "local_ranges_proposed": sum(1 for row in rows if row.get("first_local_pool_appearance_block") is not None),
            "future_replay_ranges_small_enough": narrowed,
            "ranges_still_wide_or_sparse": len(rows) - narrowed,
            "rpc_preflight_allowed_for_candidate_selection": bool(allow_rpc_preflight),
            "external_calls_performed": 0,
            "range_rpc_calls_performed": 0,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "rows": rows,
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_paircreated_replay_candidates" for _ in [1] if not rows),
            *("some_ranges_still_wide_or_sparse" for _ in [1] if rows and narrowed < len(rows)),
            "paircreated_historical_event_missing",
            "paircreated_evidence_not_persisted",
            "source_backed_scoring_remains_false",
            "mapping_ready_now_remains_false",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "DEX PairCreated reduced-range replay dry-run read-only"
            if rows and narrowed else "archive RPC or more local history collection before PairCreated replay"
            if rows else "rerun PairCreated replay plan after repairing candidate inputs"
        ),
        "would_call_external": False,
        "would_call_rpc_for_range": False,
        "would_replay_paircreated_logs": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_paircreated_reduced_range_replay_dry_run(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    creation_lookback_blocks: int = 250_000,
    max_future_replay_range_blocks: int = 250_000,
    log_chunk_blocks: int = 50_000,
    max_log_chunks_per_candidate: int = 5,
    max_rpc_calls: int = 32,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc: bool = False,
    allow_rpc_preflight: bool = True,
) -> dict[str, Any]:
    """Replay PairCreated only against local reduced ranges, in memory and read-only."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_creation_lookback = max(1_000, min(int(creation_lookback_blocks or 250_000), 2_000_000))
    safe_future_range = max(1_000, min(int(max_future_replay_range_blocks or 250_000), 2_000_000))
    safe_chunk = max(100, min(int(log_chunk_blocks or 50_000), 250_000))
    safe_chunks = max(1, min(int(max_log_chunks_per_candidate or 5), 100))
    safe_rpc_calls = max(1, min(int(max_rpc_calls or 32), 200))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only reduced-range PairCreated replay dry-run. It consumes the local creation-block range plan, "
        "calls eth_getLogs/eth_call only when allow_rpc=true, parses logs in memory, and never persists evidence, "
        "creates mappings, labels, client signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "replay_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "rpc_calls_performed": 0,
            "eth_get_logs_performed": 0,
            "eth_call_get_pair_performed": 0,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    range_plan = get_unknown_dex_paircreated_local_creation_block_range_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        creation_lookback_blocks=safe_creation_lookback,
        max_future_replay_range_blocks=safe_future_range,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc_preflight=bool(allow_rpc_preflight),
    )

    rows: list[dict[str, Any]] = []
    rpc_calls = 0
    get_logs_calls = 0
    get_pair_calls = 0
    rpc_errors = 0
    skipped_too_wide = 0
    for plan_row in range_plan.get("rows") or []:
        range_plan_data = dict(plan_row.get("proposed_creation_search_range") or {})
        range_from = range_plan_data.get("from_block")
        range_to = range_plan_data.get("to_block")
        range_width = range_plan_data.get("range_blocks")
        try:
            range_from_i = int(range_from) if range_from is not None else None
            range_to_i = int(range_to) if range_to is not None else None
            range_width_i = int(range_width) if range_width is not None else None
        except (TypeError, ValueError):
            range_from_i = range_to_i = range_width_i = None
        range_ready = bool(
            range_from_i is not None
            and range_to_i is not None
            and range_width_i is not None
            and range_from_i <= range_to_i
            and range_width_i <= safe_future_range
        )
        if not range_ready:
            skipped_too_wide += 1
        factory = str(plan_row.get("expected_factory_address") or "").strip().lower()
        pool = str(plan_row.get("expected_pool_address") or "").strip().lower()
        token0 = str(plan_row.get("expected_token0") or "").strip().lower()
        token1 = str(plan_row.get("expected_token1") or "").strip().lower()
        token0_topic = _evm_indexed_address_topic(token0) if _valid_evm_address(token0) else None
        token1_topic = _evm_indexed_address_topic(token1) if _valid_evm_address(token1) else None
        replay_filter = {
            "address": factory or None,
            "topics": [PAIR_CREATED_TOPIC, token0_topic, token1_topic],
            "fromBlock": hex(range_from_i) if range_from_i is not None else None,
            "toBlock": hex(range_to_i) if range_to_i is not None else None,
        }
        get_pair_data = (
            "0xe6a43905" + token0[2:].rjust(64, "0") + token1[2:].rjust(64, "0")
            if _valid_evm_address(token0) and _valid_evm_address(token1) else None
        )
        row_logs: list[dict[str, Any]] = []
        chunk_attempts: list[dict[str, Any]] = []
        row_rpc_errors: list[str] = []
        get_pair_result: dict[str, Any] = {
            "performed": False,
            "provider": None,
            "returned_pair_address": None,
            "matches_expected_pool": False,
            "error": None,
        }
        row_can_replay = bool(
            range_ready
            and _valid_evm_address(factory)
            and _valid_evm_address(pool)
            and _valid_evm_address(token0)
            and _valid_evm_address(token1)
        )
        if allow_rpc and row_can_replay and rpc_calls < safe_rpc_calls and get_pair_data:
            try:
                raw_pair, provider = _rpc_evm_chain(
                    requested_chain,
                    "eth_call",
                    [{"to": factory, "data": get_pair_data}, "latest"],
                )
                rpc_calls += 1
                get_pair_calls += 1
                returned_pair = _address_from_call_result(raw_pair)
                get_pair_result.update({
                    "performed": True,
                    "provider": provider,
                    "returned_pair_address": returned_pair,
                    "matches_expected_pool": bool(returned_pair and returned_pair.lower() == pool),
                })
            except Exception as exc:
                rpc_calls += 1
                get_pair_calls += 1
                rpc_errors += 1
                error = f"getPair:{type(exc).__name__}:{str(exc)[:160]}"
                row_rpc_errors.append(error)
                get_pair_result.update({"performed": True, "error": error})

        current_from = range_from_i
        if allow_rpc and row_can_replay and range_from_i is not None and range_to_i is not None:
            for chunk_index in range(safe_chunks):
                if rpc_calls >= safe_rpc_calls or current_from is None or current_from > range_to_i:
                    break
                chunk_to = min(range_to_i, current_from + safe_chunk - 1)
                chunk_filter = dict(replay_filter)
                chunk_filter["fromBlock"] = hex(current_from)
                chunk_filter["toBlock"] = hex(chunk_to)
                attempt = {
                    "chunk_index": chunk_index,
                    "from_block": current_from,
                    "to_block": chunk_to,
                    "performed": False,
                    "provider": None,
                    "logs_returned": 0,
                    "error": None,
                }
                try:
                    logs, provider = _rpc_evm_chain(requested_chain, "eth_getLogs", [chunk_filter])
                    rpc_calls += 1
                    get_logs_calls += 1
                    attempt.update({
                        "performed": True,
                        "provider": provider,
                        "logs_returned": len(logs or []) if isinstance(logs, list) else 0,
                    })
                    if isinstance(logs, list):
                        for log in logs[:25]:
                            topics = [str(topic or "").strip().lower() for topic in (log.get("topics") or [])]
                            emitted_pair = _decode_paircreated_pair_address(log)
                            row_logs.append({
                                "tx_hash": str(log.get("transactionHash") or "").strip().lower() or None,
                                "block_number": _hex_to_int_or_none(log.get("blockNumber")),
                                "log_index": _hex_to_int_or_none(log.get("logIndex")),
                                "factory_address": str(log.get("address") or "").strip().lower() or None,
                                "topic0": topics[0] if topics else None,
                                "token0_topic": topics[1] if len(topics) > 1 else None,
                                "token1_topic": topics[2] if len(topics) > 2 else None,
                                "emitted_pair_address": emitted_pair,
                                "matches_expected_pool": bool(emitted_pair and emitted_pair.lower() == pool),
                                "matches_expected_factory": str(log.get("address") or "").strip().lower() == factory,
                                "within_reduced_range": True,
                                "raw_log_not_persisted": True,
                            })
                except Exception as exc:
                    rpc_calls += 1
                    get_logs_calls += 1
                    rpc_errors += 1
                    error = f"eth_getLogs:{type(exc).__name__}:{str(exc)[:160]}"
                    row_rpc_errors.append(error)
                    attempt.update({"performed": True, "error": error})
                chunk_attempts.append(attempt)
                current_from = chunk_to + 1

        pool_matches = sum(1 for log in row_logs if log.get("matches_expected_pool"))
        factory_matches = sum(1 for log in row_logs if log.get("matches_expected_factory"))
        replay_result_status = (
            "paircreated_match_found_read_only"
            if pool_matches else "paircreated_logs_found_but_pool_mismatch_read_only"
            if row_logs else "paircreated_rpc_error_no_log_read_only"
            if row_rpc_errors else "reduced_range_not_replayable"
            if not row_can_replay else "no_paircreated_log_found_in_reduced_range"
            if allow_rpc else "blocked_rpc_disabled"
        )
        blockers = list(dict.fromkeys([
            *("rpc_disabled" for _ in [1] if not allow_rpc),
            *("reduced_range_missing_or_too_wide" for _ in [1] if not range_ready),
            *("replay_inputs_missing_or_invalid" for _ in [1] if not row_can_replay),
            *("rpc_errors_observed" for _ in [1] if row_rpc_errors),
            *("paircreated_log_not_found_in_reduced_range" for _ in [1] if allow_rpc and row_can_replay and not row_logs),
            *("paircreated_pool_mismatch" for _ in [1] if row_logs and not pool_matches),
            "paircreated_evidence_not_persisted",
            "source_backed_scoring_remains_false",
            "no_mapping_from_reduced_range_replay_dry_run",
            "client_signal_disabled",
            "trade_disabled",
        ]))
        rows.append({
            "chain": requested_chain,
            "replay_result_status": replay_result_status,
            "official_venue": plan_row.get("official_venue"),
            "expected_factory_address": factory or None,
            "expected_pool_address": pool or None,
            "expected_token0": token0 or None,
            "expected_token0_symbol": plan_row.get("expected_token0_symbol"),
            "expected_token1": token1 or None,
            "expected_token1_symbol": plan_row.get("expected_token1_symbol"),
            "observed_swap_tx_hash": plan_row.get("observed_swap_tx_hash"),
            "observed_swap_block": plan_row.get("observed_swap_block"),
            "first_local_pool_appearance_block": plan_row.get("first_local_pool_appearance_block"),
            "local_range_source": range_plan_data,
            "used_replay_filter": replay_filter,
            "used_from_block": range_from_i,
            "used_to_block": range_to_i,
            "used_range_blocks": range_width_i,
            "range_replayable": row_can_replay,
            "paircreated_event_topic": PAIR_CREATED_TOPIC,
            "chunk_attempts": chunk_attempts,
            "get_pair_preflight": get_pair_result,
            "logs_found": len(row_logs),
            "matching_paircreated_logs": pool_matches,
            "matching_factory_logs": factory_matches,
            "parsed_logs_preview": row_logs,
            "rpc_errors": row_rpc_errors,
            "historical_event_proof_candidate": bool(pool_matches),
            "future_evidence_candidate": bool(pool_matches),
            "source_backed_scoring_ready": False,
            "mapping_ready_now": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "proof_distinction": {
                "get_pair_current_state_proof": "useful preflight only, not historical event proof",
                "reduced_range_replay": "can find PairCreated proof candidate but does not persist it",
                "source_backed_mapping": "requires separate evidence-only persistence and later policy gates",
            },
            "blockers": blockers,
            "next_safe_step": (
                "PairCreated evidence-only persistence schema-plan read-only"
                if pool_matches else "try archive/indexer source or adjust reduced range; still no mapping"
                if row_rpc_errors else "widen reduced range or use archive/indexer source; still no mapping"
                if allow_rpc else "rerun with allow_rpc=true for reduced-range replay"
            ),
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
        })

    matched_rows = sum(1 for row in rows if row.get("matching_paircreated_logs"))
    limit_errors = sum(
        1 for row in rows
        for error in row.get("rpc_errors") or []
        if "limit exceeded" in str(error).lower()
    )
    return {
        "ok": True,
        "dry_run": True,
        "replay_status": (
            "paircreated_matches_found_read_only"
            if matched_rows else "completed_paircreated_rpc_limited_read_only"
            if limit_errors else "completed_paircreated_rpc_errors_read_only"
            if rpc_errors else "completed_no_paircreated_match_in_reduced_range"
            if allow_rpc and rows else "blocked_rpc_disabled"
            if rows else "blocked_no_reduced_range_candidates"
        ),
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "range_plan_status": range_plan.get("plan_status"),
        "summary": {
            "reduced_range_candidates_reviewed": len(rows),
            "reduced_ranges_replayable": sum(1 for row in rows if row.get("range_replayable")),
            "reduced_ranges_skipped": skipped_too_wide,
            "rpc_calls_performed": rpc_calls,
            "rpc_call_budget": safe_rpc_calls,
            "rpc_errors": rpc_errors,
            "rpc_limit_errors": limit_errors,
            "eth_get_logs_performed": get_logs_calls,
            "eth_call_get_pair_performed": get_pair_calls,
            "paircreated_logs_found": sum(int(row.get("logs_found") or 0) for row in rows),
            "paircreated_pool_matches": matched_rows,
            "paircreated_pool_mismatches": sum(
                1 for row in rows if int(row.get("logs_found") or 0) > 0 and not row.get("matching_paircreated_logs")
            ),
            "get_pair_matches": sum(1 for row in rows if (row.get("get_pair_preflight") or {}).get("matches_expected_pool")),
            "future_paircreated_evidence_candidates": matched_rows,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "rows": rows,
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("rpc_disabled" for _ in [1] if rows and not allow_rpc),
            *("no_reduced_range_candidates" for _ in [1] if not rows),
            *("some_reduced_ranges_missing_or_too_wide" for _ in [1] if skipped_too_wide),
            *("rpc_errors_observed" for _ in [1] if rpc_errors),
            *("no_paircreated_match_in_reduced_range" for _ in [1] if allow_rpc and rows and not matched_rows),
            "paircreated_evidence_not_persisted",
            "source_backed_scoring_remains_false",
            "no_mapping_from_reduced_range_replay_dry_run",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "PairCreated evidence-only persistence schema-plan read-only; still no mapping"
            if matched_rows else "use archive/indexer source or adjust reduced ranges for PairCreated proof"
            if limit_errors or rpc_errors else "widen reduced ranges or use archive/indexer source for PairCreated proof"
            if allow_rpc and rows else "rerun with allow_rpc=true for reduced-range replay"
        ),
        "would_get_logs": bool(rows and not allow_rpc),
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_pool_code_existence_creation_block_probe(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    creation_lookback_blocks: int = 250_000,
    max_future_replay_range_blocks: int = 250_000,
    max_binary_search_steps_per_candidate: int = 24,
    max_rpc_calls: int = 64,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc: bool = False,
    allow_rpc_preflight: bool = True,
) -> dict[str, Any]:
    """Probe historical pool code existence to narrow future PairCreated proof searches."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_creation_lookback = max(1_000, min(int(creation_lookback_blocks or 250_000), 2_000_000))
    safe_future_range = max(1_000, min(int(max_future_replay_range_blocks or 250_000), 2_000_000))
    safe_steps = max(1, min(int(max_binary_search_steps_per_candidate or 24), 32))
    safe_rpc_calls = max(0, min(int(max_rpc_calls or 64), 200))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only DEX pool code-existence creation-block probe. It consumes the local reduced "
        "PairCreated range plan and may call eth_getCode only when allow_rpc=true. It never persists code "
        "proof, PairCreated evidence, mappings, labels, client signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "pool_code_proof_persistence": True,
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "probe_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "rpc_calls_performed": 0,
            "eth_get_code_performed": 0,
            "creation_block_candidates_found": 0,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "would_persist_pool_code_proof": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    range_plan = get_unknown_dex_paircreated_local_creation_block_range_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        creation_lookback_blocks=safe_creation_lookback,
        max_future_replay_range_blocks=safe_future_range,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc_preflight=bool(allow_rpc_preflight),
    )

    def _code_present(raw_code: Any) -> bool:
        code = str(raw_code or "").strip().lower()
        if code in {"", "0x", "0x0"}:
            return False
        body = code[2:] if code.startswith("0x") else code
        return bool(body and any(ch != "0" for ch in body))

    rows: list[dict[str, Any]] = []
    rpc_calls = 0
    get_code_calls = 0
    rpc_errors = 0
    skipped_too_wide = 0
    for plan_row in range_plan.get("rows") or []:
        range_plan_data = dict(plan_row.get("proposed_creation_search_range") or {})
        range_from = range_plan_data.get("from_block")
        range_to = range_plan_data.get("to_block")
        range_width = range_plan_data.get("range_blocks")
        try:
            range_from_i = int(range_from) if range_from is not None else None
            range_to_i = int(range_to) if range_to is not None else None
            range_width_i = int(range_width) if range_width is not None else None
        except (TypeError, ValueError):
            range_from_i = range_to_i = range_width_i = None
        range_ready = bool(
            range_from_i is not None
            and range_to_i is not None
            and range_width_i is not None
            and range_from_i <= range_to_i
            and range_width_i <= safe_future_range
        )
        if not range_ready:
            skipped_too_wide += 1
        factory = str(plan_row.get("expected_factory_address") or "").strip().lower()
        pool = str(plan_row.get("expected_pool_address") or "").strip().lower()
        token0 = str(plan_row.get("expected_token0") or "").strip().lower()
        token1 = str(plan_row.get("expected_token1") or "").strip().lower()
        row_can_probe = bool(range_ready and _valid_evm_address(pool))
        initial_probes: list[dict[str, Any]] = []
        binary_search_probes: list[dict[str, Any]] = []
        row_rpc_errors: list[str] = []
        code_present_at_range_from: bool | None = None
        code_present_at_range_to: bool | None = None
        creation_block_candidate: int | None = None
        creation_block_previous_absent: int | None = None
        provider_seen: str | None = None

        def _probe_code(block_number: int, label: str, sink: list[dict[str, Any]]) -> bool | None:
            nonlocal rpc_calls, get_code_calls, rpc_errors, provider_seen
            attempt = {
                "label": label,
                "block_number": block_number,
                "performed": False,
                "provider": None,
                "code_present": None,
                "error": None,
            }
            if rpc_calls >= safe_rpc_calls:
                attempt["error"] = "rpc_call_budget_exhausted"
                sink.append(attempt)
                return None
            try:
                raw_code, provider = _rpc_evm_chain(requested_chain, "eth_getCode", [pool, hex(block_number)])
                rpc_calls += 1
                get_code_calls += 1
                provider_seen = provider_seen or provider
                present = _code_present(raw_code)
                attempt.update({
                    "performed": True,
                    "provider": provider,
                    "code_present": present,
                })
                sink.append(attempt)
                return present
            except Exception as exc:
                rpc_calls += 1
                get_code_calls += 1
                rpc_errors += 1
                error = f"eth_getCode:{type(exc).__name__}:{str(exc)[:160]}"
                row_rpc_errors.append(error)
                attempt.update({"performed": True, "error": error})
                sink.append(attempt)
                return None

        if allow_rpc and row_can_probe and range_from_i is not None and range_to_i is not None:
            code_present_at_range_to = _probe_code(range_to_i, "range_to", initial_probes)
            if code_present_at_range_to is True:
                code_present_at_range_from = _probe_code(range_from_i, "range_from", initial_probes)
                if code_present_at_range_from is False:
                    low = range_from_i + 1
                    high = range_to_i
                    last_absent = range_from_i
                    steps = 0
                    while low <= high and steps < safe_steps and rpc_calls < safe_rpc_calls:
                        mid = (low + high) // 2
                        present = _probe_code(mid, f"binary_step_{steps + 1}", binary_search_probes)
                        steps += 1
                        if present is True:
                            creation_block_candidate = mid
                            high = mid - 1
                        elif present is False:
                            last_absent = mid
                            low = mid + 1
                        else:
                            break
                    if creation_block_candidate is not None:
                        creation_block_previous_absent = last_absent

        if creation_block_candidate is not None:
            probe_result_status = "creation_block_candidate_found_read_only"
        elif code_present_at_range_from is True:
            probe_result_status = "code_already_present_at_range_start_creation_before_range"
        elif code_present_at_range_to is False:
            probe_result_status = "code_absent_at_range_end_pool_not_live_in_range"
        elif row_rpc_errors:
            probe_result_status = "pool_code_probe_rpc_error_read_only"
        elif not row_can_probe:
            probe_result_status = "reduced_range_not_probeable"
        elif not allow_rpc:
            probe_result_status = "blocked_rpc_disabled"
        else:
            probe_result_status = "no_creation_block_candidate_found_read_only"

        tiny_range = None
        if creation_block_candidate is not None:
            tiny_range = {
                "strategy": "single_pool_creation_block_neighborhood_for_future_paircreated_replay",
                "from_block": max(0, creation_block_candidate - 2),
                "to_block": creation_block_candidate + 2,
                "range_blocks": 5,
                "not_executed_now": True,
            }
        blockers = list(dict.fromkeys([
            *("rpc_disabled" for _ in [1] if not allow_rpc),
            *("reduced_range_missing_or_too_wide" for _ in [1] if not range_ready),
            *("pool_address_missing_or_invalid" for _ in [1] if not _valid_evm_address(pool)),
            *("rpc_errors_observed" for _ in [1] if row_rpc_errors),
            *("pool_code_absent_at_range_end" for _ in [1] if code_present_at_range_to is False),
            *("creation_before_reduced_range" for _ in [1] if code_present_at_range_from is True),
            *("creation_block_candidate_not_found" for _ in [1] if allow_rpc and row_can_probe and creation_block_candidate is None),
            "paircreated_event_still_required",
            "pool_code_proof_not_persisted",
            "source_backed_scoring_remains_false",
            "no_mapping_from_code_existence_probe",
            "client_signal_disabled",
            "trade_disabled",
        ]))
        rows.append({
            "chain": requested_chain,
            "probe_result_status": probe_result_status,
            "official_venue": plan_row.get("official_venue"),
            "expected_factory_address": factory or None,
            "expected_pool_address": pool or None,
            "expected_token0": token0 or None,
            "expected_token0_symbol": plan_row.get("expected_token0_symbol"),
            "expected_token1": token1 or None,
            "expected_token1_symbol": plan_row.get("expected_token1_symbol"),
            "observed_swap_tx_hash": plan_row.get("observed_swap_tx_hash"),
            "observed_swap_block": plan_row.get("observed_swap_block"),
            "first_local_pool_appearance_block": plan_row.get("first_local_pool_appearance_block"),
            "local_range_source": range_plan_data,
            "used_from_block": range_from_i,
            "used_to_block": range_to_i,
            "used_range_blocks": range_width_i,
            "range_probeable": row_can_probe,
            "eth_get_code_provider": provider_seen,
            "code_present_at_range_from": code_present_at_range_from,
            "code_present_at_range_to": code_present_at_range_to,
            "initial_code_probes": initial_probes,
            "binary_search_probes": binary_search_probes,
            "creation_block_candidate": creation_block_candidate,
            "creation_block_previous_absent": creation_block_previous_absent,
            "future_paircreated_tiny_replay_range": tiny_range,
            "rpc_errors": row_rpc_errors,
            "historical_code_existence_candidate": bool(creation_block_candidate),
            "historical_event_proof_candidate": False,
            "source_backed_scoring_ready": False,
            "mapping_ready_now": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "proof_distinction": {
                "pool_code_existence": "can narrow likely creation block but is not PairCreated event proof",
                "paircreated_historical_event_proof": "still required before evidence persistence or mapping",
                "source_backed_mapping": "requires separate evidence-only persistence and later policy gates",
            },
            "blockers": blockers,
            "next_safe_step": (
                "future tiny-range PairCreated replay around creation_block_candidate; still no persistence"
                if creation_block_candidate is not None else "use explorer/archive creation proof or broader local history; still no mapping"
                if allow_rpc else "rerun with allow_rpc=true for bounded eth_getCode probe"
            ),
            "would_persist_pool_code_proof": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
        })

    found = sum(1 for row in rows if row.get("creation_block_candidate") is not None)
    return {
        "ok": True,
        "dry_run": True,
        "probe_status": (
            "creation_block_candidates_found_read_only"
            if found else "completed_pool_code_probe_rpc_errors_read_only"
            if rpc_errors else "completed_no_creation_block_candidate_in_range"
            if allow_rpc and rows else "blocked_rpc_disabled"
            if rows else "blocked_no_reduced_range_candidates"
        ),
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "range_plan_status": range_plan.get("plan_status"),
        "summary": {
            "reduced_range_candidates_reviewed": len(rows),
            "reduced_ranges_probeable": sum(1 for row in rows if row.get("range_probeable")),
            "reduced_ranges_skipped": skipped_too_wide,
            "rpc_calls_performed": rpc_calls,
            "rpc_call_budget": safe_rpc_calls,
            "rpc_errors": rpc_errors,
            "eth_get_code_performed": get_code_calls,
            "creation_block_candidates_found": found,
            "future_tiny_paircreated_replay_ranges": sum(
                1 for row in rows if row.get("future_paircreated_tiny_replay_range")
            ),
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "rows": rows,
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("rpc_disabled" for _ in [1] if rows and not allow_rpc),
            *("no_reduced_range_candidates" for _ in [1] if not rows),
            *("some_reduced_ranges_missing_or_too_wide" for _ in [1] if skipped_too_wide),
            *("rpc_errors_observed" for _ in [1] if rpc_errors),
            *("no_creation_block_candidate_found" for _ in [1] if allow_rpc and rows and not found),
            "paircreated_event_still_required",
            "pool_code_proof_not_persisted",
            "source_backed_scoring_remains_false",
            "no_mapping_from_code_existence_probe",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "tiny-range PairCreated replay dry-run around creation block candidates; still no mapping"
            if found else "use explorer/archive creation proof or source-backed indexer; still no mapping"
            if allow_rpc and rows else "rerun with allow_rpc=true for bounded eth_getCode probe"
        ),
        "would_probe_pool_code": bool(rows and not allow_rpc),
        "would_persist_pool_code_proof": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_pool_contract_creation_proof_source_gate(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    creation_lookback_blocks: int = 250_000,
    max_future_replay_range_blocks: int = 250_000,
    timeout: int = 6,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Define acceptable source gates for historical pool creation proof without fetching or persisting it."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_creation_lookback = max(1_000, min(int(creation_lookback_blocks or 250_000), 2_000_000))
    safe_future_range = max(1_000, min(int(max_future_replay_range_blocks or 250_000), 2_000_000))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only DEX pool contract-creation proof source gate. It consumes local reduced "
        "PairCreated/code-existence context and compares acceptable future proof sources, but it performs no "
        "external lookup, persists no evidence, and creates no mappings, labels, client signals, trades, wallet "
        "orders or opt-ins."
    )
    disabled_actions = {
        "external_lookup": True,
        "contract_creation_proof_persistence": True,
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "gate_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "would_call_external": False,
            "would_persist_contract_creation_proof": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    probe = get_unknown_dex_pool_code_existence_creation_block_probe(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        creation_lookback_blocks=safe_creation_lookback,
        max_future_replay_range_blocks=safe_future_range,
        max_binary_search_steps_per_candidate=1,
        max_rpc_calls=0,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=False,
        allow_rpc_preflight=True,
    )

    explorer_keys_configured = {
        "etherscan_v2": bool(os.getenv("ETHERSCAN_API_KEY", "").strip()),
        "bscscan_legacy": bool(os.getenv("BSCSCAN_API_KEY", "").strip() or os.getenv("CORE_BSCSCAN_API_KEY", "").strip()),
    }
    acceptable_sources = [
        {
            "source_id": "archive_rpc_paircreated_or_receipt",
            "source_type": "archive_rpc",
            "accepted_if": [
                "bounded by the 4 known pools only",
                "returns exact transaction receipt or PairCreated log",
                "log address equals official factory",
                "emitted pair equals expected pool",
                "token topics match expected token0/token1",
            ],
            "reject_if": ["current_state_only", "symbol_only", "explorer_tag_only", "intermediary_only"],
            "why_it_matches_github_indexer_direction": (
                "Subgraph/indexer projects rely on historical event streams instead of ad-hoc broad public RPC scans."
            ),
            "lookup_allowed_now": False,
        },
        {
            "source_id": "explorer_contract_creation_api",
            "source_type": "explorer_api",
            "accepted_if": [
                "returns creator tx hash for the exact pool contract",
                "returns creation block or transaction hash that can be receipt-checked later",
                "source response is captured with URL, tier, digest and exact address binding before persistence",
            ],
            "reject_if": ["contract page tag only", "token symbol page", "no exact pool address", "no creation tx hash"],
            "configured_key_present": bool(explorer_keys_configured["etherscan_v2"] or explorer_keys_configured["bscscan_legacy"]),
            "lookup_allowed_now": False,
        },
        {
            "source_id": "manual_source_backed_creation_package",
            "source_type": "manual_source_package",
            "accepted_if": [
                "operator provides source_url, source_tier, digest, exact pool address, creation tx hash and creation block",
                "future dry-run validates receipt/log binding before persistence",
            ],
            "reject_if": ["screenshot_only", "unbound URL", "missing digest", "missing exact pool address"],
            "lookup_allowed_now": False,
        },
        {
            "source_id": "local_forward_indexer",
            "source_type": "forward_indexer",
            "accepted_if": [
                "collects future PairCreated events from official factories from now forward",
                "stores only under a separate confirmed evidence-only goal",
            ],
            "reject_if": ["used to prove old pools retroactively without historical event/receipt"],
            "note": "Useful for future data quality; it does not solve old pool creation proof by itself.",
            "lookup_allowed_now": False,
        },
    ]
    insufficient_proofs = [
        "getPair current-state match alone",
        "pool appears in local swaps alone",
        "pool appears in local token transfers alone",
        "explorer tag without creation tx/log",
        "symbol-only venue match",
        "router/intermediary address context without factory emitted pair",
        "social/forum claim without exact address/digest binding",
    ]
    required_future_fields = [
        "chain",
        "expected_factory_address",
        "expected_pool_address",
        "expected_token0",
        "expected_token1",
        "creation_tx_hash",
        "creation_block",
        "proof_source_url",
        "proof_source_tier",
        "proof_digest",
        "receipt_or_paircreated_log_json",
        "factory_emitted_pair_address",
        "source_policy",
    ]

    rows: list[dict[str, Any]] = []
    for probe_row in probe.get("rows") or []:
        pool = str(probe_row.get("expected_pool_address") or "").strip().lower()
        factory = str(probe_row.get("expected_factory_address") or "").strip().lower()
        route_context_ready = bool(_valid_evm_address(pool) and _valid_evm_address(factory))
        missing = [
            "creation_tx_hash",
            "creation_block",
            "paircreated_or_receipt_log",
            "factory_emitted_pair_match",
            "source_url_tier_digest_binding",
        ]
        proof_status = "ready_for_future_contract_creation_lookup" if route_context_ready else "blocked_missing_pool_or_factory"
        rows.append({
            "chain": requested_chain,
            "proof_gate_status": proof_status,
            "official_venue": probe_row.get("official_venue"),
            "expected_factory_address": factory or None,
            "expected_pool_address": pool or None,
            "expected_token0": probe_row.get("expected_token0"),
            "expected_token0_symbol": probe_row.get("expected_token0_symbol"),
            "expected_token1": probe_row.get("expected_token1"),
            "expected_token1_symbol": probe_row.get("expected_token1_symbol"),
            "observed_swap_tx_hash": probe_row.get("observed_swap_tx_hash"),
            "observed_swap_block": probe_row.get("observed_swap_block"),
            "first_local_pool_appearance_block": probe_row.get("first_local_pool_appearance_block"),
            "local_range_source": probe_row.get("local_range_source"),
            "current_state_context": {
                "get_pair_match_known_from_prior_audits": True,
                "pool_context_local": True,
                "exact_swap_local": True,
                "sufficient_for_mapping": False,
            },
            "historical_proof_missing": missing,
            "accepted_future_proof_shapes": [
                "archive_paircreated_log",
                "transaction_receipt_paircreated_log",
                "explorer_contract_creation_tx_then_receipt_check",
                "manual_source_backed_creation_package_then_receipt_check",
            ],
            "blocked_proof_shapes": insufficient_proofs,
            "proof_distinction": {
                "get_pair_current_state_proof": "useful context but not historical creation proof",
                "contract_creation_tx": "can identify the transaction to receipt-check",
                "paircreated_event": "required historical event before evidence persistence or mapping",
                "source_backed_mapping": "requires separate evidence-only persistence and later policy gates",
            },
            "source_backed_scoring_ready": False,
            "mapping_ready_now": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "blockers": [
                "historical_paircreated_event_missing",
                "contract_creation_tx_hash_missing",
                "contract_creation_block_missing",
                "source_url_tier_digest_binding_missing",
                "paircreated_evidence_not_persisted",
                "source_backed_scoring_remains_false",
                "mapping_ready_now_remains_false",
                "client_signal_disabled",
                "trade_disabled",
            ],
            "next_safe_step": "bounded explorer/archive contract creation lookup dry-run or manual source-backed package preview",
            "would_call_external": False,
            "would_persist_contract_creation_proof": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
        })

    ready_rows = sum(1 for row in rows if row.get("proof_gate_status") == "ready_for_future_contract_creation_lookup")
    recommended_source = (
        "explorer_contract_creation_api"
        if explorer_keys_configured["etherscan_v2"] or explorer_keys_configured["bscscan_legacy"]
        else "manual_source_backed_creation_package_or_configure_explorer_key"
    )
    return {
        "ok": True,
        "dry_run": True,
        "gate_status": "ready_read_only" if rows else "blocked_no_pool_candidates",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "source_probe_status": probe.get("probe_status"),
        "summary": {
            "pools_reviewed": len(rows),
            "ready_for_future_contract_creation_lookup": ready_rows,
            "creation_tx_hash_present": 0,
            "creation_block_present": 0,
            "paircreated_historical_event_present": 0,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "explorer_key_configured": bool(explorer_keys_configured["etherscan_v2"] or explorer_keys_configured["bscscan_legacy"]),
            "real_write_enabled": False,
        },
        "rows": rows,
        "acceptable_sources": acceptable_sources,
        "insufficient_proofs": insufficient_proofs,
        "required_future_fields": required_future_fields,
        "explorer_keys_configured": explorer_keys_configured,
        "recommended_source": recommended_source,
        "github_indexer_connection": {
            "subgraph_pattern": "Projects like Uniswap/PancakeSwap subgraphs index PairCreated-like factory events instead of relying on broad public RPC history scans.",
            "core_equity_takeaway": "Use archive/explorer/indexer proof for old pools, and consider a forward local indexer for future pools.",
        },
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_pool_candidates" for _ in [1] if not rows),
            "external_lookup_not_performed",
            "historical_paircreated_event_missing",
            "contract_creation_tx_hash_missing",
            "contract_creation_block_missing",
            "source_url_tier_digest_binding_missing",
            "paircreated_evidence_not_persisted",
            "source_backed_scoring_remains_false",
            "mapping_ready_now_remains_false",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": "DEX pool contract-creation explorer/archive lookup dry-run bounded" if rows else "repair PairCreated candidate selection first",
        "would_call_external": False,
        "would_persist_contract_creation_proof": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def _explorer_contract_creation_api_key(chain: str) -> tuple[str | None, str | None]:
    normalized_chain = _normalize_chain(chain or "")
    candidates = [("ETHERSCAN_API_KEY", os.getenv("ETHERSCAN_API_KEY", "").strip())]
    if normalized_chain == "bsc":
        candidates.extend([
            ("BSCSCAN_API_KEY", os.getenv("BSCSCAN_API_KEY", "").strip()),
            ("BSC_SCAN_API_KEY", os.getenv("BSC_SCAN_API_KEY", "").strip()),
            ("CORE_BSCSCAN_API_KEY", os.getenv("CORE_BSCSCAN_API_KEY", "").strip()),
        ])
    for source, key in candidates:
        if key:
            return key, source
    return None, None


def _bscscan_legacy_api_key() -> tuple[str | None, str | None]:
    for source in ("BSCSCAN_API_KEY", "BSC_SCAN_API_KEY", "CORE_BSCSCAN_API_KEY"):
        key = os.getenv(source, "").strip()
        if key:
            return key, source
    return None, None


def _normalize_contract_creation_rows(rows: Any) -> list[dict[str, Any]]:
    if not isinstance(rows, list):
        return []
    out: list[dict[str, Any]] = []
    for item in rows:
        if not isinstance(item, dict):
            continue
        address = str(item.get("contractAddress") or item.get("contract_address") or "").strip().lower()
        tx_hash = str(item.get("txHash") or item.get("hash") or "").strip().lower()
        out.append({
            "contract_address": address if _valid_evm_address(address) else None,
            "contract_creator": str(item.get("contractCreator") or item.get("contract_creator") or "").strip().lower() or None,
            "creation_tx_hash": tx_hash if re.fullmatch(r"0x[a-f0-9]{64}", tx_hash) else None,
            "creation_block": _hex_to_int_or_none(item.get("blockNumber") or item.get("block_number")),
            "creation_timestamp": _hex_to_int_or_none(item.get("timestamp") or item.get("timeStamp")),
            "contract_factory": str(item.get("contractFactory") or "").strip() or None,
            "creation_bytecode_present": bool(str(item.get("creationBytecode") or "").strip()),
            "raw_result_not_persisted": True,
        })
    return out


def _etherscan_v2_contract_creation_lookup(
    chain: str,
    contract_addresses: Sequence[str],
    timeout: int = 8,
) -> tuple[list[dict[str, Any]], str | None, str | None, str | None]:
    """Read-only Etherscan V2 contract creation lookup; caller must keep results non-persistent."""
    normalized_chain = _normalize_chain(chain or "")
    chain_id = ETHERSCAN_CHAIN_IDS.get(normalized_chain)
    if not chain_id:
        return [], None, "etherscan_chain_not_supported", None
    clean_addresses = [
        str(address or "").strip().lower()
        for address in contract_addresses
        if _valid_evm_address(str(address or "").strip().lower())
    ]
    clean_addresses = list(dict.fromkeys(clean_addresses))[:5]
    if not clean_addresses:
        return [], None, "contract_addresses_missing", None
    key, key_source = _explorer_contract_creation_api_key(normalized_chain)
    if not key:
        return [], None, "explorer_api_key_missing", None
    query_values = {
        "chainid": chain_id,
        "module": "contract",
        "action": "getcontractcreation",
        "contractaddresses": ",".join(clean_addresses),
        "apikey": key,
    }
    redacted_values = dict(query_values)
    redacted_values["apikey"] = "***"
    request_preview_url = f"{ETHERSCAN_V2_API}?{urllib.parse.urlencode(redacted_values)}"
    req = urllib.request.Request(
        f"{ETHERSCAN_V2_API}?{urllib.parse.urlencode(query_values)}",
        headers={"Accept": "application/json", "User-Agent": "CoreEquityContractCreationLookup/1.0"},
    )
    try:
        with urllib.request.urlopen(req, timeout=max(2, min(int(timeout or 8), 15))) as resp:
            payload = json.loads(resp.read(250_000).decode("utf-8", errors="replace"))
    except urllib.error.HTTPError as exc:
        return [], request_preview_url, f"etherscan_contract_creation_http_error:{exc.code}", key_source
    except Exception as exc:
        return [], request_preview_url, f"etherscan_contract_creation_error:{type(exc).__name__}", key_source
    if not isinstance(payload, dict):
        return [], request_preview_url, "etherscan_contract_creation_invalid_payload", key_source
    message = str(payload.get("message") or "").strip()
    status = str(payload.get("status") or "").strip()
    result = payload.get("result")
    if status != "1":
        warning = f"etherscan_contract_creation_not_ok:{message or status or 'unknown'}"
        if isinstance(result, str) and result:
            warning = f"{warning}:{result[:120]}"
        return [], request_preview_url, warning, key_source
    if not isinstance(result, list):
        return [], request_preview_url, "etherscan_contract_creation_result_not_list", key_source
    return _normalize_contract_creation_rows(result), request_preview_url, None, key_source


def _bscscan_legacy_contract_creation_lookup(
    contract_addresses: Sequence[str],
    timeout: int = 8,
) -> tuple[list[dict[str, Any]], str | None, str | None, str | None]:
    """Read-only legacy BscScan contract creation lookup; caller must keep results non-persistent."""
    clean_addresses = [
        str(address or "").strip().lower()
        for address in contract_addresses
        if _valid_evm_address(str(address or "").strip().lower())
    ]
    clean_addresses = list(dict.fromkeys(clean_addresses))[:5]
    if not clean_addresses:
        return [], None, "contract_addresses_missing", None
    key, key_source = _bscscan_legacy_api_key()
    if not key:
        return [], None, "bscscan_api_key_missing", None
    query_values = {
        "module": "contract",
        "action": "getcontractcreation",
        "contractaddresses": ",".join(clean_addresses),
        "apikey": key,
    }
    redacted_values = dict(query_values)
    redacted_values["apikey"] = "***"
    request_preview_url = f"https://api.bscscan.com/api?{urllib.parse.urlencode(redacted_values)}"
    req = urllib.request.Request(
        f"https://api.bscscan.com/api?{urllib.parse.urlencode(query_values)}",
        headers={"Accept": "application/json", "User-Agent": "CoreEquityContractCreationLookup/1.0"},
    )
    try:
        with urllib.request.urlopen(req, timeout=max(2, min(int(timeout or 8), 15))) as resp:
            payload = json.loads(resp.read(250_000).decode("utf-8", errors="replace"))
    except urllib.error.HTTPError as exc:
        return [], request_preview_url, f"bscscan_contract_creation_http_error:{exc.code}", key_source
    except Exception as exc:
        return [], request_preview_url, f"bscscan_contract_creation_error:{type(exc).__name__}", key_source
    if not isinstance(payload, dict):
        return [], request_preview_url, "bscscan_contract_creation_invalid_payload", key_source
    message = str(payload.get("message") or "").strip()
    status = str(payload.get("status") or "").strip()
    result = payload.get("result")
    if status != "1":
        warning = f"bscscan_contract_creation_not_ok:{message or status or 'unknown'}"
        if isinstance(result, str) and result:
            warning = f"{warning}:{result[:120]}"
        return [], request_preview_url, warning, key_source
    if not isinstance(result, list):
        return [], request_preview_url, "bscscan_contract_creation_result_not_list", key_source
    return _normalize_contract_creation_rows(result), request_preview_url, None, key_source


def get_unknown_dex_pool_contract_creation_explorer_archive_lookup_dry_run(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    creation_lookback_blocks: int = 250_000,
    max_future_replay_range_blocks: int = 250_000,
    max_source_calls: int = 2,
    timeout: int = 6,
    dry_run: bool = True,
    allow_external: bool = False,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Bounded read-only explorer/archive lookup for pool contract creation metadata."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_creation_lookback = max(1_000, min(int(creation_lookback_blocks or 250_000), 2_000_000))
    safe_future_range = max(1_000, min(int(max_future_replay_range_blocks or 250_000), 2_000_000))
    safe_source_calls = max(0, min(int(max_source_calls or 2), 4))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    required_confirm = "RUN_BOUNDED_CONTRACT_CREATION_EXPLORER_LOOKUP"
    source_policy = (
        "admin-only bounded read-only explorer/archive contract-creation lookup. It uses only the 4 gated "
        "Unknown DEX pools, may call Etherscan V2 getcontractcreation only when allow_external=true and the "
        "explicit confirm matches, keeps results in memory, and never persists evidence, creates mappings, "
        "router evidence, labels, client signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "contract_creation_proof_persistence": True,
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "lookup_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "would_call_external": False,
            "would_persist_contract_creation_proof": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    external_confirmed = bool(allow_external and confirm == required_confirm)
    gate = get_unknown_dex_pool_contract_creation_proof_source_gate(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        creation_lookback_blocks=safe_creation_lookback,
        max_future_replay_range_blocks=safe_future_range,
        timeout=safe_timeout,
        dry_run=True,
    )
    gate_rows = [
        row for row in (gate.get("rows") or [])
        if row.get("proof_gate_status") == "ready_for_future_contract_creation_lookup"
    ][:safe_pools]
    pool_addresses = [
        str(row.get("expected_pool_address") or "").strip().lower()
        for row in gate_rows
        if _valid_evm_address(str(row.get("expected_pool_address") or "").strip().lower())
    ]
    key_present, key_source = _explorer_contract_creation_api_key(requested_chain)
    chain_supported = requested_chain in ETHERSCAN_CHAIN_IDS
    source_calls = 0
    source_errors = 0
    lookup_warning: str | None = None
    request_url: str | None = None
    raw_creation_rows: list[dict[str, Any]] = []
    lookup_attempts: list[dict[str, Any]] = []
    if allow_external and not external_confirmed:
        lookup_warning = "external_confirm_required"
    elif external_confirmed and not chain_supported:
        lookup_warning = "etherscan_chain_not_supported"
    elif external_confirmed and not key_present:
        lookup_warning = "explorer_api_key_missing"
    elif external_confirmed and not pool_addresses:
        lookup_warning = "pool_addresses_missing"
    elif external_confirmed and safe_source_calls <= 0:
        lookup_warning = "source_call_budget_zero"
    elif external_confirmed:
        raw_creation_rows, request_url, lookup_warning, key_source = _etherscan_v2_contract_creation_lookup(
            requested_chain,
            pool_addresses[:5],
            timeout=safe_timeout,
        )
        source_calls = 1
        lookup_attempts.append({
            "source_type": "etherscan_v2_getcontractcreation",
            "called": True,
            "request_url": request_url,
            "warning": lookup_warning,
            "rows_returned": len(raw_creation_rows),
            "key_source_present": key_source,
        })
        if (
            lookup_warning
            and requested_chain == "bsc"
            and source_calls < safe_source_calls
            and _bscscan_legacy_api_key()[0]
        ):
            legacy_rows, legacy_url, legacy_warning, legacy_key_source = _bscscan_legacy_contract_creation_lookup(
                pool_addresses[:5],
                timeout=safe_timeout,
            )
            source_calls += 1
            lookup_attempts.append({
                "source_type": "bscscan_legacy_getcontractcreation",
                "called": True,
                "request_url": legacy_url,
                "warning": legacy_warning,
                "rows_returned": len(legacy_rows),
                "key_source_present": legacy_key_source,
            })
            if legacy_rows or not legacy_warning:
                raw_creation_rows = legacy_rows
                request_url = legacy_url
                lookup_warning = legacy_warning
                key_source = legacy_key_source
        if lookup_warning:
            source_errors = 1

    creation_by_address = {
        str(item.get("contract_address") or "").strip().lower(): item
        for item in raw_creation_rows
        if _valid_evm_address(str(item.get("contract_address") or "").strip().lower())
    }
    rows: list[dict[str, Any]] = []
    creation_found = 0
    for gate_row in gate_rows:
        pool = str(gate_row.get("expected_pool_address") or "").strip().lower()
        creation = creation_by_address.get(pool) or {}
        creation_tx = creation.get("creation_tx_hash")
        creation_block = creation.get("creation_block")
        found = bool(creation_tx and creation_block is not None)
        if found:
            creation_found += 1
        if not allow_external:
            row_status = "planned_external_lookup_disabled"
        elif allow_external and not external_confirmed:
            row_status = "not_called_confirm_required"
        elif lookup_warning and not raw_creation_rows:
            row_status = "source_error_or_not_configured_read_only"
        elif found:
            row_status = "contract_creation_metadata_found_read_only"
        else:
            row_status = "contract_creation_metadata_missing_read_only"
        rows.append({
            "chain": requested_chain,
            "lookup_status": row_status,
            "official_venue": gate_row.get("official_venue"),
            "expected_factory_address": gate_row.get("expected_factory_address"),
            "expected_pool_address": pool or None,
            "expected_token0": gate_row.get("expected_token0"),
            "expected_token0_symbol": gate_row.get("expected_token0_symbol"),
            "expected_token1": gate_row.get("expected_token1"),
            "expected_token1_symbol": gate_row.get("expected_token1_symbol"),
            "observed_swap_tx_hash": gate_row.get("observed_swap_tx_hash"),
            "observed_swap_block": gate_row.get("observed_swap_block"),
            "first_local_pool_appearance_block": gate_row.get("first_local_pool_appearance_block"),
            "source_lookup": {
                "source_type": "etherscan_v2_getcontractcreation",
                "source_label": "etherscan_v2",
                "chainid": ETHERSCAN_CHAIN_IDS.get(requested_chain),
                "request_url": request_url,
                "called": bool(external_confirmed and source_calls > 0),
                "key_source_present": key_source,
                "warning": lookup_warning,
                "attempts": lookup_attempts,
                "raw_result_not_persisted": True,
            },
            "creation_metadata": {
                "contract_creator": creation.get("contract_creator"),
                "creation_tx_hash": creation_tx,
                "creation_block": creation_block,
                "creation_timestamp": creation.get("creation_timestamp"),
                "contract_factory": creation.get("contract_factory"),
                "creation_bytecode_present": bool(creation.get("creation_bytecode_present")),
                "metadata_not_persisted": True,
            },
            "creation_metadata_found": found,
            "receipt_or_paircreated_log_checked": False,
            "factory_emitted_pair_match": False,
            "historical_event_proof_ready": False,
            "source_backed_scoring_ready": False,
            "mapping_ready_now": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "proof_distinction": {
                "contract_creation_metadata": "can identify a future receipt/log check target but is not mapping proof by itself",
                "paircreated_historical_event_proof": "still requires receipt/log where official factory emits expected pool",
                "get_pair_current_state_proof": "useful context only",
            },
            "blockers": list(dict.fromkeys([
                *("external_lookup_disabled" for _ in [1] if not allow_external),
                *("external_confirm_required" for _ in [1] if allow_external and not external_confirmed),
                *("source_warning_present" for _ in [1] if lookup_warning),
                *("creation_metadata_missing" for _ in [1] if not found),
                "receipt_or_paircreated_log_not_checked",
                "factory_emitted_pair_match_missing",
                "contract_creation_proof_not_persisted",
                "paircreated_evidence_not_persisted",
                "source_backed_scoring_remains_false",
                "mapping_ready_now_remains_false",
                "client_signal_disabled",
                "trade_disabled",
            ])),
            "next_safe_step": (
                "bounded receipt/log PairCreated verification dry-run; still no persistence"
                if found else "repair explorer/archive source or provide manual source-backed creation package"
                if allow_external else "rerun with allow_external=true and explicit confirm for bounded lookup"
            ),
            "would_persist_contract_creation_proof": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
        })

    lookup_status = (
        "contract_creation_metadata_found_read_only"
        if creation_found else "explorer_archive_lookup_errors_read_only"
        if source_errors else "explorer_archive_lookup_completed_no_creation_metadata_read_only"
        if external_confirmed and rows else "blocked_missing_external_confirm"
        if allow_external and not external_confirmed else "explorer_archive_lookup_planned_external_disabled"
        if rows else "blocked_no_contract_creation_lookup_candidates"
    )
    return {
        "ok": True,
        "dry_run": True,
        "lookup_status": lookup_status,
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "source_gate_status": gate.get("gate_status"),
        "source_type": "etherscan_v2_getcontractcreation",
        "external_call_gate": {
            "allow_external": bool(allow_external),
            "required_confirm": required_confirm,
            "confirm_matched": external_confirmed,
            "calls_performed_only_when_confirmed": True,
            "source_call_budget": safe_source_calls,
        },
        "summary": {
            "pools_planned": len(rows),
            "source_calls_performed": source_calls,
            "source_call_budget": safe_source_calls,
            "source_errors": source_errors,
            "creation_metadata_found": creation_found,
            "creation_tx_hash_found": sum(1 for row in rows if (row.get("creation_metadata") or {}).get("creation_tx_hash")),
            "creation_block_found": sum(1 for row in rows if (row.get("creation_metadata") or {}).get("creation_block") is not None),
            "receipt_or_paircreated_log_checked": 0,
            "factory_emitted_pair_matches": 0,
            "historical_event_proof_ready": 0,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "explorer_key_configured": bool(key_present),
            "real_write_enabled": False,
        },
        "rows": rows,
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_contract_creation_lookup_candidates" for _ in [1] if not rows),
            *("external_lookup_disabled" for _ in [1] if rows and not allow_external),
            *("external_confirm_required" for _ in [1] if rows and allow_external and not external_confirmed),
            *("source_warning_present" for _ in [1] if lookup_warning),
            *("creation_metadata_missing" for _ in [1] if rows and not creation_found),
            "receipt_or_paircreated_log_not_checked",
            "factory_emitted_pair_match_missing",
            "contract_creation_proof_not_persisted",
            "paircreated_evidence_not_persisted",
            "source_backed_scoring_remains_false",
            "mapping_ready_now_remains_false",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "DEX pool contract-creation receipt/log verification dry-run read-only"
            if creation_found else "manual source-backed creation package or archive/indexer repair"
            if allow_external else "rerun with allow_external=true and explicit confirm for bounded explorer/archive lookup"
        ),
        "would_call_external": bool(rows and not allow_external),
        "would_persist_contract_creation_proof": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_paircreated_forward_local_indexer_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    lookback_blocks: int = 500_000,
    creation_lookback_blocks: int = 250_000,
    max_future_replay_range_blocks: int = 250_000,
    forward_block_window: int = 5_000,
    poll_interval_seconds: int = 60,
    timeout: int = 6,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Plan a forward-only local PairCreated indexer without touching DB state."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_lookback = max(1_000, min(int(lookback_blocks or 500_000), 5_000_000))
    safe_creation_lookback = max(1_000, min(int(creation_lookback_blocks or 250_000), 2_000_000))
    safe_future_range = max(1_000, min(int(max_future_replay_range_blocks or 250_000), 2_000_000))
    safe_forward_window = max(100, min(int(forward_block_window or 5_000), 100_000))
    safe_poll_seconds = max(15, min(int(poll_interval_seconds or 60), 3_600))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only PairCreated forward local indexer plan. It plans a future forward-only event "
        "collector for official DEX factories, but it performs no RPC/indexer calls, creates no table, persists "
        "no evidence, creates no mappings, labels, client signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "rpc_collection": True,
        "table_creation": True,
        "paircreated_evidence_persistence": True,
        "dex_mapping": True,
        "dex_router_evidence": True,
        "source_backed_scoring": True,
        "cex_label": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "would_create_table": False,
            "would_start_indexer": False,
            "would_call_rpc": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
            "would_create_dex_router_evidence": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    gate = get_unknown_dex_pool_contract_creation_proof_source_gate(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        lookback_blocks=safe_lookback,
        creation_lookback_blocks=safe_creation_lookback,
        max_future_replay_range_blocks=safe_future_range,
        timeout=safe_timeout,
        dry_run=True,
    )
    gate_rows = [
        row for row in (gate.get("rows") or [])
        if _valid_evm_address(str(row.get("expected_factory_address") or "").strip().lower())
    ][:safe_pools]
    registry_rows = _official_factory_registry_rows(requested_chain)
    normalized_filter = str(factory_address or "").strip().lower()
    if normalized_filter and _valid_evm_address(normalized_filter):
        registry_rows = [
            row for row in registry_rows
            if str(row.get("factory_addr") or "").strip().lower() == normalized_filter
        ]

    registry_by_factory = {
        str(row.get("factory_addr") or "").strip().lower(): row
        for row in registry_rows
        if _valid_evm_address(str(row.get("factory_addr") or "").strip().lower())
    }
    candidate_pools_by_factory: dict[str, list[dict[str, Any]]] = {}
    for row in gate_rows:
        factory = str(row.get("expected_factory_address") or "").strip().lower()
        candidate_pools_by_factory.setdefault(factory, []).append(row)

    factory_keys = list(dict.fromkeys([
        *candidate_pools_by_factory.keys(),
        *registry_by_factory.keys(),
    ]))
    factories_to_monitor: list[dict[str, Any]] = []
    for factory in factory_keys:
        registry = registry_by_factory.get(factory) or {}
        pool_rows = candidate_pools_by_factory.get(factory) or []
        venue = registry.get("venue") or next((row.get("official_venue") for row in pool_rows if row.get("official_venue")), None)
        factories_to_monitor.append({
            "chain": requested_chain,
            "venue": venue,
            "venue_type": registry.get("venue_type"),
            "factory_address": factory,
            "factory_source_status": registry.get("source_status") or "factory_seen_in_unknown_dex_gate",
            "monitor_priority": "high_unknown_dex_candidate_factory" if pool_rows else "official_registry_factory",
            "old_candidate_pool_count": len(pool_rows),
            "old_candidate_pools": [
                {
                    "expected_pool_address": row.get("expected_pool_address"),
                    "expected_token0": row.get("expected_token0"),
                    "expected_token0_symbol": row.get("expected_token0_symbol"),
                    "expected_token1": row.get("expected_token1"),
                    "expected_token1_symbol": row.get("expected_token1_symbol"),
                    "observed_swap_tx_hash": row.get("observed_swap_tx_hash"),
                    "observed_swap_block": row.get("observed_swap_block"),
                    "still_research_only": True,
                    "forward_indexer_solves_this_old_pool": False,
                    "missing_historical_proof": "PairCreated log or creation receipt still required",
                }
                for row in pool_rows
            ],
            "event_signature": "PairCreated(address indexed token0,address indexed token1,address pair,uint256)",
            "event_topic": PAIR_CREATED_TOPIC,
            "forward_collection_strategy": {
                "mode": "forward_only",
                "initial_start_rule": f"latest_block_minus_{safe_forward_window}_or_last_indexed_block_plus_1",
                "poll_interval_seconds": safe_poll_seconds,
                "max_block_window_per_poll": safe_forward_window,
                "historical_backfill_scope": "recent_bounded_only",
                "old_pool_proof_scope": "not_solved_by_forward_indexer",
            },
            "dedupe_rule": "chain|factory_address|tx_hash|log_index|pair_address",
            "would_monitor_factory": False,
            "would_call_rpc": False,
            "would_persist_paircreated_evidence": False,
            "would_create_mapping": False,
        })

    old_candidate_rows = []
    for row in gate_rows:
        old_candidate_rows.append({
            "chain": requested_chain,
            "official_venue": row.get("official_venue"),
            "expected_factory_address": row.get("expected_factory_address"),
            "expected_pool_address": row.get("expected_pool_address"),
            "expected_token0": row.get("expected_token0"),
            "expected_token0_symbol": row.get("expected_token0_symbol"),
            "expected_token1": row.get("expected_token1"),
            "expected_token1_symbol": row.get("expected_token1_symbol"),
            "observed_swap_tx_hash": row.get("observed_swap_tx_hash"),
            "observed_swap_block": row.get("observed_swap_block"),
            "current_state_context_status": "getPair_current_state_context_only",
            "historical_paircreated_status": "missing",
            "forward_indexer_status_for_this_pool": "does_not_retroactively_prove_old_pool",
            "research_only": True,
            "mapping_ready_now": False,
            "source_backed_scoring_ready": False,
            "blockers": [
                "historical_paircreated_event_missing",
                "contract_creation_receipt_missing",
                "paircreated_evidence_not_persisted",
                "mapping_ready_now_remains_false",
                "client_signal_disabled",
                "trade_disabled",
            ],
        })

    schema_preview = {
        "target_table": "dex_paircreated_forward_event_index",
        "created_now": False,
        "fields": [
            "id INTEGER PRIMARY KEY AUTOINCREMENT",
            "chain TEXT NOT NULL",
            "factory_address TEXT NOT NULL",
            "token0 TEXT NOT NULL",
            "token1 TEXT NOT NULL",
            "pair_address TEXT NOT NULL",
            "pair_index_or_all_pairs_length INTEGER",
            "tx_hash TEXT NOT NULL",
            "log_index INTEGER NOT NULL",
            "block_number INTEGER NOT NULL",
            "block_hash TEXT",
            "event_timestamp TEXT",
            "source_rpc TEXT NOT NULL",
            "raw_log_json TEXT NOT NULL",
            "paircreated_dedupe_key TEXT NOT NULL UNIQUE",
            "status TEXT NOT NULL DEFAULT 'observed_forward_only'",
            "created_at TEXT NOT NULL",
            "source_policy TEXT NOT NULL",
        ],
    }
    indexes_preview = [
        "UNIQUE(paircreated_dedupe_key)",
        "INDEX(chain, factory_address)",
        "INDEX(pair_address)",
        "INDEX(tx_hash, log_index)",
        "INDEX(block_number)",
        "INDEX(token0)",
        "INDEX(token1)",
        "INDEX(status)",
    ]
    constraints_preview = [
        "factory_address must be an official curated factory before collection",
        "topic0 must equal PairCreated topic",
        "pair_address must be the emitted pair from the log data",
        "dedupe blocks duplicate chain/factory/tx/log/pair events",
        "forward events do not create mappings until separate source-backed evidence policy passes",
    ]
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only" if factories_to_monitor else "blocked_no_official_factory_to_monitor",
        "chain": requested_chain,
        "indexer_mode": "forward_only",
        "backfill_mode": "recent_bounded_only",
        "target_table": "dex_paircreated_forward_event_index",
        "event_signature": "PairCreated(address indexed token0,address indexed token1,address pair,uint256)",
        "event_topic": PAIR_CREATED_TOPIC,
        "source_gate_status": gate.get("gate_status"),
        "summary": {
            "factories_to_monitor": len(factories_to_monitor),
            "high_priority_unknown_dex_factories": sum(
                1 for row in factories_to_monitor if row.get("monitor_priority") == "high_unknown_dex_candidate_factory"
            ),
            "old_unknown_dex_pool_candidates_reviewed": len(old_candidate_rows),
            "old_pools_solved_by_forward_indexer": 0,
            "future_paircreated_capture_ready_as_plan": len(factories_to_monitor),
            "paircreated_events_persisted_now": 0,
            "source_backed_scoring_ready": 0,
            "mapping_ready_now": 0,
            "client_ready_signals": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "factories_to_monitor": factories_to_monitor,
        "old_candidate_rows": old_candidate_rows,
        "schema_preview": schema_preview,
        "indexes_preview": indexes_preview,
        "constraints_preview": constraints_preview,
        "dedupe_constraints": {
            "paircreated_dedupe_key": "chain|factory_address|tx_hash|log_index|pair_address",
            "duplicate_policy": "block_duplicate_no_overwrite_no_upsert_no_silent_success",
        },
        "operating_rules": [
            "Forward indexer improves future data quality only.",
            "It cannot prove old pools unless the historical event or receipt is found elsewhere.",
            "A PairCreated row is evidence candidate only; mapping/scoring/trading need later policy gates.",
            "No client-facing signal is allowed from this plan.",
        ],
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_official_factory_to_monitor" for _ in [1] if not factories_to_monitor),
            "plan_only_no_collection_started",
            "table_not_created",
            "paircreated_evidence_not_persisted",
            "old_pools_still_need_historical_paircreated_or_receipt",
            "source_backed_scoring_remains_false",
            "mapping_ready_now_remains_false",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "DEX PairCreated forward local indexer schema-plan read-only"
            if factories_to_monitor else "repair official factory registry or Unknown DEX candidate selection"
        ),
        "would_create_table": False,
        "would_start_indexer": False,
        "would_call_rpc": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_venue_family_review(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc: bool = False,
) -> dict[str, Any]:
    """Read-only review separating verified pool/factory family context from unmapped router identity."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only venue-family review. It may classify pool/factory family context, but it never "
        "turns that into a router mapping, DEX evidence row, swap rewrite, label, signal, trade, wallet order or opt-in."
    )
    disabled_actions = {
        "dex_router_evidence": True,
        "venue_mapping": True,
        "swap_rewrite": True,
        "curated_scoring": True,
        "client_signal": True,
        "trade": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "review_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "would_call_rpc": False,
            "would_create_dex_router_evidence": False,
            "would_create_venue_mapping": False,
            "would_update_swaps": False,
            "would_create_cex_label": False,
            "would_execute_trade": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    proof = get_unknown_dex_factory_official_source_proof_checkpoint(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        queries_per_factory=3,
        max_results_per_query=3,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc),
        allow_external=False,
    )

    rows: list[dict[str, Any]] = []
    for proof_row in proof.get("rows") or []:
        pool_rows = list(proof_row.get("pool_context_rows") or [])
        routers = list(dict.fromkeys(
            str(row.get("router_addr") or "").strip().lower()
            for row in pool_rows
            if _valid_evm_address(str(row.get("router_addr") or "").strip().lower())
        ))
        token_symbols = list(dict.fromkeys(
            symbol
            for row in pool_rows
            for symbol in [
                str(row.get("token0_symbol") or "").strip(),
                str(row.get("token1_symbol") or "").strip(),
                *(str(value or "").strip() for value in row.get("non_infrastructure_symbols") or []),
            ]
            if symbol
        ))
        official_verified = bool(proof_row.get("official_source_verified"))
        pool_context_count = int(proof_row.get("pool_context_count") or 0)
        venue_family = str(proof_row.get("official_venue") or "").strip() or None
        family_context_ready = bool(official_verified and pool_context_count > 0)
        venue_family_status = (
            "pool_factory_family_verified_router_unmapped"
            if family_context_ready else "official_factory_known_without_local_pool_context"
            if official_verified else "blocked_official_factory_source_missing"
        )
        route_classification = (
            "pancakeswap_v2_pool_factory_context_only"
            if venue_family == "PancakeSwap V2" and family_context_ready else "official_factory_context_only_needs_local_pool_context"
            if official_verified else "unknown_dex_family_unverified"
        )
        rows.append({
            "chain": requested_chain,
            "factory_address": proof_row.get("factory_address"),
            "factory_source_dedupe_key": proof_row.get("factory_source_dedupe_key"),
            "venue_family": venue_family,
            "venue_type": proof_row.get("venue_type"),
            "official_urls": proof_row.get("official_urls") or [],
            "official_source_verified": official_verified,
            "pool_context_count": pool_context_count,
            "pool_context_rows": pool_rows,
            "observed_router_or_intermediary_addresses": routers,
            "observed_token_symbols": token_symbols[:20],
            "venue_family_status": venue_family_status,
            "route_classification": route_classification,
            "confirmed_scope": [
                "factory_address_officially_source_backed",
                "observed_pools_return_factory",
                "observed_pool_token_pairs_match_local_context",
            ] if family_context_ready else [
                "factory_address_officially_source_backed",
            ] if official_verified else [],
            "unconfirmed_scope": [
                "router_identity",
                "router_to_factory_relationship",
                "exact_execution_path_owner",
                "venue_mapping",
                "client_signal_readiness",
                "trade_readiness",
            ],
            "router_mapping_status": (
                "blocked_router_or_intermediary_not_officially_bound_to_family"
                if routers else "blocked_no_router_context_for_family_review"
            ),
            "scoring_status": "blocked_until_source_backed_curated_route_rows",
            "safe_for_family_context_now": family_context_ready,
            "safe_for_mapping_now": False,
            "safe_for_scoring_now": False,
            "safe_for_client_signal_now": False,
            "blockers": list(dict.fromkeys([
                *("official_factory_source_missing" for _ in [1] if not official_verified),
                *("local_pool_context_missing" for _ in [1] if pool_context_count <= 0),
                *("router_or_intermediary_still_unmapped" for _ in [1] if routers),
                "factory_family_context_is_not_router_mapping",
                "no_mapping_from_venue_family_review",
                "no_scoring_from_venue_family_review",
                "client_signal_disabled",
                "trade_disabled",
            ])),
            "next_safe_step": (
                "collect_more_pool_samples_or_build_source_backed_curated_family_context_read_only"
                if family_context_ready else "rerun_factory_proof_with_allow_rpc_true_or_collect_more_pool_context"
            ),
            "would_create_dex_router_evidence": False,
            "would_create_venue_mapping": False,
            "would_update_swaps": False,
            "would_execute_trade": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
            "would_write": False,
        })

    family_ready = sum(1 for row in rows if row.get("safe_for_family_context_now"))
    return {
        "ok": True,
        "dry_run": True,
        "review_status": (
            "venue_family_context_ready_read_only"
            if family_ready else "blocked_no_verified_pool_factory_family_context"
            if rows else "blocked_no_factory_rows"
        ),
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "factory_proof_checkpoint_status": proof.get("checkpoint_status"),
        "summary": {
            "factory_rows_reviewed": len(rows),
            "venue_family_context_ready": family_ready,
            "pool_context_rows": sum(int(row.get("pool_context_count") or 0) for row in rows),
            "official_factory_sources_verified": sum(1 for row in rows if row.get("official_source_verified")),
            "observed_router_or_intermediary_addresses": len(set(
                router
                for row in rows
                for router in row.get("observed_router_or_intermediary_addresses") or []
            )),
            "mapping_ready_now": 0,
            "scoring_ready_now": 0,
            "client_ready_signals": 0,
            "real_write_enabled": False,
        },
        "rows": rows,
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_factory_rows" for _ in [1] if not rows),
            *("no_verified_pool_factory_family_context" for _ in [1] if rows and not family_ready),
            "router_or_intermediary_still_unmapped",
            "factory_family_context_is_not_router_mapping",
            "no_mapping_from_venue_family_review",
            "no_scoring_from_venue_family_review",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "collect more source-backed family context or prepare curated family-context scoring plan read-only"
            if family_ready else "rerun factory proof with allow_rpc=true or collect more pool context"
        ),
        "would_call_rpc": bool(not allow_rpc and not factory_address),
        "would_call_external": False,
        "would_create_dex_router_evidence": False,
        "would_create_venue_mapping": False,
        "would_update_swaps": False,
        "would_create_cex_label": False,
        "would_execute_trade": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_family_context_scoring_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc: bool = False,
) -> dict[str, Any]:
    """Read-only plan for research-only scoring from verified pool/factory family context."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only family-context scoring plan. It can decide whether verified pool/factory family "
        "context is useful for research, but it is explicitly not source-backed route scoring, not a client signal, "
        "not a mapping and not a trade plan."
    )
    disabled_actions = {
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "venue_mapping": True,
        "dex_router_evidence": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "would_score_for_client": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    family_review = get_unknown_dex_venue_family_review(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc),
    )
    candidate_groups: list[dict[str, Any]] = []
    for row in family_review.get("rows") or []:
        pool_rows = list(row.get("pool_context_rows") or [])
        if not row.get("safe_for_family_context_now"):
            continue
        token_groups: dict[str, dict[str, Any]] = {}
        for pool_row in pool_rows:
            symbols = [
                str(pool_row.get("token0_symbol") or "").strip().upper(),
                str(pool_row.get("token1_symbol") or "").strip().upper(),
                *(str(value or "").strip().upper() for value in pool_row.get("non_infrastructure_symbols") or []),
            ]
            for symbol in symbols:
                if not symbol or symbol in INFRASTRUCTURE_TOKEN_SYMBOLS:
                    continue
                entry = token_groups.setdefault(
                    symbol,
                    {
                        "token_symbol": symbol,
                        "pool_addresses": set(),
                        "tx_hashes": set(),
                        "routers": set(),
                        "token_pair_symbols": set(),
                    },
                )
                if pool_row.get("pool_address"):
                    entry["pool_addresses"].add(str(pool_row.get("pool_address")).lower())
                if pool_row.get("tx_hash"):
                    entry["tx_hashes"].add(str(pool_row.get("tx_hash")).lower())
                if pool_row.get("router_addr"):
                    entry["routers"].add(str(pool_row.get("router_addr")).lower())
                pair = "/".join(
                    value
                    for value in [
                        str(pool_row.get("token0_symbol") or "").strip().upper(),
                        str(pool_row.get("token1_symbol") or "").strip().upper(),
                    ]
                    if value
                )
                if pair:
                    entry["token_pair_symbols"].add(pair)

        for entry in token_groups.values():
            pool_count = len(entry["pool_addresses"])
            tx_count = len(entry["tx_hashes"])
            router_count = len(entry["routers"])
            rough_research_score = min(100, pool_count * 25 + tx_count * 10 + router_count * 10)
            blockers = list(dict.fromkeys([
                *("too_few_family_context_pools" for _ in [1] if pool_count < 3),
                *("too_few_family_context_transactions" for _ in [1] if tx_count < 5),
                *("router_or_intermediary_unmapped" for _ in [1] if router_count > 0),
                "not_source_backed_route_scoring",
                "no_price_or_outcome_backtest_on_family_context",
                "no_liquidity_slippage_or_mev_model",
                "client_signal_disabled",
                "trade_disabled",
            ]))
            candidate_groups.append({
                "chain": requested_chain,
                "venue_family": row.get("venue_family"),
                "factory_address": row.get("factory_address"),
                "token_symbol": entry["token_symbol"],
                "pool_context_count": pool_count,
                "tx_context_count": tx_count,
                "router_or_intermediary_count": router_count,
                "pool_addresses": sorted(entry["pool_addresses"]),
                "tx_hashes": sorted(entry["tx_hashes"])[:10],
                "router_or_intermediary_addresses": sorted(entry["routers"]),
                "token_pair_symbols": sorted(entry["token_pair_symbols"]),
                "rough_research_score": rough_research_score,
                "scoring_readiness": (
                    "research_family_context_only_not_client_ready"
                    if pool_count >= 1 else "blocked_no_pool_context"
                ),
                "can_feed_source_backed_scoring": False,
                "can_feed_client_signal": False,
                "can_feed_trade_agent": False,
                "recommended_next_modules": [
                    "collect_more_family_context_rows",
                    "family_context_casefile_read_only",
                    "source_backed_route_repair_before_true_scoring",
                    "shadow_backtest_after_curated_source_backed_rows",
                ],
                "blockers_for_policy_or_client_automation": blockers,
                "would_score_for_client": False,
                "would_create_client_signal": False,
                "would_execute_trade": False,
                "would_write": False,
            })

    candidate_groups.sort(
        key=lambda item: (
            int(item.get("pool_context_count") or 0),
            int(item.get("tx_context_count") or 0),
            int(item.get("rough_research_score") or 0),
        ),
        reverse=True,
    )
    ready_research = sum(
        1 for item in candidate_groups if item.get("scoring_readiness") == "research_family_context_only_not_client_ready"
    )
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_research_only" if candidate_groups else "blocked",
        "mode": "unknown_dex_family_context_scoring_plan",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "family_review_status": family_review.get("review_status"),
        "summary": {
            "venue_family_rows_reviewed": len(family_review.get("rows") or []),
            "candidate_token_groups": len(candidate_groups),
            "research_family_context_only": ready_research,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "mapping_ready_now": 0,
            "real_write_enabled": False,
        },
        "candidate_groups": candidate_groups[:safe_limit],
        "policy_gates_before_real_scoring": [
            "route_level_source_backing",
            "router_or_intermediary_identity_resolution",
            "more_repeatable_clean_rows",
            "price_outcome_backtest",
            "liquidity_slippage_mev_model",
            "client_policy_and_opt_in",
        ],
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_family_context_candidate_groups" for _ in [1] if not candidate_groups),
            "family_context_not_source_backed_route_scoring",
            "client_signal_disabled",
            "trade_disabled",
            "venue_mapping_disabled",
        ])),
        "next_safe_step": (
            "collect more family-context rows or build a family-context casefile read-only"
            if candidate_groups else "rerun venue-family review with allow_rpc=true or collect more pool context"
        ),
        "would_call_rpc": bool(not allow_rpc and not factory_address),
        "would_call_external": False,
        "would_score_for_client": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_family_context_collection_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc: bool = False,
) -> dict[str, Any]:
    """Read-only bounded collection plan for thin family-context token leads."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    source_policy = (
        "admin-only read-only family-context collection plan. It plans bounded raw block windows around thin "
        "PancakeSwap V2 family-context leads, but performs no RPC calls, no DB writes, no mappings, no labels, "
        "no client signals, no wallet orders, no trades and no opt-ins."
    )
    disabled_actions = {
        "live_collection": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "venue_mapping": True,
        "dex_router_evidence": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "would_collect_data": False,
            "would_call_rpc": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    scoring_plan = get_unknown_dex_family_context_scoring_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc),
    )

    planned_blocks: set[int] = set()
    token_plans: list[dict[str, Any]] = []
    for group in scoring_plan.get("candidate_groups") or []:
        anchors: list[dict[str, Any]] = []
        centers: list[int] = []
        for tx_hash in group.get("tx_hashes") or []:
            clean_tx = str(tx_hash or "").strip().lower()
            if not clean_tx:
                continue
            conn = _get_db()
            conn.row_factory = sqlite3.Row
            try:
                row = conn.execute(
                    """
                    SELECT block_number
                    FROM transactions
                    WHERE lower(chain) = ? AND lower(tx_hash) = ?
                    UNION
                    SELECT block_number
                    FROM swaps
                    WHERE lower(chain) = ? AND lower(tx_hash) = ?
                    UNION
                    SELECT block_number
                    FROM token_transfers
                    WHERE lower(chain) = ? AND lower(tx_hash) = ?
                    LIMIT 1
                    """,
                    (requested_chain, clean_tx, requested_chain, clean_tx, requested_chain, clean_tx),
                ).fetchone()
            finally:
                conn.close()
            if row and row["block_number"] is not None:
                centers.append(int(row["block_number"]))
        for pool in group.get("pool_addresses") or []:
            clean_pool = str(pool or "").strip().lower()
            if not clean_pool:
                continue
            conn = _get_db()
            conn.row_factory = sqlite3.Row
            try:
                pool_rows = conn.execute(
                    """
                    SELECT block_number
                    FROM swaps
                    WHERE lower(chain) = ? AND lower(coalesce(pool, '')) = ?
                    ORDER BY block_number DESC
                    LIMIT 3
                    """,
                    (requested_chain, clean_pool),
                ).fetchall()
            finally:
                conn.close()
            centers.extend(int(row["block_number"]) for row in pool_rows if row["block_number"] is not None)
        for center in sorted(set(centers))[:5]:
            start_block = max(0, center - safe_radius)
            end_block = center + safe_radius
            block_count = end_block - start_block + 1
            anchors.append({
                "window_name": f"{group.get('token_symbol')}_family_context_{center}",
                "chain": requested_chain,
                "center_block": center,
                "start_block": start_block,
                "end_block": end_block,
                "block_count": block_count,
                "reason": "collect neighboring raw blocks around observed family-context tx/pool activity",
                "would_collect_data": False,
                "would_write": False,
            })
            planned_blocks.update(range(start_block, end_block + 1))

        token_plans.append({
            "token_symbol": group.get("token_symbol"),
            "venue_family": group.get("venue_family"),
            "factory_address": group.get("factory_address"),
            "current_pool_context_count": group.get("pool_context_count"),
            "current_tx_context_count": group.get("tx_context_count"),
            "router_or_intermediary_count": group.get("router_or_intermediary_count"),
            "current_readiness": group.get("scoring_readiness"),
            "collection_windows": anchors,
            "planned_blocks": sorted({
                block
                for window in anchors
                for block in range(int(window.get("start_block") or 0), int(window.get("end_block") or -1) + 1)
            })[:safe_max_blocks],
            "target_after_collection": {
                "min_pool_context_count": 3,
                "min_tx_context_count": 5,
                "min_wallet_or_router_context_count": 3,
            },
            "still_not_allowed_after_collection": [
                "client_signal",
                "trade_execution",
                "venue_mapping_without_route_source_proof",
                "source_backed_scoring_without_clean_curated_rows",
            ],
            "would_collect_data": False,
            "would_write": False,
        })

    sorted_blocks = sorted(planned_blocks)[:safe_max_blocks]
    existing_blocks: set[int] = set()
    if sorted_blocks:
        conn = _get_db()
        try:
            placeholders = ",".join("?" for _ in sorted_blocks)
            existing_blocks = {
                int(row[0])
                for row in conn.execute(
                    f"SELECT block_number FROM blocks WHERE lower(chain) = ? AND block_number IN ({placeholders})",
                    (requested_chain, *sorted_blocks),
                ).fetchall()
            }
        finally:
            conn.close()
    target_blocks = [block for block in sorted_blocks if block not in existing_blocks]
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only" if token_plans else "blocked",
        "mode": "unknown_dex_family_context_collection_plan",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "scoring_plan_status": scoring_plan.get("plan_status"),
        "summary": {
            "candidate_token_groups": len(scoring_plan.get("candidate_groups") or []),
            "tokens_selected_for_collection": len(token_plans),
            "collection_windows": sum(len(plan.get("collection_windows") or []) for plan in token_plans),
            "planned_blocks": len(sorted_blocks),
            "existing_blocks": len(existing_blocks),
            "target_missing_blocks": len(target_blocks),
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "token_plans": token_plans,
        "planned_blocks": sorted_blocks,
        "existing_blocks_skipped": sorted(existing_blocks),
        "target_blocks": target_blocks,
        "recommended_future_collection": {
            "collector": "token_market_raw_block_no_wallet_aggregates",
            "max_receipts_per_block": 80 if requested_chain == "bsc" else 40,
            "max_seconds_per_block": 35 if requested_chain == "bsc" else 20,
            "future_confirm_required": "COLLECT_UNKNOWN_DEX_FAMILY_CONTEXT_HISTORY",
            "parallel_writers_allowed": False,
        },
        "disabled_actions": disabled_actions,
        "blockers": list(dict.fromkeys([
            *("no_family_context_tokens_to_collect" for _ in [1] if not token_plans),
            *("no_missing_blocks_to_collect" for _ in [1] if token_plans and not target_blocks),
            "dry_run_only_no_rpc_called",
            "collection_would_still_not_create_client_signal",
            "trade_disabled",
            "venue_mapping_disabled",
        ])),
        "next_safe_step": (
            "confirmed bounded family-context history collection for target_blocks only, or collect more recent generic BSC data first"
        ),
        "would_collect_data": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def run_unknown_dex_family_context_history_collection(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    confirm: str | None = None,
    allow_rpc: bool = False,
    max_receipts_per_block: int | None = None,
    max_seconds_per_block: float | None = None,
) -> dict[str, Any]:
    """Dry-run-first raw block collection for thin Unknown DEX family-context leads."""
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    plan = get_unknown_dex_family_context_collection_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc),
    )
    recommended = plan.get("recommended_future_collection") or {}
    safe_receipt_limit = max(
        1,
        min(
            int(
                max_receipts_per_block
                if max_receipts_per_block is not None
                else recommended.get("max_receipts_per_block") or 80
            ),
            MAX_TX_PER_BLOCK,
        ),
    )
    safe_seconds = max(
        1.0,
        min(
            float(
                max_seconds_per_block
                if max_seconds_per_block is not None
                else recommended.get("max_seconds_per_block") or 35
            ),
            120.0,
        ),
    )
    target_blocks = [
        int(block)
        for block in plan.get("target_blocks") or []
        if str(block).strip().lstrip("-").isdigit() and int(block) >= 0
    ][:safe_max_blocks]
    planned_blocks = [
        int(block)
        for block in plan.get("planned_blocks") or []
        if str(block).strip().lstrip("-").isdigit() and int(block) >= 0
    ][:safe_max_blocks]
    before_counts = _onchain_table_counts()
    before_label_counts = _label_ledger_guard_counts()
    upstream_context_blockers = list(plan.get("blockers") or [])
    blockers = list(dict.fromkeys([
        *("collection_plan_not_ready" for _ in [1] if plan.get("plan_status") != "ready_read_only"),
        *("no_planned_blocks" for _ in [1] if not planned_blocks),
        *("no_missing_blocks_to_collect" for _ in [1] if planned_blocks and not target_blocks),
        *("confirm_required" for _ in [1] if not dry_run and confirm != UNKNOWN_DEX_FAMILY_CONTEXT_HISTORY_COLLECTION_CONFIRM),
    ]))
    common = {
        "ok": True,
        "dry_run": bool(dry_run),
        "collection_status": "ready_but_disabled" if not blockers else "blocked",
        "mode": "unknown_dex_family_context_history_collection",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "plan": plan,
        "planned_blocks": planned_blocks,
        "existing_blocks_skipped": plan.get("existing_blocks_skipped") or [],
        "target_blocks": target_blocks,
        "token_plans": plan.get("token_plans") or [],
        "upstream_context_blockers": upstream_context_blockers,
        "max_receipts_per_block": safe_receipt_limit,
        "max_seconds_per_block": safe_seconds,
        "confirm_required": UNKNOWN_DEX_FAMILY_CONTEXT_HISTORY_COLLECTION_CONFIRM,
        "before_counts": before_counts,
        "before_label_counts": before_label_counts,
        "write_scope": "raw_data_only_when_confirmed",
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_router_mapping": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "source_policy": (
            "dry-run-first bounded raw block collection for thin Unknown DEX family-context leads. Confirmed writes "
            "are limited to blocks, transactions, swaps, token_transfers, pair_tokens and data_jobs. It never creates "
            "DEX evidence, mappings, labels, trades, wallet orders, client signals or opt-ins."
        ),
    }
    if dry_run or blockers:
        return {
            **common,
            "would_collect_data": bool(target_blocks and not blockers),
            "would_write_raw_data_only": bool(target_blocks and not blockers),
            "raw_data_write_performed": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "blockers": blockers,
        }

    backup_path = _backup_onchain_db("before_unknown_dex_family_context_history_collection")
    job_id = _start_data_job(
        "unknown_dex_family_context_history_collection",
        {
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "target_blocks": target_blocks,
            "window_radius_blocks": safe_radius,
            "max_receipts_per_block": safe_receipt_limit,
            "max_seconds_per_block": safe_seconds,
            "dry_run": False,
        },
    )
    results: list[dict[str, Any]] = []
    try:
        for block_number in target_blocks:
            results.append(
                _ingest_token_market_raw_block_no_wallet_aggregates(
                    requested_chain,
                    block_number,
                    max_receipts_per_block=safe_receipt_limit,
                    max_seconds_per_block=safe_seconds,
                )
            )
        after_counts = _onchain_table_counts()
        after_label_counts = _label_ledger_guard_counts()
        table_deltas = {
            table: int(after_counts.get(table, 0)) - int(before_counts.get(table, 0))
            for table in sorted(set(before_counts) | set(after_counts))
        }
        changed_tables = {table: delta for table, delta in table_deltas.items() if delta != 0}
        disallowed_table_deltas = {
            table: delta
            for table, delta in changed_tables.items()
            if table not in _TOKEN_MARKET_TARGETED_HISTORY_ALLOWED_TABLES
        }
        label_count_deltas = {
            key: int(after_label_counts.get(key, 0)) - int(before_label_counts.get(key, 0))
            for key in sorted(set(before_label_counts) | set(after_label_counts))
        }
        labels_changed = any(delta != 0 for delta in label_count_deltas.values())
        collection_errors = [
            {"block": result.get("block"), "error": result.get("error") or "collection_failed"}
            for result in results
            if not result.get("ok")
        ]
        guard_blockers: list[str] = []
        if collection_errors:
            guard_blockers.append("block_collection_errors")
        if disallowed_table_deltas:
            guard_blockers.append("disallowed_onchain_table_changed")
        if labels_changed:
            guard_blockers.append("label_ledger_changed")
        payload = {
            **common,
            "dry_run": False,
            "collection_status": "completed" if not guard_blockers else "completed_with_guard_blockers",
            "job_id": job_id,
            "backup_path": backup_path,
            "collected": True,
            "results": results,
            "collection_errors": collection_errors,
            "after_counts": after_counts,
            "after_label_counts": after_label_counts,
            "table_deltas": table_deltas,
            "changed_tables": changed_tables,
            "disallowed_table_deltas": disallowed_table_deltas,
            "label_count_deltas": label_count_deltas,
            "labels_changed": labels_changed,
            "would_collect_data": False,
            "would_write_raw_data_only": False,
            "raw_data_write_performed": True,
            "would_write": False,
            "real_write_enabled": True,
            "writes_performed": sum(max(0, int(delta)) for delta in changed_tables.values()),
            "blockers": guard_blockers,
        }
        _finish_data_job(job_id, "ok" if not guard_blockers else "guard_blocked", result=payload)
        return payload
    except Exception as exc:
        _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


def get_unknown_dex_family_context_post_collection_audit(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    allow_rpc: bool = False,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only audit that turns the latest family-context raw collection into research candidates."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only post-collection audit for Unknown DEX family-context data. It reads local blocks, "
        "transactions, swaps, token_transfers, pair_tokens and token_metadata only; no RPC/external calls are made "
        "by default and no candidates, mappings, labels, trades, wallet orders, client signals or opt-ins are created."
    )
    disabled_actions = {
        "candidate_insert": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "venue_mapping": True,
        "dex_router_evidence": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "audit_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_create_candidate_rows": False,
            "would_create_cex_label": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_update_swaps": False,
            "would_execute_trade": False,
            "would_create_wallet_order": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    latest_collection_job = _latest_data_job(["unknown_dex_family_context_history_collection"])
    collection_plan = get_unknown_dex_family_context_collection_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=bool(allow_rpc),
    )
    latest_collection_result = latest_collection_job.get("result") if latest_collection_job else {}
    latest_collection_plan = (latest_collection_result or {}).get("plan") or {}
    planned_blocks = [
        int(block)
        for block in collection_plan.get("planned_blocks") or []
        if str(block).strip().lstrip("-").isdigit() and int(block) >= 0
    ][:safe_max_blocks]
    using_latest_job_fallback = False
    if not planned_blocks and latest_collection_result:
        planned_blocks = [
            int(block)
            for block in (
                (latest_collection_result or {}).get("planned_blocks")
                or latest_collection_plan.get("planned_blocks")
                or []
            )
            if str(block).strip().lstrip("-").isdigit() and int(block) >= 0
        ][:safe_max_blocks]
        using_latest_job_fallback = bool(planned_blocks)
    token_plans_for_symbols = (
        collection_plan.get("token_plans")
        or (latest_collection_result or {}).get("token_plans")
        or latest_collection_plan.get("token_plans")
        or []
    )
    token_plan_symbols = {
        str(plan.get("token_symbol") or "").strip().upper()
        for plan in token_plans_for_symbols
        if str(plan.get("token_symbol") or "").strip()
    }
    blockers = list(dict.fromkeys([
        *(
            "collection_plan_not_ready"
            for _ in [1]
            if collection_plan.get("plan_status") != "ready_read_only" and not using_latest_job_fallback
        ),
        *("no_planned_blocks_for_post_collection_audit" for _ in [1] if not planned_blocks),
    ]))
    if blockers:
        return {
            "ok": True,
            "dry_run": True,
            "audit_status": "blocked",
            "mode": "unknown_dex_family_context_post_collection_audit",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "planned_blocks": planned_blocks,
            "latest_collection_job": latest_collection_job,
            "blockers": blockers,
            "disabled_actions": disabled_actions,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_create_candidate_rows": False,
            "would_create_cex_label": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_update_swaps": False,
            "would_execute_trade": False,
            "would_create_wallet_order": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    placeholders = ",".join("?" for _ in planned_blocks)
    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        metadata_cache = _load_token_metadata_cache(conn)
        present_blocks = {
            int(row["block_number"])
            for row in conn.execute(
                f"SELECT block_number FROM blocks WHERE lower(chain) = ? AND block_number IN ({placeholders})",
                (requested_chain, *planned_blocks),
            ).fetchall()
        }
        tx_summary = conn.execute(
            f"""
            SELECT COUNT(*) AS tx_rows,
                   COUNT(DISTINCT LOWER(from_addr)) AS from_addresses,
                   COUNT(DISTINCT LOWER(to_addr)) AS to_addresses,
                   MIN(timestamp) AS first_timestamp,
                   MAX(timestamp) AS last_timestamp
            FROM transactions
            WHERE lower(chain) = ? AND block_number IN ({placeholders})
            """,
            (requested_chain, *planned_blocks),
        ).fetchone()
        swap_rows = conn.execute(
            f"""
            SELECT s.tx_hash, s.block_number, s.timestamp, LOWER(COALESCE(s.wallet, '')) AS wallet,
                   COALESCE(s.dex, '') AS dex, LOWER(COALESCE(s.token_in, '')) AS token_in,
                   LOWER(COALESCE(s.token_out, '')) AS token_out, COALESCE(s.amount_usd, 0) AS amount_usd,
                   LOWER(COALESCE(s.pool, '')) AS pool, COALESCE(s.token_identity_quality, '') AS token_identity_quality,
                   COALESCE(s.pair_rpc_source, '') AS pair_rpc_source, LOWER(COALESCE(s.router_addr, '')) AS router_addr,
                   COALESCE(s.venue_source, '') AS venue_source, COALESCE(s.venue_confidence, 0) AS venue_confidence,
                   LOWER(COALESCE(p.token0, '')) AS pair_token0, LOWER(COALESCE(p.token1, '')) AS pair_token1,
                   COALESCE(p.rpc_source, '') AS pair_tokens_rpc_source
            FROM swaps s
            LEFT JOIN pair_tokens p
              ON lower(p.chain) = lower(s.chain) AND lower(p.pool) = lower(s.pool)
            WHERE lower(s.chain) = ? AND s.block_number IN ({placeholders})
            ORDER BY s.block_number, s.tx_hash
            LIMIT 5000
            """,
            (requested_chain, *planned_blocks),
        ).fetchall()
        transfer_rows = conn.execute(
            f"""
            SELECT tx_hash, log_index, block_number, timestamp, LOWER(COALESCE(token, '')) AS token,
                   LOWER(COALESCE(from_addr, '')) AS from_addr, LOWER(COALESCE(to_addr, '')) AS to_addr,
                   COALESCE(value_raw, '') AS value_raw, COALESCE(source, '') AS source
            FROM token_transfers
            WHERE lower(chain) = ? AND block_number IN ({placeholders})
            ORDER BY block_number, tx_hash, log_index
            LIMIT 12000
            """,
            (requested_chain, *planned_blocks),
        ).fetchall()
    finally:
        conn.close()

    token_stats: dict[str, dict[str, Any]] = {}
    pool_stats: dict[str, dict[str, Any]] = {}
    address_stats: dict[str, dict[str, Any]] = {}
    infrastructure_addresses = {
        str(address or "").strip().lower()
        for address, meta in (_MAJOR_TOKENS.get(requested_chain, {}) or {}).items()
        if (
            str((meta or {}).get("symbol") or "").strip().upper() in INFRASTRUCTURE_TOKEN_SYMBOLS
            or str((meta or {}).get("coin_id") or "").strip().lower() in INFRASTRUCTURE_TOKEN_COIN_ID_SYMBOLS
        )
    }

    def _token_stat(token: str) -> dict[str, Any] | None:
        clean = str(token or "").strip().lower()
        if not _is_evm_address(clean):
            return None
        meta = _token_metadata_for(requested_chain, clean, metadata_cache)
        coin_id = str(meta.get("coin_id") or "").strip().lower()
        symbol = str(meta.get("symbol") or INFRASTRUCTURE_TOKEN_COIN_ID_SYMBOLS.get(coin_id) or "").strip().upper()
        entry = token_stats.setdefault(clean, {
            "chain": requested_chain,
            "token_address": clean,
            "token_symbol": symbol or None,
            "token_name": str(meta.get("name") or "").strip() or None,
            "metadata_resolved": bool(symbol or meta.get("decimals") is not None),
            "decimals": meta.get("decimals"),
            "infrastructure_token": bool(
                (symbol and symbol in INFRASTRUCTURE_TOKEN_SYMBOLS)
                or clean in infrastructure_addresses
                or coin_id in INFRASTRUCTURE_TOKEN_COIN_ID_SYMBOLS
            ),
            "family_context_symbol_match": bool(symbol and symbol in token_plan_symbols),
            "family_context_match_basis": "symbol_only_context_not_identity" if symbol and symbol in token_plan_symbols else None,
            "source_tables": set(),
            "swap_rows": 0,
            "transfer_rows": 0,
            "pair_rows": 0,
            "distinct_pools": set(),
            "distinct_wallets": set(),
            "distinct_blocks": set(),
            "router_or_intermediary_addresses": set(),
            "venue_names": set(),
            "max_venue_confidence": 0.0,
        })
        return entry

    def _address_stat(address: str, role: str, token: str | None = None, block_number: Any | None = None) -> None:
        clean = str(address or "").strip().lower()
        if not _is_evm_address(clean):
            return
        entry = address_stats.setdefault(clean, {
            "address": clean,
            "transfer_rows": 0,
            "swap_rows": 0,
            "roles": set(),
            "tokens": set(),
            "blocks": set(),
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
        })
        entry["roles"].add(role)
        if role.startswith("transfer_"):
            entry["transfer_rows"] += 1
        if role in {"swap_wallet", "router_or_intermediary_context", "swap_pool"}:
            entry["swap_rows"] += 1
        if token:
            entry["tokens"].add(str(token).lower())
        if block_number is not None:
            entry["blocks"].add(int(block_number))

    for row in swap_rows:
        pool = str(row["pool"] or "").strip().lower()
        router_addr = str(row["router_addr"] or "").strip().lower()
        wallet = str(row["wallet"] or "").strip().lower()
        dex = str(row["dex"] or "").strip() or "Unknown DEX"
        venue_confidence = float(row["venue_confidence"] or 0.0)
        if pool:
            pool_entry = pool_stats.setdefault(pool, {
                "chain": requested_chain,
                "pool_address": pool,
                "swap_rows": 0,
                "tx_hashes": set(),
                "wallets": set(),
                "routers": set(),
                "tokens": set(),
                "venue_names": set(),
                "venue_sources": set(),
                "max_venue_confidence": 0.0,
                "pair_tokens_bound": bool(row["pair_token0"] and row["pair_token1"]),
                "token0": row["pair_token0"] or None,
                "token1": row["pair_token1"] or None,
                "pair_tokens_rpc_source": row["pair_tokens_rpc_source"] or row["pair_rpc_source"] or None,
            })
            pool_entry["swap_rows"] += 1
            pool_entry["tx_hashes"].add(str(row["tx_hash"] or "").lower())
            if wallet:
                pool_entry["wallets"].add(wallet)
            if router_addr:
                pool_entry["routers"].add(router_addr)
            for token in (row["token_in"], row["token_out"], row["pair_token0"], row["pair_token1"]):
                if _is_evm_address(token):
                    pool_entry["tokens"].add(str(token).lower())
            pool_entry["venue_names"].add(dex)
            if row["venue_source"]:
                pool_entry["venue_sources"].add(str(row["venue_source"]))
            pool_entry["max_venue_confidence"] = max(float(pool_entry["max_venue_confidence"]), venue_confidence)
        token_sources: dict[str, set[str]] = {}
        for token, source_table in (
            (row["token_in"], "swaps"),
            (row["token_out"], "swaps"),
            (row["pair_token0"], "pair_tokens"),
            (row["pair_token1"], "pair_tokens"),
        ):
            if _is_evm_address(token):
                token_sources.setdefault(str(token).lower(), set()).add(source_table)
        for token, source_tables in token_sources.items():
            stat = _token_stat(token)
            if not stat:
                continue
            stat["source_tables"].update(source_tables)
            if "swaps" in source_tables:
                stat["swap_rows"] += 1
            if "pair_tokens" in source_tables:
                stat["pair_rows"] += 1
            if pool:
                stat["distinct_pools"].add(pool)
            if wallet:
                stat["distinct_wallets"].add(wallet)
            if row["block_number"] is not None:
                stat["distinct_blocks"].add(int(row["block_number"]))
            if router_addr:
                stat["router_or_intermediary_addresses"].add(router_addr)
            stat["venue_names"].add(dex)
            stat["max_venue_confidence"] = max(float(stat["max_venue_confidence"]), venue_confidence)
        _address_stat(wallet, "swap_wallet", block_number=row["block_number"])
        _address_stat(router_addr, "router_or_intermediary_context", block_number=row["block_number"])
        _address_stat(pool, "swap_pool", block_number=row["block_number"])

    for row in transfer_rows:
        token = str(row["token"] or "").strip().lower()
        stat = _token_stat(token)
        if stat:
            stat["source_tables"].add("token_transfers")
            stat["transfer_rows"] += 1
            if row["from_addr"]:
                stat["distinct_wallets"].add(str(row["from_addr"]).lower())
            if row["to_addr"]:
                stat["distinct_wallets"].add(str(row["to_addr"]).lower())
            if row["block_number"] is not None:
                stat["distinct_blocks"].add(int(row["block_number"]))
        _address_stat(row["from_addr"], "transfer_from", token=token, block_number=row["block_number"])
        _address_stat(row["to_addr"], "transfer_to", token=token, block_number=row["block_number"])

    token_candidates: list[dict[str, Any]] = []
    for stat in token_stats.values():
        source_tables = sorted(stat["source_tables"])
        observation_count = int(stat["swap_rows"]) + int(stat["transfer_rows"]) + int(stat["pair_rows"])
        metadata_resolved = bool(stat["metadata_resolved"])
        infrastructure = bool(stat["infrastructure_token"])
        has_pool_or_swap = bool(stat["swap_rows"] or stat["pair_rows"])
        quality_score = min(
            100,
            int(stat["swap_rows"]) * 12
            + min(25, int(stat["transfer_rows"]) * 2)
            + len(stat["distinct_pools"]) * 15
            + min(20, len(stat["distinct_wallets"]) * 2)
            + (10 if metadata_resolved else 0)
            + (10 if stat["family_context_symbol_match"] else 0)
            - (35 if infrastructure else 0),
        )
        blockers_for_research = list(dict.fromkeys([
            *("infrastructure_token_deprioritized" for _ in [1] if infrastructure),
            *("token_metadata_missing" for _ in [1] if not metadata_resolved),
            *("no_swap_or_pool_context" for _ in [1] if not has_pool_or_swap),
            *("too_few_swap_rows" for _ in [1] if int(stat["swap_rows"]) < 3),
            *("too_few_distinct_pools" for _ in [1] if len(stat["distinct_pools"]) < 2),
            *("family_context_match_is_symbol_only_not_address_proof" for _ in [1] if stat["family_context_symbol_match"]),
            "route_source_proof_missing",
            "no_price_or_outcome_backtest",
            "liquidity_slippage_mev_model_missing",
            "client_signal_disabled",
            "trade_disabled",
        ]))
        if infrastructure:
            candidate_status = "blocked_infrastructure_token"
        elif not metadata_resolved:
            candidate_status = "blocked_metadata_missing"
        elif has_pool_or_swap and observation_count >= 2:
            candidate_status = "post_collection_research_candidate"
        elif stat["transfer_rows"]:
            candidate_status = "transfer_only_context_not_enough"
        else:
            candidate_status = "blocked_thin_context"
        token_candidates.append({
            "chain": stat["chain"],
            "token_address": stat["token_address"],
            "token_symbol": stat["token_symbol"],
            "token_name": stat["token_name"],
            "metadata_resolved": metadata_resolved,
            "infrastructure_token": infrastructure,
            "family_context_symbol_match": bool(stat["family_context_symbol_match"]),
            "family_context_match_basis": stat["family_context_match_basis"],
            "observation_count": observation_count,
            "swap_rows": int(stat["swap_rows"]),
            "transfer_rows": int(stat["transfer_rows"]),
            "pair_rows": int(stat["pair_rows"]),
            "distinct_pools": len(stat["distinct_pools"]),
            "distinct_wallets": len(stat["distinct_wallets"]),
            "distinct_blocks": len(stat["distinct_blocks"]),
            "router_or_intermediary_addresses": sorted(stat["router_or_intermediary_addresses"])[:10],
            "venue_names": sorted(stat["venue_names"])[:10],
            "max_venue_confidence": round(float(stat["max_venue_confidence"]), 3),
            "source_tables": source_tables,
            "quality_score": quality_score,
            "candidate_status": candidate_status,
            "blockers_for_source_backed_scoring": blockers_for_research,
            "can_feed_source_backed_scoring": False,
            "can_feed_client_signal": False,
            "can_feed_trade_agent": False,
            "would_create_candidate_row": False,
            "would_write": False,
        })
    token_candidates.sort(
        key=lambda row: (
            row["candidate_status"] == "post_collection_research_candidate",
            not row["infrastructure_token"],
            int(row["quality_score"]),
            int(row["swap_rows"]),
            int(row["transfer_rows"]),
            str(row["token_symbol"] or ""),
        ),
        reverse=True,
    )

    pool_candidates: list[dict[str, Any]] = []
    for pool in pool_stats.values():
        token_symbols: list[str] = []
        for token in sorted(pool["tokens"]):
            meta = _token_metadata_for(requested_chain, token, metadata_cache)
            coin_id = str(meta.get("coin_id") or "").strip().lower()
            symbol = str(meta.get("symbol") or INFRASTRUCTURE_TOKEN_COIN_ID_SYMBOLS.get(coin_id) or "").strip().upper()
            if symbol:
                token_symbols.append(symbol)
        blockers_for_pool = list(dict.fromkeys([
            *("pair_tokens_missing" for _ in [1] if not pool["pair_tokens_bound"]),
            *("too_few_pool_swaps" for _ in [1] if int(pool["swap_rows"]) < 3),
            *("router_or_intermediary_unmapped" for _ in [1] if pool["routers"]),
            "official_route_source_proof_required",
            "no_mapping_from_pool_context_only",
            "client_signal_disabled",
            "trade_disabled",
        ]))
        pool_candidates.append({
            "chain": pool["chain"],
            "pool_address": pool["pool_address"],
            "swap_rows": int(pool["swap_rows"]),
            "distinct_transactions": len(pool["tx_hashes"]),
            "distinct_wallets": len(pool["wallets"]),
            "routers_or_intermediaries": sorted(pool["routers"])[:10],
            "token_addresses": sorted(pool["tokens"])[:10],
            "token_symbols": sorted(set(token_symbols))[:10],
            "venue_names": sorted(pool["venue_names"])[:10],
            "venue_sources": sorted(pool["venue_sources"])[:10],
            "max_venue_confidence": round(float(pool["max_venue_confidence"]), 3),
            "pair_tokens_bound": bool(pool["pair_tokens_bound"]),
            "pair_tokens_rpc_source": pool["pair_tokens_rpc_source"],
            "pool_candidate_status": (
                "pool_context_candidate_for_trace_or_source_repair"
                if pool["pair_tokens_bound"] else "blocked_pair_tokens_missing"
            ),
            "blockers_for_mapping_or_scoring": blockers_for_pool,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "would_write": False,
        })
    pool_candidates.sort(
        key=lambda row: (
            bool(row["pair_tokens_bound"]),
            int(row["swap_rows"]),
            int(row["distinct_wallets"]),
            str(row["pool_address"]),
        ),
        reverse=True,
    )

    address_candidates = []
    for entry in address_stats.values():
        address_candidates.append({
            "address": entry["address"],
            "transfer_rows": int(entry["transfer_rows"]),
            "swap_rows": int(entry["swap_rows"]),
            "roles": sorted(entry["roles"]),
            "distinct_tokens": len(entry["tokens"]),
            "distinct_blocks": len(entry["blocks"]),
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "context_only": True,
        })
    address_candidates.sort(
        key=lambda row: (
            int(row["transfer_rows"]) + int(row["swap_rows"]),
            int(row["distinct_tokens"]),
            str(row["address"]),
        ),
        reverse=True,
    )

    post_collection_candidates = [
        row
        for row in token_candidates
        if row["candidate_status"] == "post_collection_research_candidate"
    ]
    audit_blockers = list(dict.fromkeys([
        *("no_present_blocks_in_collection_window" for _ in [1] if not present_blocks),
        *("no_raw_swaps_in_collection_window" for _ in [1] if not swap_rows),
        *("no_raw_transfers_in_collection_window" for _ in [1] if not transfer_rows),
        *("no_non_infrastructure_research_candidates" for _ in [1] if not post_collection_candidates),
        "source_backed_scoring_disabled",
        "client_signal_disabled",
        "trade_disabled",
        "venue_mapping_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "audit_status": "ready_read_only" if present_blocks and (swap_rows or transfer_rows) else "blocked",
        "mode": "unknown_dex_family_context_post_collection_audit",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "collection_window": {
            "planned_blocks": planned_blocks,
            "present_blocks": sorted(present_blocks),
            "missing_blocks": [block for block in planned_blocks if block not in present_blocks],
            "target_blocks_remaining": collection_plan.get("target_blocks") or [],
            "latest_collection_job": latest_collection_job,
            "used_latest_collection_job_fallback": using_latest_job_fallback,
        },
        "summary": {
            "blocks_planned": len(planned_blocks),
            "blocks_present": len(present_blocks),
            "transactions_in_window": int(tx_summary["tx_rows"] or 0) if tx_summary else 0,
            "from_addresses_in_window": int(tx_summary["from_addresses"] or 0) if tx_summary else 0,
            "to_addresses_in_window": int(tx_summary["to_addresses"] or 0) if tx_summary else 0,
            "raw_swaps_in_window": len(swap_rows),
            "raw_transfers_in_window": len(transfer_rows),
            "tokens_observed": len(token_candidates),
            "post_collection_research_candidates": len(post_collection_candidates),
            "infrastructure_tokens_deprioritized": sum(1 for row in token_candidates if row["infrastructure_token"]),
            "metadata_missing_tokens": sum(1 for row in token_candidates if not row["metadata_resolved"]),
            "pool_candidates": len(pool_candidates),
            "pair_bound_pool_candidates": sum(1 for row in pool_candidates if row["pair_tokens_bound"]),
            "address_context_candidates": len(address_candidates),
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "collection_plan_summary": collection_plan.get("summary") or latest_collection_plan.get("summary") or {},
        "family_context_symbols": sorted(token_plan_symbols),
        "token_candidates": token_candidates[:safe_candidate_limit],
        "pool_candidates": pool_candidates[:safe_candidate_limit],
        "address_context_candidates": address_candidates[:safe_candidate_limit],
        "policy_gates_before_use": [
            "metadata_repair_for_unknown_tokens",
            "route_level_source_backing",
            "router_or_intermediary_identity_resolution",
            "repeatable_clean_rows_across_more_windows",
            "price_outcome_backtest",
            "liquidity_slippage_mev_model",
            "client_policy_and_opt_in",
        ],
        "disabled_actions": disabled_actions,
        "blockers": audit_blockers,
        "next_safe_step": (
            "metadata_and_route_source_repair_for_top_post_collection_candidates_read_only"
            if post_collection_candidates else "collect_more_bounded_raw_context_or_repair_metadata_read_only"
        ),
        "would_call_rpc": False,
        "would_call_external": False,
        "would_create_candidate_rows": False,
        "would_score_for_client": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_unknown_dex_family_context_candidate_repair_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only repair plan for candidates found by the family-context post-collection audit."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only repair plan for Unknown DEX family-context research candidates. It reads the "
        "post-collection audit only, plans metadata/source/route repair, and creates no candidate rows, labels, "
        "router evidence, mappings, trades, wallet orders, client signals or opt-ins."
    )
    disabled_actions = {
        "candidate_insert": True,
        "metadata_write": True,
        "route_source_write": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "venue_mapping": True,
        "dex_router_evidence": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_enrich_metadata": False,
        "would_create_candidate_rows": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    audit = get_unknown_dex_family_context_post_collection_audit(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        allow_rpc=False,
        candidate_limit=safe_candidate_limit,
    )
    audit_summary = audit.get("summary") or {}
    audit_ready = audit.get("audit_status") == "ready_read_only"
    if not audit_ready:
        return {
            "ok": True,
            "dry_run": True,
            "plan_status": "blocked",
            "mode": "unknown_dex_family_context_candidate_repair_plan",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "source_audit_status": audit.get("audit_status"),
            "collection_window": audit.get("collection_window") or {},
            "latest_collection_job": (audit.get("collection_window") or {}).get("latest_collection_job"),
            "summary": {
                "repair_candidates": 0,
                "metadata_repair_required": 0,
                "route_source_repair_required": 0,
                "pool_context_repair_required": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "audit_summary": audit_summary,
            "candidate_repair_rows": [],
            "metadata_repair_rows": [],
            "route_source_repair_rows": [],
            "pool_repair_rows": [],
            "required_before_source_backed_scoring": [
                "post_collection_audit_ready",
                "metadata_resolved",
                "exact_route_source_proof",
                "router_or_intermediary_identity_resolved",
                "repeatable_clean_rows_across_more_windows",
                "price_outcome_backtest",
                "liquidity_slippage_mev_model",
                "client_policy_and_opt_in",
            ],
            "policy_gates_before_use": [
                "post_collection_audit_ready",
                "metadata_resolution",
                "exact_route_source_proof",
                "repeatability_across_windows",
                "liquidity_slippage_mev_model",
                "client_policy_and_opt_in",
            ],
            "blockers": list(dict.fromkeys(["post_collection_audit_not_ready", *(audit.get("blockers") or [])])),
            "next_safe_step": "repair_or_collect_more_local_context_before_candidate_use",
            **common_disabled,
        }

    token_rows = list(audit.get("token_candidates") or [])[:safe_candidate_limit]
    pool_rows = list(audit.get("pool_candidates") or [])[:safe_candidate_limit]
    candidate_repair_rows: list[dict[str, Any]] = []
    metadata_repair_rows: list[dict[str, Any]] = []
    route_source_repair_rows: list[dict[str, Any]] = []
    excluded_candidates: list[dict[str, Any]] = []

    def _repair_key(prefix: str, payload: dict[str, Any]) -> str:
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str)
        return f"{prefix}:{hashlib.sha256(canonical.encode('utf-8')).hexdigest()}"

    for row in token_rows:
        token_address = str(row.get("token_address") or "").strip().lower()
        token_symbol = str(row.get("token_symbol") or "").strip() or None
        infrastructure = bool(row.get("infrastructure_token"))
        metadata_resolved = bool(row.get("metadata_resolved"))
        candidate_status = str(row.get("candidate_status") or "").strip()
        if infrastructure:
            excluded_candidates.append({
                "token_address": token_address,
                "token_symbol": token_symbol,
                "exclusion_reason": "infrastructure_token_deprioritized",
                "would_write": False,
            })
            continue
        needs_metadata = not metadata_resolved
        has_market_context = candidate_status == "post_collection_research_candidate"
        has_pool_or_swap_context = int(row.get("swap_rows") or 0) > 0 or int(row.get("pair_rows") or 0) > 0
        repair_lanes = list(dict.fromkeys([
            *("metadata_resolution_read_only" for _ in [1] if needs_metadata),
            *("route_source_repair_read_only" for _ in [1] if has_market_context or has_pool_or_swap_context),
            *("pool_context_trace_read_only" for _ in [1] if int(row.get("distinct_pools") or 0) > 0),
            "repeatability_window_collection_plan_read_only",
        ]))
        blockers = list(dict.fromkeys([
            "candidate_is_context_only_not_source_backed",
            *("token_metadata_repair_required" for _ in [1] if needs_metadata),
            *("candidate_not_ready_market_context" for _ in [1] if not has_market_context),
            *("symbol_only_family_context_not_address_proof" for _ in [1] if row.get("family_context_match_basis")),
            "exact_route_source_proof_required",
            "repeatability_across_more_windows_required",
            "liquidity_slippage_mev_model_required",
            "client_signal_disabled",
            "trade_disabled",
        ]))
        key_payload = {
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "token_address": token_address,
            "token_symbol": token_symbol,
            "candidate_status": candidate_status,
            "source_tables": row.get("source_tables") or [],
        }
        candidate_repair_rows.append({
            "chain": requested_chain,
            "token_address": token_address,
            "token_symbol": token_symbol,
            "token_name": row.get("token_name"),
            "candidate_status": candidate_status,
            "repair_status": (
                "route_source_repair_required"
                if has_market_context and not needs_metadata else
                "metadata_repair_required_before_route_source"
                if needs_metadata else
                "more_local_context_required"
            ),
            "repair_plan_dedupe_key": _repair_key("unknown_dex_candidate_repair", key_payload),
            "metadata_resolved": metadata_resolved,
            "family_context_symbol_match": bool(row.get("family_context_symbol_match")),
            "family_context_match_basis": row.get("family_context_match_basis"),
            "quality_score": int(row.get("quality_score") or 0),
            "research_priority_score": int(row.get("quality_score") or 0),
            "swap_rows": int(row.get("swap_rows") or 0),
            "transfer_rows": int(row.get("transfer_rows") or 0),
            "pair_rows": int(row.get("pair_rows") or 0),
            "distinct_pools": int(row.get("distinct_pools") or 0),
            "distinct_wallets": int(row.get("distinct_wallets") or 0),
            "venue_names": list(row.get("venue_names") or []),
            "source_tables": list(row.get("source_tables") or []),
            "repair_lanes": repair_lanes,
            "blockers": blockers,
            "context_only": True,
            "not_source_backed": True,
            "not_client_ready": True,
            "safe_for_source_backed_scoring_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "would_create_candidate_row": False,
            "would_write": False,
        })
        if needs_metadata:
            metadata_repair_rows.append({
                "chain": requested_chain,
                "token_address": token_address,
                "token_symbol": token_symbol,
                "metadata_repair_status": "metadata_resolution_required",
                "required_fields": ["symbol", "name", "decimals", "source", "observed_at"],
                "allowed_sources_next": ["local token_metadata cache", "bounded RPC metadata read in a separate confirmed goal"],
                "would_enrich_metadata": False,
                "would_write": False,
            })
        if has_market_context or has_pool_or_swap_context:
            route_source_repair_rows.append({
                "chain": requested_chain,
                "token_address": token_address,
                "token_symbol": token_symbol,
                "route_source_repair_status": "exact_route_source_proof_required",
                "current_route_state": "local_context_only_not_source_backed",
                "required_evidence": [
                    "exact token address bound to source",
                    "exact pool/router/factory source",
                    "repeatable rows across more than one local window",
                    "non-symbol-only family context proof",
                ],
                "not_enough_as_final_proof": [
                    "token symbol match",
                    "local swap row only",
                    "pair_tokens RPC only",
                    "single-window observation",
                ],
                "would_create_dex_router_evidence": False,
                "would_create_mapping": False,
                "would_create_client_signal": False,
                "would_write": False,
            })

    pool_repair_rows: list[dict[str, Any]] = []
    for pool in pool_rows:
        pool_address = str(pool.get("pool_address") or "").strip().lower()
        pool_repair_rows.append({
            "chain": requested_chain,
            "pool_address": pool_address,
            "pool_candidate_status": pool.get("pool_candidate_status"),
            "pool_repair_status": (
                "pool_route_source_repair_required"
                if pool.get("pair_tokens_bound") else "pair_tokens_repair_required"
            ),
            "token_addresses": list(pool.get("token_addresses") or []),
            "token_symbols": list(pool.get("token_symbols") or []),
            "swap_rows": int(pool.get("swap_rows") or 0),
            "distinct_transactions": int(pool.get("distinct_transactions") or 0),
            "distinct_wallets": int(pool.get("distinct_wallets") or 0),
            "pair_tokens_bound": bool(pool.get("pair_tokens_bound")),
            "pair_tokens_rpc_source": pool.get("pair_tokens_rpc_source"),
            "required_evidence": [
                "exact pool address source",
                "factory or protocol source",
                "token pair still matches local pair_tokens",
                "router/intermediary identity if present",
            ],
            "blockers": list(pool.get("blockers_for_mapping_or_scoring") or []),
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
        })

    repair_blockers = list(dict.fromkeys([
        *("no_non_infrastructure_candidates_to_repair" for _ in [1] if not candidate_repair_rows),
        "source_backed_scoring_disabled_until_repairs_complete",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only" if candidate_repair_rows else "blocked",
        "mode": "unknown_dex_family_context_candidate_repair_plan",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "source_audit_status": audit.get("audit_status"),
        "collection_window": audit.get("collection_window") or {},
        "latest_collection_job": (audit.get("collection_window") or {}).get("latest_collection_job"),
        "summary": {
            "repair_candidates": len(candidate_repair_rows),
            "metadata_repair_required": len(metadata_repair_rows),
            "route_source_repair_required": len(route_source_repair_rows),
            "pool_context_repair_required": len(pool_repair_rows),
            "excluded_infrastructure_candidates": len(excluded_candidates),
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "audit_summary": audit_summary,
        "candidate_repair_rows": candidate_repair_rows[:safe_candidate_limit],
        "metadata_repair_rows": metadata_repair_rows[:safe_candidate_limit],
        "route_source_repair_rows": route_source_repair_rows[:safe_candidate_limit],
        "pool_repair_rows": pool_repair_rows[:safe_candidate_limit],
        "excluded_candidates": excluded_candidates[:safe_candidate_limit],
        "required_before_source_backed_scoring": [
            "metadata_resolved",
            "exact_route_source_proof",
            "router_or_intermediary_identity_resolved",
            "repeatable_clean_rows_across_more_windows",
            "price_outcome_backtest",
            "liquidity_slippage_mev_model",
            "client_policy_and_opt_in",
        ],
        "policy_gates_before_use": [
            "metadata_resolution_for_unknown_tokens",
            "exact_route_source_proof",
            "pool_router_factory_context_repair",
            "repeatability_across_more_windows",
            "liquidity_slippage_mev_model",
            "shadow_backtest_before_signal",
            "client_policy_and_opt_in_before_any_client_action",
        ],
        "blockers": repair_blockers,
        "next_safe_step": (
            "metadata_and_route_source_repair_dry_run_for_top_candidates"
            if candidate_repair_rows else "collect_more_bounded_raw_context_or_repair_metadata_inputs"
        ),
        **common_disabled,
    }


def get_unknown_dex_family_context_casefile(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only casefile explaining family-context candidates and why they remain blocked."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only family-context casefile. It turns Unknown DEX pool/factory context into "
        "human-readable research cases, separates symbol-only hints from address proof, and creates no candidate "
        "rows, labels, router evidence, mappings, trades, wallet orders, client signals or opt-ins."
    )
    disabled_actions = {
        "candidate_insert": True,
        "metadata_write": True,
        "route_source_write": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "venue_mapping": True,
        "dex_router_evidence": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_create_candidate_rows": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "casefile_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    repair = get_unknown_dex_family_context_candidate_repair_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    repair_rows = list(repair.get("candidate_repair_rows") or [])[:safe_candidate_limit]
    route_rows = {
        str(row.get("token_address") or "").strip().lower(): row
        for row in repair.get("route_source_repair_rows") or []
    }
    pool_rows = list(repair.get("pool_repair_rows") or [])[:safe_candidate_limit]

    casefiles: list[dict[str, Any]] = []
    for idx, row in enumerate(repair_rows, start=1):
        token_address = str(row.get("token_address") or "").strip().lower()
        route_repair = route_rows.get(token_address) or {}
        metadata_resolved = bool(row.get("metadata_resolved"))
        symbol_hint = bool(row.get("family_context_symbol_match"))
        address_observed = _valid_evm_address(token_address)
        source_tables = list(row.get("source_tables") or [])
        proof_status = {
            "metadata_resolved": metadata_resolved,
            "token_address_observed_locally": address_observed,
            "family_context_symbol_match": symbol_hint,
            "family_context_match_basis": row.get("family_context_match_basis"),
            "route_source_proof_ready": False,
            "repeatability_ready": False,
            "liquidity_slippage_model_ready": False,
            "client_policy_ready": False,
        }
        why_candidate_matters = list(dict.fromkeys([
            *("metadata is resolved" for _ in [1] if metadata_resolved),
            *("token address is observed in local swaps/transfers/pair rows" for _ in [1] if address_observed),
            *("symbol appears in verified pool/factory family context" for _ in [1] if symbol_hint),
            *("has local swap rows" for _ in [1] if int(row.get("swap_rows") or 0) > 0),
            *("has local transfer rows" for _ in [1] if int(row.get("transfer_rows") or 0) > 0),
            *("has pair/pool context" for _ in [1] if int(row.get("pair_rows") or 0) > 0),
        ]))
        required_next_proofs = [
            "exact route source proof for router/intermediary/pool path",
            "repeatability across more local windows",
            "liquidity/slippage/MEV model",
            "shadow backtest on clean source-backed rows",
            "client policy and opt-in before any client action",
        ]
        casefiles.append({
            "casefile_rank": idx,
            "casefile_status": "research_only_blocked_for_source_backed_use",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "token_address": token_address,
            "token_symbol": row.get("token_symbol"),
            "token_name": row.get("token_name"),
            "candidate_status": row.get("candidate_status"),
            "repair_status": row.get("repair_status"),
            "research_priority_score": int(row.get("research_priority_score") or row.get("quality_score") or 0),
            "observed_context": {
                "swap_rows": int(row.get("swap_rows") or 0),
                "transfer_rows": int(row.get("transfer_rows") or 0),
                "pair_rows": int(row.get("pair_rows") or 0),
                "distinct_pools": int(row.get("distinct_pools") or 0),
                "distinct_wallets": int(row.get("distinct_wallets") or 0),
                "venue_names": list(row.get("venue_names") or []),
                "source_tables": source_tables,
            },
            "proof_status": proof_status,
            "route_source_repair_status": route_repair.get("route_source_repair_status"),
            "not_enough_as_final_proof": route_repair.get("not_enough_as_final_proof") or [
                "symbol-only match",
                "local swap row only",
                "single-window observation",
            ],
            "why_candidate_matters": why_candidate_matters,
            "why_blocked": list(row.get("blockers") or []),
            "required_next_proofs": required_next_proofs,
            "safe_for_source_backed_scoring_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "would_create_candidate_row": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_score_for_client": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_write": False,
        })

    summary = {
        "casefiles": len(casefiles),
        "context_only_casefiles": len(casefiles),
        "source_backed_casefiles": 0,
        "metadata_resolved_casefiles": sum(1 for row in casefiles if row["proof_status"]["metadata_resolved"]),
        "symbol_only_family_matches": sum(1 for row in casefiles if row["proof_status"]["family_context_symbol_match"]),
        "route_source_proof_ready": 0,
        "repeatability_ready": 0,
        "liquidity_slippage_model_ready": 0,
        "source_backed_scoring_ready": 0,
        "client_signal_ready": 0,
        "trade_ready": 0,
        "pool_repair_rows": len(pool_rows),
        "real_write_enabled": False,
    }
    blockers = list(dict.fromkeys([
        *("no_family_context_casefiles" for _ in [1] if not casefiles),
        "casefiles_are_research_only",
        "exact_route_source_proof_required",
        "repeatability_across_more_windows_required",
        "liquidity_slippage_mev_model_required",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "casefile_status": "ready_read_only" if casefiles else "blocked",
        "mode": "unknown_dex_family_context_casefile",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "source_audit_status": repair.get("source_audit_status"),
        "repair_plan_status": repair.get("plan_status"),
        "summary": summary,
        "audit_summary": repair.get("audit_summary") or {},
        "casefiles": casefiles,
        "pool_repair_rows": pool_rows,
        "required_before_source_backed_use": [
            "metadata_resolved",
            "exact token address proof, not symbol-only match",
            "exact route source proof",
            "router/intermediary identity resolved",
            "repeatable clean rows across more windows",
            "liquidity/slippage/MEV model",
            "shadow backtest",
            "client policy and opt-in before any client action",
        ],
        "blockers": blockers,
        "next_safe_step": (
            "route_source_repair_or_repeatability_collection_read_only"
            if casefiles else "run post-collection audit and candidate repair plan first"
        ),
        **common_disabled,
    }


def get_unknown_dex_family_context_route_source_repeatability_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only plan to repair Unknown DEX route/source proof and repeatability gaps."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only Unknown DEX route/source and repeatability repair plan. It reads research-only "
        "casefiles, separates missing route proof from missing repeatability, and creates no labels, router "
        "evidence, mappings, trades, wallet orders, client signals or opt-ins."
    )
    disabled_actions = {
        "route_source_write": True,
        "repeatability_collection_write": True,
        "source_backed_scoring": True,
        "candidate_insert": True,
        "metadata_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_collect_more_windows": False,
        "would_create_candidate_rows": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    casefile_report = get_unknown_dex_family_context_casefile(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    casefiles = list(casefile_report.get("casefiles") or [])[:safe_candidate_limit]
    casefiles_ready = casefile_report.get("casefile_status") == "ready_read_only" and bool(casefiles)

    if not casefiles_ready:
        return {
            "ok": True,
            "dry_run": True,
            "plan_status": "blocked",
            "mode": "unknown_dex_family_context_route_source_repeatability_plan",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "casefile_status": casefile_report.get("casefile_status"),
            "summary": {
                "casefiles_reviewed": 0,
                "route_source_proof_present": 0,
                "route_source_proof_missing": 0,
                "repeatability_present": 0,
                "repeatability_missing": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "casefiles": [],
            "route_source_plans": [],
            "repeatability_plans": [],
            "blockers": list(dict.fromkeys(["casefiles_not_ready", *(casefile_report.get("blockers") or [])])),
            "next_safe_step": "run_unknown_dex_family_context_casefile_first",
            **common_disabled,
        }

    route_source_plans: list[dict[str, Any]] = []
    repeatability_plans: list[dict[str, Any]] = []
    research_casefiles: list[dict[str, Any]] = []

    for casefile in casefiles:
        proof_status = casefile.get("proof_status") or {}
        observed_context = casefile.get("observed_context") or {}
        route_ready = bool(proof_status.get("route_source_proof_ready"))
        repeatability_ready = bool(proof_status.get("repeatability_ready"))
        liquidity_ready = bool(proof_status.get("liquidity_slippage_model_ready"))
        source_backed_ready = bool(route_ready and repeatability_ready and liquidity_ready)
        casefile_rank = int(casefile.get("casefile_rank") or len(research_casefiles) + 1)
        token_address = str(casefile.get("token_address") or "").strip().lower()
        token_symbol = casefile.get("token_symbol")
        route_status = "present" if route_ready else "missing"
        repeatability_status = "present" if repeatability_ready else "missing"

        case_blockers = list(dict.fromkeys([
            *(casefile.get("why_blocked") or []),
            *("exact_route_source_proof_required" for _ in [1] if not route_ready),
            *("repeatability_across_more_windows_required" for _ in [1] if not repeatability_ready),
            *("liquidity_slippage_mev_model_required" for _ in [1] if not liquidity_ready),
            *("source_backed_scoring_still_disabled" for _ in [1] if not source_backed_ready),
            "client_signal_disabled",
            "trade_disabled",
        ]))

        route_source_plans.append({
            "casefile_rank": casefile_rank,
            "chain": requested_chain,
            "token_address": token_address,
            "token_symbol": token_symbol,
            "route_source_status": route_status,
            "current_route_state": (
                "route_source_proof_bound"
                if route_ready else "research_context_only_not_source_backed"
            ),
            "required_route_source_proofs": [
                "exact chain and token address bound to source",
                "exact pool/router/factory source",
                "source digest or immutable snapshot",
                "address-bound payload, not symbol-only proof",
                "no explorer tag or UI hint as final proof by itself",
            ],
            "not_enough_as_final_proof": casefile.get("not_enough_as_final_proof") or [
                "symbol-only match",
                "local swap row only",
                "single-window observation",
            ],
            "allowed_next_checks": [
                "read existing local source registry",
                "compare local pool/router/factory addresses already collected",
                "prepare bounded route-source proof acquisition only under a separate explicit goal",
            ],
            "blocked_until_present": not route_ready,
            "safe_for_mapping_now": False,
            "safe_for_source_backed_scoring_now": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
        })
        repeatability_plans.append({
            "casefile_rank": casefile_rank,
            "chain": requested_chain,
            "token_address": token_address,
            "token_symbol": token_symbol,
            "repeatability_status": repeatability_status,
            "observed_context": {
                "swap_rows": int(observed_context.get("swap_rows") or 0),
                "transfer_rows": int(observed_context.get("transfer_rows") or 0),
                "pair_rows": int(observed_context.get("pair_rows") or 0),
                "distinct_pools": int(observed_context.get("distinct_pools") or 0),
                "distinct_wallets": int(observed_context.get("distinct_wallets") or 0),
            },
            "required_repeatability": [
                "same token address seen across more than one local window",
                "multiple clean swaps or transfers tied to the same address",
                "pool context stays stable across windows",
                "wallet/funding context does not collapse to infrastructure-only tokens",
                "price/liquidity outcome can be replayed in shadow mode",
            ],
            "collection_shape_preview": {
                "mode": "future_bounded_repeatability_collection_only",
                "would_collect_more_windows": False,
                "would_update_swaps": False,
                "requires_separate_confirmed_data_goal": True,
            },
            "blocked_until_present": not repeatability_ready,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "would_write": False,
        })
        research_casefiles.append({
            "casefile_rank": casefile_rank,
            "casefile_status": casefile.get("casefile_status"),
            "token_address": token_address,
            "token_symbol": token_symbol,
            "research_priority_score": int(casefile.get("research_priority_score") or 0),
            "route_source_proof": route_status,
            "repeatability": repeatability_status,
            "source_backed_scoring_ready": source_backed_ready,
            "client_signal_ready": False,
            "trade_ready": False,
            "blockers": case_blockers,
            "research_only": True,
            "would_write": False,
        })

    route_present = sum(1 for row in route_source_plans if row["route_source_status"] == "present")
    repeatability_present = sum(1 for row in repeatability_plans if row["repeatability_status"] == "present")
    scoring_ready = sum(1 for row in research_casefiles if row["source_backed_scoring_ready"])
    blockers = list(dict.fromkeys([
        "casefiles_are_research_only",
        *("exact_route_source_proof_required" for _ in [1] if route_present < len(casefiles)),
        *("repeatability_across_more_windows_required" for _ in [1] if repeatability_present < len(casefiles)),
        *("source_backed_scoring_still_disabled" for _ in [1] if scoring_ready < len(casefiles)),
        "client_signal_disabled",
        "trade_disabled",
    ]))

    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only",
        "mode": "unknown_dex_family_context_route_source_repeatability_plan",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "casefile_status": casefile_report.get("casefile_status"),
        "summary": {
            "casefiles_reviewed": len(casefiles),
            "route_source_proof_present": route_present,
            "route_source_proof_missing": len(casefiles) - route_present,
            "repeatability_present": repeatability_present,
            "repeatability_missing": len(casefiles) - repeatability_present,
            "source_backed_scoring_ready": scoring_ready,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "casefiles": research_casefiles,
        "route_source_plans": route_source_plans,
        "repeatability_plans": repeatability_plans,
        "required_before_source_backed_scoring": [
            "exact_route_source_proof",
            "source_digest_or_immutable_snapshot",
            "repeatability_across_more_windows",
            "pool_wallet_transfer_context_consistent",
            "liquidity_slippage_mev_model",
            "shadow_backtest_on_clean_rows",
            "client_policy_and_opt_in_before_any_client_action",
        ],
        "blockers": blockers,
        "next_safe_step": (
            "exact_route_source_proof_acquisition_plan_read_only"
            if route_present < len(casefiles)
            else "bounded_repeatability_collection_plan_read_only"
            if repeatability_present < len(casefiles)
            else "shadow_backtest_plan_read_only"
        ),
        **common_disabled,
    }


def get_unknown_dex_family_context_exact_route_source_proof_acquisition_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only acquisition plan for exact route/source proof on Unknown DEX casefiles."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only exact route/source proof acquisition plan. It reads the Unknown DEX "
        "route-source/repeatability plan, defines acceptable source packages, and performs no source "
        "acquisition, RPC, scraping, evidence persistence, mapping, signal or trade."
    )
    disabled_actions = {
        "source_acquisition": True,
        "rpc_route_trace": True,
        "external_search": True,
        "scraping": True,
        "route_source_write": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_acquire_source": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_persist_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    route_plan = get_unknown_dex_family_context_route_source_repeatability_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    route_source_plans = list(route_plan.get("route_source_plans") or [])[:safe_candidate_limit]
    casefiles = list(route_plan.get("casefiles") or [])[:safe_candidate_limit]
    route_plan_ready = route_plan.get("plan_status") == "ready_read_only" and bool(route_source_plans)

    if not route_plan_ready:
        return {
            "ok": True,
            "dry_run": True,
            "plan_status": "blocked",
            "mode": "unknown_dex_family_context_exact_route_source_proof_acquisition_plan",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "route_source_plan_status": route_plan.get("plan_status"),
            "summary": {
                "casefiles_reviewed": 0,
                "acquisition_targets": 0,
                "exact_route_source_proof_ready": 0,
                "official_or_canonical_source_required": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "proof_acquisition_plans": [],
            "source_acceptance_policy": {},
            "blockers": list(dict.fromkeys(["route_source_repeatability_plan_not_ready", *(route_plan.get("blockers") or [])])),
            "next_safe_step": "run_route_source_repeatability_plan_first",
            **common_disabled,
        }

    casefile_by_rank = {
        int(row.get("casefile_rank") or 0): row
        for row in casefiles
    }
    proof_acquisition_plans: list[dict[str, Any]] = []
    for route_row in route_source_plans:
        casefile_rank = int(route_row.get("casefile_rank") or len(proof_acquisition_plans) + 1)
        casefile = casefile_by_rank.get(casefile_rank) or {}
        token_address = str(route_row.get("token_address") or casefile.get("token_address") or "").strip().lower()
        token_symbol = route_row.get("token_symbol") or casefile.get("token_symbol")
        route_source_status = str(route_row.get("route_source_status") or "missing").strip().lower()
        proof_ready = route_source_status == "present"
        proof_acquisition_plans.append({
            "casefile_rank": casefile_rank,
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "token_address": token_address,
            "token_symbol": token_symbol,
            "research_priority_score": int(casefile.get("research_priority_score") or 0),
            "route_source_status": route_source_status,
            "acquisition_status": "already_present_no_acquisition_needed" if proof_ready else "planned_read_only",
            "target_identity_hypothesis": "pancakeswap_v2_family_context_only" if factory_address else "unknown_dex_route_context_only",
            "required_proof_package": [
                "official_or_canonical_source_url",
                "exact_chain_id_or_chain_name",
                "exact_token_or_pool_or_router_or_factory_address",
                "source_digest_or_immutable_snapshot",
                "address_bound_payload_json",
                "route_role_classification_router_pool_factory_or_intermediary",
                "negative_check_that_symbol_only_or_explorer_tag_is_not_the_final_proof",
            ],
            "acceptable_source_types": [
                "official protocol documentation",
                "official verified repository or deployment registry",
                "canonical factory/router deployment source",
                "verified onchain contract metadata only when address-bound and corroborated",
                "local official source registry when already populated",
            ],
            "insufficient_source_types": [
                "symbol-only match",
                "single local swap row",
                "single-window observation",
                "explorer tag without address-bound source",
                "Arkham/entity UI hint by itself",
                "social post without contract/deployment binding",
                "generic DEX family context without observed route binding",
            ],
            "allowed_future_acquisition_methods": [
                "local source registry lookup",
                "bounded official/canonical web search under separate explicit goal",
                "bounded RPC/code/trace confirmation under separate explicit goal",
                "manual source-backed intake with digest under separate explicit goal",
            ],
            "blocked_actions": [
                "persist_dex_router_evidence",
                "create_venue_mapping",
                "score_for_client",
                "create_client_signal",
                "execute_trade",
            ],
            "future_confirm_required": "ACQUIRE_UNKNOWN_DEX_EXACT_ROUTE_SOURCE_PROOF",
            "source_backed_scoring_ready": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "would_acquire_source": False,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_scrape": False,
            "would_persist_evidence": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
        })

    proof_ready_count = sum(1 for row in proof_acquisition_plans if row["route_source_status"] == "present")
    blockers = list(dict.fromkeys([
        *("exact_route_source_proof_required" for _ in [1] if proof_ready_count < len(proof_acquisition_plans)),
        "source_acquisition_not_executed_in_this_goal",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only",
        "mode": "unknown_dex_family_context_exact_route_source_proof_acquisition_plan",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "route_source_plan_status": route_plan.get("plan_status"),
        "summary": {
            "casefiles_reviewed": len(route_source_plans),
            "acquisition_targets": len(proof_acquisition_plans),
            "exact_route_source_proof_ready": proof_ready_count,
            "official_or_canonical_source_required": len(proof_acquisition_plans) - proof_ready_count,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "proof_acquisition_plans": proof_acquisition_plans,
        "source_acceptance_policy": {
            "must_be_address_bound": True,
            "must_include_digest_or_snapshot": True,
            "must_separate_router_pool_factory_and_intermediary_roles": True,
            "symbol_only_proof_allowed": False,
            "explorer_tag_only_allowed": False,
            "scraped_ui_only_allowed": False,
            "single_window_only_allowed": False,
            "source_backed_scoring_ready": False,
        },
        "policy_gates": {
            "route_source_gate": "blocked_until_exact_official_or_canonical_source",
            "repeatability_gate": "blocked_until_more_windows_after_source_plan",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": blockers,
        "next_safe_step": "bounded_official_source_lookup_or_manual_source_intake_read_only",
        **common_disabled,
    }


def get_unknown_dex_family_context_bounded_official_source_lookup_plan(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only plan for future bounded official-source lookup or manual source-backed intake."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only bounded official-source lookup/manual intake plan. It reads the exact "
        "route-source proof acquisition plan, defines future lookup/intake targets, and performs no lookup, "
        "RPC, scraping, evidence persistence, mapping, signal or trade."
    )
    disabled_actions = {
        "source_lookup_execution": True,
        "manual_intake_persistence": True,
        "rpc_route_trace": True,
        "external_search": True,
        "scraping": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_lookup_source": False,
        "would_accept_manual_source": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_persist_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    acquisition_plan = get_unknown_dex_family_context_exact_route_source_proof_acquisition_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    proof_targets = list(acquisition_plan.get("proof_acquisition_plans") or [])[:safe_candidate_limit]
    acquisition_ready = acquisition_plan.get("plan_status") == "ready_read_only" and bool(proof_targets)

    if not acquisition_ready:
        return {
            "ok": True,
            "dry_run": True,
            "plan_status": "blocked",
            "mode": "unknown_dex_family_context_bounded_official_source_lookup_plan",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "acquisition_plan_status": acquisition_plan.get("plan_status"),
            "summary": {
                "proof_targets_reviewed": 0,
                "official_lookup_targets": 0,
                "manual_intake_targets": 0,
                "sources_verified_now": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "official_lookup_targets": [],
            "manual_source_intake_targets": [],
            "manual_intake_contract": {},
            "blockers": list(dict.fromkeys(["exact_route_source_proof_acquisition_plan_not_ready", *(acquisition_plan.get("blockers") or [])])),
            "next_safe_step": "run_exact_route_source_proof_acquisition_plan_first",
            **common_disabled,
        }

    official_lookup_targets: list[dict[str, Any]] = []
    manual_source_intake_targets: list[dict[str, Any]] = []
    for target in proof_targets:
        route_source_status = str(target.get("route_source_status") or "missing").strip().lower()
        needs_source = route_source_status != "present"
        token_symbol = target.get("token_symbol")
        token_address = str(target.get("token_address") or "").strip().lower()
        casefile_rank = int(target.get("casefile_rank") or len(official_lookup_targets) + 1)
        base_payload = {
            "casefile_rank": casefile_rank,
            "chain": requested_chain,
            "factory_address": str(factory_address or target.get("factory_address") or "").strip().lower() or None,
            "token_address": token_address,
            "token_symbol": token_symbol,
            "target_identity_hypothesis": target.get("target_identity_hypothesis"),
            "route_source_status": route_source_status,
            "source_required": needs_source,
            "source_backed_scoring_ready": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "would_write": False,
        }
        official_lookup_targets.append({
            **base_payload,
            "lookup_status": "planned_read_only" if needs_source else "blocked_not_needed_or_already_present",
            "allowed_lookup_scope": [
                "official protocol docs",
                "canonical deployment registry",
                "official verified repository",
                "verified contract metadata only when address-bound and corroborated",
                "existing local official source registry",
            ],
            "query_blueprint": {
                "must_include_chain": requested_chain,
                "must_include_address": token_address,
                "may_include_symbol": token_symbol,
                "must_not_accept_symbol_only_result": True,
                "must_not_accept_explorer_tag_only_result": True,
            },
            "future_confirm_required": "RUN_BOUNDED_UNKNOWN_DEX_OFFICIAL_SOURCE_LOOKUP",
            "would_lookup_source": False,
            "would_call_external": False,
            "would_scrape": False,
        })
        manual_source_intake_targets.append({
            **base_payload,
            "manual_intake_status": "allowed_as_preview_only" if needs_source else "blocked_not_needed_or_already_present",
            "required_manual_fields": [
                "source_url",
                "source_tier",
                "source_digest",
                "evidence_preview",
                "chain",
                "address",
                "address_role",
                "route_role_classification",
                "observed_context_reference",
            ],
            "source_tier_allowed": ["official", "canonical", "tier_1", "tier_2"],
            "blocked_if_missing": [
                "source_url",
                "source_digest",
                "exact_address_binding",
                "route_role_classification",
            ],
            "future_confirm_required": "PREVIEW_UNKNOWN_DEX_MANUAL_SOURCE_BACKED_INTAKE",
            "would_accept_manual_source": False,
            "would_persist_evidence": False,
        })

    source_required = sum(1 for row in official_lookup_targets if row["source_required"])
    blockers = list(dict.fromkeys([
        *("official_or_canonical_source_required" for _ in [1] if source_required),
        "lookup_not_executed_in_this_goal",
        "manual_intake_not_persisted_in_this_goal",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only",
        "mode": "unknown_dex_family_context_bounded_official_source_lookup_plan",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "acquisition_plan_status": acquisition_plan.get("plan_status"),
        "summary": {
            "proof_targets_reviewed": len(proof_targets),
            "official_lookup_targets": source_required,
            "manual_intake_targets": source_required,
            "sources_verified_now": 0,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "official_lookup_targets": official_lookup_targets,
        "manual_source_intake_targets": manual_source_intake_targets,
        "manual_intake_contract": {
            "preview_only": True,
            "required_fields": [
                "source_url",
                "source_tier",
                "source_digest",
                "evidence_preview",
                "chain",
                "address",
                "address_role",
                "route_role_classification",
            ],
            "reject_if": [
                "symbol_only_source",
                "explorer_tag_only_source",
                "no_digest",
                "no_exact_address_binding",
                "route_role_unclear",
                "source_tier_not_allowed",
            ],
            "would_write": False,
        },
        "source_lookup_policy": {
            "external_lookup_enabled_now": False,
            "rpc_lookup_enabled_now": False,
            "scraping_enabled_now": False,
            "manual_preview_enabled_now": True,
            "persistence_enabled_now": False,
            "source_backed_scoring_ready": False,
        },
        "policy_gates": {
            "source_lookup_gate": "blocked_until_explicit_future_lookup_goal",
            "manual_intake_gate": "preview_only_no_persistence",
            "route_source_gate": "blocked_until_source_verified_and_bound",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": blockers,
        "next_safe_step": "choose_manual_source_intake_preview_or_confirm_bounded_lookup_strategy",
        **common_disabled,
    }


def get_unknown_dex_family_context_source_acquisition_strategy_decision_preview(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    proposed_strategy: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only strategy preview for choosing the next Unknown DEX source acquisition path."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_strategy = str(proposed_strategy or "").strip().lower() or None
    allowed_strategies = {
        "manual_source_intake_preview",
        "bounded_official_source_lookup",
        "defer_collect_more_local_context",
    }
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only source acquisition strategy decision preview. It compares manual source intake "
        "preview, future bounded official-source lookup, and deferral. It executes no lookup, accepts no manual "
        "source, persists no evidence, and creates no mapping, signal or trade."
    )
    disabled_actions = {
        "strategy_apply": True,
        "source_lookup_execution": True,
        "manual_intake_persistence": True,
        "rpc_route_trace": True,
        "external_search": True,
        "scraping": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_apply_strategy": False,
        "would_lookup_source": False,
        "would_accept_manual_source": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_persist_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "preview_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }
    if safe_strategy and safe_strategy not in allowed_strategies:
        return {
            "ok": False,
            "dry_run": True,
            "preview_status": "blocked",
            "error": "invalid_strategy",
            "proposed_strategy": safe_strategy,
            "allowed_strategies": sorted(allowed_strategies),
            "blockers": ["invalid_strategy"],
            **common_disabled,
        }

    lookup_plan = get_unknown_dex_family_context_bounded_official_source_lookup_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    lookup_ready = lookup_plan.get("plan_status") == "ready_read_only"
    if not lookup_ready:
        return {
            "ok": True,
            "dry_run": True,
            "preview_status": "blocked",
            "mode": "unknown_dex_family_context_source_acquisition_strategy_decision_preview",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "lookup_plan_status": lookup_plan.get("plan_status"),
            "proposed_strategy": safe_strategy,
            "recommended_strategy": None,
            "decision_allowed": False,
            "strategy_comparison": [],
            "summary": {
                "proof_targets_reviewed": 0,
                "manual_intake_targets": 0,
                "official_lookup_targets": 0,
                "sources_verified_now": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "blockers": list(dict.fromkeys(["bounded_official_source_lookup_plan_not_ready", *(lookup_plan.get("blockers") or [])])),
            "next_safe_step": "run_bounded_official_source_lookup_plan_first",
            **common_disabled,
        }

    summary = lookup_plan.get("summary") or {}
    lookup_policy = lookup_plan.get("source_lookup_policy") or {}
    manual_targets = int(summary.get("manual_intake_targets") or 0)
    official_targets = int(summary.get("official_lookup_targets") or 0)
    sources_verified_now = int(summary.get("sources_verified_now") or 0)
    manual_preview_enabled = bool(lookup_policy.get("manual_preview_enabled_now"))
    external_lookup_enabled = bool(lookup_policy.get("external_lookup_enabled_now"))
    rpc_lookup_enabled = bool(lookup_policy.get("rpc_lookup_enabled_now"))
    scraping_enabled = bool(lookup_policy.get("scraping_enabled_now"))
    persistence_enabled = bool(lookup_policy.get("persistence_enabled_now"))
    recommended_strategy = (
        "manual_source_intake_preview"
        if manual_targets and manual_preview_enabled and not persistence_enabled
        else "bounded_official_source_lookup"
        if official_targets and (external_lookup_enabled or rpc_lookup_enabled)
        else "defer_collect_more_local_context"
    )
    effective_strategy = safe_strategy or recommended_strategy
    decision_allowed = effective_strategy in allowed_strategies and (
        (effective_strategy == "manual_source_intake_preview" and manual_targets > 0 and manual_preview_enabled)
        or (effective_strategy == "bounded_official_source_lookup" and official_targets > 0)
        or (effective_strategy == "defer_collect_more_local_context")
    )
    comparison = [
        {
            "strategy": "manual_source_intake_preview",
            "decision_status": "recommended_now" if recommended_strategy == "manual_source_intake_preview" else "available_preview_only",
            "targets": manual_targets,
            "why_use": [
                "no external lookup required",
                "no RPC required",
                "source digest and address binding can be checked before any persistence",
            ],
            "limits": [
                "depends on user or operator supplied source",
                "preview only; persistence remains disabled",
                "does not scale as well as automated lookup",
            ],
            "required_future_confirm": "PREVIEW_UNKNOWN_DEX_MANUAL_SOURCE_BACKED_INTAKE",
            "would_apply_strategy": False,
            "would_accept_manual_source": False,
            "would_persist_evidence": False,
            "would_write": False,
        },
        {
            "strategy": "bounded_official_source_lookup",
            "decision_status": (
                "available_later_requires_confirm"
                if official_targets else "blocked_no_targets"
            ),
            "targets": official_targets,
            "why_use": [
                "better long-term automation path",
                "can search official/canonical sources systematically",
                "reduces manual bottleneck if later explicitly enabled",
            ],
            "limits": [
                "external/RPC/scraping are disabled now",
                "must remain bounded and official-source-only",
                "must not persist evidence in the same step",
            ],
            "required_future_confirm": "CONFIRM_BOUNDED_UNKNOWN_DEX_OFFICIAL_SOURCE_LOOKUP_STRATEGY",
            "would_apply_strategy": False,
            "would_lookup_source": False,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_scrape": False,
            "would_write": False,
        },
        {
            "strategy": "defer_collect_more_local_context",
            "decision_status": "fallback_if_sources_remain_unavailable",
            "targets": int(summary.get("proof_targets_reviewed") or 0),
            "why_use": [
                "safe fallback if no source can be provided or found",
                "can improve repeatability without claiming source-backed status",
            ],
            "limits": [
                "more local context still will not replace official/canonical source proof",
                "data collection must be a separate confirmed data-quality goal",
            ],
            "required_future_confirm": "CONFIRM_BOUNDED_LOCAL_CONTEXT_COLLECTION",
            "would_apply_strategy": False,
            "would_update_swaps": False,
            "would_write": False,
        },
    ]
    blockers = list(dict.fromkeys([
        *("manual_source_intake_preview_not_available" for _ in [1] if effective_strategy == "manual_source_intake_preview" and not manual_preview_enabled),
        *("bounded_lookup_requires_future_explicit_confirm" for _ in [1] if effective_strategy == "bounded_official_source_lookup"),
        *("no_sources_verified_now" for _ in [1] if sources_verified_now == 0),
        "strategy_not_applied_in_this_goal",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "preview_status": "ready_read_only",
        "mode": "unknown_dex_family_context_source_acquisition_strategy_decision_preview",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "lookup_plan_status": lookup_plan.get("plan_status"),
        "proposed_strategy": safe_strategy,
        "recommended_strategy": recommended_strategy,
        "effective_strategy": effective_strategy,
        "decision_allowed": bool(decision_allowed),
        "decision_preview": {
            "future_next_step": (
                "unknown_dex_manual_source_intake_preview_read_only"
                if effective_strategy == "manual_source_intake_preview"
                else "bounded_official_source_lookup_confirm_design_read_only"
                if effective_strategy == "bounded_official_source_lookup"
                else "bounded_local_context_collection_plan_read_only"
            ),
            "status_after_preview": "no_status_change",
            "source_backed_scoring_ready_after_preview": False,
            "mapping_ready_after_preview": False,
            "client_signal_ready_after_preview": False,
            "trade_ready_after_preview": False,
        },
        "strategy_comparison": comparison,
        "summary": {
            "proof_targets_reviewed": int(summary.get("proof_targets_reviewed") or 0),
            "manual_intake_targets": manual_targets,
            "official_lookup_targets": official_targets,
            "sources_verified_now": sources_verified_now,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "source_lookup_policy": lookup_policy,
        "manual_intake_contract": lookup_plan.get("manual_intake_contract") or {},
        "policy_gates": {
            "strategy_apply_gate": "blocked",
            "manual_intake_gate": "preview_only_no_persistence",
            "bounded_lookup_gate": "blocked_until_explicit_future_confirm",
            "source_backed_scoring_gate": "blocked",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": blockers,
        "next_safe_step": (
            "unknown_dex_manual_source_intake_preview_read_only"
            if recommended_strategy == "manual_source_intake_preview"
            else "bounded_official_source_lookup_confirm_design_read_only"
            if recommended_strategy == "bounded_official_source_lookup"
            else "bounded_local_context_collection_plan_read_only"
        ),
        **common_disabled,
    }


def get_unknown_dex_family_context_manual_source_intake_preview(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    manual_sources: list[dict[str, Any]] | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only preview that validates manual source packages for Unknown DEX routes."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_sources = list(manual_sources or [])[:25]
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    allowed_source_tiers = {"official", "canonical", "tier_1", "tier_2"}
    allowed_roles = {"token_contract", "router", "pool", "factory", "intermediary"}
    source_policy = (
        "admin-only read-only manual source intake preview. It validates manually supplied source packages "
        "against Unknown DEX source-intake targets, but accepts nothing, persists nothing, and creates no "
        "router evidence, mapping, signal or trade."
    )
    disabled_actions = {
        "manual_intake_persistence": True,
        "source_acceptance": True,
        "evidence_persistence": True,
        "rpc_route_trace": True,
        "external_search": True,
        "scraping": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_accept_manual_source": False,
        "would_persist_evidence": False,
        "would_lookup_source": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "preview_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    decision = get_unknown_dex_family_context_source_acquisition_strategy_decision_preview(
        chain=requested_chain,
        factory_address=factory_address,
        proposed_strategy="manual_source_intake_preview",
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    if decision.get("preview_status") != "ready_read_only" or not decision.get("decision_allowed"):
        return {
            "ok": True,
            "dry_run": True,
            "preview_status": "blocked",
            "mode": "unknown_dex_family_context_manual_source_intake_preview",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "strategy_preview_status": decision.get("preview_status"),
            "decision_allowed": bool(decision.get("decision_allowed")),
            "summary": {
                "manual_sources_received": len(safe_sources),
                "manual_sources_preview_valid": 0,
                "manual_sources_blocked": len(safe_sources),
                "manual_targets_available": 0,
                "sources_verified_now": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "manual_source_previews": [],
            "expected_input_schema": {},
            "blockers": list(dict.fromkeys(["manual_source_intake_strategy_not_allowed", *(decision.get("blockers") or [])])),
            "next_safe_step": "repair_source_acquisition_strategy_before_manual_intake",
            **common_disabled,
        }

    lookup_plan = get_unknown_dex_family_context_bounded_official_source_lookup_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    manual_targets = list(lookup_plan.get("manual_source_intake_targets") or [])[:safe_candidate_limit]
    target_by_rank = {
        int(row.get("casefile_rank") or 0): row
        for row in manual_targets
    }
    target_by_token = {
        str(row.get("token_address") or "").strip().lower(): row
        for row in manual_targets
        if str(row.get("token_address") or "").strip()
    }
    preview_rows: list[dict[str, Any]] = []

    def _source_digest_ok(value: Any) -> bool:
        text = str(value or "").strip().lower()
        if text.startswith("sha256:"):
            text = text.split(":", 1)[1]
        return len(text) >= 16 and all(ch in "0123456789abcdef" for ch in text[: min(len(text), 64)])

    for idx, source in enumerate(safe_sources, start=1):
        source_url = str(source.get("source_url") or "").strip()
        source_tier = str(source.get("source_tier") or "").strip().lower()
        source_digest = str(source.get("source_digest") or "").strip()
        evidence_preview = str(source.get("evidence_preview") or "").strip()
        source_chain = _normalize_chain(str(source.get("chain") or requested_chain))
        address = str(source.get("address") or "").strip().lower()
        address_role = str(source.get("address_role") or "").strip().lower()
        route_role = str(source.get("route_role_classification") or "").strip().lower()
        observed_ref = str(source.get("observed_context_reference") or "").strip()
        token_address = str(source.get("token_address") or "").strip().lower()
        casefile_rank_raw = source.get("casefile_rank")
        try:
            casefile_rank = int(casefile_rank_raw or 0)
        except (TypeError, ValueError):
            casefile_rank = 0
        target = target_by_rank.get(casefile_rank) if casefile_rank else None
        if target is None and token_address:
            target = target_by_token.get(token_address)
        target_token = str((target or {}).get("token_address") or token_address).strip().lower()
        target_factory = str((target or {}).get("factory_address") or factory_address or "").strip().lower()
        address_matches_known_target = bool(
            address and (
                address == target_token
                or (_valid_evm_address(target_factory) and address == target_factory)
            )
        )
        address_bound_by_context = bool(_valid_evm_address(address) and observed_ref)
        source_blockers = list(dict.fromkeys([
            *("target_not_found" for _ in [1] if target is None),
            *("source_url_required" for _ in [1] if not source_url),
            *("source_url_must_be_http" for _ in [1] if source_url and not source_url.lower().startswith(("https://", "http://"))),
            *("source_tier_not_allowed" for _ in [1] if source_tier not in allowed_source_tiers),
            *("source_digest_required_or_invalid" for _ in [1] if not _source_digest_ok(source_digest)),
            *("evidence_preview_required" for _ in [1] if not evidence_preview),
            *("chain_mismatch" for _ in [1] if source_chain != requested_chain),
            *("valid_evm_address_required" for _ in [1] if not _valid_evm_address(address)),
            *("address_role_not_allowed" for _ in [1] if address_role not in allowed_roles),
            *("route_role_classification_not_allowed" for _ in [1] if route_role not in allowed_roles),
            *(
                "exact_address_binding_or_observed_context_reference_required"
                for _ in [1]
                if _valid_evm_address(address) and not address_matches_known_target and not address_bound_by_context
            ),
            *("symbol_only_source_not_allowed" for _ in [1] if address_role == "" and not address),
        ]))
        package_status = "preview_valid_not_persisted" if not source_blockers else "blocked"
        computed_preview_digest = hashlib.sha256(
            json.dumps(
                {
                    "source_url": source_url,
                    "source_tier": source_tier,
                    "source_digest": source_digest,
                    "chain": source_chain,
                    "address": address,
                    "address_role": address_role,
                    "route_role_classification": route_role,
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        preview_rows.append({
            "input_index": idx,
            "casefile_rank": casefile_rank or (target or {}).get("casefile_rank"),
            "token_address": target_token or None,
            "token_symbol": (target or {}).get("token_symbol") if target else source.get("token_symbol"),
            "source_url": source_url or None,
            "source_tier": source_tier or None,
            "chain": source_chain,
            "address": address or None,
            "address_role": address_role or None,
            "route_role_classification": route_role or None,
            "source_package_status": package_status,
            "source_digest_present": bool(source_digest),
            "source_digest_valid_shape": _source_digest_ok(source_digest),
            "address_bound": bool(address_matches_known_target or address_bound_by_context),
            "computed_preview_digest": computed_preview_digest,
            "blockers": source_blockers,
            "eligible_for_future_persistence": package_status == "preview_valid_not_persisted",
            "would_accept_manual_source": False,
            "would_persist_evidence": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
        })

    valid_count = sum(1 for row in preview_rows if row["source_package_status"] == "preview_valid_not_persisted")
    blocked_count = len(preview_rows) - valid_count
    blockers = list(dict.fromkeys([
        *("manual_source_packages_not_provided" for _ in [1] if not safe_sources),
        *("manual_source_packages_blocked" for _ in [1] if blocked_count),
        "manual_intake_preview_only_no_persistence",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "preview_status": "ready_read_only",
        "mode": "unknown_dex_family_context_manual_source_intake_preview",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "strategy_preview_status": decision.get("preview_status"),
        "recommended_strategy": decision.get("recommended_strategy"),
        "decision_allowed": True,
        "summary": {
            "manual_sources_received": len(safe_sources),
            "manual_sources_preview_valid": valid_count,
            "manual_sources_blocked": blocked_count,
            "manual_targets_available": len(manual_targets),
            "sources_verified_now": 0,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "manual_source_previews": preview_rows,
        "manual_source_intake_targets": manual_targets,
        "expected_input_schema": {
            "required_fields": [
                "casefile_rank or token_address",
                "source_url",
                "source_tier",
                "source_digest",
                "evidence_preview",
                "chain",
                "address",
                "address_role",
                "route_role_classification",
                "observed_context_reference if address is not the known token/factory target",
            ],
            "allowed_source_tiers": sorted(allowed_source_tiers),
            "allowed_roles": sorted(allowed_roles),
            "preview_only": True,
            "persistence_enabled_now": False,
        },
        "policy_gates": {
            "manual_intake_gate": "preview_only_no_persistence",
            "source_persistence_gate": "blocked",
            "source_backed_scoring_gate": "blocked",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": blockers,
        "next_safe_step": (
            "manual_source_persistence_contract_read_only"
            if valid_count else "provide_source_packages_with_url_digest_address_and_route_role"
        ),
        **common_disabled,
    }


def get_unknown_dex_family_context_bounded_official_source_lookup_gate(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
) -> dict[str, Any]:
    """Read-only gate for future bounded official/canonical source lookup."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    source_policy = (
        "admin-only read-only bounded official-source lookup gate. It turns Unknown DEX proof targets "
        "into per-target acceptance/rejection rules for future official/canonical source lookup, but runs "
        "no lookup, no RPC, no provider, no scraping, no evidence persistence, no mapping, no signal and no trade."
    )
    disabled_actions = {
        "source_lookup_execution": True,
        "source_acceptance": True,
        "evidence_persistence": True,
        "rpc_route_trace": True,
        "external_search": True,
        "scraping": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_lookup_source": False,
        "would_accept_source": False,
        "would_accept_manual_source": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_persist_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "gate_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    lookup_plan = get_unknown_dex_family_context_bounded_official_source_lookup_plan(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    if lookup_plan.get("plan_status") != "ready_read_only":
        return {
            "ok": True,
            "dry_run": True,
            "gate_status": "blocked",
            "mode": "unknown_dex_family_context_bounded_official_source_lookup_gate",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "lookup_plan_status": lookup_plan.get("plan_status"),
            "summary": {
                "targets_reviewed": 0,
                "gate_targets": 0,
                "official_lookup_methods_planned": 0,
                "sources_verified_now": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "lookup_gate_targets": [],
            "blockers": list(dict.fromkeys(["bounded_official_source_lookup_plan_not_ready", *(lookup_plan.get("blockers") or [])])),
            "next_safe_step": "repair_bounded_official_source_lookup_plan_first",
            **common_disabled,
        }

    plan_targets = list(lookup_plan.get("official_lookup_targets") or [])[:safe_candidate_limit]
    gate_targets: list[dict[str, Any]] = []
    accept_if_all = [
        "official_or_canonical_source_url_present",
        "source_digest_present",
        "source_mentions_exact_chain",
        "source_mentions_exact_address",
        "address_role_is_explicit",
        "route_role_classification_is_explicit",
        "no_conflicting_identity",
        "source_tier_allowed",
    ]
    reject_if_any = [
        "symbol_only_result",
        "explorer_tag_only_result",
        "social_or_forum_claim_only",
        "family_context_without_exact_address",
        "intermediary_context_only",
        "pool_or_factory_context_claims_router_without_source",
        "missing_or_weak_digest",
        "source_address_drift",
        "chain_mismatch",
        "conflicting_identity",
    ]
    for target in plan_targets:
        token_address = str(target.get("token_address") or "").strip().lower()
        factory = str(target.get("factory_address") or factory_address or "").strip().lower()
        token_symbol = target.get("token_symbol")
        casefile_rank = int(target.get("casefile_rank") or len(gate_targets) + 1)
        target_queries = []
        if _valid_evm_address(factory):
            target_queries.append({
                "lookup_type": "factory_address_official_or_canonical_source",
                "must_include": [requested_chain, factory],
                "may_include": ["PancakeSwap V2", "factory", str(token_symbol or "")],
                "result_must_bind_address": factory,
            })
        if _valid_evm_address(token_address):
            target_queries.append({
                "lookup_type": "token_or_pool_context_source",
                "must_include": [requested_chain, token_address],
                "may_include": [str(token_symbol or ""), "pool", "router", "deployment"],
                "result_must_bind_address": token_address,
            })
        gate_targets.append({
            "casefile_rank": casefile_rank,
            "chain": requested_chain,
            "factory_address": factory or None,
            "token_address": token_address or None,
            "token_symbol": token_symbol,
            "target_identity_hypothesis": target.get("target_identity_hypothesis"),
            "route_source_status": target.get("route_source_status"),
            "gate_status": "planned_not_executed",
            "source_verification_method": {
                "allowed_source_types": [
                    "official protocol docs",
                    "canonical deployment registry",
                    "official verified repository",
                    "verified contract metadata if address-bound and corroborated",
                    "existing local official source registry",
                ],
                "accept_if_all": accept_if_all,
                "reject_if_any": reject_if_any,
                "manual_review_reason_if_blocked": "source package cannot become scoring or mapping input until exact address and route role are bound",
            },
            "query_blueprint": {
                "queries": target_queries,
                "must_not_execute_now": True,
                "must_not_accept_symbol_only_result": True,
                "must_not_accept_explorer_tag_only_result": True,
                "must_not_accept_intermediary_only_result": True,
            },
            "future_source_package_schema": {
                "required_fields": [
                    "source_url",
                    "source_tier",
                    "source_digest",
                    "evidence_preview",
                    "chain",
                    "address",
                    "address_role",
                    "route_role_classification",
                    "observed_context_reference",
                ],
                "allowed_source_tiers": ["official", "canonical", "tier_1", "tier_2"],
                "allowed_address_roles": ["token_contract", "router", "pool", "factory", "intermediary"],
            },
            "policy_result_now": {
                "source_verified_now": False,
                "source_backed_scoring_ready": False,
                "safe_for_mapping_now": False,
                "safe_for_client_signal_now": False,
                "safe_for_trade_now": False,
            },
            "would_lookup_source": False,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_scrape": False,
            "would_persist_evidence": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_write": False,
        })

    gate_blockers = list(dict.fromkeys([
        *("official_lookup_targets_missing" for _ in [1] if not gate_targets),
        "lookup_gate_read_only_not_executed",
        "source_acceptance_disabled",
        "evidence_persistence_disabled",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "gate_status": "ready_read_only",
        "mode": "unknown_dex_family_context_bounded_official_source_lookup_gate",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "lookup_plan_status": lookup_plan.get("plan_status"),
        "summary": {
            "targets_reviewed": len(plan_targets),
            "gate_targets": len(gate_targets),
            "official_lookup_methods_planned": sum(len((row.get("query_blueprint") or {}).get("queries") or []) for row in gate_targets),
            "sources_verified_now": 0,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "lookup_gate_targets": gate_targets,
        "global_acceptance_policy": {
            "accept_if_all": accept_if_all,
            "reject_if_any": reject_if_any,
            "no_silent_success": True,
            "no_overwrite": True,
            "no_upsert": True,
            "no_source_backed_scoring_until_persisted_source_package_future_goal": True,
        },
        "policy_gates": {
            "lookup_execution_gate": "blocked_until_explicit_future_confirm",
            "source_acceptance_gate": "blocked",
            "evidence_persistence_gate": "blocked",
            "route_source_gate": "blocked_until_exact_source_verified_and_bound",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": gate_blockers,
        "next_safe_step": "bounded_official_source_lookup_dry_run_first_or_manual_source_packages",
        **common_disabled,
    }


def get_unknown_dex_family_context_bounded_official_source_lookup(
    chain: str | None = "bsc",
    factory_address: str | None = None,
    block_window: int = 10_000,
    limit: int = 5,
    tx_transfer_limit: int = 80,
    max_pools: int = 4,
    window_radius_blocks: int = 3,
    max_blocks: int = 30,
    timeout: int = 6,
    dry_run: bool = True,
    candidate_limit: int = 8,
    max_targets: int = 3,
    max_results_per_query: int = 3,
    allow_external: bool = False,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Bounded read-only lookup for candidate official/canonical sources."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_window = max(1, min(int(block_window or 10_000), 50_000))
    safe_limit = max(1, min(int(limit or 5), 25))
    safe_transfer_limit = max(1, min(int(tx_transfer_limit or 80), 200))
    safe_pools = max(1, min(int(max_pools or 4), 12))
    safe_radius = max(1, min(int(window_radius_blocks or 3), 25))
    safe_max_blocks = max(1, min(int(max_blocks or 30), 100))
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_candidate_limit = max(1, min(int(candidate_limit or 8), 25))
    safe_targets = max(1, min(int(max_targets or 3), 8))
    safe_results = max(1, min(int(max_results_per_query or 3), 5))
    required_confirm = "RUN_BOUNDED_UNKNOWN_DEX_OFFICIAL_SOURCE_LOOKUP"
    source_policy = (
        "admin-only bounded read-only official/canonical source lookup for Unknown DEX targets. "
        "External search is disabled by default and requires explicit confirm. Search results are "
        "candidate URLs only, not accepted evidence. It writes no DB rows, creates no DEX evidence, "
        "creates no mapping, sends no signal and executes no trade."
    )
    disabled_actions = {
        "evidence_persistence": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_accept_source": False,
        "would_persist_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "lookup_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "would_lookup_source": False,
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }
    if allow_external and str(confirm or "").strip() != required_confirm:
        return {
            "ok": False,
            "dry_run": True,
            "lookup_status": "blocked",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "error": "confirm_required",
            "required_confirm": required_confirm,
            "blockers": [f"confirm_{required_confirm}_required"],
            "lookup_rows": [],
            "summary": {
                "targets_reviewed": 0,
                "lookup_targets": 0,
                "external_calls_performed": 0,
                "candidate_urls_found": 0,
                "exact_address_surface_hits": 0,
                "future_fetch_candidates": 0,
                "sources_verified_now": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "would_lookup_source": False,
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }

    gate = get_unknown_dex_family_context_bounded_official_source_lookup_gate(
        chain=requested_chain,
        factory_address=factory_address,
        block_window=safe_window,
        limit=safe_limit,
        tx_transfer_limit=safe_transfer_limit,
        max_pools=safe_pools,
        window_radius_blocks=safe_radius,
        max_blocks=safe_max_blocks,
        timeout=safe_timeout,
        dry_run=True,
        candidate_limit=safe_candidate_limit,
    )
    if gate.get("gate_status") != "ready_read_only":
        return {
            "ok": True,
            "dry_run": True,
            "lookup_status": "blocked",
            "mode": "unknown_dex_family_context_bounded_official_source_lookup",
            "chain": requested_chain,
            "factory_address": str(factory_address or "").strip().lower() or None,
            "gate_status": gate.get("gate_status"),
            "summary": {
                "targets_reviewed": 0,
                "lookup_targets": 0,
                "external_calls_performed": 0,
                "candidate_urls_found": 0,
                "exact_address_surface_hits": 0,
                "future_fetch_candidates": 0,
                "sources_verified_now": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "lookup_rows": [],
            "blockers": list(dict.fromkeys(["bounded_official_source_lookup_gate_not_ready", *(gate.get("blockers") or [])])),
            "next_safe_step": "repair_lookup_gate_before_source_lookup",
            "would_lookup_source": False,
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }

    def _host_matches_domain(host: str, domains: tuple[str, ...]) -> bool:
        clean_host = str(host or "").strip().lower()
        return any(clean_host == domain or clean_host.endswith(f".{domain}") for domain in domains)

    social_or_forum_hosts = ("twitter.com", "x.com", "t.me", "telegram.org", "reddit.com", "discord.com", "discord.gg")
    explorer_hosts = ("bscscan.com", "etherscan.io", "arbiscan.io", "polygonscan.com", "basescan.org", "snowtrace.io")
    rows: list[dict[str, Any]] = []
    external_calls = 0
    external_errors = 0
    for target in list(gate.get("lookup_gate_targets") or [])[:safe_targets]:
        query_specs = list(((target.get("query_blueprint") or {}).get("queries") or []))
        query_rows: list[dict[str, Any]] = []
        candidate_urls: list[dict[str, Any]] = []
        target_addresses = [
            str(value or "").strip().lower()
            for value in [target.get("factory_address"), target.get("token_address")]
            if _valid_evm_address(str(value or "").strip().lower())
        ]
        for query_spec in query_specs:
            must_include = [str(value).strip() for value in query_spec.get("must_include") or [] if str(value).strip()]
            may_include = [str(value).strip() for value in query_spec.get("may_include") or [] if str(value).strip()]
            query = " ".join([*must_include, *may_include[:3], "official canonical source"]).strip()
            row = {
                "lookup_type": query_spec.get("lookup_type"),
                "query": query,
                "search_performed": bool(allow_external),
                "results": [],
                "error": None,
            }
            if allow_external and query:
                try:
                    external_calls += 1
                    for result in _public_source_search_results(query, timeout=safe_timeout, max_results=safe_results):
                        url = str(result.get("url") or "").strip()
                        host = urllib.parse.urlparse(url).netloc.lower() if url else ""
                        title = str(result.get("title") or "").strip()
                        snippet = str(result.get("snippet") or "").strip()
                        surface = " ".join([url, host, title, snippet]).lower()
                        exact_addresses = [addr for addr in target_addresses if addr and addr in surface]
                        social_or_forum = _host_matches_domain(host, social_or_forum_hosts)
                        explorer_only = _host_matches_domain(host, explorer_hosts)
                        future_fetch_candidate = bool(exact_addresses and not social_or_forum)
                        blockers = list(dict.fromkeys([
                            *("symbol_only_or_address_missing_from_search_surface" for _ in [1] if not exact_addresses),
                            *("social_or_forum_result_not_official_source" for _ in [1] if social_or_forum),
                            *("explorer_tag_only_is_not_enough" for _ in [1] if explorer_only),
                            "official_source_page_not_fetched_or_graded",
                            "source_not_persisted",
                            "no_mapping_from_lookup_result",
                        ]))
                        candidate = {
                            "url": url,
                            "host": host,
                            "title": title[:220],
                            "snippet": snippet[:300],
                            "exact_addresses_seen_in_search_surface": exact_addresses,
                            "exact_address_seen_in_search_surface": bool(exact_addresses),
                            "social_or_forum_result": social_or_forum,
                            "explorer_only_result": explorer_only,
                            "future_fetch_candidate": future_fetch_candidate,
                            "candidate_status": (
                                "future_fetch_candidate_not_proof"
                                if future_fetch_candidate else "blocked_candidate_url_not_address_bound"
                            ),
                            "official_source_verified": False,
                            "source_backed_scoring_ready": False,
                            "blockers": blockers,
                        }
                        candidate_urls.append(candidate)
                        row["results"].append(candidate)
                except Exception as exc:
                    external_errors += 1
                    row["error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
            query_rows.append(row)

        exact_hits = sum(1 for candidate in candidate_urls if candidate.get("exact_address_seen_in_search_surface"))
        future_fetch_candidates = sum(1 for candidate in candidate_urls if candidate.get("future_fetch_candidate"))
        rows.append({
            "casefile_rank": target.get("casefile_rank"),
            "chain": requested_chain,
            "factory_address": target.get("factory_address"),
            "token_address": target.get("token_address"),
            "token_symbol": target.get("token_symbol"),
            "target_identity_hypothesis": target.get("target_identity_hypothesis"),
            "route_source_status": target.get("route_source_status"),
            "lookup_status": (
                "external_lookup_completed_read_only"
                if allow_external else "ready_but_external_lookup_disabled"
            ),
            "queries_reviewed": len(query_rows),
            "query_rows": query_rows,
            "candidate_urls": candidate_urls[: safe_results * max(1, len(query_rows))],
            "candidate_url_count": len(candidate_urls),
            "exact_address_surface_hits": exact_hits,
            "future_fetch_candidates": future_fetch_candidates,
            "official_sources_verified": 0,
            "source_backed_scoring_ready": False,
            "safe_for_mapping_now": False,
            "safe_for_client_signal_now": False,
            "safe_for_trade_now": False,
            "blockers": list(dict.fromkeys([
                *("external_lookup_disabled" for _ in [1] if not allow_external),
                *("external_lookup_error" for _ in [1] if any(q.get("error") for q in query_rows)),
                *("candidate_urls_are_not_proof" for _ in [1] if candidate_urls),
                *("no_candidate_urls_found" for _ in [1] if allow_external and not candidate_urls),
                "official_source_page_fetch_and_grading_required",
                "source_persistence_disabled",
                "source_backed_scoring_still_disabled",
                "dex_mapping_disabled",
                "client_signal_disabled",
                "trade_disabled",
            ])),
            "next_safe_step": (
                "fetch_and_grade_future_fetch_candidates_read_only"
                if future_fetch_candidates else "manual_source_package_or_refine_queries"
                if allow_external else "rerun_with_allow_external_true_and_confirm_for_bounded_lookup"
            ),
            "would_lookup_source": bool(allow_external),
            "would_call_external": bool(allow_external),
            "would_persist_evidence": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_score_for_client": False,
            "would_create_client_signal": False,
            "would_execute_trade": False,
            "would_write": False,
        })

    candidate_count = sum(int(row.get("candidate_url_count") or 0) for row in rows)
    future_fetch_count = sum(int(row.get("future_fetch_candidates") or 0) for row in rows)
    return {
        "ok": True,
        "dry_run": True,
        "lookup_status": (
            "external_lookup_completed_read_only"
            if allow_external and rows else "ready_but_external_lookup_disabled"
            if rows else "blocked_no_lookup_targets"
        ),
        "mode": "unknown_dex_family_context_bounded_official_source_lookup",
        "chain": requested_chain,
        "factory_address": str(factory_address or "").strip().lower() or None,
        "gate_status": gate.get("gate_status"),
        "required_confirm": required_confirm,
        "allow_external": bool(allow_external),
        "summary": {
            "targets_reviewed": len(rows),
            "lookup_targets": len(rows),
            "external_calls_performed": external_calls,
            "external_errors": external_errors,
            "candidate_urls_found": candidate_count,
            "exact_address_surface_hits": sum(int(row.get("exact_address_surface_hits") or 0) for row in rows),
            "future_fetch_candidates": future_fetch_count,
            "sources_verified_now": 0,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "lookup_rows": rows,
        "policy_gates": {
            "external_lookup_gate": "explicit_confirm_required" if not allow_external else "confirmed_for_bounded_read_only_lookup",
            "source_acceptance_gate": "blocked",
            "evidence_persistence_gate": "blocked",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": list(dict.fromkeys([
            *("no_lookup_targets" for _ in [1] if not rows),
            *("external_lookup_disabled" for _ in [1] if rows and not allow_external),
            *("external_lookup_errors_observed" for _ in [1] if external_errors),
            *("candidate_urls_are_not_proof" for _ in [1] if candidate_count),
            "official_source_page_fetch_and_grading_required",
            "source_persistence_disabled",
            "source_backed_scoring_still_disabled",
            "dex_mapping_disabled",
            "client_signal_disabled",
            "trade_disabled",
        ])),
        "next_safe_step": (
            "source_page_fetch_and_grading_checkpoint_read_only"
            if future_fetch_count else "manual_source_package_or_refine_queries"
            if allow_external else "rerun_with_allow_external_true_and_confirm_for_bounded_lookup"
        ),
        "would_lookup_source": bool(allow_external and rows),
        "would_call_external": bool(allow_external and rows),
        "external_calls_performed": external_calls,
        **common_disabled,
    }


def get_unknown_dex_family_context_source_page_fetch_grading_checkpoint(
    source_url: str | None = None,
    expected_address: str | None = None,
    expected_chain: str | None = "bsc",
    expected_token_symbol: str | None = None,
    expected_route_role: str | None = None,
    dry_run: bool = True,
    allow_external: bool = False,
    confirm: str | None = None,
    timeout: int = 6,
) -> dict[str, Any]:
    """Read-only fetch/grading checkpoint for one Unknown DEX source candidate URL."""
    _init_db()
    clean_url = str(source_url or "").strip()
    clean_chain = _normalize_chain(expected_chain or "bsc")
    clean_address = str(expected_address or "").strip().lower()
    clean_symbol = str(expected_token_symbol or "").strip()
    clean_role = str(expected_route_role or "").strip().lower()
    safe_timeout = max(2, min(int(timeout or 6), 15))
    required_confirm = "FETCH_GRADE_UNKNOWN_DEX_SOURCE_PAGE"
    source_policy = (
        "admin-only read-only source page fetch/grading checkpoint for one Unknown DEX candidate URL. "
        "External fetch is disabled by default and requires explicit confirm. The checkpoint may read "
        "one URL and compute a preview digest, but accepts no source, persists no evidence, creates no "
        "DEX router evidence, creates no mapping, sends no signal and executes no trade."
    )
    disabled_actions = {
        "source_acceptance": True,
        "evidence_persistence": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_accept_source": False,
        "would_persist_evidence": False,
        "would_insert_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    parsed = urllib.parse.urlparse(clean_url)
    input_blockers = list(dict.fromkeys([
        *("dry_run_required" for _ in [1] if not dry_run),
        *("source_url_required" for _ in [1] if not clean_url),
        *("https_source_url_required" for _ in [1] if clean_url and (parsed.scheme != "https" or not parsed.netloc)),
        *("expected_address_required" for _ in [1] if not clean_address),
        *("expected_address_invalid" for _ in [1] if clean_address and not _valid_evm_address(clean_address)),
    ]))
    if input_blockers:
        return {
            "ok": False,
            "dry_run": bool(dry_run),
            "allow_external": bool(allow_external),
            "checkpoint_status": "blocked",
            "source_url": clean_url or None,
            "expected_address": clean_address or None,
            "expected_chain": clean_chain,
            "expected_token_symbol": clean_symbol or None,
            "summary": {
                "fetched": 0,
                "address_bound": 0,
                "official_or_canonical": 0,
                "route_role_present": 0,
                "source_backed_scoring_ready": 0,
                "real_write_enabled": False,
            },
            "blockers": input_blockers,
            "would_fetch_source": False,
            "would_call_external": False,
            **common_disabled,
        }
    if allow_external and str(confirm or "").strip() != required_confirm:
        return {
            "ok": False,
            "dry_run": True,
            "allow_external": True,
            "checkpoint_status": "blocked",
            "source_url": clean_url,
            "expected_address": clean_address,
            "expected_chain": clean_chain,
            "expected_token_symbol": clean_symbol or None,
            "required_confirm": required_confirm,
            "summary": {
                "fetched": 0,
                "address_bound": 0,
                "official_or_canonical": 0,
                "route_role_present": 0,
                "source_backed_scoring_ready": 0,
                "real_write_enabled": False,
            },
            "blockers": [f"confirm_{required_confirm}_required"],
            "would_fetch_source": False,
            "would_call_external": False,
            **common_disabled,
        }
    if not allow_external:
        return {
            "ok": True,
            "dry_run": True,
            "allow_external": False,
            "checkpoint_status": "ready_but_external_fetch_disabled",
            "source_url": clean_url,
            "expected_address": clean_address,
            "expected_chain": clean_chain,
            "expected_token_symbol": clean_symbol or None,
            "required_confirm": required_confirm,
            "summary": {
                "fetched": 0,
                "address_bound": 0,
                "official_or_canonical": 0,
                "route_role_present": 0,
                "source_backed_scoring_ready": 0,
                "real_write_enabled": False,
            },
            "blockers": ["allow_external_true_required"],
            "next_safe_step": "rerun_with_allow_external_true_and_confirm_for_single_url_fetch_grading",
            "would_fetch_source": False,
            "would_call_external": False,
            **common_disabled,
        }

    def _count_table_if_exists(conn: sqlite3.Connection, table: str) -> int:
        return int(conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]) if _table_exists(conn, table) else 0

    before_counts: dict[str, int] = {}
    after_counts: dict[str, int] = {}
    if DB_PATH.exists() and LABEL_LEDGER_PATH.exists():
        onchain_conn = sqlite3.connect(str(DB_PATH))
        label_conn = sqlite3.connect(str(LABEL_LEDGER_PATH))
        try:
            before_counts = {
                "data_jobs": int(onchain_conn.execute("SELECT COUNT(*) FROM data_jobs").fetchone()[0]),
                "swaps": int(onchain_conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]),
                "token_transfers": int(onchain_conn.execute("SELECT COUNT(*) FROM token_transfers").fetchone()[0]),
                "dex_router_official_evidence_queue": _count_table_if_exists(onchain_conn, "dex_router_official_evidence_queue"),
                "source_backed_venue_mappings": _count_table_if_exists(onchain_conn, "source_backed_venue_mappings"),
                "labels": int(label_conn.execute("SELECT COUNT(*) FROM labels").fetchone()[0]),
                "label_candidates": int(label_conn.execute("SELECT COUNT(*) FROM label_candidates").fetchone()[0]),
            }
        finally:
            onchain_conn.close()
            label_conn.close()

    fetch_status = "not_attempted"
    status_code = None
    final_url = clean_url
    text = ""
    content_digest = None
    text_sample = ""
    fetch_error = None
    try:
        payload = _public_explorer_text(clean_url, timeout=safe_timeout)
        fetch_status = "fetched_preview_only"
        status_code = payload.get("status_code")
        final_url = str(payload.get("final_url") or clean_url)
        text = str(payload.get("text") or "")
        content_digest = hashlib.sha256(text.encode("utf-8", errors="ignore")).hexdigest()
        text_sample = re.sub(r"\s+", " ", html.unescape(text[:800])).strip()
    except Exception as exc:
        fetch_status = "fetch_failed"
        fetch_error = f"{type(exc).__name__}:{str(exc)[:180]}"

    parsed_final = urllib.parse.urlparse(final_url)
    host = parsed_final.netloc.lower()
    surface = " ".join([clean_url, final_url, host, text]).lower()
    address_no_prefix = clean_address[2:] if clean_address.startswith("0x") else clean_address
    address_bound = bool(clean_address and (clean_address in surface or address_no_prefix in surface))
    chain_terms = {
        "bsc": ["bsc", "bnb chain", "bnb smart chain", "/bsc/"],
        "eth": ["ethereum", "/eth/", "mainnet"],
        "polygon": ["polygon", "/polygon/"],
        "base": ["base", "/base/"],
        "arbitrum": ["arbitrum", "/arbitrum/"],
    }.get(clean_chain, [clean_chain])
    chain_bound = any(term in surface for term in chain_terms if term)
    symbol_bound = bool(clean_symbol and clean_symbol.lower() in surface)
    role_terms = [
        term for term in [
            clean_role,
            "router",
            "factory",
            "pool",
            "pair",
            "deployment",
            "contract address",
        ]
        if term
    ]
    role_hits = [term for term in dict.fromkeys(role_terms) if term in surface]

    official_hint_hosts = ("github.com", "docs.", "developer.", "developers.", "pancakeswap.finance", "uniswap.org")
    explorer_market_hosts = (
        "bscscan.com",
        "etherscan.io",
        "arbiscan.io",
        "polygonscan.com",
        "basescan.org",
        "web3.okx.com",
        "dexscreener.com",
        "geckoterminal.com",
        "coinmarketcap.com",
        "coingecko.com",
        "gate.com",
    )
    official_or_canonical = any(host == domain or host.endswith(f".{domain}") or domain in host for domain in official_hint_hosts)
    market_or_explorer_only = any(host == domain or host.endswith(f".{domain}") for domain in explorer_market_hosts)
    route_role_present = bool(
        (clean_role and clean_role in role_hits)
        or (
            official_or_canonical
            and any(term in role_hits for term in {"router", "factory", "pool", "pair", "deployment"})
        )
    )
    address_bound_market_page = bool(address_bound and market_or_explorer_only and not official_or_canonical)

    row_blockers = list(dict.fromkeys([
        *([fetch_error] if fetch_error else []),
        *("source_page_fetch_failed" for _ in [1] if fetch_status == "fetch_failed"),
        *("exact_address_missing_from_page" for _ in [1] if fetch_status != "fetch_failed" and not address_bound),
        *("chain_missing_or_weak_from_page" for _ in [1] if fetch_status != "fetch_failed" and not chain_bound),
        *("source_not_official_or_canonical" for _ in [1] if fetch_status != "fetch_failed" and not official_or_canonical),
        *("market_or_explorer_page_not_route_proof" for _ in [1] if address_bound_market_page),
        *("route_role_missing_or_weak" for _ in [1] if fetch_status != "fetch_failed" and not route_role_present),
        "source_not_accepted",
        "source_not_persisted",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    grade_status = (
        "fetch_failed"
        if fetch_status == "fetch_failed" else "official_route_source_candidate_not_persisted"
        if address_bound and chain_bound and official_or_canonical and route_role_present else "address_bound_market_or_explorer_page_not_route_proof"
        if address_bound_market_page else "address_bound_but_not_source_backed"
        if address_bound else "blocked_not_address_bound"
    )

    if DB_PATH.exists() and LABEL_LEDGER_PATH.exists():
        onchain_conn = sqlite3.connect(str(DB_PATH))
        label_conn = sqlite3.connect(str(LABEL_LEDGER_PATH))
        try:
            after_counts = {
                "data_jobs": int(onchain_conn.execute("SELECT COUNT(*) FROM data_jobs").fetchone()[0]),
                "swaps": int(onchain_conn.execute("SELECT COUNT(*) FROM swaps").fetchone()[0]),
                "token_transfers": int(onchain_conn.execute("SELECT COUNT(*) FROM token_transfers").fetchone()[0]),
                "dex_router_official_evidence_queue": _count_table_if_exists(onchain_conn, "dex_router_official_evidence_queue"),
                "source_backed_venue_mappings": _count_table_if_exists(onchain_conn, "source_backed_venue_mappings"),
                "labels": int(label_conn.execute("SELECT COUNT(*) FROM labels").fetchone()[0]),
                "label_candidates": int(label_conn.execute("SELECT COUNT(*) FROM label_candidates").fetchone()[0]),
            }
        finally:
            onchain_conn.close()
            label_conn.close()
    db_unchanged = before_counts == after_counts
    if not db_unchanged:
        row_blockers.append("unexpected_db_change_detected")

    return {
        "ok": bool(db_unchanged),
        "dry_run": True,
        "allow_external": True,
        "checkpoint_status": "completed_read_only" if db_unchanged else "blocked_after_preview",
        "source_url": clean_url,
        "final_url": final_url,
        "host": host,
        "status_code": status_code,
        "fetch_status": fetch_status,
        "fetch_error": fetch_error,
        "expected_address": clean_address,
        "expected_chain": clean_chain,
        "expected_token_symbol": clean_symbol or None,
        "expected_route_role": clean_role or None,
        "source_digest": f"sha256:{content_digest}" if content_digest else None,
        "text_sample": text_sample,
        "grading": {
            "grade_status": grade_status,
            "address_bound": address_bound,
            "chain_bound": chain_bound,
            "token_symbol_bound": symbol_bound,
            "official_or_canonical": official_or_canonical,
            "market_or_explorer_only": market_or_explorer_only,
            "route_role_present": route_role_present,
            "route_role_terms_observed": role_hits,
            "eligible_for_future_source_persistence": False,
            "source_backed_scoring_ready": False,
        },
        "summary": {
            "fetched": 1 if fetch_status == "fetched_preview_only" else 0,
            "address_bound": 1 if address_bound else 0,
            "official_or_canonical": 1 if official_or_canonical else 0,
            "route_role_present": 1 if route_role_present else 0,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "db_counts_before": before_counts,
        "db_counts_after": after_counts,
        "db_unchanged": db_unchanged,
        "blockers": list(dict.fromkeys(row_blockers)),
        "next_safe_step": (
            "collect_stronger_official_or_canonical_route_source"
            if address_bound_market_page or not official_or_canonical or not route_role_present
            else "future_source_persistence_contract_read_only"
        ),
        "plain_summary_fr": (
            "La page contient l'adresse attendue mais reste une page marche/explorer, pas une preuve officielle de route."
            if address_bound_market_page else
            "La page a ete lue en preview, mais elle ne debloque aucune persistence ni mapping."
        ),
        "would_fetch_source": True,
        "would_call_external": True,
        **common_disabled,
    }


def get_unknown_dex_family_context_stronger_official_route_source_package_plan(
    source_url: str | None = None,
    expected_address: str | None = None,
    expected_chain: str | None = "bsc",
    expected_token_symbol: str | None = None,
    current_grade_status: str | None = None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only plan for stronger official/canonical route-source packages."""
    _init_db()
    clean_url = str(source_url or "").strip()
    clean_chain = _normalize_chain(expected_chain or "bsc")
    clean_address = str(expected_address or "").strip().lower()
    clean_symbol = str(expected_token_symbol or "").strip()
    clean_grade = str(current_grade_status or "").strip().lower()
    source_policy = (
        "admin-only read-only stronger official route-source package plan for Unknown DEX targets. "
        "It translates a weak candidate page into exact source-package requirements, but fetches no "
        "source, persists no evidence, creates no DEX router evidence, creates no mapping, sends no "
        "client signal and executes no trade."
    )
    disabled_actions = {
        "source_fetch": True,
        "source_acceptance": True,
        "evidence_persistence": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_fetch_source": False,
        "would_call_external": False,
        "would_accept_source": False,
        "would_persist_evidence": False,
        "would_insert_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "plan_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    current_page_assessment = {
        "source_url": clean_url or None,
        "expected_address": clean_address or None,
        "expected_chain": clean_chain,
        "expected_token_symbol": clean_symbol or None,
        "current_grade_status": clean_grade or "not_supplied",
        "usable_as_route_proof": False,
        "why_blocked": list(dict.fromkeys([
            *("candidate_page_is_market_or_explorer_only" for _ in [1] if "market_or_explorer" in clean_grade),
            *("candidate_page_not_official_or_canonical" for _ in [1] if "official" not in clean_grade),
            "exact_route_role_not_proven",
            "source_not_persisted",
        ])),
    }
    accepted_source_package_schema = {
        "required_fields": [
            "source_url",
            "source_tier",
            "source_digest",
            "evidence_preview",
            "chain",
            "address",
            "address_role",
            "route_role_classification",
            "observed_context_reference",
        ],
        "allowed_source_tiers": ["official", "canonical", "tier_1"],
        "allowed_address_roles": ["router", "factory", "pool", "pair", "token_contract"],
        "allowed_route_roles": [
            "official_router",
            "official_factory",
            "official_pool",
            "official_pair",
            "official_deployment_reference",
        ],
        "digest_shape": "sha256:<64_hex_chars>",
        "must_bind": [
            "same_chain",
            "exact_address",
            "explicit_address_role",
            "explicit_route_role",
            "source_url_to_digest",
        ],
    }
    accepted_source_types = [
        {
            "source_type": "official_protocol_docs_deployments",
            "priority": 1,
            "examples": ["PancakeSwap docs deployments", "official protocol deployment pages"],
            "must_show": ["chain", "exact address", "component role"],
        },
        {
            "source_type": "canonical_deployment_registry",
            "priority": 2,
            "examples": ["official deployment JSON", "official addresses registry"],
            "must_show": ["chain", "exact address", "router/factory/pool role"],
        },
        {
            "source_type": "official_verified_repository",
            "priority": 3,
            "examples": ["official GitHub deployment config", "release deployment registry"],
            "must_show": ["chain", "exact address", "deployment context"],
        },
        {
            "source_type": "verified_contract_metadata_with_corresponding_official_context",
            "priority": 4,
            "examples": ["verified contract metadata plus official registry corroboration"],
            "must_show": ["exact address", "contract role", "separate official/canonical corroboration"],
        },
    ]
    reject_if_any = [
        "market_price_page_only",
        "explorer_page_only",
        "symbol_only_result",
        "social_or_forum_claim_only",
        "generic_chain_explorer_homepage",
        "token_trading_page_without_route_role",
        "intermediary_or_wallet_context_only",
        "address_seen_but_role_missing",
        "chain_mismatch",
        "conflicting_identity",
        "missing_digest",
    ]
    search_package = {
        "search_intent": "find official/canonical route role proof, not market data",
        "bounded_queries": list(dict.fromkeys([
            " ".join(part for part in [clean_chain, clean_address, clean_symbol, "official deployment router factory pool"] if part).strip(),
            " ".join(part for part in [clean_chain, clean_symbol, "official contract address deployment registry"] if part).strip(),
            " ".join(part for part in [clean_address, "official docs deployment"] if part).strip(),
            " ".join(part for part in [clean_address, "github deployment addresses"] if part).strip(),
        ])),
        "must_not_accept": reject_if_any,
        "fetch_grade_before_any_persistence": True,
        "manual_source_intake_preview_available": True,
    }
    blockers = list(dict.fromkeys([
        *("expected_address_missing" for _ in [1] if not clean_address),
        *("expected_address_invalid" for _ in [1] if clean_address and not _valid_evm_address(clean_address)),
        "current_candidate_not_route_proof",
        "stronger_official_or_canonical_source_required",
        "source_package_not_supplied",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "plan_status": "ready_read_only",
        "mode": "unknown_dex_stronger_official_route_source_package_plan",
        "source_url": clean_url or None,
        "expected_address": clean_address or None,
        "expected_chain": clean_chain,
        "expected_token_symbol": clean_symbol or None,
        "current_page_assessment": current_page_assessment,
        "accepted_source_package_schema": accepted_source_package_schema,
        "accepted_source_types": accepted_source_types,
        "reject_if_any": reject_if_any,
        "search_package": search_package,
        "policy_gates": {
            "source_package_gate": "preview_only_no_persistence",
            "fetch_grading_gate": "required_before_source_acceptance",
            "source_persistence_gate": "blocked",
            "source_backed_scoring_gate": "blocked",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "summary": {
            "accepted_source_types": len(accepted_source_types),
            "required_fields": len(accepted_source_package_schema["required_fields"]),
            "current_candidate_usable_as_route_proof": False,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "blockers": blockers,
        "next_safe_step": "bounded_official_route_source_lookup_or_manual_source_package_preview",
        "plain_summary_fr": (
            "La page actuelle prouve surtout que le token existe dans un contexte marche/explorer. "
            "Pour avancer, il faut une source officielle/canonique qui lie explicitement l'adresse a un role de route."
        ),
        **common_disabled,
    }


def get_unknown_dex_family_context_bounded_official_route_source_package_preview(
    source_url: str | None = None,
    expected_address: str | None = None,
    expected_chain: str | None = "bsc",
    expected_token_symbol: str | None = None,
    current_grade_status: str | None = None,
    manual_sources: list[dict[str, Any]] | None = None,
    dry_run: bool = True,
    allow_external: bool = False,
    confirm: str | None = None,
    timeout: int = 6,
    max_results_per_query: int = 3,
) -> dict[str, Any]:
    """Read-only preview for official route-source packages before any persistence."""
    _init_db()
    clean_url = str(source_url or "").strip()
    clean_chain = _normalize_chain(expected_chain or "bsc")
    clean_address = str(expected_address or "").strip().lower()
    clean_symbol = str(expected_token_symbol or "").strip()
    clean_grade = str(current_grade_status or "").strip().lower()
    safe_sources = list(manual_sources or [])[:10]
    safe_timeout = max(2, min(int(timeout or 6), 15))
    safe_results = max(1, min(int(max_results_per_query or 3), 5))
    required_confirm = "RUN_BOUNDED_UNKNOWN_DEX_OFFICIAL_ROUTE_SOURCE_LOOKUP"
    source_policy = (
        "admin-only read-only official route-source package preview for Unknown DEX targets. "
        "It validates supplied source packages and can optionally run a bounded candidate URL lookup, "
        "but accepts no source, persists no evidence, creates no DEX router evidence, creates no mapping, "
        "sends no client signal and executes no trade."
    )
    disabled_actions = {
        "source_acceptance": True,
        "evidence_persistence": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "source_backed_scoring": True,
        "client_signal": True,
        "trade": True,
        "wallet_order": True,
        "client_opt_in": True,
        "label_promotion": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_accept_source": False,
        "would_persist_evidence": False,
        "would_insert_evidence": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_score_for_client": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "preview_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "manual_source_previews": [],
            "lookup_rows": [],
            "would_lookup_source": False,
            "would_call_external": False,
            **common_disabled,
        }
    if allow_external and str(confirm or "").strip() != required_confirm:
        return {
            "ok": False,
            "dry_run": True,
            "allow_external": True,
            "preview_status": "blocked",
            "source_url": clean_url or None,
            "expected_address": clean_address or None,
            "expected_chain": clean_chain,
            "expected_token_symbol": clean_symbol or None,
            "required_confirm": required_confirm,
            "error": "confirm_required",
            "blockers": [f"confirm_{required_confirm}_required"],
            "summary": {
                "manual_sources_received": len(safe_sources),
                "manual_sources_valid": 0,
                "manual_sources_blocked": len(safe_sources),
                "external_calls_performed": 0,
                "candidate_urls_found": 0,
                "official_route_source_packages_ready": 0,
                "source_backed_scoring_ready": 0,
                "client_signal_ready": 0,
                "trade_ready": 0,
                "real_write_enabled": False,
            },
            "manual_source_previews": [],
            "lookup_rows": [],
            "would_lookup_source": False,
            "would_call_external": False,
            **common_disabled,
        }

    plan = get_unknown_dex_family_context_stronger_official_route_source_package_plan(
        source_url=clean_url,
        expected_address=clean_address,
        expected_chain=clean_chain,
        expected_token_symbol=clean_symbol,
        current_grade_status=clean_grade,
        dry_run=True,
    )
    schema = plan.get("accepted_source_package_schema") or {}
    allowed_tiers = {str(value).strip().lower() for value in schema.get("allowed_source_tiers") or []}
    allowed_address_roles = {str(value).strip().lower() for value in schema.get("allowed_address_roles") or []}
    allowed_route_roles = {str(value).strip().lower() for value in schema.get("allowed_route_roles") or []}
    reject_terms = {str(value).strip().lower() for value in plan.get("reject_if_any") or []}
    required_fields = list(schema.get("required_fields") or [])

    def _host_matches_domain(host: str, domains: tuple[str, ...]) -> bool:
        clean_host = str(host or "").strip().lower()
        return any(clean_host == domain or clean_host.endswith(f".{domain}") for domain in domains)

    def _sha256_digest_ok(value: Any) -> bool:
        text = str(value or "").strip().lower()
        if not text.startswith("sha256:"):
            return False
        digest = text.split(":", 1)[1]
        return len(digest) == 64 and all(ch in "0123456789abcdef" for ch in digest)

    official_hosts = (
        "github.com",
        "gitlab.com",
        "docs.pancakeswap.finance",
        "developer.pancakeswap.finance",
        "developers.pancakeswap.finance",
        "pancakeswap.finance",
        "uniswap.org",
    )
    market_or_explorer_hosts = (
        "web3.okx.com",
        "bscscan.com",
        "etherscan.io",
        "arbiscan.io",
        "polygonscan.com",
        "basescan.org",
        "dexscreener.com",
        "geckoterminal.com",
        "coinmarketcap.com",
        "coingecko.com",
    )
    social_or_forum_hosts = (
        "twitter.com",
        "x.com",
        "t.me",
        "telegram.org",
        "reddit.com",
        "discord.com",
        "discord.gg",
        "medium.com",
    )

    manual_rows: list[dict[str, Any]] = []
    for idx, package in enumerate(safe_sources, start=1):
        package_url = str(package.get("source_url") or "").strip()
        parsed = urllib.parse.urlparse(package_url)
        host = parsed.netloc.lower()
        package_chain = _normalize_chain(str(package.get("chain") or clean_chain))
        package_address = str(package.get("address") or "").strip().lower()
        package_symbol = str(package.get("token_symbol") or clean_symbol).strip()
        source_tier = str(package.get("source_tier") or "").strip().lower()
        source_digest = str(package.get("source_digest") or "").strip()
        evidence_preview = str(package.get("evidence_preview") or "").strip()
        address_role = str(package.get("address_role") or "").strip().lower()
        route_role = str(package.get("route_role_classification") or "").strip().lower()
        observed_ref = str(package.get("observed_context_reference") or "").strip()
        url_surface = " ".join([package_url, host]).lower()
        preview_surface = " ".join([package_url, host, evidence_preview, observed_ref]).lower()
        official_or_canonical = bool(
            source_tier in {"official", "canonical"}
            or _host_matches_domain(host, official_hosts)
            or host.startswith("docs.")
            or ".docs." in host
            or host.startswith("developer.")
            or host.startswith("developers.")
        )
        market_or_explorer_only = _host_matches_domain(host, market_or_explorer_hosts)
        social_or_forum = _host_matches_domain(host, social_or_forum_hosts)
        address_exact_match = bool(clean_address and package_address == clean_address)
        address_seen_in_preview = bool(clean_address and clean_address in preview_surface)
        route_role_present = route_role in allowed_route_roles and (
            route_role.replace("official_", "") in preview_surface
            or route_role == "official_deployment_reference"
            or any(term in preview_surface for term in ("router", "factory", "pool", "pair", "deployment", "registry"))
        )
        blockers = list(dict.fromkeys([
            *("source_url_required" for _ in [1] if not package_url),
            *("https_source_url_required" for _ in [1] if package_url and (parsed.scheme != "https" or not parsed.netloc)),
            *("source_tier_not_allowed" for _ in [1] if source_tier not in allowed_tiers),
            *("source_digest_invalid_shape" for _ in [1] if not _sha256_digest_ok(source_digest)),
            *("evidence_preview_required" for _ in [1] if not evidence_preview),
            *("chain_mismatch" for _ in [1] if package_chain != clean_chain),
            *("expected_address_required" for _ in [1] if not clean_address),
            *("expected_address_invalid" for _ in [1] if clean_address and not _valid_evm_address(clean_address)),
            *("package_address_invalid" for _ in [1] if not _valid_evm_address(package_address)),
            *("exact_address_mismatch" for _ in [1] if clean_address and package_address and package_address != clean_address),
            *("address_not_bound_in_source_preview" for _ in [1] if clean_address and not (address_exact_match or address_seen_in_preview)),
            *("address_role_not_allowed" for _ in [1] if address_role not in allowed_address_roles),
            *("route_role_classification_not_allowed" for _ in [1] if route_role not in allowed_route_roles),
            *("official_or_canonical_source_required" for _ in [1] if not official_or_canonical),
            *("route_role_missing_or_weak" for _ in [1] if not route_role_present),
            *("observed_context_reference_required" for _ in [1] if not observed_ref),
            *("market_price_page_only" for _ in [1] if market_or_explorer_only),
            *("explorer_page_only" for _ in [1] if market_or_explorer_only and "explorer_page_only" in reject_terms),
            *("social_or_forum_claim_only" for _ in [1] if social_or_forum),
            *("symbol_only_result" for _ in [1] if package_symbol and package_symbol.lower() in url_surface and not (address_exact_match or address_seen_in_preview)),
            "source_package_preview_only_no_persistence",
        ]))
        package_status = "eligible_for_future_source_persistence_preview" if blockers == ["source_package_preview_only_no_persistence"] else "blocked"
        computed_digest = hashlib.sha256(
            json.dumps(
                {
                    "source_url": package_url,
                    "source_tier": source_tier,
                    "source_digest": source_digest,
                    "chain": package_chain,
                    "address": package_address,
                    "address_role": address_role,
                    "route_role_classification": route_role,
                    "observed_context_reference": observed_ref,
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        manual_rows.append({
            "input_index": idx,
            "source_url": package_url or None,
            "host": host or None,
            "source_tier": source_tier or None,
            "source_digest_present": bool(source_digest),
            "source_digest_valid_shape": _sha256_digest_ok(source_digest),
            "chain": package_chain,
            "expected_address": clean_address or None,
            "address": package_address or None,
            "token_symbol": package_symbol or None,
            "address_role": address_role or None,
            "route_role_classification": route_role or None,
            "official_or_canonical_source": official_or_canonical,
            "market_or_explorer_only": market_or_explorer_only,
            "social_or_forum": social_or_forum,
            "address_bound": bool(address_exact_match or address_seen_in_preview),
            "route_role_present": route_role_present,
            "source_package_status": package_status,
            "eligible_for_future_source_persistence_preview": package_status == "eligible_for_future_source_persistence_preview",
            "computed_preview_digest": f"sha256:{computed_digest}",
            "blockers": blockers,
            "would_accept_source": False,
            "would_persist_evidence": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_score_for_client": False,
            "would_write": False,
        })

    lookup_rows: list[dict[str, Any]] = []
    external_calls = 0
    external_errors = 0
    if allow_external:
        for query in list((plan.get("search_package") or {}).get("bounded_queries") or [])[:4]:
            clean_query = str(query or "").strip()
            row = {
                "query": clean_query,
                "search_performed": bool(clean_query),
                "results": [],
                "error": None,
            }
            if clean_query:
                try:
                    external_calls += 1
                    for result in _public_source_search_results(clean_query, timeout=safe_timeout, max_results=safe_results):
                        url = str(result.get("url") or "").strip()
                        host = urllib.parse.urlparse(url).netloc.lower() if url else ""
                        title = str(result.get("title") or "").strip()
                        snippet = str(result.get("snippet") or "").strip()
                        surface = " ".join([url, host, title, snippet]).lower()
                        exact_address_seen = bool(clean_address and clean_address in surface)
                        market_or_explorer_only = _host_matches_domain(host, market_or_explorer_hosts)
                        social_or_forum = _host_matches_domain(host, social_or_forum_hosts)
                        official_candidate = bool(
                            _host_matches_domain(host, official_hosts)
                            or host.startswith("docs.")
                            or ".docs." in host
                            or host.startswith("developer.")
                            or host.startswith("developers.")
                        )
                        candidate_blockers = list(dict.fromkeys([
                            *("exact_address_not_seen_in_search_surface" for _ in [1] if not exact_address_seen),
                            *("market_price_page_only" for _ in [1] if market_or_explorer_only),
                            *("social_or_forum_claim_only" for _ in [1] if social_or_forum),
                            *("official_or_canonical_source_not_confirmed" for _ in [1] if not official_candidate),
                            "candidate_url_is_not_route_proof",
                            "source_page_fetch_grading_still_required",
                            "source_not_persisted",
                        ]))
                        row["results"].append({
                            "url": url,
                            "host": host or None,
                            "title": title[:220],
                            "snippet": snippet[:300],
                            "exact_address_seen_in_search_surface": exact_address_seen,
                            "official_or_canonical_candidate": official_candidate,
                            "market_or_explorer_only": market_or_explorer_only,
                            "social_or_forum": social_or_forum,
                            "candidate_status": "source_candidate_not_proof",
                            "blockers": candidate_blockers,
                            "would_fetch_source": False,
                            "would_accept_source": False,
                            "would_persist_evidence": False,
                            "would_write": False,
                        })
                except Exception as exc:
                    external_errors += 1
                    row["error"] = f"{type(exc).__name__}:{str(exc)[:160]}"
            lookup_rows.append(row)

    valid_manual_count = sum(1 for row in manual_rows if row.get("eligible_for_future_source_persistence_preview"))
    blocked_manual_count = len(manual_rows) - valid_manual_count
    candidate_url_count = sum(len(row.get("results") or []) for row in lookup_rows)
    blockers = list(dict.fromkeys([
        *("source_package_not_supplied" for _ in [1] if not safe_sources),
        *("manual_source_packages_blocked" for _ in [1] if blocked_manual_count),
        *("external_lookup_disabled" for _ in [1] if not allow_external),
        *("external_lookup_errors_observed" for _ in [1] if external_errors),
        *("candidate_urls_are_not_proof" for _ in [1] if candidate_url_count),
        "source_package_preview_only_no_persistence",
        "source_backed_scoring_still_disabled",
        "dex_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "allow_external": bool(allow_external),
        "preview_status": "ready_read_only",
        "mode": "unknown_dex_family_context_bounded_official_route_source_package_preview",
        "source_url": clean_url or None,
        "expected_address": clean_address or None,
        "expected_chain": clean_chain,
        "expected_token_symbol": clean_symbol or None,
        "current_grade_status": clean_grade or None,
        "plan_status": plan.get("plan_status"),
        "required_confirm": required_confirm,
        "accepted_source_package_schema": schema,
        "accepted_source_types": plan.get("accepted_source_types") or [],
        "reject_if_any": plan.get("reject_if_any") or [],
        "manual_source_previews": manual_rows,
        "lookup_rows": lookup_rows,
        "summary": {
            "manual_sources_received": len(safe_sources),
            "manual_sources_valid": valid_manual_count,
            "manual_sources_blocked": blocked_manual_count,
            "external_calls_performed": external_calls,
            "external_errors": external_errors,
            "candidate_urls_found": candidate_url_count,
            "official_route_source_packages_ready": 0,
            "source_backed_scoring_ready": 0,
            "client_signal_ready": 0,
            "trade_ready": 0,
            "real_write_enabled": False,
        },
        "policy_gates": {
            "source_package_gate": "preview_only_no_persistence",
            "external_lookup_gate": "confirmed_for_bounded_read_only_lookup" if allow_external else "disabled_by_default",
            "source_acceptance_gate": "blocked",
            "evidence_persistence_gate": "blocked",
            "source_backed_scoring_gate": "blocked",
            "mapping_gate": "blocked",
            "client_signal_gate": "blocked",
            "trade_gate": "blocked",
        },
        "blockers": blockers,
        "next_safe_step": (
            "future_source_persistence_contract_read_only"
            if valid_manual_count else "collect_real_official_route_source_package_or_try_next_candidate"
        ),
        "plain_summary_fr": (
            "Cette preview peut valider la forme d'une preuve officielle, mais elle n'accepte et ne persiste rien. "
            "Les URLs trouvees par lookup restent seulement des candidates, pas des preuves."
        ),
        "would_lookup_source": bool(allow_external),
        "would_call_external": bool(allow_external),
        "external_calls_performed": external_calls,
        **common_disabled,
    }


def get_core_equity_agent_control_plane(
    chain: str | None = "bsc",
    focus: str | None = "unknown_dex_data_quality",
    limit: int = 5,
    dry_run: bool = True,
    allow_live_checks: bool = False,
) -> dict[str, Any]:
    """Read-only control plane that recommends the next bounded Core Equity agent job."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_focus = str(focus or "unknown_dex_data_quality").strip().lower()
    safe_limit = max(1, min(int(limit or 5), 12))
    source_policy = (
        "admin-only read-only Core Equity agent control plane. It reads local diagnostics and existing dry-run "
        "checkpoints, selects a recommended next job, and writes nothing. Live checks are disabled unless "
        "allow_live_checks=true, and even then only read-only RPC/external diagnostics may be planned by downstream "
        "jobs. No labels, mappings, trades, wallet orders, client signals or opt-ins are created."
    )
    disabled_actions = {
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "autonomous_code_edits": True,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "control_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "disabled_actions": disabled_actions,
            "would_call_rpc": False,
            "would_call_external": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            "source_policy": source_policy,
        }

    table_counts = _onchain_table_counts()
    path_workbench = get_unknown_dex_local_transfer_path_workbench(
        chain=requested_chain,
        block_window=10_000,
        limit=safe_limit,
        tx_transfer_limit=80,
        dry_run=True,
    )
    source_repair = get_unknown_dex_local_path_official_source_repair_plan(
        chain=requested_chain,
        block_window=10_000,
        limit=safe_limit,
        tx_transfer_limit=80,
        dry_run=True,
    )
    source_search = get_unknown_dex_local_path_official_source_search_scan(
        chain=requested_chain,
        block_window=10_000,
        limit=safe_limit,
        tx_transfer_limit=80,
        max_targets=min(4, safe_limit),
        queries_per_target=1,
        max_results_per_query=2,
        dry_run=True,
        allow_external=False,
    )
    explorer_hint = get_unknown_dex_local_path_explorer_identity_hint_scan(
        chain=requested_chain,
        block_window=10_000,
        limit=safe_limit,
        tx_transfer_limit=80,
        max_targets=min(4, safe_limit),
        dry_run=True,
        allow_external=False,
    )
    pool_factory = get_unknown_dex_local_path_pool_factory_inference_checkpoint(
        chain=requested_chain,
        block_window=10_000,
        limit=safe_limit,
        tx_transfer_limit=80,
        max_pools=min(4, safe_limit),
        dry_run=True,
        allow_rpc=bool(allow_live_checks),
    )

    path_summary = path_workbench.get("summary") or {}
    source_summary = source_repair.get("summary") or {}
    search_summary = source_search.get("summary") or {}
    explorer_summary = explorer_hint.get("summary") or {}
    factory_summary = pool_factory.get("summary") or {}
    recovered_factories = {
        str(row.get("factory") or "").strip().lower()
        for row in pool_factory.get("rows") or []
        if _valid_evm_address(str(row.get("factory") or "").strip().lower())
    }
    official_factory_addresses = {
        str(row.get("factory_addr") or "").strip().lower()
        for row in _official_factory_registry_rows(requested_chain)
    }
    recovered_official_factories = sorted(recovered_factories & official_factory_addresses)

    candidate_jobs = [
        {
            "job_id": "unknown_dex_collect_more_fresh_path_rows",
            "agent": "Data Agent",
            "reason": "increase repeated local path samples when current path rows are thin",
            "priority_score": 55 + max(0, 5 - int(path_summary.get("local_path_context_ready") or 0)) * 8,
            "endpoint": "/api/onchain/rpc/unknown-dex-traceability-candidate-selector",
            "mode": "dry_run_only",
            "would_write": False,
        },
        {
            "job_id": "unknown_dex_official_source_search_bounded",
            "agent": "Evidence Agent",
            "reason": "ranked source targets exist and need exact official/canonical proof",
            "priority_score": 60 + min(25, int(source_summary.get("source_targets") or 0)),
            "endpoint": "/api/onchain/rpc/unknown-dex-local-path-official-source-search-scan",
            "mode": "dry_run_external_disabled_by_default",
            "would_write": False,
        },
        {
            "job_id": "unknown_dex_explorer_identity_hint_scan",
            "agent": "Evidence Agent",
            "reason": "public search did not find proof; explorer metadata may improve future source queries",
            "priority_score": 58 + max(0, 4 - int(explorer_summary.get("targets_with_metadata") or 0)) * 5,
            "endpoint": "/api/onchain/rpc/unknown-dex-local-path-explorer-identity-hint-scan",
            "mode": "dry_run_external_disabled_by_default",
            "would_write": False,
        },
        {
            "job_id": "unknown_dex_pool_factory_inference_checkpoint",
            "agent": "Evidence Agent",
            "reason": "pair-pool targets can reveal factory/token context when source search is weak",
            "priority_score": 75
            + min(20, int(factory_summary.get("pair_pool_targets_reviewed") or 0) * 5)
            + min(20, int(factory_summary.get("factories_recovered") or 0) * 10),
            "endpoint": "/api/onchain/rpc/unknown-dex-local-path-pool-factory-inference-checkpoint",
            "mode": "dry_run_rpc_disabled_by_default",
            "would_write": False,
        },
        {
            "job_id": "shadow_backtest_hold_until_clean_routes",
            "agent": "Shadow/Backtest Agent",
            "reason": "shadow scoring should stay blocked until multiple source-backed clean route rows exist",
            "priority_score": 20,
            "endpoint": "/api/onchain/rpc/dex-trades-curated/shadow-scoring-plan",
            "mode": "read_only_shadow_only",
            "would_write": False,
        },
    ]
    if int(factory_summary.get("factories_recovered") or 0) > 0:
        candidate_jobs.append({
            "job_id": "unknown_dex_factory_official_source_proof_checkpoint",
            "agent": "Evidence Agent",
            "reason": "factory was recovered in read-only RPC; next proof must tie factory to official/canonical source",
            "priority_score": 115,
            "endpoint": "/api/onchain/rpc/unknown-dex-factory-official-source-proof-checkpoint",
            "mode": "dry_run_external_disabled_by_default",
            "would_write": False,
        })
    if recovered_official_factories:
        family_collection_plan = get_unknown_dex_family_context_collection_plan(
            chain=requested_chain,
            factory_address=recovered_official_factories[0],
            block_window=10_000,
            limit=safe_limit,
            tx_transfer_limit=80,
            max_pools=min(4, safe_limit),
            window_radius_blocks=3,
            max_blocks=30,
            timeout=6,
            dry_run=True,
            allow_rpc=bool(allow_live_checks),
        )
        family_collection_summary = family_collection_plan.get("summary") or {}
        candidate_jobs.append({
            "job_id": "unknown_dex_venue_family_review",
            "agent": "Evidence Agent",
            "reason": "recovered factory already has official source context; review family context while keeping router unmapped",
            "priority_score": 125,
            "endpoint": "/api/onchain/rpc/unknown-dex-venue-family-review",
            "mode": "dry_run_read_only",
            "would_write": False,
            "factory_addresses": recovered_official_factories[:5],
        })
        candidate_jobs.append({
            "job_id": "unknown_dex_family_context_scoring_plan",
            "agent": "Shadow/Backtest Agent",
            "reason": "official pool/factory family context exists; plan research-only scoring without client signals or trades",
            "priority_score": 130,
            "endpoint": "/api/onchain/rpc/unknown-dex-family-context-scoring-plan",
            "mode": "dry_run_research_only",
            "would_write": False,
            "factory_addresses": recovered_official_factories[:5],
        })
        if int(family_collection_summary.get("target_missing_blocks") or 0) > 0:
            candidate_jobs.append({
                "job_id": "unknown_dex_family_context_collection_plan",
                "agent": "Data Agent",
                "reason": "family-context tokens are thin; plan bounded missing-block collection before true scoring",
                "priority_score": 135,
                "endpoint": "/api/onchain/rpc/unknown-dex-family-context-collection-plan",
                "mode": "dry_run_collection_plan_only",
                "would_write": False,
                "factory_addresses": recovered_official_factories[:5],
            })
        else:
            post_collection_audit = get_unknown_dex_family_context_post_collection_audit(
                chain=requested_chain,
                factory_address=recovered_official_factories[0],
                block_window=10_000,
                limit=safe_limit,
                tx_transfer_limit=80,
                max_pools=min(4, safe_limit),
                window_radius_blocks=3,
                max_blocks=30,
                timeout=6,
                dry_run=True,
                allow_rpc=False,
                candidate_limit=safe_limit,
            )
            post_collection_summary = post_collection_audit.get("summary") or {}
            candidate_jobs.append({
                "job_id": "unknown_dex_family_context_post_collection_audit",
                "agent": "Data Agent",
                "reason": "bounded family-context blocks are collected; audit raw swaps/transfers into context-only research candidates",
                "priority_score": 140,
                "endpoint": "/api/onchain/rpc/unknown-dex-family-context-post-collection-audit",
                "mode": "dry_run_post_collection_audit_only",
                "would_write": False,
                "factory_addresses": recovered_official_factories[:5],
            })
            if (
                int(post_collection_summary.get("post_collection_research_candidates") or 0) > 0
                or int(post_collection_summary.get("metadata_missing_tokens") or 0) > 0
                or int(post_collection_summary.get("pool_candidates") or 0) > 0
            ):
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_candidate_repair_plan",
                    "agent": "Evidence Agent",
                    "reason": "post-collection candidates exist but need metadata, route/source, pool and repeatability repairs before any scoring",
                    "priority_score": 145,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-candidate-repair-plan",
                    "mode": "dry_run_repair_plan_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_casefile",
                    "agent": "Research Agent",
                    "reason": "turn context-only candidates into readable casefiles before deciding source repair or more collection",
                    "priority_score": 150,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-casefile",
                    "mode": "dry_run_casefile_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_route_source_repeatability_plan",
                    "agent": "Evidence Agent",
                    "reason": "casefiles are useful but still need exact route-source proof and repeatability before source-backed scoring",
                    "priority_score": 155,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-route-source-repeatability-plan",
                    "mode": "dry_run_route_source_repeatability_plan_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_exact_route_source_proof_acquisition_plan",
                    "agent": "Evidence Agent",
                    "reason": "route-source gaps are known; define exact official/canonical proof packages before any acquisition or mapping",
                    "priority_score": 160,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-exact-route-source-proof-acquisition-plan",
                    "mode": "dry_run_exact_route_source_proof_acquisition_plan_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_bounded_official_source_lookup_plan",
                    "agent": "Evidence Agent",
                    "reason": "exact proof packages are defined; choose bounded official-source lookup or manual source-backed intake without executing it",
                    "priority_score": 165,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-bounded-official-source-lookup-plan",
                    "mode": "dry_run_lookup_or_manual_intake_plan_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_source_acquisition_strategy_decision_preview",
                    "agent": "Policy Agent",
                    "reason": "compare manual source intake preview against future bounded official-source lookup before any source acquisition",
                    "priority_score": 170,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-source-acquisition-strategy-decision-preview",
                    "mode": "dry_run_strategy_decision_preview_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_manual_source_intake_preview",
                    "agent": "Evidence Agent",
                    "reason": "strategy preview recommends manual source intake first; validate source package shape without accepting or persisting evidence",
                    "priority_score": 175,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-manual-source-intake-preview",
                    "mode": "dry_run_manual_source_intake_preview_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_bounded_official_source_lookup_gate",
                    "agent": "Evidence Agent",
                    "reason": "manual intake preview exists but no real sources are verified; define the official/canonical lookup gate before any lookup or persistence",
                    "priority_score": 180,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-bounded-official-source-lookup-gate",
                    "mode": "dry_run_lookup_gate_only",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
                candidate_jobs.append({
                    "job_id": "unknown_dex_family_context_bounded_official_source_lookup",
                    "agent": "Evidence Agent",
                    "reason": "lookup gate is ready; run bounded official/canonical source lookup in dry-run with external search disabled by default",
                    "priority_score": 185,
                    "endpoint": "/api/onchain/rpc/unknown-dex-family-context-bounded-official-source-lookup",
                    "mode": "dry_run_external_disabled_by_default",
                    "would_write": False,
                    "factory_addresses": recovered_official_factories[:5],
                })
    candidate_jobs.sort(key=lambda item: (-int(item.get("priority_score") or 0), str(item.get("job_id") or "")))
    selected_job = candidate_jobs[0] if candidate_jobs else None

    agent_lanes = [
        {
            "agent": "Data Agent",
            "role": "collect bounded raw facts and local context",
            "allowed_now": True,
            "allowed_actions": ["read local DB", "plan bounded collection", "prepare dry-run diagnostics"],
            "blocked_actions": ["labels", "mappings", "trades", "client signals"],
        },
        {
            "agent": "Evidence Agent",
            "role": "grade proof quality and source gaps",
            "allowed_now": True,
            "allowed_actions": ["source repair plans", "explorer hints", "pool/factory inference"],
            "blocked_actions": ["official source creation", "mapping write", "signal write"],
        },
        {
            "agent": "Policy Agent",
            "role": "convert proof state into allow/block decisions",
            "allowed_now": True,
            "allowed_actions": ["block unsafe transitions", "recommend next safe job"],
            "blocked_actions": ["override missing official source", "override client opt-in"],
        },
        {
            "agent": "Research Agent",
            "role": "choose the next best read-only investigation",
            "allowed_now": True,
            "allowed_actions": ["rank jobs", "summarize blockers", "update RAG after verified milestones"],
            "blocked_actions": ["autonomous code edits", "unbounded web/RPC scans"],
        },
        {
            "agent": "Shadow/Backtest Agent",
            "role": "simulate only after enough clean facts exist",
            "allowed_now": True,
            "allowed_actions": ["read-only shadow plans"],
            "blocked_actions": ["client-facing signals", "profit claims", "real trades"],
        },
        {
            "agent": "Trade Agent",
            "role": "future controlled execution under risk/opt-in policy",
            "allowed_now": False,
            "allowed_actions": [],
            "blocked_actions": ["all trade execution", "wallet orders", "perps", "spot", "client automation"],
        },
    ]

    policy_gates = {
        "official_source_gate": "blocked_until_exact_chain_address_official_or_canonical_source",
        "mapping_gate": "blocked",
        "client_signal_gate": "blocked",
        "trade_gate": "blocked",
        "client_opt_in_gate": "blocked",
        "auto_code_change_gate": "blocked_without_codex_validation",
        "shadow_mode": "allowed_read_only",
        "paper_trading": "blocked_until_clean_route_backtests_exist",
        "real_trading": "blocked_until_policy_opt_in_and_risk_engine_exist",
    }

    automation_loop = [
        "observe_local_state",
        "grade_evidence_quality",
        "select_next_bounded_job",
        "run_read_only_or_confirmed_data_only_job",
        "measure_delta",
        "update_rag_audit_memory",
        "repeat_until_policy_gate_allows_shadow_only",
    ]
    blockers = list(dict.fromkeys([
        "official_source_missing_for_unknown_dex_routes",
        "venue_mapping_disabled",
        "client_signal_disabled",
        "trade_disabled",
        "client_opt_in_missing",
        *("live_checks_disabled" for _ in [1] if not allow_live_checks),
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "control_status": "ready_read_only",
        "chain": requested_chain,
        "focus": safe_focus,
        "mode": "agent_control_plane_shadow_read_only",
        "allow_live_checks": bool(allow_live_checks),
        "simple_state": {
            "where_we_are": "data_quality_and_evidence_repair",
            "what_is_ready": "local path context, source repair targets, pool/factory inference checkpoint",
            "what_is_blocked": "official venue identity, mappings, client signals, trades, opt-ins",
            "why_not_trading": "routes are still not source-backed and no client/risk policy is active",
        },
        "data_snapshot": {
            "swaps": int(table_counts.get("swaps", 0)),
            "token_transfers": int(table_counts.get("token_transfers", 0)),
            "pair_tokens": int(table_counts.get("pair_tokens", 0)),
            "dex_trades_curated": int(table_counts.get("dex_trades_curated", 0)),
            "dex_venue_mappings": int(table_counts.get("dex_venue_mappings", 0)),
            "data_jobs": int(table_counts.get("data_jobs", 0)),
        },
        "diagnostic_summaries": {
            "local_path_workbench": path_summary,
            "source_repair_plan": source_summary,
            "source_search_scan": search_summary,
            "explorer_identity_hint_scan": explorer_summary,
            "pool_factory_inference": factory_summary,
        },
        "selected_next_job": selected_job,
        "candidate_jobs": candidate_jobs,
        "agent_lanes": agent_lanes,
        "policy_gates": policy_gates,
        "automation_loop": automation_loop,
        "disabled_actions": disabled_actions,
        "blockers": blockers,
        "would_call_rpc": False,
        "selected_job_requires_rpc": bool(
            selected_job and selected_job.get("job_id") == "unknown_dex_pool_factory_inference_checkpoint"
        ),
        "selected_job_requires_external": bool(
            selected_job
            and selected_job.get("job_id")
            in {
                "unknown_dex_official_source_search_bounded",
                "unknown_dex_explorer_identity_hint_scan",
                "unknown_dex_factory_official_source_proof_checkpoint",
            }
        ),
        "would_call_external": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }


def get_core_equity_agent_task_contract_preview(
    chain: str | None = "bsc",
    focus: str | None = "unknown_dex_data_quality",
    limit: int = 5,
    dry_run: bool = True,
    allow_live_checks: bool = False,
    max_tasks: int = 8,
) -> dict[str, Any]:
    """Read-only Codex-only task contracts for future 24/7 data-improvement cycles."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_limit = max(1, min(int(limit or 5), 12))
    safe_max_tasks = max(1, min(int(max_tasks or 8), 20))
    source_policy = (
        "admin-only read-only Codex task-contract preview. It converts the Core Equity control plane into "
        "bounded task contracts for future scheduled Codex cycles. It does not schedule, run, write, trade, "
        "signal, label, map, create opt-ins, call providers, or grant Hermes/operator authority."
    )
    disabled_actions = {
        "schedule_creation": True,
        "agent_task_execution": True,
        "hermes_operator": True,
        "opencode_operator": True,
        "local_model_operator": True,
        "unbounded_loop": True,
        "db_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "autonomous_code_edits": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_schedule_codex_job": False,
        "would_start_24_7_runner": False,
        "would_run_agent_task": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "task_executed_read_only": False,
        "tasks_executed": 0,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "preview_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    control = get_core_equity_agent_control_plane(
        chain=requested_chain,
        focus=focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
    )
    control_ready = control.get("control_status") == "ready_read_only"
    if not control_ready:
        return {
            "ok": True,
            "dry_run": True,
            "preview_status": "blocked",
            "mode": "core_equity_codex_agent_task_contract_preview",
            "chain": requested_chain,
            "focus": str(focus or "unknown_dex_data_quality").strip().lower(),
            "control_status": control.get("control_status"),
            "task_contracts": [],
            "selected_task_contract": None,
            "blockers": list(dict.fromkeys(["control_plane_not_ready", *(control.get("blockers") or [])])),
            "codex_only_policy": {
                "codex_is_operator": True,
                "hermes_is_operator": False,
                "opencode_is_operator": False,
                "local_models_are_operator": False,
                "sidecars_decide": False,
            },
            **common_disabled,
        }

    forbidden_actions = [
        "unbounded_scan",
        "repo_write_without_codex_patch",
        "db_write",
        "metadata_write",
        "candidate_insert",
        "cex_label_creation",
        "dex_router_evidence_creation",
        "venue_mapping",
        "swap_rewrite",
        "client_signal",
        "wallet_order",
        "trade_execution",
        "client_opt_in",
        "credential_or_secret_access",
        "hermes_runtime_operator",
    ]
    data_quality_success = [
        "returns_structured_report",
        "reports_data_delta_or_blocker",
        "keeps_source_backed_scoring_ready_zero_until_proof_complete",
        "keeps_client_signal_ready_zero",
        "keeps_trade_ready_zero",
        "writes_performed_zero",
    ]

    def _contract_for_job(job: dict[str, Any], selected: bool) -> dict[str, Any]:
        task_id = str(job.get("job_id") or "unknown_task").strip()
        endpoint = str(job.get("endpoint") or "").strip()
        mode = str(job.get("mode") or "dry_run_only").strip()
        agent_role = str(job.get("agent") or "Research Agent").strip()
        needs_rpc = bool(
            task_id in {
                "unknown_dex_pool_factory_inference_checkpoint",
                "unknown_dex_family_context_collection_plan",
            }
        )
        needs_external = bool(
            task_id in {
                "unknown_dex_official_source_search_bounded",
                "unknown_dex_explorer_identity_hint_scan",
                "unknown_dex_factory_official_source_proof_checkpoint",
            }
        )
        writes_allowed_now = False
        return {
            "task_id": task_id,
            "selected_now": bool(selected),
            "agent_role": agent_role,
            "operator": "codex_scheduled_cycle_only",
            "model_policy": {
                "primary": "Codex/GPT-5.5",
                "cloud_review_optional": "OpenCode Go only for manual review, not automatic operator",
                "local_review_optional": "Qwen only for focused read-only snippets, not automatic operator",
                "hermes": "Safe/Lab/report-only, not Core Equity operator",
            },
            "reason": job.get("reason"),
            "priority_score": int(job.get("priority_score") or 0),
            "endpoint": endpoint,
            "mode": mode,
            "factory_addresses": list(job.get("factory_addresses") or []),
            "input_sources": [
                "Core Equity control plane",
                "local read-only diagnostics",
                endpoint or "task_specific_read_only_endpoint",
            ],
            "allowed_actions_now": [
                "read control-plane state",
                "call dry-run/read-only endpoint only",
                "summarize blockers",
                "measure whether data quality improved",
                "write audit report only after a future runner exists",
            ],
            "forbidden_actions": forbidden_actions,
            "dry_run_default": True,
            "confirm_required_for_any_non_read_only_future": True,
            "writes_allowed_now": writes_allowed_now,
            "future_raw_data_write_possible": (
                "only in a separate confirmed data-only task contract"
                if agent_role == "Data Agent" else "not in this contract"
            ),
            "requires_rpc_if_run_later": needs_rpc,
            "requires_external_if_run_later": needs_external,
            "max_runtime_seconds_initial": 900 if needs_rpc else 300,
            "budget_policy": {
                "max_tasks_per_cycle": 1,
                "max_rpc_blocks_per_cycle": 30 if needs_rpc else 0,
                "max_external_calls_per_cycle": 0,
                "stop_on_error": True,
            },
            "expected_outputs": [
                "ok",
                "status",
                "summary",
                "blockers",
                "next_safe_step",
                "would_write=false",
                "writes_performed=0",
            ],
            "success_criteria": data_quality_success,
            "failure_blockers": [
                "endpoint_missing",
                "dry_run_refused",
                "unexpected_write_flag",
                "writes_performed_nonzero",
                "label_mapping_trade_or_signal_flag_true",
                "timeout",
                "malformed_output",
            ],
            "audit_log_required": True,
            "self_improvement_role": "improve_data_quality_or_proof_quality_only",
            "not_allowed_to_decide": [
                "label finality",
                "DEX mapping finality",
                "client signal",
                "trade entry",
                "wallet order",
                "client opt-in",
            ],
            "would_run_now": False,
            "would_write": False,
        }

    candidate_jobs = list(control.get("candidate_jobs") or [])[:safe_max_tasks]
    selected_job_id = str((control.get("selected_next_job") or {}).get("job_id") or "")
    task_contracts = [
        _contract_for_job(job, str(job.get("job_id") or "") == selected_job_id)
        for job in candidate_jobs
    ]
    selected_contract = next((row for row in task_contracts if row.get("selected_now")), None)
    automation_readiness = {
        "can_run_24_7_eventually": True,
        "can_run_24_7_now": False,
        "why_not_now": [
            "runner_not_implemented",
            "audit_log_table_or_report_contract_not_finalized",
            "max_cycle_budget_not_enforced_by_runtime_yet",
            "raw_data_write_mode_not_separated_from_read_only_mode_yet",
        ],
        "safe_initial_schedule_after_runner_exists": "every_60_to_120_minutes_read_only_single_task",
        "always_on_trading": "blocked_until_shadow_paper_policy_risk_and_client_opt_in_exist",
    }
    codex_self_improvement_loop = [
        "wake_scheduled_codex_cycle",
        "read_control_plane",
        "select_one_task_contract",
        "verify_contract_allows_read_only_or_data_only_action",
        "run_task_with_budget",
        "validate_output_schema_and_write_flags",
        "measure_data_or_proof_quality_delta",
        "write_audit_report",
        "stop_cycle",
    ]
    return {
        "ok": True,
        "dry_run": True,
        "preview_status": "ready_read_only",
        "mode": "core_equity_codex_agent_task_contract_preview",
        "chain": requested_chain,
        "focus": str(focus or "unknown_dex_data_quality").strip().lower(),
        "control_status": control.get("control_status"),
        "codex_only_policy": {
            "codex_is_operator": True,
            "codex_can_schedule_future_cycles": True,
            "hermes_is_operator": False,
            "opencode_is_operator": False,
            "local_models_are_operator": False,
            "sidecars_decide": False,
            "human_required_for_enabling_runner": True,
        },
        "automation_readiness": automation_readiness,
        "selected_task_contract": selected_contract,
        "task_contracts": task_contracts,
        "task_contract_schema": [
            "task_id",
            "agent_role",
            "operator",
            "model_policy",
            "input_sources",
            "allowed_actions_now",
            "forbidden_actions",
            "dry_run_default",
            "confirm_required_for_any_non_read_only_future",
            "writes_allowed_now",
            "budget_policy",
            "expected_outputs",
            "success_criteria",
            "failure_blockers",
            "audit_log_required",
        ],
        "codex_self_improvement_loop": codex_self_improvement_loop,
        "control_plane_snapshot": {
            "selected_next_job": control.get("selected_next_job"),
            "simple_state": control.get("simple_state"),
            "data_snapshot": control.get("data_snapshot"),
            "policy_gates": control.get("policy_gates"),
        },
        "blockers": [
            "runner_not_enabled",
            "schedule_not_created",
            "all_tasks_preview_only",
            "trading_disabled",
            "client_signal_disabled",
            "client_opt_in_missing",
        ],
        "next_safe_step": "implement_read_only_codex_agent_runner_dry_run_or_create_codex_schedule_after_user_confirms",
        **common_disabled,
    }


def run_dex_local_event_reader_sqd_lookup_dry_run(
    event_reader_run_id: int | None,
    dry_run: bool = True,
    allow_external: bool = False,
    confirm: str | None = None,
    max_sqd_calls: int = 24,
    max_logs_total: int = 2_000,
    timeout: int = 8,
) -> dict[str, Any]:
    """Bounded SQD lookup for a planned DEX local event-reader run, with no persistence."""
    source_policy = (
        "admin-only bounded SQD event-reader lookup dry-run. It can call SQD Portal only for already planned "
        "event-reader filters after explicit confirmation, parses logs in memory, and persists nothing. It creates "
        "no raw events, evidence, mappings, labels, client signals, trades, wallet orders or opt-ins."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_insert_raw_event": False,
        "would_persist_paircreated_evidence": False,
        "would_update_checkpoint": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "sqd_lookup_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }
    if event_reader_run_id is None:
        return {
            "ok": True,
            "dry_run": True,
            "sqd_lookup_status": "blocked",
            "error": "event_reader_run_id_required",
            "blockers": ["event_reader_run_id_required"],
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }
    try:
        safe_max_sqd_calls = max(1, min(int(max_sqd_calls or 24), 100))
    except (TypeError, ValueError):
        safe_max_sqd_calls = 24
    try:
        safe_max_logs_total = max(1, min(int(max_logs_total or 2_000), 20_000))
    except (TypeError, ValueError):
        safe_max_logs_total = 2_000
    safe_timeout = max(2, min(int(timeout or 8), 15))

    contract = get_dex_local_event_reader_execution_contract(
        event_reader_run_id=event_reader_run_id,
        dry_run=True,
        max_rpc_calls=100,
    )
    contract_blockers = list(contract.get("blockers") or [])
    if contract.get("execution_contract_status") != "ready_but_disabled" or contract_blockers:
        return {
            "ok": True,
            "dry_run": True,
            "sqd_lookup_status": "blocked",
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "blockers": list(dict.fromkeys(["execution_contract_not_ready", *contract_blockers])),
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }
    planned_calls = list(contract.get("planned_rpc_calls_preview") or [])
    selected_calls = planned_calls[:safe_max_sqd_calls]
    if not allow_external:
        return {
            "ok": True,
            "dry_run": True,
            "sqd_lookup_status": "ready_but_external_disabled",
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "planned_call_count": contract.get("planned_rpc_call_count"),
            "selected_sqd_call_count": len(selected_calls),
            "required_confirm": "RUN_DEX_LOCAL_EVENT_READER_SQD_LOOKUP",
            "blockers": ["allow_external_required_for_sqd_lookup"],
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }
    if confirm != "RUN_DEX_LOCAL_EVENT_READER_SQD_LOOKUP":
        return {
            "ok": True,
            "dry_run": True,
            "sqd_lookup_status": "blocked",
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "planned_call_count": contract.get("planned_rpc_call_count"),
            "selected_sqd_call_count": len(selected_calls),
            "required_confirm": "RUN_DEX_LOCAL_EVENT_READER_SQD_LOOKUP",
            "blockers": ["confirm_RUN_DEX_LOCAL_EVENT_READER_SQD_LOOKUP_required"],
            "would_call_external": False,
            "external_calls_performed": 0,
            **common_disabled,
        }

    chain = str(contract.get("chain") or "bsc")
    call_results: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    event_counts: dict[str, int] = {}
    endpoint_counts: dict[str, int] = {}
    key_sources: dict[str, int] = {}
    request_previews: list[dict[str, Any]] = []
    log_previews: list[dict[str, Any]] = []
    total_logs = 0
    truncated = False

    for call in selected_calls:
        event_name = str(call.get("event_name") or "")
        log_filter = {
            "address": call.get("address"),
            "fromBlock": call.get("from_block_hex"),
            "toBlock": call.get("to_block_hex"),
            "topics": call.get("topics") or [],
        }
        logs, endpoint, error, key_source, request_preview = _sqd_portal_event_logs(
            chain,
            log_filter,
            timeout=safe_timeout,
        )
        if endpoint:
            endpoint_counts[endpoint] = endpoint_counts.get(endpoint, 0) + 1
        if key_source:
            key_sources[key_source] = key_sources.get(key_source, 0) + 1
        if len(request_previews) < 3 and request_preview:
            request_previews.append(request_preview)
        if error:
            error_row = {
                "checkpoint_id": call.get("checkpoint_id"),
                "event_name": event_name,
                "filter_role": call.get("filter_role"),
                "address": call.get("address"),
                "from_block": call.get("from_block"),
                "to_block": call.get("to_block"),
                "error": error,
            }
            errors.append(error_row)
            call_results.append({**error_row, "status": "error", "log_count": 0})
            continue
        total_logs += len(logs)
        event_counts[event_name] = event_counts.get(event_name, 0) + len(logs)
        for log in logs:
            if len(log_previews) >= min(25, safe_max_logs_total):
                break
            log_previews.append(_dex_event_reader_log_preview(event_name, log))
        call_results.append({
            "checkpoint_id": call.get("checkpoint_id"),
            "event_name": event_name,
            "filter_role": call.get("filter_role"),
            "address": call.get("address"),
            "from_block": call.get("from_block"),
            "to_block": call.get("to_block"),
            "endpoint": endpoint,
            "log_count": len(logs),
            "status": "ok",
        })
        if total_logs > safe_max_logs_total:
            truncated = True
            errors.append({
                "error": "max_logs_total_exceeded",
                "max_logs_total": safe_max_logs_total,
                "observed_logs": total_logs,
            })
            break

    external_calls = len(call_results)
    partial = len(selected_calls) < int(contract.get("planned_rpc_call_count") or 0)
    status = "completed_no_persistence"
    if errors:
        status = "completed_with_errors_no_persistence"
    if partial:
        status = "partial_no_persistence" if not errors else "partial_with_errors_no_persistence"
    blockers = list(dict.fromkeys([
        *("sqd_errors_observed" for _ in [1] if errors),
        *("execution_truncated_by_max_logs_total" for _ in [1] if truncated),
        *("partial_lookup_due_to_max_sqd_calls" for _ in [1] if partial),
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "sqd_lookup_status": status,
        "event_reader_run_id": event_reader_run_id,
        "contract_status": contract.get("execution_contract_status"),
        "chain": chain,
        "run_status": contract.get("run_status"),
        "checkpoint_count": contract.get("checkpoint_count"),
        "planned_call_count": contract.get("planned_rpc_call_count"),
        "selected_sqd_call_count": len(selected_calls),
        "external_calls_performed": external_calls,
        "total_logs_seen": total_logs,
        "event_counts": event_counts,
        "endpoint_counts": endpoint_counts,
        "api_key_sources_used": key_sources,
        "call_results": call_results,
        "log_previews": log_previews,
        "request_previews": request_previews,
        "truncated": truncated,
        "errors": errors,
        "blockers": blockers,
        "next_safe_step": (
            "raw_event_persistence_schema_or_event_proof_package_plan_read_only"
            if total_logs and not errors else "repair_sqd_lookup_or_try_forward_only_reader"
        ),
        "would_call_external": True,
        "would_call_rpc": False,
        **common_disabled,
    }


def persist_dex_local_event_reader_sqd_raw_events(
    event_reader_run_id: int | None,
    dry_run: bool = True,
    allow_external: bool = False,
    confirm: str | None = None,
    expected_persistence_dedupe_digest: str | None = None,
    max_sqd_calls: int = 24,
    max_logs_total: int = 2_000,
    timeout: int = 8,
) -> dict[str, Any]:
    """Dry-run-first persistence of SQD logs into raw event tables only."""
    preview_confirm = "PREVIEW_DEX_LOCAL_EVENT_READER_SQD_RAW_EVENT_PERSISTENCE"
    persist_confirm = "PERSIST_DEX_LOCAL_EVENT_READER_SQD_RAW_EVENTS"
    source_policy = (
        "admin-only dry-run-first SQD raw event persistence lane. It may call SQD only for planned "
        "event-reader filters after explicit confirmation. Confirmed writes are limited to raw event tables; "
        "it does not persist PairCreated evidence, create mappings/router evidence/labels, emit client signals, "
        "execute trades, create wallet orders or opt-ins."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_update_checkpoint": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "source_policy": source_policy,
    }
    if event_reader_run_id is None:
        return {
            "ok": True,
            "dry_run": bool(dry_run),
            "persistence_status": "blocked",
            "error": "event_reader_run_id_required",
            "blockers": ["event_reader_run_id_required"],
            "would_call_external": False,
            "external_calls_performed": 0,
            "would_insert_raw_event": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            **common_disabled,
        }
    try:
        safe_max_sqd_calls = max(1, min(int(max_sqd_calls or 24), 100))
    except (TypeError, ValueError):
        safe_max_sqd_calls = 24
    try:
        safe_max_logs_total = max(1, min(int(max_logs_total or 2_000), 20_000))
    except (TypeError, ValueError):
        safe_max_logs_total = 2_000
    safe_timeout = max(2, min(int(timeout or 8), 15))

    blockers: list[str] = []
    if not allow_external:
        blockers.append("allow_external_required_for_sqd_raw_event_persistence_preview")
    if dry_run and allow_external and confirm not in {preview_confirm, persist_confirm}:
        blockers.append("confirm_PREVIEW_DEX_LOCAL_EVENT_READER_SQD_RAW_EVENT_PERSISTENCE_required")
    if not dry_run:
        if confirm != persist_confirm:
            blockers.append("confirm_PERSIST_DEX_LOCAL_EVENT_READER_SQD_RAW_EVENTS_required")
        if not str(expected_persistence_dedupe_digest or "").strip():
            blockers.append("expected_persistence_dedupe_digest_required")

    contract = get_dex_local_event_reader_execution_contract(
        event_reader_run_id=event_reader_run_id,
        dry_run=True,
        max_rpc_calls=100,
    )
    contract_blockers = list(contract.get("blockers") or [])
    if contract.get("execution_contract_status") != "ready_but_disabled" or contract_blockers:
        blockers.extend(["execution_contract_not_ready", *contract_blockers])
    planned_calls = list(contract.get("planned_rpc_calls_preview") or [])
    selected_calls = planned_calls[:safe_max_sqd_calls]
    required_tables = {
        "dex_raw_paircreated_events",
        "dex_raw_swap_events",
        "erc20_transfer_events",
    }
    conn = _get_db()
    try:
        table_status: dict[str, dict[str, Any]] = {}
        for table_name in sorted(required_tables):
            exists = _table_exists(conn, table_name)
            count = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0) if exists else 0
            table_status[table_name] = {"exists": exists, "row_count": count}
            if not exists:
                blockers.append(f"{table_name}_missing")
    finally:
        conn.close()

    if blockers:
        return {
            "ok": False,
            "dry_run": bool(dry_run),
            "persistence_status": "blocked",
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "planned_call_count": contract.get("planned_rpc_call_count"),
            "selected_sqd_call_count": len(selected_calls),
            "table_status": table_status if "table_status" in locals() else {},
            "required_preview_confirm": preview_confirm,
            "required_persist_confirm": persist_confirm,
            "blockers": list(dict.fromkeys(blockers)),
            "would_call_external": False,
            "external_calls_performed": 0,
            "would_insert_raw_event": False,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            **common_disabled,
        }

    chain = str(contract.get("chain") or "bsc")
    raw_source_policy = (
        "SQD Portal raw event persisted as raw observation only from planned local event-reader filters. "
        "This raw row is not evidence acceptance, not a DEX mapping, not a client signal and not a trade."
    )
    call_results: list[dict[str, Any]] = []
    raw_candidates: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    event_counts: dict[str, int] = {}
    endpoint_counts: dict[str, int] = {}
    total_logs = 0
    truncated = False

    for call in selected_calls:
        event_name = str(call.get("event_name") or "")
        log_filter = {
            "address": call.get("address"),
            "fromBlock": call.get("from_block_hex"),
            "toBlock": call.get("to_block_hex"),
            "topics": call.get("topics") or [],
        }
        logs, endpoint, error, _key_source, _request_preview = _sqd_portal_event_logs(
            chain,
            log_filter,
            timeout=safe_timeout,
        )
        if endpoint:
            endpoint_counts[endpoint] = endpoint_counts.get(endpoint, 0) + 1
        if error:
            errors.append({
                "checkpoint_id": call.get("checkpoint_id"),
                "event_name": event_name,
                "error": error,
            })
            call_results.append({
                "checkpoint_id": call.get("checkpoint_id"),
                "event_name": event_name,
                "status": "error",
                "log_count": 0,
                "error": error,
            })
            continue
        total_logs += len(logs)
        event_counts[event_name] = event_counts.get(event_name, 0) + len(logs)
        for log in logs:
            if len(raw_candidates) >= safe_max_logs_total:
                truncated = True
                break
            raw_candidates.append(_dex_event_reader_raw_candidate_from_log(
                event_name,
                call,
                log,
                chain,
                raw_source_policy,
            ))
        call_results.append({
            "checkpoint_id": call.get("checkpoint_id"),
            "event_name": event_name,
            "filter_role": call.get("filter_role"),
            "address": call.get("address"),
            "from_block": call.get("from_block"),
            "to_block": call.get("to_block"),
            "status": "ok",
            "log_count": len(logs),
        })
        if truncated:
            errors.append({
                "error": "max_logs_total_reached",
                "max_logs_total": safe_max_logs_total,
            })
            break

    candidate_blockers = [
        blocker
        for candidate in raw_candidates
        for blocker in (candidate.get("blockers") or [])
    ]
    event_dedupe_keys = [
        str(candidate.get("event_dedupe_key") or "")
        for candidate in raw_candidates
        if candidate.get("event_dedupe_key") and not candidate.get("blockers")
    ]
    persistence_dedupe_digest = hashlib.sha256(
        json.dumps(sorted(event_dedupe_keys), sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest() if event_dedupe_keys else None

    duplicates: list[str] = []
    conn = _get_db()
    try:
        for candidate in raw_candidates:
            if candidate.get("blockers"):
                continue
            table_name = str(candidate.get("target_table") or "")
            dedupe_key = str(candidate.get("event_dedupe_key") or "")
            if table_name not in required_tables or not dedupe_key:
                continue
            row = conn.execute(
                f"SELECT id FROM {table_name} WHERE event_dedupe_key = ? LIMIT 1",
                (dedupe_key,),
            ).fetchone()
            if row:
                duplicates.append(dedupe_key)
    finally:
        conn.close()

    if errors:
        blockers.append("sqd_lookup_errors_observed")
    if truncated:
        blockers.append("max_logs_total_reached")
    if candidate_blockers:
        blockers.append("raw_candidate_parse_blockers")
    if duplicates:
        blockers.append("duplicate_raw_event_dedupe_key")
    if not raw_candidates:
        blockers.append("no_sqd_logs_to_persist")
    if not dry_run and persistence_dedupe_digest != str(expected_persistence_dedupe_digest or "").strip():
        blockers.append("expected_persistence_dedupe_digest_mismatch")

    clean_candidates = [
        candidate for candidate in raw_candidates
        if not candidate.get("blockers") and candidate.get("event_dedupe_key") not in duplicates
    ]
    target_counts: dict[str, int] = {}
    for candidate in clean_candidates:
        table_name = str(candidate.get("target_table") or "")
        target_counts[table_name] = target_counts.get(table_name, 0) + 1
    blockers = list(dict.fromkeys(blockers))
    would_insert = bool(not blockers and clean_candidates)
    status = "ready_for_persistence" if would_insert else "blocked"
    preview_rows = [candidate.get("preview") for candidate in raw_candidates[:25]]
    if dry_run or blockers:
        return {
            "ok": bool(not blockers),
            "dry_run": bool(dry_run),
            "persistence_status": status,
            "event_reader_run_id": event_reader_run_id,
            "contract_status": contract.get("execution_contract_status"),
            "planned_call_count": contract.get("planned_rpc_call_count"),
            "selected_sqd_call_count": len(selected_calls),
            "external_calls_performed": len(call_results),
            "total_logs_seen": total_logs,
            "raw_event_candidates": len(raw_candidates),
            "clean_raw_event_candidates": len(clean_candidates),
            "target_insert_counts": target_counts,
            "event_counts": event_counts,
            "endpoint_counts": endpoint_counts,
            "persistence_dedupe_digest": persistence_dedupe_digest,
            "expected_persistence_dedupe_digest": expected_persistence_dedupe_digest,
            "required_preview_confirm": preview_confirm,
            "required_persist_confirm": persist_confirm,
            "call_results": call_results,
            "raw_event_previews": preview_rows,
            "duplicate_event_dedupe_keys": duplicates[:25],
            "blockers": blockers,
            "would_call_external": True,
            "would_insert_raw_event": would_insert,
            "would_insert_raw_event_count": len(clean_candidates) if would_insert else 0,
            "inserted": False,
            "rows_inserted": 0,
            "would_write": False,
            "real_write_enabled": False,
            "writes_performed": 0,
            **common_disabled,
        }

    conn = _get_db()
    try:
        for candidate in clean_candidates:
            table_name = str(candidate.get("target_table") or "")
            columns = list(candidate.get("insert_columns") or [])
            values = list(candidate.get("insert_values") or [])
            placeholders = ", ".join("?" for _ in columns)
            column_sql = ", ".join(columns)
            conn.execute(
                f"INSERT INTO {table_name} ({column_sql}) VALUES ({placeholders})",
                values,
            )
        conn.commit()
        row_counts_after = {
            table_name: int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0)
            for table_name in sorted(required_tables)
        }
    finally:
        conn.close()

    return {
        "ok": True,
        "dry_run": False,
        "persistence_status": "inserted",
        "event_reader_run_id": event_reader_run_id,
        "contract_status": contract.get("execution_contract_status"),
        "planned_call_count": contract.get("planned_rpc_call_count"),
        "selected_sqd_call_count": len(selected_calls),
        "external_calls_performed": len(call_results),
        "total_logs_seen": total_logs,
        "raw_event_candidates": len(raw_candidates),
        "clean_raw_event_candidates": len(clean_candidates),
        "target_insert_counts": target_counts,
        "event_counts": event_counts,
        "persistence_dedupe_digest": persistence_dedupe_digest,
        "row_counts_after": row_counts_after,
        "inserted": True,
        "rows_inserted": len(clean_candidates),
        "would_call_external": False,
        "would_insert_raw_event": False,
        "would_write": False,
        "real_write_enabled": True,
        "writes_performed": len(clean_candidates),
        "blockers": [],
        **common_disabled,
    }


def get_dex_local_event_reader_proof_package_preview(
    event_reader_run_id: int | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only proof-package preview from persisted local raw DEX events."""
    source_policy = (
        "admin-only read-only DEX local event proof-package preview. It reads persisted raw event rows and "
        "checkpoint scope, binds payload digests, and creates no proof package, evidence promotion, mapping, "
        "router evidence, label, client signal, trade, wallet order or opt-in."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_create_proof_package": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    if event_reader_run_id is None:
        blockers.append("event_reader_run_id_required")

    required_tables = [
        "dex_event_reader_runs",
        "dex_event_reader_checkpoints",
        "dex_raw_paircreated_events",
        "dex_raw_swap_events",
        "erc20_transfer_events",
        "dex_event_proof_packages",
    ]
    table_status: dict[str, dict[str, Any]] = {}
    run: dict[str, Any] | None = None
    checkpoints: list[dict[str, Any]] = []
    paircreated_rows: list[dict[str, Any]] = []
    swap_rows: list[dict[str, Any]] = []
    transfer_rows: list[dict[str, Any]] = []
    existing_package_count = 0
    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        for table_name in required_tables:
            exists = _table_exists(conn, table_name)
            count = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0) if exists else 0
            table_status[table_name] = {"exists": exists, "row_count": count}
            if not exists:
                blockers.append(f"{table_name}_missing")

        if event_reader_run_id is not None and _table_exists(conn, "dex_event_reader_runs"):
            row = conn.execute(
                "SELECT * FROM dex_event_reader_runs WHERE id = ? LIMIT 1",
                (event_reader_run_id,),
            ).fetchone()
            if row:
                run = dict(row)
            else:
                blockers.append("event_reader_run_missing")

        if event_reader_run_id is not None and _table_exists(conn, "dex_event_reader_checkpoints"):
            checkpoints = [
                dict(row)
                for row in conn.execute(
                    "SELECT * FROM dex_event_reader_checkpoints WHERE run_id = ? ORDER BY id",
                    (event_reader_run_id,),
                ).fetchall()
            ]
            if not checkpoints:
                blockers.append("event_reader_checkpoints_missing")

        if event_reader_run_id is not None and _table_exists(conn, "dex_raw_paircreated_events"):
            paircreated_rows = [
                dict(row)
                for row in conn.execute(
                    """
                    SELECT e.*
                    FROM dex_raw_paircreated_events e
                    JOIN dex_event_reader_checkpoints c ON c.id = e.checkpoint_id
                    WHERE c.run_id = ?
                    ORDER BY e.block_number, e.log_index, e.id
                    """,
                    (event_reader_run_id,),
                ).fetchall()
            ]
        if event_reader_run_id is not None and _table_exists(conn, "dex_raw_swap_events"):
            swap_rows = [
                dict(row)
                for row in conn.execute(
                    """
                    SELECT e.*
                    FROM dex_raw_swap_events e
                    JOIN dex_event_reader_checkpoints c ON c.id = e.checkpoint_id
                    WHERE c.run_id = ?
                    ORDER BY e.block_number, e.log_index, e.id
                    """,
                    (event_reader_run_id,),
                ).fetchall()
            ]
        if event_reader_run_id is not None and _table_exists(conn, "erc20_transfer_events"):
            transfer_rows = [
                dict(row)
                for row in conn.execute(
                    """
                    SELECT e.*
                    FROM erc20_transfer_events e
                    JOIN dex_event_reader_checkpoints c ON c.id = e.checkpoint_id
                    WHERE c.run_id = ?
                    ORDER BY e.block_number, e.log_index, e.id
                    """,
                    (event_reader_run_id,),
                ).fetchall()
            ]
        if _table_exists(conn, "dex_event_proof_packages"):
            existing_package_count = int(
                conn.execute("SELECT COUNT(*) FROM dex_event_proof_packages").fetchone()[0] or 0
            )
    finally:
        conn.close()

    event_scope: dict[str, Any] = {}
    event_scope_json_valid = False
    if run:
        try:
            parsed = json.loads(str(run.get("event_scope_json") or "{}"))
            if isinstance(parsed, dict):
                event_scope = parsed
                event_scope_json_valid = True
        except (TypeError, json.JSONDecodeError):
            event_scope_json_valid = False
        if not event_scope_json_valid:
            blockers.append("event_scope_json_invalid")

    chain = _normalize_chain(str((run or {}).get("chain") or event_scope.get("chain") or "bsc"))
    expected_factory = str((run or {}).get("factory_address") or event_scope.get("factory_address") or "").lower()
    expected_pair = str(event_scope.get("pair_address") or "").lower()
    expected_token0 = str(event_scope.get("token0") or "").lower()
    expected_token1 = str(event_scope.get("token1") or "").lower()
    if expected_factory and not _valid_evm_address(expected_factory):
        blockers.append("expected_factory_invalid")
    if expected_pair and not _valid_evm_address(expected_pair):
        blockers.append("expected_pair_invalid")
    if expected_token0 and not _valid_evm_address(expected_token0):
        blockers.append("expected_token0_invalid")
    if expected_token1 and not _valid_evm_address(expected_token1):
        blockers.append("expected_token1_invalid")

    if len(paircreated_rows) != 1:
        blockers.append("exactly_one_raw_paircreated_required")
    if len(transfer_rows) < 2:
        blockers.append("at_least_two_raw_transfer_context_events_required")
    if swap_rows:
        blockers.append("swap_raw_rows_present_but_not_used_by_this_package")

    def _digest_bound(row: Mapping[str, Any]) -> bool:
        raw_json = str(row.get("raw_log_json") or "")
        return bool(raw_json) and hashlib.sha256(raw_json.encode("utf-8")).hexdigest() == str(row.get("payload_digest") or "")

    paircreated_preview: dict[str, Any] | None = None
    transfer_previews: list[dict[str, Any]] = []
    payload_digest_bindings: list[dict[str, Any]] = []
    token_transfer_coverage: dict[str, bool] = {}
    if paircreated_rows:
        row = paircreated_rows[0]
        row_blockers: list[str] = []
        raw_log: dict[str, Any] = {}
        try:
            parsed_log = json.loads(str(row.get("raw_log_json") or "{}"))
            raw_log = parsed_log if isinstance(parsed_log, dict) else {}
        except (TypeError, json.JSONDecodeError):
            row_blockers.append("paircreated_raw_log_json_invalid")
        raw_topics = [str(item).lower() for item in (raw_log.get("topics") or [])]
        raw_data = str(raw_log.get("data") or "0x")
        raw_pair = _dex_event_reader_topic_address(
            "0x" + raw_data[2:66] if raw_data.startswith("0x") else "0x" + raw_data[:64]
        )
        raw_token0 = _dex_event_reader_topic_address(raw_topics[1] if len(raw_topics) > 1 else None)
        raw_token1 = _dex_event_reader_topic_address(raw_topics[2] if len(raw_topics) > 2 else None)
        if str(row.get("status") or "") != "raw_observed":
            row_blockers.append("paircreated_status_not_raw_observed")
        if str(row.get("chain") or "").lower() != chain:
            row_blockers.append("paircreated_chain_mismatch")
        if expected_factory and str(row.get("factory_address") or "").lower() != expected_factory:
            row_blockers.append("paircreated_factory_mismatch")
        if expected_pair and str(row.get("pair_address") or "").lower() != expected_pair:
            row_blockers.append("paircreated_pair_mismatch")
        if expected_token0 and str(row.get("token0") or "").lower() != expected_token0:
            row_blockers.append("paircreated_token0_mismatch")
        if expected_token1 and str(row.get("token1") or "").lower() != expected_token1:
            row_blockers.append("paircreated_token1_mismatch")
        if str(row.get("event_topic") or "").lower() != PAIR_CREATED_TOPIC:
            row_blockers.append("paircreated_topic_mismatch")
        if raw_log and str(raw_log.get("address") or "").lower() != str(row.get("factory_address") or "").lower():
            row_blockers.append("paircreated_raw_log_factory_mismatch")
        if raw_topics and raw_topics[0] != PAIR_CREATED_TOPIC:
            row_blockers.append("paircreated_raw_topic_mismatch")
        if raw_pair and raw_pair != str(row.get("pair_address") or "").lower():
            row_blockers.append("paircreated_raw_pair_mismatch")
        if raw_token0 and raw_token0 != str(row.get("token0") or "").lower():
            row_blockers.append("paircreated_raw_token0_mismatch")
        if raw_token1 and raw_token1 != str(row.get("token1") or "").lower():
            row_blockers.append("paircreated_raw_token1_mismatch")
        if not _digest_bound(row):
            row_blockers.append("paircreated_payload_digest_mismatch")
        blockers.extend(row_blockers)
        payload_digest_bindings.append({
            "table": "dex_raw_paircreated_events",
            "id": row.get("id"),
            "event_dedupe_key": row.get("event_dedupe_key"),
            "payload_digest": row.get("payload_digest"),
            "digest_bound": not row_blockers or "paircreated_payload_digest_mismatch" not in row_blockers,
        })
        paircreated_preview = {
            "raw_paircreated_event_id": row.get("id"),
            "checkpoint_id": row.get("checkpoint_id"),
            "factory_address": row.get("factory_address"),
            "pair_address": row.get("pair_address"),
            "token0": row.get("token0"),
            "token1": row.get("token1"),
            "tx_hash": row.get("tx_hash"),
            "log_index": row.get("log_index"),
            "block_number": row.get("block_number"),
            "payload_digest": row.get("payload_digest"),
            "event_dedupe_key": row.get("event_dedupe_key"),
            "blockers": row_blockers,
        }

    expected_tokens = {token for token in [expected_token0, expected_token1] if _valid_evm_address(token)}
    for row in transfer_rows:
        row_blockers: list[str] = []
        token_address = str(row.get("token_address") or "").lower()
        from_address = str(row.get("from_address") or "").lower()
        to_address = str(row.get("to_address") or "").lower()
        if str(row.get("status") or "") != "raw_observed":
            row_blockers.append("transfer_status_not_raw_observed")
        if str(row.get("chain") or "").lower() != chain:
            row_blockers.append("transfer_chain_mismatch")
        if expected_tokens and token_address not in expected_tokens:
            row_blockers.append("transfer_token_not_in_pair")
        if expected_pair and expected_pair not in {from_address, to_address}:
            row_blockers.append("transfer_not_pair_related")
        if not _digest_bound(row):
            row_blockers.append("transfer_payload_digest_mismatch")
        try:
            raw_log = json.loads(str(row.get("raw_log_json") or "{}"))
            raw_topics = [str(item).lower() for item in (raw_log.get("topics") or [])] if isinstance(raw_log, dict) else []
            if raw_topics and raw_topics[0] != TRANSFER_TOPIC:
                row_blockers.append("transfer_raw_topic_mismatch")
        except (TypeError, json.JSONDecodeError):
            row_blockers.append("transfer_raw_log_json_invalid")
        if token_address in expected_tokens:
            token_transfer_coverage[token_address] = True
        blockers.extend(row_blockers)
        payload_digest_bindings.append({
            "table": "erc20_transfer_events",
            "id": row.get("id"),
            "event_dedupe_key": row.get("event_dedupe_key"),
            "payload_digest": row.get("payload_digest"),
            "digest_bound": not row_blockers or "transfer_payload_digest_mismatch" not in row_blockers,
        })
        transfer_previews.append({
            "raw_transfer_event_id": row.get("id"),
            "checkpoint_id": row.get("checkpoint_id"),
            "token_address": row.get("token_address"),
            "from_address": row.get("from_address"),
            "to_address": row.get("to_address"),
            "value_raw": row.get("value_raw"),
            "tx_hash": row.get("tx_hash"),
            "log_index": row.get("log_index"),
            "block_number": row.get("block_number"),
            "payload_digest": row.get("payload_digest"),
            "event_dedupe_key": row.get("event_dedupe_key"),
            "blockers": row_blockers,
        })
    missing_transfer_tokens = sorted(expected_tokens - {token for token, present in token_transfer_coverage.items() if present})
    if missing_transfer_tokens:
        blockers.append("transfer_context_missing_for_pair_token")

    related_event_ids = {
        "dex_raw_paircreated_events": [row.get("id") for row in paircreated_rows],
        "erc20_transfer_events": [row.get("id") for row in transfer_rows],
        "dex_raw_swap_events": [row.get("id") for row in swap_rows],
    }
    proof_package_preview = {
        "event_reader_run_id": event_reader_run_id,
        "proof_type": "paircreated_with_transfer_context",
        "chain": chain,
        "venue_family": (run or {}).get("venue_family"),
        "subject_address": expected_pair or (paircreated_preview or {}).get("pair_address"),
        "factory_address": expected_factory or (paircreated_preview or {}).get("factory_address"),
        "paircreated_event": paircreated_preview,
        "transfer_events": transfer_previews,
        "payload_digest_bindings": payload_digest_bindings,
        "raw_event_counts": {
            "paircreated": len(paircreated_rows),
            "swap": len(swap_rows),
            "erc20_transfer": len(transfer_rows),
        },
        "caveats": [
            "raw_event_package_is_not_mapping",
            "paircreated_proves_pool_creation_not_router_execution",
            "transfer_context_is_liquidity_context_not_trade_signal",
            "requires_later_review_before_evidence_or_mapping",
        ],
    }
    proof_package_digest = hashlib.sha256(
        json.dumps(proof_package_preview, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    ).hexdigest()
    subject_address = str(proof_package_preview.get("subject_address") or "").lower()
    proof_package_dedupe_key = f"{chain}|paircreated_with_transfer_context|{subject_address}|{proof_package_digest}"

    if existing_package_count and table_status.get("dex_event_proof_packages", {}).get("exists"):
        conn = _get_db()
        try:
            row = conn.execute(
                "SELECT id FROM dex_event_proof_packages WHERE proof_package_dedupe_key = ? LIMIT 1",
                (proof_package_dedupe_key,),
            ).fetchone()
            if row:
                blockers.append("proof_package_duplicate_exists")
        finally:
            conn.close()

    blockers = list(dict.fromkeys(blockers))
    ready = bool(dry_run and not blockers)
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "preview_status": "ready_read_only" if ready else "blocked",
        "event_reader_run_id": event_reader_run_id,
        "chain": chain,
        "run_status": (run or {}).get("status"),
        "venue_family": (run or {}).get("venue_family"),
        "factory_address": expected_factory,
        "pair_address": expected_pair,
        "token0": expected_token0,
        "token1": expected_token1,
        "event_scope_json_valid": event_scope_json_valid,
        "table_status": table_status,
        "raw_event_counts": proof_package_preview["raw_event_counts"],
        "related_event_ids": related_event_ids,
        "paircreated_event": paircreated_preview,
        "transfer_events": transfer_previews,
        "payload_digest_bindings": payload_digest_bindings,
        "proof_package_preview": proof_package_preview,
        "proof_package_digest": proof_package_digest,
        "proof_package_dedupe_key": proof_package_dedupe_key,
        "target_table": "dex_event_proof_packages",
        "existing_proof_package_count": existing_package_count,
        "required_future_confirm": "FUTURE_SEPARATE_CONFIRMED_PROOF_PACKAGE_INSERT_REQUIRED",
        "next_safe_step": "dex_event_proof_package_insert_dry_run_first" if ready else "repair_raw_event_package_blockers",
        "blockers": blockers,
        **common_disabled,
    }


def insert_dex_local_event_reader_proof_package(
    event_reader_run_id: int | None,
    expected_proof_package_digest: str | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Dry-run-first insert of one DEX event proof package from persisted raw rows."""
    required_confirm = "INSERT_DEX_LOCAL_EVENT_READER_PROOF_PACKAGE"
    source_policy = (
        "admin-only dry-run-first DEX event proof-package insert. Confirmed writes are limited to "
        "dex_event_proof_packages. It does not promote evidence, create mappings/router evidence/labels, "
        "emit client signals, execute trades, create wallet orders or opt-ins."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "source_policy": source_policy,
    }
    preview = get_dex_local_event_reader_proof_package_preview(
        event_reader_run_id=event_reader_run_id,
        dry_run=True,
    )
    blockers = list(preview.get("blockers") or [])
    if preview.get("preview_status") != "ready_read_only":
        blockers.append("proof_package_preview_not_ready")
    if not dry_run:
        if confirm != required_confirm:
            blockers.append("confirm_INSERT_DEX_LOCAL_EVENT_READER_PROOF_PACKAGE_required")
        if not str(expected_proof_package_digest or "").strip():
            blockers.append("expected_proof_package_digest_required")
    expected_digest = str(expected_proof_package_digest or "").strip()
    current_digest = str(preview.get("proof_package_digest") or "").strip()
    if expected_digest and expected_digest != current_digest:
        blockers.append("expected_proof_package_digest_mismatch")

    conn = _get_db()
    try:
        table_exists = _table_exists(conn, "dex_event_proof_packages")
        existing_row = None
        if table_exists and preview.get("proof_package_dedupe_key"):
            existing_row = conn.execute(
                "SELECT id FROM dex_event_proof_packages WHERE proof_package_dedupe_key = ? LIMIT 1",
                (preview.get("proof_package_dedupe_key"),),
            ).fetchone()
        if not table_exists:
            blockers.append("dex_event_proof_packages_missing")
        if existing_row:
            blockers.append("proof_package_duplicate_exists")
        before_count = int(conn.execute("SELECT COUNT(*) FROM dex_event_proof_packages").fetchone()[0] or 0) if table_exists else 0
    finally:
        conn.close()

    blockers = list(dict.fromkeys(blockers))
    would_insert = bool(not blockers)
    response_base = {
        "ok": bool(not blockers),
        "dry_run": bool(dry_run),
        "event_reader_run_id": event_reader_run_id,
        "target_table": "dex_event_proof_packages",
        "preview_status": preview.get("preview_status"),
        "proof_package_digest": preview.get("proof_package_digest"),
        "expected_proof_package_digest": expected_proof_package_digest,
        "proof_package_dedupe_key": preview.get("proof_package_dedupe_key"),
        "proof_type": "paircreated_with_transfer_context",
        "subject_address": (preview.get("proof_package_preview") or {}).get("subject_address"),
        "related_event_ids": preview.get("related_event_ids"),
        "raw_event_counts": preview.get("raw_event_counts"),
        "payload_digest_bindings": preview.get("payload_digest_bindings"),
        "required_confirm": required_confirm,
        "existing_proof_package_count": before_count,
        "would_create_proof_package": would_insert,
        "would_write": False if dry_run else would_insert,
        "real_write_enabled": False if dry_run else would_insert,
        "writes_performed": 0,
        "blockers": blockers,
        **common_disabled,
    }
    if dry_run or blockers:
        return {
            **response_base,
            "insert_status": "ready_for_insert" if would_insert else "blocked",
            "inserted": False,
            "proof_package_id": None,
        }

    package_json = json.dumps(
        preview.get("proof_package_preview") or {},
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    related_ids_json = json.dumps(
        preview.get("related_event_ids") or {},
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    created_at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    conn = _get_db()
    try:
        cur = conn.execute(
            """
            INSERT INTO dex_event_proof_packages (
                chain,
                proof_type,
                related_event_ids_json,
                subject_address,
                proof_package_json,
                proof_package_digest,
                proof_package_dedupe_key,
                status,
                created_at,
                source_policy
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                preview.get("chain"),
                "paircreated_with_transfer_context",
                related_ids_json,
                (preview.get("proof_package_preview") or {}).get("subject_address"),
                package_json,
                preview.get("proof_package_digest"),
                preview.get("proof_package_dedupe_key"),
                "pending_admin_review",
                created_at,
                source_policy,
            ),
        )
        proof_package_id = int(cur.lastrowid)
        conn.commit()
        after_count = int(conn.execute("SELECT COUNT(*) FROM dex_event_proof_packages").fetchone()[0] or 0)
    finally:
        conn.close()

    return {
        **response_base,
        "ok": True,
        "dry_run": False,
        "insert_status": "inserted",
        "inserted": True,
        "proof_package_id": proof_package_id,
        "proof_package_status": "pending_admin_review",
        "proof_package_count_before": before_count,
        "proof_package_count_after": after_count,
        "would_create_proof_package": False,
        "would_write": False,
        "real_write_enabled": True,
        "writes_performed": 1,
        "blockers": [],
    }


def get_dex_local_event_reader_proof_package_review_queue(
    status: str | None = "pending_admin_review",
    limit: int = 50,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only review queue for local DEX event proof packages."""
    source_policy = (
        "admin-only read-only DEX event proof-package review queue. It verifies stored package JSON, digest, "
        "dedupe and raw-row bindings. It does not update status, promote evidence, create mappings/router evidence, "
        "labels, client signals, trades, wallet orders or opt-ins."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_update_proof_package_status": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    try:
        safe_limit = max(1, min(int(limit or 50), 100))
    except (TypeError, ValueError):
        safe_limit = 50
        blockers.append("limit_invalid")
    requested_status = str(status or "pending_admin_review").strip()

    package_rows: list[dict[str, Any]] = []
    table_status: dict[str, dict[str, Any]] = {}
    required_tables = [
        "dex_event_proof_packages",
        "dex_raw_paircreated_events",
        "dex_raw_swap_events",
        "erc20_transfer_events",
    ]
    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        for table_name in required_tables:
            exists = _table_exists(conn, table_name)
            count = int(conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0] or 0) if exists else 0
            table_status[table_name] = {"exists": exists, "row_count": count}
            if not exists:
                blockers.append(f"{table_name}_missing")
        if _table_exists(conn, "dex_event_proof_packages"):
            if requested_status == "all":
                rows = conn.execute(
                    "SELECT * FROM dex_event_proof_packages ORDER BY id LIMIT ?",
                    (safe_limit,),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM dex_event_proof_packages WHERE status = ? ORDER BY id LIMIT ?",
                    (requested_status, safe_limit),
                ).fetchall()
            package_rows = [dict(row) for row in rows]
    finally:
        conn.close()

    def _raw_row_exists(table_name: str, row_id: Any) -> bool:
        try:
            safe_id = int(row_id)
        except (TypeError, ValueError):
            return False
        if not table_status.get(table_name, {}).get("exists"):
            return False
        conn = _get_db()
        try:
            row = conn.execute(f"SELECT id FROM {table_name} WHERE id = ? LIMIT 1", (safe_id,)).fetchone()
            return bool(row)
        finally:
            conn.close()

    review_rows: list[dict[str, Any]] = []
    for package in package_rows:
        row_blockers: list[str] = []
        package_json = str(package.get("proof_package_json") or "")
        try:
            parsed_package = json.loads(package_json)
            if not isinstance(parsed_package, dict):
                parsed_package = {}
                row_blockers.append("proof_package_json_not_object")
        except (TypeError, json.JSONDecodeError):
            parsed_package = {}
            row_blockers.append("proof_package_json_invalid")
        digest_recomputed = hashlib.sha256(
            json.dumps(parsed_package, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
        ).hexdigest() if parsed_package else None
        digest_bound = bool(digest_recomputed and digest_recomputed == str(package.get("proof_package_digest") or ""))
        if not digest_bound:
            row_blockers.append("proof_package_digest_mismatch")
        expected_dedupe = (
            f"{package.get('chain')}|{package.get('proof_type')}|"
            f"{str(package.get('subject_address') or '').lower()}|{package.get('proof_package_digest')}"
        )
        dedupe_bound = expected_dedupe == str(package.get("proof_package_dedupe_key") or "")
        if not dedupe_bound:
            row_blockers.append("proof_package_dedupe_mismatch")
        related_ids = package.get("related_event_ids_json")
        try:
            related = json.loads(str(related_ids or "{}"))
            if not isinstance(related, dict):
                related = {}
                row_blockers.append("related_event_ids_not_object")
        except (TypeError, json.JSONDecodeError):
            related = {}
            row_blockers.append("related_event_ids_json_invalid")
        missing_raw_refs: list[dict[str, Any]] = []
        for table_name in ["dex_raw_paircreated_events", "erc20_transfer_events", "dex_raw_swap_events"]:
            for raw_id in related.get(table_name) or []:
                if not _raw_row_exists(table_name, raw_id):
                    missing_raw_refs.append({"table": table_name, "id": raw_id})
        if missing_raw_refs:
            row_blockers.append("related_raw_event_missing")

        payload_bindings = list(parsed_package.get("payload_digest_bindings") or []) if isinstance(parsed_package, dict) else []
        if not payload_bindings:
            row_blockers.append("payload_digest_bindings_missing")
        if any(not bool(item.get("digest_bound")) for item in payload_bindings if isinstance(item, dict)):
            row_blockers.append("payload_digest_binding_false")
        raw_counts = parsed_package.get("raw_event_counts") or {}
        if int(raw_counts.get("paircreated") or 0) != 1:
            row_blockers.append("raw_paircreated_count_not_one")
        if int(raw_counts.get("erc20_transfer") or 0) < 2:
            row_blockers.append("raw_transfer_context_count_too_low")
        if str(package.get("status") or "") != "pending_admin_review":
            row_blockers.append("proof_package_status_not_pending_admin_review")
        caveats = list(parsed_package.get("caveats") or [])
        if "paircreated_proves_pool_creation_not_router_execution" not in caveats:
            row_blockers.append("paircreated_caveat_missing")

        readiness = "ready_for_proof_package_decision_preview" if not row_blockers else "blocked"
        review_rows.append({
            "proof_package_id": package.get("id"),
            "chain": package.get("chain"),
            "proof_type": package.get("proof_type"),
            "subject_address": package.get("subject_address"),
            "status": package.get("status"),
            "proof_package_digest": package.get("proof_package_digest"),
            "proof_package_digest_recomputed": digest_recomputed,
            "proof_package_digest_bound": digest_bound,
            "proof_package_dedupe_key": package.get("proof_package_dedupe_key"),
            "proof_package_dedupe_bound": dedupe_bound,
            "related_event_ids": related,
            "missing_raw_refs": missing_raw_refs,
            "raw_event_counts": raw_counts,
            "payload_digest_bindings": payload_bindings,
            "review_readiness": readiness,
            "review_blockers": row_blockers,
            "next_admin_action": (
                "prepare_proof_package_decision_preview"
                if readiness == "ready_for_proof_package_decision_preview"
                else "repair_or_reject_proof_package"
            ),
            **common_disabled,
        })

    summary = {
        "total_proof_packages": len(review_rows),
        "ready_for_proof_package_decision_preview": sum(
            1 for row in review_rows if row.get("review_readiness") == "ready_for_proof_package_decision_preview"
        ),
        "blocked": sum(1 for row in review_rows if row.get("review_readiness") == "blocked"),
        "digest_bound": sum(1 for row in review_rows if row.get("proof_package_digest_bound")),
        "dedupe_bound": sum(1 for row in review_rows if row.get("proof_package_dedupe_bound")),
        "real_write_enabled": False,
    }
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "queue_status": "ready" if dry_run and not blockers else "blocked",
        "status_filter": requested_status,
        "limit": safe_limit,
        "table_status": table_status,
        "summary": summary,
        "rows": review_rows,
        "blockers": list(dict.fromkeys(blockers)),
        **common_disabled,
    }


def get_dex_local_event_reader_proof_package_decision_preview(
    proof_package_id: int | None,
    proposed_decision: str | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only human/policy decision preview for a DEX event proof package."""
    allowed_decisions = {
        "accept_for_future_proof_package_evidence_review": "accepted_for_future_proof_package_evidence_review",
        "request_repair": "needs_repair",
        "reject": "rejected",
    }
    source_policy = (
        "admin-only read-only DEX event proof-package decision preview. It reads the proof-package review queue "
        "and explains a future status-only decision. It does not update status, promote evidence, create mappings, "
        "router evidence, labels, client signals, trades, wallet orders or opt-ins."
    )
    common_disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_update_proof_package_status": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    if proof_package_id is None:
        blockers.append("proof_package_id_required")
    decision = str(proposed_decision or "").strip()
    if decision not in allowed_decisions:
        blockers.append("invalid_proposed_decision")

    review = get_dex_local_event_reader_proof_package_review_queue(status="all", limit=100, dry_run=True)
    if review.get("queue_status") != "ready":
        blockers.append("proof_package_review_queue_not_ready")
    row = None
    for item in review.get("rows") or []:
        if item.get("proof_package_id") == proof_package_id:
            row = item
            break
    if proof_package_id is not None and row is None:
        blockers.append("proof_package_missing")

    row_blockers = list((row or {}).get("review_blockers") or [])
    row_ready = (row or {}).get("review_readiness") == "ready_for_proof_package_decision_preview"
    row_status = (row or {}).get("status")
    if decision == "accept_for_future_proof_package_evidence_review":
        if not row_ready:
            blockers.append("proof_package_not_ready_for_accept")
        if row_status != "pending_admin_review":
            blockers.append("proof_package_status_not_pending_admin_review")
        if not (row or {}).get("proof_package_digest_bound"):
            blockers.append("proof_package_digest_not_bound")
        if not (row or {}).get("proof_package_dedupe_bound"):
            blockers.append("proof_package_dedupe_not_bound")
        if row_blockers:
            blockers.extend(row_blockers)
    elif decision == "request_repair" and row is None:
        blockers.append("proof_package_required_for_repair_request")
    elif decision == "reject" and row is None:
        blockers.append("proof_package_required_for_reject")

    future_status = allowed_decisions.get(decision)
    decision_allowed = bool(not blockers and row is not None and decision in allowed_decisions)
    if decision == "request_repair" and row is not None:
        decision_allowed = bool(dry_run)
        blockers = [b for b in blockers if b not in row_blockers]
    if decision == "reject" and row is not None:
        decision_allowed = bool(dry_run)
        blockers = [b for b in blockers if b not in row_blockers]
    blockers = list(dict.fromkeys(blockers))
    preview_status = "ready_but_disabled" if decision_allowed and not blockers else "blocked"
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "preview_status": preview_status,
        "proof_package_id": proof_package_id,
        "proposed_decision": decision,
        "allowed_decisions": sorted(allowed_decisions),
        "decision_allowed": decision_allowed and not blockers,
        "decision_preview": {
            "future_status": future_status,
            "next_step": (
                "future status-only apply, then separate evidence-review contract; not mapping"
                if decision == "accept_for_future_proof_package_evidence_review"
                else "repair raw/package binding before another review"
                if decision == "request_repair"
                else "no evidence promotion from this package"
                if decision == "reject"
                else None
            ),
            "mapping_created_by_this_decision": False,
            "signal_created_by_this_decision": False,
            "trade_created_by_this_decision": False,
        },
        "required_future_confirm": "FUTURE_SEPARATE_CONFIRMED_PROOF_PACKAGE_DECISION_APPLY_REQUIRED",
        "proof_package": row,
        "review_queue_summary": review.get("summary"),
        "blockers": blockers,
        **common_disabled,
    }


def apply_dex_local_event_reader_proof_package_decision(
    proof_package_id: int | None,
    proposed_decision: str | None,
    dry_run: bool = True,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Apply a confirmed proof-package decision as a status-only update."""
    allowed_decisions = {
        "accept_for_future_proof_package_evidence_review": "accepted_for_future_proof_package_evidence_review",
        "request_repair": "needs_repair",
        "reject": "rejected",
    }
    preview = get_dex_local_event_reader_proof_package_decision_preview(
        proof_package_id=proof_package_id,
        proposed_decision=proposed_decision,
        dry_run=True,
    )
    blockers = list(preview.get("blockers") or [])
    decision = str(proposed_decision or "").strip()
    if proof_package_id is None:
        blockers.append("proof_package_id_required")
    if decision not in allowed_decisions:
        blockers.append("invalid_proposed_decision")
    if not dry_run and confirm != "APPLY_DEX_EVENT_PROOF_PACKAGE_DECISION":
        blockers.append("confirm_APPLY_DEX_EVENT_PROOF_PACKAGE_DECISION_required")
    if not preview.get("decision_allowed"):
        blockers.append("proof_package_decision_preview_not_allowed")

    previous_status = None
    if proof_package_id is not None:
        conn = _get_db()
        try:
            row = conn.execute(
                "SELECT status FROM dex_event_proof_packages WHERE id = ? LIMIT 1",
                (proof_package_id,),
            ).fetchone()
            if row is None:
                blockers.append("proof_package_missing")
            else:
                previous_status = row[0]
                if previous_status != "pending_admin_review":
                    blockers.append("proof_package_status_not_pending_admin_review")
        except sqlite3.OperationalError:
            blockers.append("dex_event_proof_packages_table_missing")
        finally:
            conn.close()

    decision_preview = preview.get("decision_preview") or {}
    new_status = decision_preview.get("future_status") or allowed_decisions.get(decision)
    if new_status not in set(allowed_decisions.values()):
        blockers.append("target_status_unknown")

    blockers = list(dict.fromkeys(blockers))
    can_update = not blockers and previous_status == "pending_admin_review" and bool(new_status)
    response_base = {
        "ok": True,
        "dry_run": bool(dry_run),
        "proof_package_id": proof_package_id,
        "proposed_decision": decision or None,
        "previous_status": previous_status,
        "new_status": new_status,
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
    }
    if dry_run or blockers:
        return {
            **response_base,
            "apply_status": "ready_but_disabled" if can_update else "blocked",
            "would_update_proof_package_status": bool(can_update),
            "updated": False,
            "writes_performed": 0,
            "blockers": blockers,
            "source_policy": (
                "admin-only DEX event proof-package status preview; no evidence writes, no mappings, no router "
                "evidence, no labels, no trades, no wallet orders, no client signals and no opt-ins"
            ),
        }

    conn = _get_db()
    try:
        cur = conn.execute(
            """
            UPDATE dex_event_proof_packages
            SET status = ?
            WHERE id = ? AND status = 'pending_admin_review'
            """,
            (new_status, proof_package_id),
        )
        if cur.rowcount != 1:
            conn.rollback()
            return {
                **response_base,
                "dry_run": False,
                "apply_status": "blocked",
                "would_update_proof_package_status": False,
                "updated": False,
                "writes_performed": 0,
                "blockers": ["proof_package_status_update_rowcount_not_one"],
                "source_policy": "proof-package status-only update blocked because rowcount was not exactly one",
            }
        conn.commit()
    finally:
        conn.close()

    return {
        **response_base,
        "dry_run": False,
        "apply_status": "updated",
        "would_update_proof_package_status": False,
        "updated": True,
        "writes_performed": 1,
        "blockers": [],
        "source_policy": (
            "admin-confirmed DEX event proof-package status-only update; changed only "
            "dex_event_proof_packages.status, no evidence writes, no DEX mappings, no router evidence, "
            "no labels, no trades, no wallet orders, no client signals and no opt-ins"
        ),
    }


def get_dex_local_event_reader_proof_package_evidence_review_contract(
    proof_package_id: int | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only contract for turning an accepted proof package into an evidence-review lane."""
    source_policy = (
        "admin-only read-only DEX event proof-package evidence-review contract. It validates the accepted "
        "proof package, checks raw payload bindings, detects existing PairCreated evidence, and describes a "
        "future evidence-review action. It does not persist evidence, create mappings, create router evidence, "
        "emit signals, trade, create wallet orders or opt-ins."
    )
    disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_create_evidence_review": False,
        "would_persist_paircreated_evidence": False,
        "would_link_existing_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    if proof_package_id is None:
        blockers.append("proof_package_id_required")

    package: dict[str, Any] | None = None
    parsed_package: dict[str, Any] = {}
    related: dict[str, Any] = {}
    raw_ref_checks: list[dict[str, Any]] = []
    existing_evidence: dict[str, Any] | None = None
    conn = _get_db()
    conn.row_factory = sqlite3.Row
    try:
        if not _table_exists(conn, "dex_event_proof_packages"):
            blockers.append("dex_event_proof_packages_missing")
        elif proof_package_id is not None:
            row = conn.execute(
                "SELECT * FROM dex_event_proof_packages WHERE id = ? LIMIT 1",
                (proof_package_id,),
            ).fetchone()
            if row is None:
                blockers.append("proof_package_missing")
            else:
                package = dict(row)

        if package:
            if str(package.get("status") or "") != "accepted_for_future_proof_package_evidence_review":
                blockers.append("proof_package_not_accepted_for_evidence_review")
            try:
                parsed = json.loads(str(package.get("proof_package_json") or "{}"))
                if isinstance(parsed, dict):
                    parsed_package = parsed
                else:
                    blockers.append("proof_package_json_not_object")
            except (TypeError, json.JSONDecodeError):
                blockers.append("proof_package_json_invalid")
            try:
                related_value = json.loads(str(package.get("related_event_ids_json") or "{}"))
                if isinstance(related_value, dict):
                    related = related_value
                else:
                    blockers.append("related_event_ids_not_object")
            except (TypeError, json.JSONDecodeError):
                blockers.append("related_event_ids_json_invalid")

            if parsed_package:
                recomputed_digest = hashlib.sha256(
                    json.dumps(parsed_package, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
                ).hexdigest()
                if recomputed_digest != str(package.get("proof_package_digest") or ""):
                    blockers.append("proof_package_digest_mismatch")
                expected_package_dedupe = (
                    f"{package.get('chain')}|{package.get('proof_type')}|"
                    f"{str(package.get('subject_address') or '').lower()}|{package.get('proof_package_digest')}"
                )
                if expected_package_dedupe != str(package.get("proof_package_dedupe_key") or ""):
                    blockers.append("proof_package_dedupe_mismatch")

                pair_event = parsed_package.get("paircreated_event") or {}
                raw_counts = parsed_package.get("raw_event_counts") or {}
                if int(raw_counts.get("paircreated") or 0) != 1:
                    blockers.append("raw_paircreated_count_not_one")
                if int(raw_counts.get("erc20_transfer") or 0) < 2:
                    blockers.append("raw_transfer_context_count_too_low")
                for field in ["factory_address", "pair_address", "token0", "token1", "tx_hash", "log_index", "block_number"]:
                    if pair_event.get(field) in (None, ""):
                        blockers.append(f"paircreated_{field}_missing")
                if str(package.get("proof_type") or "") != "paircreated_with_transfer_context":
                    blockers.append("proof_type_not_paircreated_with_transfer_context")
                caveats = list(parsed_package.get("caveats") or [])
                if "paircreated_proves_pool_creation_not_router_execution" not in caveats:
                    blockers.append("paircreated_caveat_missing")

                binding_by_ref: dict[tuple[str, int], dict[str, Any]] = {}
                for item in parsed_package.get("payload_digest_bindings") or []:
                    if not isinstance(item, dict) or item.get("id") is None:
                        continue
                    try:
                        binding_id = int(item.get("id"))
                    except (TypeError, ValueError):
                        blockers.append("payload_digest_binding_id_invalid")
                        continue
                    binding_by_ref[(str(item.get("table")), binding_id)] = item
                for table_name in ["dex_raw_paircreated_events", "erc20_transfer_events", "dex_raw_swap_events"]:
                    if not _table_exists(conn, table_name):
                        blockers.append(f"{table_name}_missing")
                        continue
                    for raw_id in related.get(table_name) or []:
                        try:
                            raw_id_int = int(raw_id)
                        except (TypeError, ValueError):
                            raw_ref_checks.append({"table": table_name, "id": raw_id, "exists": False, "digest_bound": False})
                            blockers.append("related_raw_event_id_invalid")
                            continue
                        raw = conn.execute(f"SELECT * FROM {table_name} WHERE id = ? LIMIT 1", (raw_id_int,)).fetchone()
                        binding = binding_by_ref.get((table_name, raw_id_int)) or {}
                        digest_bound = bool(raw and binding and raw["payload_digest"] == binding.get("payload_digest"))
                        raw_ref_checks.append({
                            "table": table_name,
                            "id": raw_id_int,
                            "exists": bool(raw),
                            "payload_digest": raw["payload_digest"] if raw else None,
                            "bound_payload_digest": binding.get("payload_digest"),
                            "digest_bound": digest_bound,
                        })
                        if not raw:
                            blockers.append("related_raw_event_missing")
                        elif not digest_bound:
                            blockers.append("related_raw_event_digest_mismatch")

                evidence_dedupe_key = None
                if pair_event:
                    evidence_dedupe_key = (
                        f"{package.get('chain')}|{str(pair_event.get('factory_address') or '').lower()}|"
                        f"{str(pair_event.get('tx_hash') or '').lower()}|{pair_event.get('log_index')}|"
                        f"{str(pair_event.get('pair_address') or '').lower()}"
                    )
                if evidence_dedupe_key and _table_exists(conn, "dex_paircreated_evidence"):
                    evidence_row = conn.execute(
                        "SELECT * FROM dex_paircreated_evidence WHERE paircreated_dedupe_key = ? LIMIT 1",
                        (evidence_dedupe_key,),
                    ).fetchone()
                    if evidence_row:
                        existing_evidence = dict(evidence_row)
    finally:
        conn.close()

    paircreated_event = parsed_package.get("paircreated_event") or {}
    transfer_events = parsed_package.get("transfer_events") or []
    paircreated_evidence_dedupe_key = (
        f"{(package or {}).get('chain')}|{str(paircreated_event.get('factory_address') or '').lower()}|"
        f"{str(paircreated_event.get('tx_hash') or '').lower()}|{paircreated_event.get('log_index')}|"
        f"{str(paircreated_event.get('pair_address') or '').lower()}"
        if package and paircreated_event
        else None
    )
    proposed_action = (
        "future_corroboration_review_for_existing_paircreated_evidence"
        if existing_evidence
        else "future_paircreated_evidence_review_row"
    )
    blockers = list(dict.fromkeys(blockers))
    ready = bool(dry_run and not blockers and package and paircreated_event)
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "contract_status": "ready_but_disabled" if ready else "blocked",
        "proof_package_id": proof_package_id,
        "proof_package_status": (package or {}).get("status"),
        "target_lane": "dex_paircreated_evidence_review",
        "target_table": "dex_paircreated_evidence",
        "proposed_evidence_action": proposed_action,
        "existing_paircreated_evidence_id": (existing_evidence or {}).get("id"),
        "existing_paircreated_evidence_status": (existing_evidence or {}).get("status"),
        "paircreated_evidence_dedupe_key": paircreated_evidence_dedupe_key,
        "proof_package_digest": (package or {}).get("proof_package_digest"),
        "proof_package_dedupe_key": (package or {}).get("proof_package_dedupe_key"),
        "source_evidence": {
            "source": "local_sqd_raw_event_reader_package",
            "proof_type": (package or {}).get("proof_type"),
            "raw_event_counts": parsed_package.get("raw_event_counts") or {},
            "raw_ref_checks": raw_ref_checks,
            "payload_digest_bindings": parsed_package.get("payload_digest_bindings") or [],
        },
        "proposed_evidence_review": {
            "chain": (package or {}).get("chain"),
            "venue_family": parsed_package.get("venue_family"),
            "factory_address": paircreated_event.get("factory_address"),
            "pair_address": paircreated_event.get("pair_address"),
            "token0": paircreated_event.get("token0"),
            "token1": paircreated_event.get("token1"),
            "tx_hash": paircreated_event.get("tx_hash"),
            "log_index": paircreated_event.get("log_index"),
            "block_number": paircreated_event.get("block_number"),
            "transfer_context_count": len(transfer_events) if isinstance(transfer_events, list) else 0,
            "status": "future_pending_admin_review",
            "creates_mapping": False,
        },
        "schema_preview": {
            "target_table": "dex_paircreated_evidence",
            "required_fields": [
                "chain",
                "source_type",
                "source_label",
                "source_url",
                "source_tier",
                "official_venue",
                "factory_address",
                "pair_address",
                "token0",
                "token1",
                "tx_hash",
                "log_index",
                "block_number",
                "paircreated_event_topic",
                "paircreated_dedupe_key",
                "evidence_payload_digest",
                "raw_payload_json",
                "status",
                "source_policy",
            ],
            "dedupe_rule": "chain|factory_address|tx_hash|log_index|pair_address",
            "duplicate_policy": "block_duplicate_or_route_to_corroboration_review_no_upsert",
        },
        "route_safety": {
            "paircreated_proves_pool_creation": True,
            "paircreated_does_not_prove_router_execution": True,
            "mapping_created": False,
            "client_signal_created": False,
            "trade_created": False,
        },
        "required_future_confirm": "FUTURE_SEPARATE_PAIRCREATED_EVIDENCE_OR_CORROBORATION_REVIEW_REQUIRED",
        "blockers": blockers,
        **disabled,
    }


def get_dex_local_event_reader_proof_package_corroboration_review(
    proof_package_id: int | None,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Read-only review showing how an accepted proof package corroborates existing PairCreated evidence."""
    source_policy = (
        "admin-only read-only proof-package corroboration review. It compares an accepted proof package against "
        "existing PairCreated evidence and reports whether it strengthens that evidence. It does not update the "
        "evidence, create duplicate evidence, create mappings, router evidence, signals, trades, wallet orders or opt-ins."
    )
    disabled = {
        "source_backed_scoring": False,
        "mapping_ready_now": 0,
        "would_update_paircreated_evidence": False,
        "would_create_duplicate_evidence": False,
        "would_persist_paircreated_evidence": False,
        "would_create_mapping": False,
        "would_create_dex_router_evidence": False,
        "would_create_cex_label": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "would_write": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    blockers: list[str] = [] if dry_run else ["dry_run_required"]
    if proof_package_id is None:
        blockers.append("proof_package_id_required")

    contract = get_dex_local_event_reader_proof_package_evidence_review_contract(
        proof_package_id=proof_package_id,
        dry_run=True,
    )
    if contract.get("contract_status") != "ready_but_disabled":
        blockers.append("proof_package_evidence_review_contract_not_ready")
        blockers.extend(contract.get("blockers") or [])
    existing_evidence_id = contract.get("existing_paircreated_evidence_id")
    if not existing_evidence_id:
        blockers.append("existing_paircreated_evidence_required_for_corroboration")
    if contract.get("proposed_evidence_action") != "future_corroboration_review_for_existing_paircreated_evidence":
        blockers.append("proof_package_not_a_corroboration_candidate")

    evidence_row: dict[str, Any] | None = None
    if existing_evidence_id:
        conn = _get_db()
        conn.row_factory = sqlite3.Row
        try:
            if not _table_exists(conn, "dex_paircreated_evidence"):
                blockers.append("dex_paircreated_evidence_missing")
            else:
                row = conn.execute(
                    "SELECT * FROM dex_paircreated_evidence WHERE id = ? LIMIT 1",
                    (int(existing_evidence_id),),
                ).fetchone()
                if row is None:
                    blockers.append("existing_paircreated_evidence_missing")
                else:
                    evidence_row = dict(row)
        finally:
            conn.close()

    proposed = contract.get("proposed_evidence_review") or {}
    comparisons: dict[str, dict[str, Any]] = {}

    def _norm(value: Any) -> str:
        return str(value or "").strip().lower()

    def _match(field: str, evidence_field: str | None = None) -> None:
        evidence_key = evidence_field or field
        proposed_value = proposed.get(field)
        evidence_value = (evidence_row or {}).get(evidence_key)
        matched = _norm(proposed_value) == _norm(evidence_value)
        comparisons[field] = {
            "proof_package_value": proposed_value,
            "existing_evidence_value": evidence_value,
            "matched": matched,
        }
        if not matched:
            blockers.append(f"{field}_mismatch")

    if evidence_row:
        for field_name in ["chain", "factory_address", "pair_address", "token0", "token1", "tx_hash"]:
            _match(field_name)
        for field_name in ["log_index", "block_number"]:
            proposed_value = proposed.get(field_name)
            evidence_value = evidence_row.get(field_name)
            try:
                matched = int(proposed_value) == int(evidence_value)
            except (TypeError, ValueError):
                matched = False
            comparisons[field_name] = {
                "proof_package_value": proposed_value,
                "existing_evidence_value": evidence_value,
                "matched": matched,
            }
            if not matched:
                blockers.append(f"{field_name}_mismatch")
        expected_dedupe = contract.get("paircreated_evidence_dedupe_key")
        actual_dedupe = evidence_row.get("paircreated_dedupe_key")
        dedupe_matched = _norm(expected_dedupe) == _norm(actual_dedupe)
        comparisons["paircreated_dedupe_key"] = {
            "proof_package_value": expected_dedupe,
            "existing_evidence_value": actual_dedupe,
            "matched": dedupe_matched,
        }
        if not dedupe_matched:
            blockers.append("paircreated_dedupe_key_mismatch")

    source_evidence = contract.get("source_evidence") or {}
    raw_ref_checks = source_evidence.get("raw_ref_checks") or []
    raw_refs_bound = bool(raw_ref_checks) and all(bool(item.get("exists") and item.get("digest_bound")) for item in raw_ref_checks)
    transfer_context_count = int((proposed.get("transfer_context_count") or 0))
    if not raw_refs_bound:
        blockers.append("raw_refs_not_fully_bound")
    if transfer_context_count < 2:
        blockers.append("transfer_context_too_low_for_corroboration")

    blockers = list(dict.fromkeys(blockers))
    ready = bool(dry_run and not blockers and evidence_row)
    corroboration_strength = (
        "strong_same_paircreated_event_plus_transfer_context"
        if ready and transfer_context_count >= 2
        else "blocked_or_incomplete"
    )
    return {
        "ok": True,
        "dry_run": bool(dry_run),
        "corroboration_status": "ready_but_disabled" if ready else "blocked",
        "proof_package_id": proof_package_id,
        "existing_paircreated_evidence_id": existing_evidence_id,
        "existing_paircreated_evidence_status": (evidence_row or {}).get("status"),
        "corroboration_strength": corroboration_strength,
        "corroboration_summary": {
            "same_paircreated_event": bool(ready),
            "raw_refs_bound": raw_refs_bound,
            "transfer_context_count": transfer_context_count,
            "duplicate_evidence_insert_blocked": bool(existing_evidence_id),
            "mapping_created": False,
            "signal_created": False,
            "trade_created": False,
        },
        "field_comparisons": comparisons,
        "source_evidence": source_evidence,
        "next_safe_step": (
            "corroboration_review_queue_schema_plan_read_only"
            if ready
            else "repair_corroboration_blockers"
        ),
        "blockers": blockers,
        **disabled,
    }


def get_core_equity_agent_os_lite_runtime_preflight(
    dry_run: bool = True,
    event_reader_run_id: int | None = 1,
    require_qdrant: bool = False,
) -> dict[str, Any]:
    """Read-only runtime discovery for Agent OS Lite before any automated cycle."""
    source_policy = (
        "admin-only read-only Agent OS Lite runtime preflight. It checks local runtime availability, source-of-truth "
        "RAG files, and the freshest safe data task. It does not launch servers, call RPC/providers, write audit rows, "
        "write raw data, create labels, mappings, signals, trades, wallet orders or opt-ins."
    )
    disabled_actions = {
        "server_launch": True,
        "background_loop": True,
        "agent_task_execution": True,
        "audit_log_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "provider_call": True,
        "scraping": True,
        "legacy_memory_source": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_launch_server": False,
        "would_start_24_7_runner": False,
        "would_run_agent_task": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_write_audit_log": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "preflight_status": "blocked_actionable",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    project_root = Path(__file__).resolve().parents[2]
    windows_python = project_root / ".venv-win" / "Scripts" / "python.exe"
    fallback_windows_python = project_root / ".venv" / "Scripts" / "python.exe"
    current_python = Path(sys.executable)
    source_truth_paths = [
        project_root / "rag" / "memory" / "core_equity_operating_map.md",
        project_root / "rag" / "memory" / "core_equity_management_map.md",
        project_root / "rag" / "memory" / "core_equity_agent_os_runtime_policy.md",
        project_root / "rag" / "memory" / "current_automation_state.md",
        project_root / "rag" / "memory" / "project_state.md",
    ]
    source_truth_files = [
        {
            "path": str(path),
            "exists": path.exists(),
            "size_bytes": path.stat().st_size if path.exists() else 0,
            "source_role": "history_only" if path.name == "project_state.md" else "state_source",
        }
        for path in source_truth_paths
    ]
    missing_source_files = [item["path"] for item in source_truth_files if not item.get("exists")]

    def _small_command(args: list[str], timeout: int = 4) -> dict[str, Any]:
        try:
            completed = subprocess.run(
                args,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
            return {
                "available": completed.returncode == 0,
                "returncode": completed.returncode,
                "stdout_preview": (completed.stdout or "").strip()[:300],
                "stderr_preview": (completed.stderr or "").strip()[:300],
                "error": None,
            }
        except FileNotFoundError as exc:
            return {
                "available": False,
                "returncode": None,
                "stdout_preview": "",
                "stderr_preview": "",
                "error": type(exc).__name__,
            }
        except subprocess.TimeoutExpired:
            return {
                "available": False,
                "returncode": None,
                "stdout_preview": "",
                "stderr_preview": "timeout",
                "error": "TimeoutExpired",
            }

    wsl_list = _small_command(["wsl.exe", "-l", "-q"])
    wsl_stdout = str(wsl_list.get("stdout_preview") or "").strip()
    wsl_stderr = str(wsl_list.get("stderr_preview") or "").strip().lower()
    wsl_has_distro = bool(
        wsl_list.get("available")
        and wsl_stdout
        and "no installed" not in wsl_stderr
        and "aucune distribution" not in wsl_stderr
    )
    wsl_path_check = (
        _small_command(["wsl.exe", "bash", "-lc", "test -d /mnt/d/trading-agent"])
        if wsl_has_distro else {
            "available": False,
            "returncode": None,
            "stdout_preview": "",
            "stderr_preview": "wsl_distro_unavailable_or_not_required",
            "error": None,
        }
    )

    qdrant_status = {
        "required": bool(require_qdrant),
        "checked": bool(require_qdrant),
        "available": None,
        "endpoint": "http://127.0.0.1:6333/",
        "error": None,
    }
    if require_qdrant:
        try:
            with urllib.request.urlopen("http://127.0.0.1:6333/", timeout=1.5) as response:
                qdrant_status["available"] = 200 <= int(response.status) < 500
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            qdrant_status["available"] = False
            qdrant_status["error"] = type(exc).__name__

    runtime_candidates = [
        {
            "runtime_id": "windows_project_venv",
            "kind": "windows_python",
            "project_path": str(project_root),
            "python_path": str(windows_python),
            "available": project_root.exists() and windows_python.exists(),
            "preferred_order": 1,
        },
        {
            "runtime_id": "windows_project_fallback_venv",
            "kind": "windows_python",
            "project_path": str(project_root),
            "python_path": str(fallback_windows_python),
            "available": project_root.exists() and fallback_windows_python.exists(),
            "preferred_order": 2,
        },
        {
            "runtime_id": "current_python_process",
            "kind": "current_python",
            "project_path": str(project_root),
            "python_path": str(current_python),
            "available": project_root.exists() and current_python.exists(),
            "preferred_order": 3,
        },
        {
            "runtime_id": "wsl_workspace",
            "kind": "wsl_python",
            "project_path": "/mnt/d/trading-agent",
            "python_path": "/mnt/d/trading-agent/.venv/bin/python",
            "available": bool(wsl_has_distro and wsl_path_check.get("available")),
            "preferred_order": 4,
            "wsl_list": wsl_list,
            "wsl_path_check": wsl_path_check,
        },
    ]
    selected_runtime = next((item for item in runtime_candidates if item.get("available")), None)

    run_lane_status: dict[str, Any] = {
        "event_reader_run_id": event_reader_run_id,
        "db_exists": DB_PATH.exists(),
        "run_exists": False,
        "run_status": None,
        "checkpoint_count": 0,
        "raw_event_rows": 0,
        "ready_for_execution_contract": False,
        "blockers": [],
    }
    if DB_PATH.exists() and event_reader_run_id is not None:
        conn = sqlite3.connect(str(DB_PATH))
        conn.row_factory = sqlite3.Row
        try:
            if _table_exists(conn, "dex_event_reader_runs"):
                run_row = conn.execute(
                    "SELECT id, status FROM dex_event_reader_runs WHERE id = ? LIMIT 1",
                    (event_reader_run_id,),
                ).fetchone()
                if run_row:
                    run_lane_status["run_exists"] = True
                    run_lane_status["run_status"] = run_row["status"]
                else:
                    run_lane_status["blockers"].append("event_reader_run_missing")
            else:
                run_lane_status["blockers"].append("dex_event_reader_runs_missing")
            if _table_exists(conn, "dex_event_reader_checkpoints"):
                run_lane_status["checkpoint_count"] = int(
                    conn.execute(
                        "SELECT COUNT(*) FROM dex_event_reader_checkpoints WHERE run_id = ?",
                        (event_reader_run_id,),
                    ).fetchone()[0]
                    or 0
                )
            else:
                run_lane_status["blockers"].append("dex_event_reader_checkpoints_missing")
            for table_name in (
                "dex_raw_paircreated_events",
                "dex_raw_swap_events",
                "erc20_transfer_events",
            ):
                if _table_exists(conn, table_name):
                    run_lane_status["raw_event_rows"] += int(
                        conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]
                        or 0
                    )
        finally:
            conn.close()
    elif event_reader_run_id is None:
        run_lane_status["blockers"].append("event_reader_run_id_required")
    else:
        run_lane_status["blockers"].append("onchain_db_missing")
    if run_lane_status["run_status"] != "planned":
        run_lane_status["blockers"].append("event_reader_run_not_planned")
    if int(run_lane_status["checkpoint_count"] or 0) <= 0:
        run_lane_status["blockers"].append("event_reader_checkpoints_missing")
    run_lane_status["blockers"] = list(dict.fromkeys(run_lane_status["blockers"]))
    run_lane_status["ready_for_execution_contract"] = not run_lane_status["blockers"]

    degraded_conditions = list(dict.fromkeys([
        *("wsl_unavailable_but_not_fatal" for _ in [1] if not runtime_candidates[-1].get("available")),
        *("qdrant_not_required" for _ in [1] if not require_qdrant),
        *("qdrant_unavailable" for _ in [1] if require_qdrant and qdrant_status.get("available") is False),
        *(
            "preferred_windows_venv_missing_using_fallback"
            for _ in [1]
            if selected_runtime and selected_runtime.get("runtime_id") != "windows_project_venv"
        ),
    ]))
    blockers = list(dict.fromkeys([
        *("project_root_missing" for _ in [1] if not project_root.exists()),
        *("source_truth_file_missing" for _ in [1] if missing_source_files),
        *("no_safe_runtime_available" for _ in [1] if not selected_runtime),
        *("qdrant_required_unavailable" for _ in [1] if require_qdrant and qdrant_status.get("available") is False),
    ]))
    preflight_status = "blocked_actionable" if blockers else ("ready_degraded" if degraded_conditions else "ready")
    return {
        "ok": True,
        "dry_run": True,
        "preflight_status": preflight_status,
        "mode": "core_equity_agent_os_lite_runtime_preflight",
        "runtime_policy": {
            "wsl_failure_alone_is_fatal": False,
            "windows_workspace_is_valid_fallback": True,
            "legacy_memory_md_is_source_of_truth": False,
            "must_select_one_task_only": True,
            "no_op_audit_receipts_allowed": False,
        },
        "selected_runtime": selected_runtime,
        "runtime_candidates": runtime_candidates,
        "source_of_truth_files": source_truth_files,
        "missing_source_truth_files": missing_source_files,
        "qdrant_status": qdrant_status,
        "current_safe_task": {
            "task_id": "dex_local_event_reader_execution_contract",
            "event_reader_run_id": event_reader_run_id,
            "endpoint": "/api/onchain/rpc/dex-local-event-reader-run/execution-contract",
            "purpose": "preview exact bounded future eth_getLogs calls before any event-reader execution",
            "read_only_now": True,
            "writes_allowed_now": False,
        },
        "run_lane_status": run_lane_status,
        "degraded_conditions": degraded_conditions,
        "blockers": blockers,
        "next_safe_step": (
            "run_dex_local_event_reader_execution_contract_or_bounded_no_persistence_dry_run"
            if selected_runtime and run_lane_status.get("ready_for_execution_contract")
            else "repair_runtime_or_event_reader_run_lane_before_next_cycle"
        ),
        **common_disabled,
    }


def get_core_equity_agent_os_lite_cycle_preview(
    dry_run: bool = True,
    event_reader_run_id: int | None = 1,
    max_rpc_calls: int = 25,
    require_qdrant: bool = False,
) -> dict[str, Any]:
    """Read-only one-cycle preview: select the safest current Agent OS task and stop before execution."""
    source_policy = (
        "admin-only read-only Agent OS Lite cycle preview. It performs runtime preflight, selects one safe "
        "data-quality task, validates its dry-run contract, and stops. It calls no RPC/provider, launches no server, "
        "writes no audit/raw/business data, and creates no labels, mappings, client signals, trades or opt-ins."
    )
    disabled_actions = {
        "server_launch": True,
        "schedule_creation": True,
        "background_loop": True,
        "multi_task_execution": True,
        "agent_task_execution": True,
        "audit_log_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "provider_call": True,
        "scraping": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_create_schedule": False,
        "would_start_24_7_runner": False,
        "would_run_background_loop": False,
        "would_run_agent_task": False,
        "would_call_rpc": False,
        "would_call_external": False,
        "would_scrape": False,
        "would_write_audit_log": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_create_client_signal": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "cycle_preview_status": "blocked_actionable",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    try:
        safe_max_rpc_calls = max(1, min(int(max_rpc_calls or 25), 100))
    except (TypeError, ValueError):
        safe_max_rpc_calls = 25

    preflight = get_core_equity_agent_os_lite_runtime_preflight(
        dry_run=True,
        event_reader_run_id=event_reader_run_id,
        require_qdrant=bool(require_qdrant),
    )
    selected_runtime = preflight.get("selected_runtime") or {}
    current_safe_task = preflight.get("current_safe_task") or {}
    run_lane_status = preflight.get("run_lane_status") or {}
    execution_contract: dict[str, Any] | None = None
    blockers = list(preflight.get("blockers") or [])

    if preflight.get("preflight_status") not in {"ready", "ready_degraded"}:
        blockers.append("runtime_preflight_not_ready")
    if current_safe_task.get("task_id") != "dex_local_event_reader_execution_contract":
        blockers.append("selected_task_not_allowlisted")
    if not run_lane_status.get("ready_for_execution_contract"):
        blockers.extend(run_lane_status.get("blockers") or ["event_reader_run_lane_not_ready"])

    if not blockers:
        execution_contract = get_dex_local_event_reader_execution_contract(
            event_reader_run_id=event_reader_run_id,
            dry_run=True,
            max_rpc_calls=safe_max_rpc_calls,
        )
        if execution_contract.get("execution_contract_status") != "ready_but_disabled":
            blockers.append("task_contract_not_ready")
        blockers.extend(execution_contract.get("blockers") or [])

    task_contract_summary = {
        "task_id": "dex_local_event_reader_execution_contract",
        "event_reader_run_id": event_reader_run_id,
        "endpoint": "/api/onchain/rpc/dex-local-event-reader-run/execution-contract",
        "operator": "codex_agent_os_lite",
        "agent_role": "Data Agent",
        "purpose": "preview bounded future event-reader RPC calls before any collection is allowed",
        "input_sources": [
            "runtime preflight",
            "dex_event_reader_runs",
            "dex_event_reader_checkpoints",
            "read-only execution contract",
        ],
        "allowed_now": [
            "read runtime preflight",
            "read planned event-reader run",
            "read planned checkpoints",
            "expand future eth_getLogs chunks in memory",
            "validate safety flags",
            "stop",
        ],
        "forbidden_now": [
            "call RPC",
            "insert raw events",
            "update checkpoints",
            "persist evidence",
            "create mapping",
            "create signal",
            "execute trade",
            "write audit unless separate confirmed audit policy allows it",
        ],
        "writes_allowed_now": False,
    }
    task_contract_status = (execution_contract or {}).get("execution_contract_status")
    safety_checks = [
        {
            "check": "runtime_has_safe_fallback",
            "passed": preflight.get("preflight_status") in {"ready", "ready_degraded"} and bool(selected_runtime),
            "detail": {
                "preflight_status": preflight.get("preflight_status"),
                "selected_runtime": selected_runtime.get("runtime_id"),
            },
        },
        {
            "check": "one_task_selected",
            "passed": current_safe_task.get("task_id") == "dex_local_event_reader_execution_contract",
            "detail": current_safe_task,
        },
        {
            "check": "event_reader_run_lane_ready",
            "passed": bool(run_lane_status.get("ready_for_execution_contract")),
            "detail": run_lane_status,
        },
        {
            "check": "task_contract_ready_but_disabled",
            "passed": task_contract_status == "ready_but_disabled",
            "detail": {
                "execution_contract_status": task_contract_status,
                "planned_rpc_call_count": (execution_contract or {}).get("planned_rpc_call_count"),
                "checkpoint_count": (execution_contract or {}).get("checkpoint_count"),
            },
        },
        {
            "check": "no_rpc_or_external_call_now",
            "passed": not bool((execution_contract or {}).get("would_call_rpc")) and not bool((execution_contract or {}).get("would_call_external")),
            "detail": {
                "would_call_rpc": (execution_contract or {}).get("would_call_rpc"),
                "would_call_external": (execution_contract or {}).get("would_call_external"),
            },
        },
        {
            "check": "no_write_now",
            "passed": not bool((execution_contract or {}).get("would_write")) and int((execution_contract or {}).get("writes_performed") or 0) == 0,
            "detail": {
                "would_write": (execution_contract or {}).get("would_write"),
                "writes_performed": (execution_contract or {}).get("writes_performed"),
            },
        },
        {
            "check": "no_label_mapping_signal_trade_opt_in",
            "passed": not any(bool((execution_contract or {}).get(flag)) for flag in [
                "would_create_cex_label",
                "would_create_dex_router_evidence",
                "would_create_mapping",
                "would_create_client_signal",
                "would_execute_trade",
                "would_create_wallet_order",
                "would_create_client_opt_in",
            ]),
            "detail": {
                "would_create_mapping": (execution_contract or {}).get("would_create_mapping"),
                "would_create_client_signal": (execution_contract or {}).get("would_create_client_signal"),
                "would_execute_trade": (execution_contract or {}).get("would_execute_trade"),
            },
        },
    ]
    failed_checks = [row["check"] for row in safety_checks if not row.get("passed")]
    blockers = list(dict.fromkeys([*blockers, *failed_checks]))
    ready = not blockers

    return {
        "ok": True,
        "dry_run": True,
        "cycle_preview_status": "ready_read_only" if ready else "blocked_actionable",
        "mode": "core_equity_agent_os_lite_cycle_preview",
        "selected_runtime": selected_runtime,
        "selected_task": task_contract_summary,
        "cycle_steps": [
            "runtime_preflight",
            "select_one_allowlisted_task",
            "load_task_contract_read_only",
            "validate_safety_flags",
            "stop_before_execution",
        ],
        "preflight": {
            "preflight_status": preflight.get("preflight_status"),
            "degraded_conditions": preflight.get("degraded_conditions") or [],
            "blockers": preflight.get("blockers") or [],
            "source_of_truth_files": preflight.get("source_of_truth_files") or [],
        },
        "task_contract": execution_contract,
        "task_contract_summary": {
            "contract_status": task_contract_status,
            "planned_rpc_call_count": (execution_contract or {}).get("planned_rpc_call_count"),
            "checkpoint_count": (execution_contract or {}).get("checkpoint_count"),
            "max_rpc_calls_preview": (execution_contract or {}).get("max_rpc_calls_preview"),
            "next_micro_step": (execution_contract or {}).get("next_micro_step"),
        },
        "safety_checks": safety_checks,
        "agent_os_value": {
            "less_prompt_fragile": True,
            "runtime_selected_by_code": True,
            "task_selected_by_policy": True,
            "single_task_cycle": True,
            "stops_before_execution": True,
        },
        "blockers": blockers,
        "next_safe_step": (
            "bounded_event_reader_execution_dry_run_no_persistence"
            if ready else "repair_cycle_preview_blockers"
        ),
        **common_disabled,
    }


def get_core_equity_agent_os_lite_state_snapshot(
    chain: str | None = "bsc",
    focus: str | None = "unknown_dex_data_quality",
    limit: int = 5,
    dry_run: bool = True,
    allow_live_checks: bool = False,
) -> dict[str, Any]:
    """Read-only Agent OS Lite dashboard: state, last audit, next task, blockers and disabled surfaces."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_focus = str(focus or "unknown_dex_data_quality").strip().lower()
    safe_limit = max(1, min(int(limit or 5), 12))
    source_policy = (
        "admin-only read-only Agent OS Lite state snapshot. It combines control plane, schedule plan and last "
        "Codex audit receipt into a simple status report. It creates no schedule, runs no task, writes no audit, "
        "and cannot create labels, mappings, trades, wallet orders, client signals or opt-ins."
    )
    disabled_actions = {
        "schedule_creation": True,
        "background_loop": True,
        "agent_task_execution": True,
        "audit_log_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "swap_rewrite": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "hermes_operator": True,
        "crewai_operator": True,
        "opencode_operator": True,
        "local_model_operator": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_create_schedule": False,
        "would_schedule_codex_job": False,
        "would_start_24_7_runner": False,
        "would_run_background_loop": False,
        "would_run_agent_task": False,
        "would_write_audit_log": False,
        "would_insert_data_job": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "snapshot_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    control = get_core_equity_agent_control_plane(
        chain=requested_chain,
        focus=safe_focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
    )
    schedule = get_core_equity_codex_schedule_plan(
        chain=requested_chain,
        focus=safe_focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
    )
    latest_jobs = get_data_jobs(limit=1, job_type="core_equity_codex_agent_cycle").get("rows") or []
    latest_audit = latest_jobs[0] if latest_jobs else None
    latest_audit_result = latest_audit.get("result") if latest_audit else {}
    audit_entry = (latest_audit_result or {}).get("audit_entry") or {}
    selected_job = control.get("selected_next_job") or {}
    data_snapshot = control.get("data_snapshot") or {}
    policy_gates = control.get("policy_gates") or {}
    schedule_ready = bool(schedule.get("plan_status") == "ready_read_only")
    last_audit_clean = bool(
        latest_audit
        and latest_audit.get("status") == "ok"
        and (audit_entry.get("safety_result") or {}).get("trades_executed", 0) == 0
        and (audit_entry.get("safety_result") or {}).get("client_signals_created", 0) == 0
    )
    simple_state = {
        "where_we_are": "Agent OS Lite foundation is ready in read-only/audit-first mode.",
        "what_is_ready": (
            "control plane, task contracts, one-task runner dry-run, audit receipt, schedule plan, and paused card"
        ),
        "what_is_not_ready": (
            "autonomous data collection, autonomous business writes, labels, mappings, client signals and real trades"
        ),
        "best_next_action": (
            "enable a paused/suggested bounded schedule only after deciding cadence, or keep manual cycles while "
            "improving route/source proof"
        ),
        "why_not_trade_yet": (
            "data is still evidence-repair level; no source-backed route confidence, no backtest proof, no client "
            "risk profile and no opt-in"
        ),
    }
    agent_os_status = "ready_read_only" if schedule_ready and last_audit_clean else "needs_attention"
    blockers = list(dict.fromkeys([
        *(control.get("blockers") or []),
        *(schedule.get("blockers") or []),
        *("last_codex_audit_missing_or_not_clean" for _ in [1] if not last_audit_clean),
        "schedule_not_enabled",
        "background_loop_disabled",
        "trading_disabled",
        "client_signal_disabled",
        "client_opt_in_missing",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "snapshot_status": agent_os_status,
        "mode": "core_equity_agent_os_lite_state_snapshot",
        "chain": requested_chain,
        "focus": safe_focus,
        "simple_state": simple_state,
        "agent_os_lite": {
            "version": "v1_read_only",
            "operator": "codex",
            "policy_authority": "core_equity_policy_engine_future_deterministic",
            "sidecars": ["spark_rawls_bacon_helmholtz", "qwen_local_read_only"],
            "hermes_role": "lab_safe_report_only",
            "crewai_role": "lab_safe_report_only",
            "cycle_rule": "one_task_validate_audit_stop",
            "can_run_24_7_eventually": True,
            "can_run_24_7_now": False,
        },
        "last_audit_receipt": {
            "exists": bool(latest_audit),
            "data_job_id": latest_audit.get("id") if latest_audit else None,
            "status": latest_audit.get("status") if latest_audit else None,
            "executed_task_id": audit_entry.get("executed_task_id"),
            "runner_status": audit_entry.get("runner_status"),
            "task_status": audit_entry.get("task_status"),
            "audit_dedupe_key": audit_entry.get("audit_dedupe_key") or (latest_audit_result or {}).get("audit_dedupe_key"),
            "safety_result": audit_entry.get("safety_result") or {},
            "clean": last_audit_clean,
        },
        "schedule_state": {
            "plan_status": schedule.get("plan_status"),
            "can_schedule_eventually": schedule.get("can_schedule_eventually"),
            "can_schedule_now": schedule.get("can_schedule_now"),
            "audit_satisfied": (schedule.get("audit_requirement") or {}).get("audit_satisfied_for_schedule_plan"),
            "audit_already_logged": (schedule.get("audit_requirement") or {}).get("current_audit_already_logged"),
            "would_create_schedule": schedule.get("would_create_schedule"),
            "would_start_24_7_runner": schedule.get("would_start_24_7_runner"),
        },
        "next_task": {
            "job_id": selected_job.get("job_id"),
            "agent": selected_job.get("agent"),
            "reason": selected_job.get("reason"),
            "endpoint": selected_job.get("endpoint"),
            "mode": selected_job.get("mode"),
            "would_write": bool(selected_job.get("would_write")),
            "priority_score": selected_job.get("priority_score"),
        },
        "data_snapshot": data_snapshot,
        "policy_gates": policy_gates,
        "readiness": {
            "data_improvement_ready": True,
            "source_backed_scoring_ready": False,
            "shadow_backtest_ready": policy_gates.get("shadow_mode") == "allowed_read_only",
            "client_signal_ready": False,
            "trade_ready": False,
        },
        "blockers": blockers,
        "next_safe_step": (
            "create_paused_schedule_or_continue_manual_agent_cycles"
            if agent_os_status == "ready_read_only" else "repair_agent_os_snapshot_blockers"
        ),
        **common_disabled,
    }


def get_core_equity_agent_os_lite_task_queue_view(
    chain: str | None = "bsc",
    focus: str | None = "unknown_dex_data_quality",
    limit: int = 5,
    dry_run: bool = True,
    allow_live_checks: bool = False,
    max_tasks: int = 8,
) -> dict[str, Any]:
    """Read-only ranked Agent OS Lite task queue; it does not execute or schedule tasks."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_focus = str(focus or "unknown_dex_data_quality").strip().lower()
    safe_limit = max(1, min(int(limit or 5), 12))
    safe_max_tasks = max(1, min(int(max_tasks or 8), 20))
    source_policy = (
        "admin-only read-only Agent OS Lite task queue view. It ranks task contracts from the control plane, "
        "shows why each task matters, and keeps every action disabled. It does not run tasks, create schedules, "
        "write audit rows, collect raw data, or create labels, mappings, trades, client signals or opt-ins."
    )
    disabled_actions = {
        "schedule_creation": True,
        "background_loop": True,
        "agent_task_execution": True,
        "audit_log_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "swap_rewrite": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "hermes_operator": True,
        "crewai_operator": True,
        "opencode_operator": True,
        "local_model_operator": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_create_schedule": False,
        "would_schedule_codex_job": False,
        "would_start_24_7_runner": False,
        "would_run_background_loop": False,
        "would_run_agent_task": False,
        "would_write_audit_log": False,
        "would_insert_data_job": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "queue_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    snapshot = get_core_equity_agent_os_lite_state_snapshot(
        chain=requested_chain,
        focus=safe_focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
    )
    contracts = get_core_equity_agent_task_contract_preview(
        chain=requested_chain,
        focus=safe_focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
        max_tasks=safe_max_tasks,
    )
    rows: list[dict[str, Any]] = []
    for contract in contracts.get("task_contracts") or []:
        task_id = str(contract.get("task_id") or "").strip()
        agent_role = str(contract.get("agent_role") or "").strip()
        priority_score = int(contract.get("priority_score") or 0)
        requires_rpc = bool(contract.get("requires_rpc_if_run_later"))
        requires_external = bool(contract.get("requires_external_if_run_later"))
        writes_allowed_now = bool(contract.get("writes_allowed_now"))
        task_blockers = list(dict.fromkeys([
            *("rpc_not_enabled_for_default_cycle" for _ in [1] if requires_rpc and not allow_live_checks),
            *("external_sources_disabled" for _ in [1] if requires_external),
            *("writes_not_allowed_in_queue_view" for _ in [1] if writes_allowed_now),
            "task_execution_disabled_in_queue_view",
            "audit_required_if_run_later",
            "client_signal_disabled",
            "trade_disabled",
            "client_opt_in_missing",
        ]))
        queue_readiness = (
            "ready_for_manual_or_future_bounded_cycle"
            if contract.get("selected_now") and not writes_allowed_now else "queued_read_only"
        )
        rows.append({
            "task_id": task_id,
            "rank": 0,
            "selected_now": bool(contract.get("selected_now")),
            "agent_role": agent_role,
            "priority_score": priority_score,
            "reason": contract.get("reason"),
            "endpoint": contract.get("endpoint"),
            "mode": contract.get("mode"),
            "queue_readiness": queue_readiness,
            "self_improvement_role": contract.get("self_improvement_role"),
            "requires_rpc_if_run_later": requires_rpc,
            "requires_external_if_run_later": requires_external,
            "writes_allowed_now": writes_allowed_now,
            "expected_outputs": contract.get("expected_outputs") or [],
            "success_criteria": contract.get("success_criteria") or [],
            "failure_blockers": contract.get("failure_blockers") or [],
            "task_blockers": task_blockers,
            "would_run_now": False,
            "would_write": False,
            "would_create_cex_label": False,
            "would_create_dex_router_evidence": False,
            "would_create_mapping": False,
            "would_execute_trade": False,
            "would_create_client_signal": False,
            "would_create_client_opt_in": False,
        })
    rows.sort(key=lambda item: (-int(item.get("priority_score") or 0), str(item.get("task_id") or "")))
    for index, row in enumerate(rows, start=1):
        row["rank"] = index

    selected_task = next((row for row in rows if row.get("selected_now")), rows[0] if rows else None)
    schedule_safe_task = next(
        (
            row for row in rows
            if (
                not row.get("requires_rpc_if_run_later")
                and not row.get("requires_external_if_run_later")
                and not row.get("writes_allowed_now")
            )
        ),
        None,
    )
    summary = {
        "total_tasks": len(rows),
        "selected_task_id": selected_task.get("task_id") if selected_task else None,
        "schedule_safe_task_id": schedule_safe_task.get("task_id") if schedule_safe_task else None,
        "data_agent_tasks": sum(1 for row in rows if row.get("agent_role") == "Data Agent"),
        "evidence_agent_tasks": sum(1 for row in rows if row.get("agent_role") == "Evidence Agent"),
        "shadow_backtest_tasks": sum(1 for row in rows if row.get("agent_role") == "Shadow/Backtest Agent"),
        "tasks_requiring_rpc_later": sum(1 for row in rows if row.get("requires_rpc_if_run_later")),
        "tasks_requiring_external_later": sum(1 for row in rows if row.get("requires_external_if_run_later")),
        "tasks_with_writes_allowed_now": sum(1 for row in rows if row.get("writes_allowed_now")),
        "schedule_safe_tasks": sum(
            1 for row in rows
            if (
                not row.get("requires_rpc_if_run_later")
                and not row.get("requires_external_if_run_later")
                and not row.get("writes_allowed_now")
            )
        ),
        "client_signal_ready": 0,
        "trade_ready": 0,
    }
    blockers = list(dict.fromkeys([
        *(snapshot.get("blockers") or []),
        *(contracts.get("blockers") or []),
        *("no_task_contracts_available" for _ in [1] if not rows),
        "queue_view_read_only",
        "schedule_not_enabled",
        "trading_disabled",
        "client_signal_disabled",
        "client_opt_in_missing",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "queue_status": "ready_read_only" if rows else "blocked",
        "mode": "core_equity_agent_os_lite_task_queue_view",
        "chain": requested_chain,
        "focus": safe_focus,
        "summary": summary,
        "selected_task": selected_task,
        "schedule_safe_task": schedule_safe_task,
        "rows": rows,
        "snapshot_summary": {
            "snapshot_status": snapshot.get("snapshot_status"),
            "last_audit_clean": (snapshot.get("last_audit_receipt") or {}).get("clean"),
            "can_schedule_eventually": (snapshot.get("schedule_state") or {}).get("can_schedule_eventually"),
            "can_schedule_now": (snapshot.get("schedule_state") or {}).get("can_schedule_now"),
            "trade_ready": (snapshot.get("readiness") or {}).get("trade_ready"),
        },
        "queue_rules": {
            "max_one_task_per_cycle": True,
            "selected_task_is_recommendation_not_execution": True,
            "schedule_safe_task_may_differ_from_top_task": True,
            "all_tasks_require_future_audit_if_run": True,
            "no_business_writes": True,
            "no_trade_or_client_signal": True,
        },
        "blockers": blockers,
        "next_safe_step": (
            "run_selected_task_manually_or_keep_schedule_paused"
            if rows else "repair_control_plane_until_tasks_exist"
        ),
        **common_disabled,
    }


def get_core_equity_agent_os_lite_schedule_activation_checklist(
    chain: str | None = "bsc",
    focus: str | None = "unknown_dex_data_quality",
    limit: int = 5,
    dry_run: bool = True,
    allow_live_checks: bool = False,
    max_tasks: int = 8,
    cadence_minutes: int = 60,
    max_cycles_per_day: int = 6,
) -> dict[str, Any]:
    """Read-only checklist before any Agent OS Lite recurring schedule can be enabled."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_focus = str(focus or "unknown_dex_data_quality").strip().lower()
    safe_limit = max(1, min(int(limit or 5), 12))
    safe_max_tasks = max(1, min(int(max_tasks or 8), 20))
    safe_cadence_minutes = max(15, min(int(cadence_minutes or 60), 24 * 60))
    safe_max_cycles_per_day = max(1, min(int(max_cycles_per_day or 6), 24))
    source_policy = (
        "admin-only read-only Agent OS Lite schedule activation checklist. It verifies prerequisites and "
        "shows the exact limits required before recurring Codex cycles may be enabled. It creates no schedule, "
        "starts no background loop, executes no agent task, writes no audit row, and cannot create labels, "
        "mappings, trades, wallet orders, client signals or opt-ins."
    )
    disabled_actions = {
        "schedule_creation": True,
        "background_loop": True,
        "agent_task_execution": True,
        "audit_log_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "swap_rewrite": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "hermes_operator": True,
        "crewai_operator": True,
        "opencode_operator": True,
        "local_model_operator": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_create_schedule": False,
        "would_enable_schedule": False,
        "would_schedule_codex_job": False,
        "would_start_24_7_runner": False,
        "would_run_background_loop": False,
        "would_run_agent_task": False,
        "would_write_audit_log": False,
        "would_insert_data_job": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "checklist_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    snapshot = get_core_equity_agent_os_lite_state_snapshot(
        chain=requested_chain,
        focus=safe_focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
    )
    queue = get_core_equity_agent_os_lite_task_queue_view(
        chain=requested_chain,
        focus=safe_focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
        max_tasks=safe_max_tasks,
    )
    runtime_preflight = get_core_equity_agent_os_lite_runtime_preflight(
        dry_run=True,
        event_reader_run_id=1,
        require_qdrant=False,
    )
    top_task = queue.get("selected_task") or {}
    schedule_safe_task = queue.get("schedule_safe_task") or {}
    selected_task = (
        top_task
        if (
            top_task
            and (not top_task.get("requires_rpc_if_run_later") or allow_live_checks)
            and not top_task.get("requires_external_if_run_later")
        )
        else schedule_safe_task
    ) or top_task or {}
    used_fallback_task = bool(
        selected_task
        and top_task
        and selected_task.get("task_id") != top_task.get("task_id")
    )
    checks = [
        {
            "check": "agent_os_snapshot_ready",
            "passed": snapshot.get("snapshot_status") == "ready_read_only",
            "detail": snapshot.get("snapshot_status"),
        },
        {
            "check": "runtime_preflight_has_safe_fallback",
            "passed": runtime_preflight.get("preflight_status") in {"ready", "ready_degraded"},
            "detail": {
                "preflight_status": runtime_preflight.get("preflight_status"),
                "selected_runtime": (runtime_preflight.get("selected_runtime") or {}).get("runtime_id"),
                "degraded_conditions": runtime_preflight.get("degraded_conditions") or [],
                "blockers": runtime_preflight.get("blockers") or [],
            },
        },
        {
            "check": "wsl_failure_not_fatal_if_windows_runtime_available",
            "passed": bool(
                (runtime_preflight.get("runtime_policy") or {}).get("wsl_failure_alone_is_fatal") is False
                and runtime_preflight.get("selected_runtime")
            ),
            "detail": runtime_preflight.get("runtime_policy") or {},
        },
        {
            "check": "last_codex_audit_clean",
            "passed": bool((snapshot.get("last_audit_receipt") or {}).get("clean")),
            "detail": (snapshot.get("last_audit_receipt") or {}).get("data_job_id"),
        },
        {
            "check": "schedule_plan_ready_but_not_enabled",
            "passed": bool(
                (snapshot.get("schedule_state") or {}).get("can_schedule_eventually")
                and not (snapshot.get("schedule_state") or {}).get("can_schedule_now")
            ),
            "detail": snapshot.get("schedule_state") or {},
        },
        {
            "check": "task_queue_ready",
            "passed": queue.get("queue_status") == "ready_read_only" and bool(queue.get("rows")),
            "detail": {"queue_status": queue.get("queue_status"), "total_tasks": (queue.get("summary") or {}).get("total_tasks")},
        },
        {
            "check": "selected_task_is_read_only_recommendation",
            "passed": bool(selected_task and not selected_task.get("would_run_now") and not selected_task.get("would_write")),
            "detail": {"task_id": selected_task.get("task_id"), "queue_readiness": selected_task.get("queue_readiness")},
        },
        {
            "check": "selected_task_runtime_inputs_enabled",
            "passed": bool(
                selected_task
                and (not selected_task.get("requires_rpc_if_run_later") or allow_live_checks)
                and not selected_task.get("requires_external_if_run_later")
            ),
            "detail": {
                "task_id": selected_task.get("task_id"),
                "requires_rpc_if_run_later": selected_task.get("requires_rpc_if_run_later"),
                "requires_external_if_run_later": selected_task.get("requires_external_if_run_later"),
                "allow_live_checks": bool(allow_live_checks),
            },
        },
        {
            "check": "trade_and_client_outputs_disabled",
            "passed": not bool((snapshot.get("readiness") or {}).get("trade_ready")) and not bool((snapshot.get("readiness") or {}).get("client_signal_ready")),
            "detail": snapshot.get("readiness") or {},
        },
        {
            "check": "cadence_bounded",
            "passed": safe_cadence_minutes >= 60 and safe_max_cycles_per_day <= 6,
            "detail": {"cadence_minutes": safe_cadence_minutes, "max_cycles_per_day": safe_max_cycles_per_day},
        },
    ]
    failed_checks = [row["check"] for row in checks if not row.get("passed")]
    checklist_ready = not failed_checks
    blockers = list(dict.fromkeys([
        *(snapshot.get("blockers") or []),
        *(queue.get("blockers") or []),
        *(runtime_preflight.get("blockers") or []),
        *failed_checks,
        "schedule_activation_not_requested",
        "schedule_must_start_paused",
        "background_loop_disabled",
        "trading_disabled",
        "client_signal_disabled",
        "client_opt_in_missing",
    ]))
    return {
        "ok": True,
        "dry_run": True,
        "checklist_status": "ready_but_paused" if checklist_ready else "blocked",
        "mode": "core_equity_agent_os_lite_schedule_activation_checklist",
        "chain": requested_chain,
        "focus": safe_focus,
        "activation_target": "core_equity_codex_agent_cycle",
        "recommended_schedule": {
            "status": "PAUSED",
            "cadence_minutes": safe_cadence_minutes,
            "max_cycles_per_day": safe_max_cycles_per_day,
            "max_tasks_per_cycle": 1,
            "allow_live_checks": bool(allow_live_checks),
            "first_mode": "audit_only_or_read_only_cycle",
        },
        "write_scope_policy": {
            "business_write_allowed": False,
            "raw_data_write_allowed": False,
            "audit_write_allowed_only_in_separate_confirmed_cycle": True,
            "schedule_write_allowed_here": False,
        },
        "provider_call_policy": {
            "rpc_allowed_for_scheduled_cycle": bool(allow_live_checks),
            "external_provider_allowed": False,
            "scraping_allowed": False,
        },
        "runtime_preflight": {
            "preflight_status": runtime_preflight.get("preflight_status"),
            "selected_runtime": runtime_preflight.get("selected_runtime"),
            "degraded_conditions": runtime_preflight.get("degraded_conditions") or [],
            "current_safe_task": runtime_preflight.get("current_safe_task"),
            "run_lane_status": runtime_preflight.get("run_lane_status"),
        },
        "required_future_confirm": "ENABLE_CORE_EQUITY_CODEX_BOUNDED_SCHEDULE",
        "preflight_checks": checks,
        "top_task": top_task,
        "selected_task": selected_task,
        "schedule_safe_fallback_used": used_fallback_task,
        "schedule_safe_fallback_reason": (
            "top_task_requires_disabled_runtime_inputs"
            if used_fallback_task else None
        ),
        "allowed_if_enabled_later": [
            "read_agent_os_lite_state",
            "select_one_allowlisted_task",
            "run_one_bounded_read_only_task",
            "validate_schema_and_safety_flags",
            "write_one_audit_receipt_when_policy_allows",
            "stop_cycle",
        ],
        "must_remain_disabled": [
            "unbounded_background_loop",
            "raw_data_write_without_separate_data_policy",
            "cex_label_creation",
            "dex_router_evidence_creation",
            "venue_mapping",
            "swap_rewrite",
            "client_signal",
            "trade_execution",
            "wallet_order",
            "client_opt_in",
            "hermes_operator",
            "crewai_operator",
        ],
        "blockers": blockers,
        "next_safe_step": (
            "enable_only_a_paused_or_strictly_bounded_schedule_after_explicit_user_confirmation"
            if checklist_ready else "repair_failed_preflight_checks_before_schedule"
        ),
        **common_disabled,
    }


def run_core_equity_codex_agent_runner_dry_run(
    chain: str | None = "bsc",
    focus: str | None = "unknown_dex_data_quality",
    limit: int = 5,
    dry_run: bool = True,
    allow_live_checks: bool = False,
    max_tasks: int = 8,
    task_id: str | None = None,
) -> dict[str, Any]:
    """Run one selected Codex task contract in read-only preview mode and validate safety flags."""
    _init_db()
    requested_chain = _normalize_chain(chain or "bsc")
    safe_limit = max(1, min(int(limit or 5), 12))
    safe_max_tasks = max(1, min(int(max_tasks or 8), 20))
    requested_task_id = str(task_id or "").strip()
    source_policy = (
        "admin-only read-only Codex agent runner dry-run. It executes at most one allowlisted task contract "
        "through local service functions, validates output safety flags, writes no audit record, schedules nothing, "
        "and creates no labels, mappings, trades, wallet orders, client signals or opt-ins."
    )
    disabled_actions = {
        "schedule_creation": True,
        "background_loop": True,
        "multi_task_execution": True,
        "db_write": True,
        "raw_data_write": True,
        "cex_label_creation": True,
        "dex_router_evidence_creation": True,
        "venue_mapping": True,
        "swap_rewrite": True,
        "client_signal": True,
        "trade_execution": True,
        "wallet_order": True,
        "client_opt_in": True,
        "hermes_operator": True,
        "opencode_operator": True,
        "local_model_operator": True,
    }
    common_disabled = {
        "disabled_actions": disabled_actions,
        "would_schedule_codex_job": False,
        "would_start_24_7_runner": False,
        "would_run_background_loop": False,
        "would_write_audit_log": False,
        "would_write_raw_data": False,
        "would_write": False,
        "would_create_cex_label": False,
        "would_create_dex_router_evidence": False,
        "would_create_mapping": False,
        "would_update_swaps": False,
        "would_execute_trade": False,
        "would_create_wallet_order": False,
        "would_create_client_signal": False,
        "would_create_client_opt_in": False,
        "real_write_enabled": False,
        "writes_performed": 0,
        "source_policy": source_policy,
    }
    if not dry_run:
        return {
            "ok": False,
            "dry_run": False,
            "runner_status": "blocked",
            "error": "dry_run_required",
            "blockers": ["dry_run_required"],
            **common_disabled,
        }

    preview = get_core_equity_agent_task_contract_preview(
        chain=requested_chain,
        focus=focus,
        limit=safe_limit,
        dry_run=True,
        allow_live_checks=bool(allow_live_checks),
        max_tasks=safe_max_tasks,
    )
    contracts = list(preview.get("task_contracts") or [])
