# Manipulation verdict helpers live in services.onchain.manipulation_verdicts.
# Manipulation readiness lives in services.onchain.manipulation_readiness.
def run_readiness_gap_auto_fill(
    entity: str | None = None,
    chain: str | None = None,
    dry_run: bool = True,
    confirm: str | None = None,
    max_cycles: int = 3,
    max_pairs: int = 2,
) -> dict[str, Any]:
    """Preview or run a bounded admin data-improvement pass from readiness gaps."""
    safe_cycles = max(1, min(int(max_cycles or 3), 8))
    safe_pairs = max(1, min(int(max_pairs or 2), 5))
    normalized_chain = _normalize_chain(chain or "") if chain else None
    before = get_manipulation_detection_readiness(entity=entity, chain=normalized_chain, limit=12)
    contract = before.get("readiness_contract", {}) or {}
    steps = list((contract.get("gap_closure_plan") or {}).get("steps") or [])[:safe_cycles]
    if not dry_run and confirm != "RUN_READYNESS_GAP_FILL":
        return {
            "ok": False,
            "dry_run": dry_run,
            "error": "confirm_RUN_READYNESS_GAP_FILL_required",
            "before": before,
            "source_trace": [],
            "execution_envelope": {
                "client_execution_enabled": False,
                "copy_trading_enabled": False,
                "profit_guarantee_allowed": False,
                "admin_confirm_required": True,
            },
            "source_policy": "real readiness gap fill is blocked without explicit admin confirmation",
        }

    def preview_step(step: dict[str, Any]) -> dict[str, Any]:
        action_id = str(step.get("action_id") or "")
        if action_id in {"inspect_entity_coverage", "grow_strict_label_evidence"}:
            if action_id == "grow_strict_label_evidence":
                return stage_rpc_label_source_gap_candidates(entity=entity, chain=normalized_chain, limit=safe_pairs * 10, dry_run=True)
            return get_onchain_data_readiness(entity=entity, limit=5)
        if action_id in {"inspect_label_source_gaps", "stage_label_source_gap_candidates", "corroborate_label_source_gap_candidates"}:
            if action_id == "stage_label_source_gap_candidates":
                return stage_rpc_label_source_gap_candidates(entity=entity, chain=normalized_chain, limit=safe_pairs * 10, dry_run=True)
            if action_id == "corroborate_label_source_gap_candidates":
                return corroborate_rpc_label_source_gap_candidates(entity=entity, chain=normalized_chain, limit=safe_pairs, dry_run=True)
            return get_rpc_label_source_gap_report(entity=entity, chain=normalized_chain, limit=safe_pairs * 10)
        if action_id in {"inspect_swap_identity_readiness", "plan_exact_swap_ingestion", "run_bounded_exact_swap_ingestion"}:
            return get_exact_swap_ingestion_plan(max_chains=safe_pairs)
        if action_id == "review_verified_label_candidates":
            from services.label_ledger import get_label_candidate_evidence_scores

            return get_label_candidate_evidence_scores(limit=safe_pairs * 5, entity=entity, chain=normalized_chain)
        if action_id == "inspect_unknown_router_source_gaps":
            return get_unknown_router_source_gap_report(chain=normalized_chain, limit=safe_pairs * 5, include_public_evidence=False)
        return {
            "ok": True,
            "preview_only": True,
            "action_id": action_id,
            "source_policy": "no concrete auto-fill preview registered for this action yet",
        }

    def run_step(step: dict[str, Any]) -> dict[str, Any]:
        action_id = str(step.get("action_id") or "")
        if action_id in {"stage_label_source_gap_candidates", "grow_strict_label_evidence"}:
            return stage_rpc_label_source_gap_candidates(entity=entity, chain=normalized_chain, limit=safe_pairs * 10, dry_run=False)
        if action_id == "corroborate_label_source_gap_candidates":
            return corroborate_rpc_label_source_gap_candidates(entity=entity, chain=normalized_chain, limit=safe_pairs, dry_run=False)
        if action_id == "run_bounded_exact_swap_ingestion":
            return run_exact_swap_ingestion_plan_once(max_chains=safe_pairs, count_per_chain=1, confirmations=12)
        return preview_step(step)

    source_trace: list[dict[str, Any]] = []
    for index, step in enumerate(steps, start=1):
        result = preview_step(step) if dry_run else run_step(step)
        source_trace.append({
            "index": index,
            "dry_run": dry_run,
            "phase": step.get("phase"),
            "gap_id": step.get("gap_id"),
            "action_id": step.get("action_id"),
            "method": step.get("method"),
            "endpoint": step.get("endpoint"),
            "admin_required": step.get("admin_required"),
            "before": {
                "status": before.get("status"),
                "failed_count": contract.get("failed_count"),
                "signal_readiness_score": before.get("signal_readiness_score"),
            },
            "result": result,
            "source_policy": str(result.get("source_policy") or step.get("data_source") or "readiness_gap_auto_fill"),
            "warnings": [
                "client_execution_disabled",
                *([] if dry_run else ["real_admin_data_mutation_requested"]),
            ],
        })

    after = before if dry_run else get_manipulation_detection_readiness(entity=entity, chain=normalized_chain, limit=12)
    return {
        "ok": True,
        "dry_run": dry_run,
        "entity": entity,
        "chain": normalized_chain or chain,
        "max_cycles": safe_cycles,
        "max_pairs": safe_pairs,
        "before": before,
        "after": after,
        "source_trace": source_trace,
        "execution_envelope": {
            "client_execution_enabled": False,
            "copy_trading_enabled": False,
            "profit_guarantee_allowed": False,
            "admin_confirm_required": not dry_run,
            "confirm": "RUN_READYNESS_GAP_FILL" if not dry_run else None,
        },
        "source_policy": (
            "readiness gap auto-fill orchestrator; dry-run previews by default, "
            "real writes require admin router auth plus confirm, and client execution stays disabled"
        ),
    }


def enrich_priority_entity_chain_gaps_rpc(
    limit_per_pair: int = 8,
    max_pairs: int = 8,
    min_confidence: str = "medium",
    include_tokens: bool = True,
    allow_audit_debt: bool = False,
    stale_after_hours: int = 24,
) -> dict[str, Any]:
    """Enrich the most under-covered entity/chain pairs instead of defaulting to one chain."""
    job_params = {
        "limit_per_pair": limit_per_pair,
        "max_pairs": max_pairs,
        "min_confidence": min_confidence,
        "include_tokens": include_tokens,
        "allow_audit_debt": allow_audit_debt,
        "stale_after_hours": stale_after_hours,
    }
    job_id = _start_data_job("priority_entity_chain_rpc_enrichment", job_params)
    limit_per_pair = max(1, min(int(limit_per_pair or 8), 50))
    max_pairs = max(1, min(int(max_pairs or 8), 30))
    stale_after_hours = max(1, min(int(stale_after_hours or 24), 24 * 30))
    try:
        plan = get_rpc_entity_chain_gap_verification(
            min_confidence=min_confidence,
            limit=max_pairs,
            stale_after_hours=stale_after_hours,
        )
        results = []
        skipped = []
        for row in plan.get("rows", [])[:max_pairs]:
            entity = row.get("entity")
            chain = row.get("chain")
            if not entity or not chain:
                continue
            verification_status = row.get("verification_status")
            can_enrich = verification_status == "safe_to_enrich" or (
                allow_audit_debt and verification_status == "enrich_but_audit_existing_rows"
            )
            if not can_enrich:
                skipped.append(
                    {
                        "entity": entity,
                        "chain": chain,
                        "verification_status": verification_status,
                        "blockers": row.get("blockers", []),
                        "recommended_action": row.get("recommended_action"),
                        "labelled_wallets": row.get("labelled_wallets"),
                        "rpc_wallets_before": row.get("rpc_wallets"),
                        "missing_wallets_before": row.get("missing_wallets"),
                    }
                )
                continue
            result = enrich_labeled_wallets_rpc(
                chain=chain,
                entity=entity,
                limit=min(limit_per_pair, max(1, int(row.get("missing_wallets") or 1))),
                min_confidence=min_confidence,
                include_tokens=include_tokens,
                missing_only=True,
            )
            results.append(
                {
                    "entity": entity,
                    "chain": chain,
                    "verification_status": verification_status,
                    "blockers": row.get("blockers", []),
                    "labelled_wallets": row.get("labelled_wallets"),
                    "rpc_wallets_before": row.get("rpc_wallets"),
                    "missing_wallets_before": row.get("missing_wallets"),
                    "wallets_updated": result.get("wallets_updated"),
                    "seeds_loaded": result.get("seeds_loaded"),
                    "chains_seen": result.get("chains_seen"),
                    "errors": result.get("errors", [])[:5],
                }
            )
        post_report = get_rpc_entity_chain_gap_report(min_confidence=min_confidence, limit=200)
        post_by_pair = {
            (row.get("entity"), row.get("chain")): row
            for row in post_report.get("rows", [])
        }
        for item in results:
            key = (item.get("entity"), item.get("chain"))
            after = post_by_pair.get(key)
            labelled = int(item.get("labelled_wallets") or 0)
            missing_before = int(item.get("missing_wallets_before") or 0)
            if after:
                rpc_after = int(after.get("rpc_wallets") or 0)
                missing_after = int(after.get("missing_wallets") or 0)
                coverage_after = after.get("rpc_coverage_pct")
            else:
                rpc_after = labelled
                missing_after = 0
                coverage_after = 100.0 if labelled else 0.0
            item["rpc_wallets_after"] = rpc_after
            item["missing_wallets_after"] = missing_after
            item["net_rpc_wallets_added"] = max(0, missing_before - missing_after)
            item["rpc_coverage_pct_after"] = coverage_after

        payload = {
            "ok": True,
            "mode": "priority_entity_chain_rpc_enrichment",
            "job_id": job_id,
            "limit_per_pair": limit_per_pair,
            "max_pairs": max_pairs,
            "min_confidence": min_confidence,
            "pairs_attempted": len(results),
            "pairs_skipped": len(skipped),
            "verification_summary": plan.get("summary", {}),
            "results": results,
            "skipped": skipped,
            "source_policy": (
                "uses read-only entity-chain gap verification before RPC enrichment; "
                "skips audit-debt and inconsistent gaps by default; never creates or promotes labels"
            ),
            "post_chain_gap_report": get_rpc_entity_chain_gap_report(min_confidence=min_confidence, limit=max_pairs),
        }
        _finish_data_job(job_id, "ok", payload)
        return payload
    except Exception as exc:
        _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


def refresh_rpc_wallet_state_audit_targets(
    limit_per_target: int = 5,
    max_targets: int = 5,
    include_tokens: bool = False,
    min_confidence: str = "medium",
    stale_after_hours: int = 24,
    quality_below: int = 50,
    entity: str | None = None,
    chain: str | None = None,
) -> dict[str, Any]:
    """Refresh existing RPC wallet rows selected by the traceability audit."""
    limit_per_target = max(1, min(int(limit_per_target or 5), 50))
    max_targets = max(1, min(int(max_targets or 5), 20))
    stale_after_hours = max(1, min(int(stale_after_hours or 24), 24 * 30))
    quality_below = max(0, min(int(quality_below or 0), 100))
    job_params = {
        "limit_per_target": limit_per_target,
        "max_targets": max_targets,
        "include_tokens": include_tokens,
        "min_confidence": min_confidence,
        "stale_after_hours": stale_after_hours,
        "quality_below": quality_below,
        "entity": entity,
        "chain": chain,
    }
    job_id = _start_data_job("rpc_wallet_state_audit_refresh", job_params)
    try:
        before = get_rpc_wallet_state_audit(entity=entity, chain=chain, stale_after_hours=stale_after_hours, limit=max_targets)
        results: list[dict[str, Any]] = []
        for target in before.get("refresh_targets", [])[:max_targets]:
            target_entity = target.get("entity")
            target_chain = target.get("chain")
            if not target_entity or not target_chain or target_entity == "unknown":
                continue
            target_rows = max(
                int(target.get("missing_source_attribution") or 0),
                int(target.get("missing_label_sources") or 0),
                int(target.get("stale_rows") or 0),
                int(target.get("low_quality_rows") or 0),
                1,
            )
            result = enrich_labeled_wallets_rpc(
                chain=target_chain,
                entity=target_entity,
                limit=min(limit_per_target, target_rows),
                include_tokens=include_tokens,
                min_confidence=min_confidence,
                missing_only=False,
                refresh_missing_attribution=True,
                refresh_stale_hours=stale_after_hours,
                refresh_quality_below=quality_below,
            )
            results.append(
                {
                    "entity": target_entity,
                    "chain": target_chain,
                    "wallets": target.get("wallets"),
                    "missing_source_attribution_before": target.get("missing_source_attribution"),
                    "missing_label_sources_before": target.get("missing_label_sources"),
                    "stale_rows_before": target.get("stale_rows"),
                    "low_quality_rows_before": target.get("low_quality_rows"),
                    "wallets_updated": result.get("wallets_updated"),
                    "seeds_loaded": result.get("seeds_loaded"),
                    "chains_seen": result.get("chains_seen"),
                    "errors": result.get("errors", [])[:5],
                }
            )
        after = get_rpc_wallet_state_audit(entity=entity, chain=chain, stale_after_hours=stale_after_hours, limit=max_targets)
        payload = {
            "ok": True,
            "mode": "rpc_wallet_state_audit_refresh",
            "job_id": job_id,
            "limit_per_target": limit_per_target,
            "max_targets": max_targets,
            "targets_attempted": len(results),
            "wallets_updated": sum(int(item.get("wallets_updated") or 0) for item in results),
            "before": {
                "total_wallets": before.get("total_wallets"),
                "traceable_wallets": before.get("traceable_wallets"),
                "traceability_pct": before.get("traceability_pct"),
                "missing_source_attribution": before.get("missing_source_attribution"),
                "missing_label_sources": before.get("missing_label_sources"),
                "stale_rows": before.get("stale_rows"),
                "low_quality_rows": before.get("low_quality_rows"),
            },
            "after": {
                "total_wallets": after.get("total_wallets"),
                "traceable_wallets": after.get("traceable_wallets"),
                "traceability_pct": after.get("traceability_pct"),
                "missing_source_attribution": after.get("missing_source_attribution"),
                "missing_label_sources": after.get("missing_label_sources"),
                "stale_rows": after.get("stale_rows"),
                "low_quality_rows": after.get("low_quality_rows"),
            },
            "results": results,
            "source_policy": "bounded admin refresh of existing wallet_chain_state audit targets; no labels are created or promoted",
        }
        _finish_data_job(job_id, "ok", payload)
        return payload
    except Exception as exc:
        _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


def _auto_enrich_loop(
    interval_seconds: int,
    limit_per_entity: int,
    max_entities: int,
    min_confidence: str,
    include_tokens: bool,
    mode: str,
) -> None:
    while not _auto_enrich_stop.is_set():
        if _auto_enrich_lock.acquire(blocking=False):
            try:
                _run_auto_enrich_once(
                    limit_per_entity=limit_per_entity,
                    max_entities=max_entities,
                    min_confidence=min_confidence,
                    include_tokens=include_tokens,
                    mode=mode,
                )
            except Exception as exc:
                job_id = _start_data_job(
                    f"priority_{mode}_rpc_enrichment_auto_error",
                    {
                        "interval_seconds": interval_seconds,
                        "limit_per_entity": limit_per_entity,
                        "max_entities": max_entities,
                        "min_confidence": min_confidence,
                        "include_tokens": include_tokens,
                        "mode": mode,
                    },
                )
                _finish_data_job(job_id, "failed", error=str(exc)[:500])
            finally:
                _auto_enrich_lock.release()
        _auto_enrich_stop.wait(max(60, int(interval_seconds or 3600)))


def _run_auto_enrich_once(
    limit_per_entity: int,
    max_entities: int,
    min_confidence: str,
    include_tokens: bool,
    mode: str,
) -> dict[str, Any]:
    """One guarded auto-enrich pass; separated so tests can verify routing without a thread."""
    if _env_bool("CORE_AUTO_LABEL_BUILD_ENABLED", True):
        build_label_ledger_job(_env_optional_int("CORE_AUTO_LABEL_BUILD_LIMIT_FILES", 1, 10000))
    if mode == "entities":
        return enrich_priority_entities_rpc(
            limit_per_entity=limit_per_entity,
            max_entities=max_entities,
            min_confidence=min_confidence,
            include_tokens=include_tokens,
        )
    result = enrich_priority_entity_chain_gaps_rpc(
        limit_per_pair=limit_per_entity,
        max_pairs=max_entities,
        min_confidence=min_confidence,
        include_tokens=include_tokens,
    )
    audit_refresh_enabled = _env_bool("CORE_AUTO_AUDIT_REFRESH_ENABLED", True)
    has_skipped_audit_debt = any(
        row.get("verification_status") == "enrich_but_audit_existing_rows"
        for row in result.get("skipped", [])
    )
    if (
        audit_refresh_enabled
        and int(result.get("pairs_attempted") or 0) == 0
        and has_skipped_audit_debt
    ):
        result["idle_audit_refresh"] = refresh_rpc_wallet_state_audit_targets(
            limit_per_target=_env_int("CORE_AUTO_AUDIT_REFRESH_LIMIT_PER_TARGET", 2, 1, 10),
            max_targets=_env_int("CORE_AUTO_AUDIT_REFRESH_MAX_TARGETS", 2, 1, 10),
            include_tokens=False,
            min_confidence=min_confidence,
            stale_after_hours=_env_int("CORE_AUTO_AUDIT_REFRESH_STALE_HOURS", 24, 1, 24 * 30),
            quality_below=_env_int("CORE_AUTO_AUDIT_REFRESH_QUALITY_BELOW", 50, 0, 100),
        )
        result["source_policy"] = (
            f"{result.get('source_policy')}; when gap verification is blocked by audit debt, "
            "auto-refresh repairs existing wallet_chain_state attribution/quality first and waits for the next pass"
        )
        return result
    source_acquire_enabled = _env_bool("CORE_AUTO_SOURCE_ACQUIRE_ENABLED", True)
    if source_acquire_enabled and int(result.get("pairs_attempted") or 0) == 0:
        source_limit = _env_int("CORE_AUTO_SOURCE_ACQUIRE_LIMIT", 2, 1, 5)
        min_trusted = _env_int("CORE_AUTO_SOURCE_MIN_TRUSTED_PER_ENTITY", 100, 25, 1000)
        timeout_ms = _env_int("CORE_AUTO_SOURCE_TIMEOUT_MS", 20000, 5000, 120000)
        max_xhr = _env_int("CORE_AUTO_SOURCE_MAX_XHR", 40, 10, 200)
        result["idle_source_acquisition"] = acquire_label_sources_job(
            limit=source_limit,
            min_trusted_per_entity=min_trusted,
            timeout_ms=timeout_ms,
            max_xhr=max_xhr,
        )
        if _env_bool("CORE_AUTO_CANDIDATE_DEDUP_ENABLED", True):
            result["idle_candidate_dedup"] = consolidate_label_candidate_duplicates_job(
                limit=_env_int("CORE_AUTO_CANDIDATE_DEDUP_LIMIT", 25, 1, 25),
                dry_run=False,
            )
        result["source_policy"] = (
            f"{result.get('source_policy')}; when no RPC entity-chain gaps remain, "
            "auto-acquisition stages source-backed label candidates only, merges exact duplicate candidates, "
            "and does not promote trusted labels"
        )
        corroborate_enabled = _env_bool("CORE_AUTO_CORROBORATE_ENABLED", True)
        if corroborate_enabled:
            corroborate_limit = _env_int("CORE_AUTO_CORROBORATE_LIMIT", 3, 1, 25)
            corroborate_timeout = _env_int("CORE_AUTO_CORROBORATE_TIMEOUT", 8, 2, 20)
            result["idle_candidate_corroboration"] = corroborate_label_candidates_job(
                limit=corroborate_limit,
                timeout=corroborate_timeout,
                include_manual_review=False,
            )
            result["source_policy"] = (
                f"{result.get('source_policy')}; idle candidate corroboration persists evidence bundles only "
                "and never promotes trusted labels"
            )
        if _env_bool("CORE_AUTO_MAPPING_REVIEW_QUEUE_ENABLED", False):
            result["idle_mapping_review_queue"] = get_source_backed_venue_mapping_admin_review_queue(
                chain=None,
                limit=_env_int("CORE_AUTO_MAPPING_REVIEW_QUEUE_LIMIT", 3, 1, 10),
                timeout=_env_int("CORE_AUTO_MAPPING_REVIEW_QUEUE_TIMEOUT", 6, 2, 15),
                include_counterparty_source_search=_env_bool(
                    "CORE_AUTO_MAPPING_REVIEW_QUEUE_COUNTERPARTY_SEARCH_ENABLED",
                    True,
                ),
            )
            result["source_policy"] = (
                f"{result.get('source_policy')}; idle source-backed mapping review queue is read-only, "
                "admin-token gated at the API layer, and never writes venue mappings automatically"
            )
        if _env_bool("CORE_AUTO_CEX_DEPOSIT_HOLDER_REFRESH_ENABLED", False):
            holder_refresh_cooldown = _env_int(
                "CORE_AUTO_CEX_DEPOSIT_HOLDER_REFRESH_COOLDOWN_SECONDS",
                21600,
                300,
                86400,
            )
            last_holder_refresh_job = _latest_data_job(["cex_deposit_holder_snapshot_refresh"])
            if (
                last_holder_refresh_job
                and int(last_holder_refresh_job.get("age_seconds") or 0) < holder_refresh_cooldown
            ):
                result["idle_cex_deposit_holder_snapshot_refresh_skipped"] = {
                    "ok": True,
                    "reason": "cooldown_active",
                    "cooldown_seconds": holder_refresh_cooldown,
                    "age_seconds": int(last_holder_refresh_job.get("age_seconds") or 0),
                    "last_job": {
                        key: last_holder_refresh_job.get(key)
                        for key in ["id", "job_type", "status", "started_at", "finished_at"]
                    },
                    "source_policy": (
                        "holder snapshot auto-refresh skipped because a recent refresh already ran; "
                        "this prevents repeated Firecrawl/Blockscout-style external fetches and cache churn"
                    ),
                }
                result["source_policy"] = (
                    f"{result.get('source_policy')}; idle CEX-deposit holder snapshot refresh is cooldown-gated "
                    "to prevent repeated external fetches and holders_cache churn"
                )
            else:
                result["idle_cex_deposit_holder_snapshot_refresh"] = refresh_cex_deposit_holder_snapshots_job(
                    chain=None,
                    limit=_env_int("CORE_AUTO_CEX_DEPOSIT_HOLDER_REFRESH_LIMIT", 1, 1, 5),
                )
                result["source_policy"] = (
                    f"{result.get('source_policy')}; idle CEX-deposit holder snapshot refresh is opt-in, bounded, "
                    "audited in data_jobs, writes only holders_cache, and never enables client execution"
                )
        if _env_bool("CORE_AUTO_EXACT_SWAP_INGEST_ENABLED", False):
            exact_swap_cooldown = _env_int("CORE_AUTO_EXACT_SWAP_COOLDOWN_SECONDS", 3600, 60, 86400)
            last_exact_swap_job = _latest_data_job(["exact_swap_progressive_ingest", "exact_swap_window_ingest"])
            if last_exact_swap_job and int(last_exact_swap_job.get("age_seconds") or 0) < exact_swap_cooldown:
                result["idle_exact_swap_ingestion_skipped"] = {
                    "ok": True,
                    "reason": "cooldown_active",
                    "cooldown_seconds": exact_swap_cooldown,
                    "age_seconds": int(last_exact_swap_job.get("age_seconds") or 0),
                    "last_job": {
                        key: last_exact_swap_job.get(key)
                        for key in ["id", "job_type", "status", "started_at", "finished_at"]
                    },
                    "source_policy": (
                        "exact swap auto-ingestion skipped because a recent exact-swap data job already ran; "
                        "this prevents RPC hammering and repeated writes from the background loop"
                    ),
                }
                result["source_policy"] = (
                    f"{result.get('source_policy')}; idle exact swap ingestion is cooldown-gated to prevent "
                    "RPC hammering and repeated swap writes"
                )
                return result
            result["idle_exact_swap_ingestion"] = run_exact_swap_ingestion_plan_once(
                max_chains=_env_int("CORE_AUTO_EXACT_SWAP_MAX_CHAINS", 1, 1, 3),
                count_per_chain=_env_int("CORE_AUTO_EXACT_SWAP_COUNT_PER_CHAIN", 1, 1, 3),
                confirmations=_env_int("CORE_AUTO_EXACT_SWAP_CONFIRMATIONS", 12, 0, 50),
            )
            result["source_policy"] = (
                f"{result.get('source_policy')}; idle exact swap ingestion is bounded and writes "
                "blocks/transactions/swaps only for manipulation-readiness history, never labels, candidates, "
                "client wallet authority or trade execution"
            )
    return result


def start_auto_enrich_priority(
    interval_seconds: int | None = None,
    limit_per_entity: int | None = None,
    max_entities: int | None = None,
    min_confidence: str | None = None,
    include_tokens: bool | None = None,
    mode: str | None = None,
) -> dict[str, Any]:
    """Start a safe background priority enrichment loop."""
    global _auto_enrich_thread, _auto_enrich_config
    interval = _coerce_int(
        interval_seconds if interval_seconds is not None else os.getenv("CORE_AUTO_ENRICH_INTERVAL_SECONDS"),
        3600,
        300,
        86400,
    )
    per_entity = _coerce_int(
        limit_per_entity if limit_per_entity is not None else os.getenv("CORE_AUTO_ENRICH_LIMIT_PER_ENTITY"),
        10,
        1,
        50,
    )
    entities = _coerce_int(
        max_entities if max_entities is not None else os.getenv("CORE_AUTO_ENRICH_MAX_ENTITIES"),
        4,
        1,
        20,
    )
    confidence = (min_confidence or os.getenv("CORE_AUTO_ENRICH_MIN_CONFIDENCE", "medium")).strip() or "medium"
    enrich_mode = (mode or os.getenv("CORE_AUTO_ENRICH_MODE", "chain_gaps")).strip().lower() or "chain_gaps"
    if enrich_mode not in {"chain_gaps", "entities"}:
        enrich_mode = "chain_gaps"
    tokens = include_tokens
    if tokens is None:
        tokens = _env_bool("CORE_AUTO_ENRICH_INCLUDE_TOKENS", True)

    _auto_enrich_config = {
        "interval_seconds": interval,
        "limit_per_entity": per_entity,
        "max_entities": entities,
        "min_confidence": confidence,
        "include_tokens": bool(tokens),
        "mode": enrich_mode,
    }
    if _auto_enrich_thread is None or not _auto_enrich_thread.is_alive():
        _auto_enrich_stop.clear()
        _auto_enrich_thread = threading.Thread(
            target=_auto_enrich_loop,
            args=(interval, per_entity, entities, confidence, bool(tokens), enrich_mode),
            daemon=True,
        )
        _auto_enrich_thread.start()
    return get_auto_enrich_status()


def stop_auto_enrich_priority() -> dict[str, Any]:
    _auto_enrich_stop.set()
    if _auto_enrich_thread:
        _auto_enrich_thread.join(timeout=2)
    return get_auto_enrich_status()


def get_auto_enrich_status() -> dict[str, Any]:
    return {
        "ok": True,
        "running": bool(_auto_enrich_thread and _auto_enrich_thread.is_alive() and not _auto_enrich_stop.is_set()),
        "locked": _auto_enrich_lock.locked(),
        "config": _auto_enrich_config,
        "automation_rails": {
            "label_build_enabled": _env_bool("CORE_AUTO_LABEL_BUILD_ENABLED", True),
            "source_acquire_enabled": _env_bool("CORE_AUTO_SOURCE_ACQUIRE_ENABLED", True),
            "source_acquire_limit": _env_int("CORE_AUTO_SOURCE_ACQUIRE_LIMIT", 2, 1, 5),
            "source_min_trusted_per_entity": _env_int("CORE_AUTO_SOURCE_MIN_TRUSTED_PER_ENTITY", 100, 25, 1000),
            "source_timeout_ms": _env_int("CORE_AUTO_SOURCE_TIMEOUT_MS", 20000, 5000, 120000),
            "source_max_xhr": _env_int("CORE_AUTO_SOURCE_MAX_XHR", 40, 10, 200),
            "audit_refresh_enabled": _env_bool("CORE_AUTO_AUDIT_REFRESH_ENABLED", True),
            "audit_refresh_limit_per_target": _env_int("CORE_AUTO_AUDIT_REFRESH_LIMIT_PER_TARGET", 2, 1, 10),
            "audit_refresh_max_targets": _env_int("CORE_AUTO_AUDIT_REFRESH_MAX_TARGETS", 2, 1, 10),
            "audit_refresh_stale_hours": _env_int("CORE_AUTO_AUDIT_REFRESH_STALE_HOURS", 24, 1, 24 * 30),
            "audit_refresh_quality_below": _env_int("CORE_AUTO_AUDIT_REFRESH_QUALITY_BELOW", 50, 0, 100),
            "candidate_dedup_enabled": _env_bool("CORE_AUTO_CANDIDATE_DEDUP_ENABLED", True),
            "candidate_dedup_limit": _env_int("CORE_AUTO_CANDIDATE_DEDUP_LIMIT", 25, 1, 25),
            "candidate_corroboration_enabled": _env_bool("CORE_AUTO_CORROBORATE_ENABLED", True),
            "candidate_corroboration_limit": _env_int("CORE_AUTO_CORROBORATE_LIMIT", 3, 1, 25),
            "candidate_corroboration_timeout": _env_int("CORE_AUTO_CORROBORATE_TIMEOUT", 8, 2, 20),
            "mapping_review_queue_enabled": _env_bool("CORE_AUTO_MAPPING_REVIEW_QUEUE_ENABLED", False),
            "mapping_review_queue_limit": _env_int("CORE_AUTO_MAPPING_REVIEW_QUEUE_LIMIT", 3, 1, 10),
            "mapping_review_queue_timeout": _env_int("CORE_AUTO_MAPPING_REVIEW_QUEUE_TIMEOUT", 6, 2, 15),
            "mapping_review_queue_counterparty_search_enabled": _env_bool(
                "CORE_AUTO_MAPPING_REVIEW_QUEUE_COUNTERPARTY_SEARCH_ENABLED",
                True,
            ),
            "cex_deposit_holder_snapshot_refresh_enabled": _env_bool(
                "CORE_AUTO_CEX_DEPOSIT_HOLDER_REFRESH_ENABLED",
                False,
            ),
            "cex_deposit_holder_snapshot_refresh_limit": _env_int(
                "CORE_AUTO_CEX_DEPOSIT_HOLDER_REFRESH_LIMIT",
                1,
                1,
                5,
            ),
            "cex_deposit_holder_snapshot_refresh_cooldown_seconds": _env_int(
                "CORE_AUTO_CEX_DEPOSIT_HOLDER_REFRESH_COOLDOWN_SECONDS",
                21600,
                300,
                86400,
            ),
            "cex_deposit_holder_snapshot_refresh_last_job": (
                lambda job: None if not job else {
                    key: job.get(key)
                    for key in ["id", "job_type", "status", "started_at", "finished_at", "age_seconds"]
                }
            )(_latest_data_job(["cex_deposit_holder_snapshot_refresh"])),
            "exact_swap_ingest_enabled": _env_bool("CORE_AUTO_EXACT_SWAP_INGEST_ENABLED", False),
            "exact_swap_max_chains": _env_int("CORE_AUTO_EXACT_SWAP_MAX_CHAINS", 1, 1, 3),
            "exact_swap_count_per_chain": _env_int("CORE_AUTO_EXACT_SWAP_COUNT_PER_CHAIN", 1, 1, 3),
            "exact_swap_confirmations": _env_int("CORE_AUTO_EXACT_SWAP_CONFIRMATIONS", 12, 0, 50),
            "exact_swap_cooldown_seconds": _env_int("CORE_AUTO_EXACT_SWAP_COOLDOWN_SECONDS", 3600, 60, 86400),
            "exact_swap_last_job": (
                lambda job: None if not job else {
                    key: job.get(key)
                    for key in ["id", "job_type", "status", "started_at", "finished_at", "age_seconds"]
                }
            )(_latest_data_job(["exact_swap_progressive_ingest", "exact_swap_window_ingest"])),
            "trusted_auto_promotion": False,
        },
        "source_policy": (
            "background loop rebuilds verified local labels, then enriches labelled priority entity-chain gaps by default; "
            "when gaps are blocked by audit debt it refreshes existing wallet state first; when gaps are empty it may stage "
            "and corroborate source-backed label candidates, can optionally prepare a read-only source-backed venue mapping "
            "review queue, can optionally refresh missing CEX-deposit holder snapshots into holders_cache, and can optionally "
            "ingest bounded exact swap history for manipulation-readiness, but never auto-promotes trusted labels, auto-maps "
            "venues or enables client execution"
        ),
    }


def get_rpc_wallet_state(limit: int = 100, entity: str | None = None, chain: str | None = None) -> dict[str, Any]:
    _init_db()
    requested_chain = _normalize_chain(chain or "") if chain else None
    where = []
    params: list[Any] = []
    if requested_chain:
        where.append("chain = ?")
        params.append(requested_chain)
    if entity:
        clause, clause_params = entity_in_clause("entity", entity)
        where.append(clause)
        params.extend(clause_params)
    where_sql = f"WHERE {' AND '.join(where)}" if where else ""
    conn = _get_db()
    try:
        rows = conn.execute(
            f"""
            SELECT chain, address, native_balance, tx_count, token_balances_json,
                   rpc_source, label, entity, confidence, address_kind, is_contract,
                   native_value_usd, activity_tier, risk_flags_json, data_quality_score,
                   label_sources_json, source_attribution_json, observed_at
            FROM wallet_chain_state
            {where_sql}
            ORDER BY tx_count DESC, native_balance DESC
            LIMIT ?
            """,
            [*params, max(1, min(int(limit or 100), 500))],
        ).fetchall()
        total = conn.execute(f"SELECT COUNT(*) FROM wallet_chain_state {where_sql}", params).fetchone()[0]
        by_chain = {
            row[0]: row[1]
            for row in conn.execute("SELECT chain, COUNT(*) FROM wallet_chain_state GROUP BY chain").fetchall()
        }
    finally:
        conn.close()
    return {
        "ok": True,
        "total": total,
        "by_chain": by_chain,
        "rows": [
            {
                "chain": row[0],
                "address": row[1],
                "native_balance": row[2],
                "tx_count": row[3],
                "token_balances": json.loads(row[4] or "[]"),
                "rpc_source": row[5],
                "label": row[6],
                "entity": row[7],
                "confidence": row[8],
                "address_kind": row[9],
                "is_contract": bool(row[10]),
                "native_value_usd": row[11],
                "activity_tier": row[12],
                "risk_flags": json.loads(row[13] or "[]"),
                "data_quality_score": row[14],
                "label_sources": json.loads(row[15] or "[]"),
                "source_attribution": json.loads(row[16] or "{}"),
                "observed_at": row[17],
            }
            for row in rows
        ],
    }


def get_rpc_wallet_source(address: str, chain: str | None = None) -> dict[str, Any]:
    """Read-only source trace for one wallet/address across wallet_chain_state rows."""
    _init_db()
    normalized_address = str(address or "").strip()
    if not normalized_address:
        return {
            "ok": False,
            "address": normalized_address,
            "chain": chain,
            "total": 0,
            "rows": [],
            "reason": "address_required",
            "source_policy": "read-only wallet source trace; no RPC calls, labels, or wallet rows are changed",
        }

    requested_chain = _normalize_chain(chain or "") if chain else None
    where = ["LOWER(address) = ?"]
    params: list[Any] = [normalized_address.lower()]
    if requested_chain:
        where.append("chain = ?")
        params.append(requested_chain)
    where_sql = f"WHERE {' AND '.join(where)}"
    conn = _get_db()
    try:
        rows = conn.execute(
            f"""
            SELECT chain, address, rpc_source, label, entity, confidence,
                   address_kind, is_contract, native_value_usd, tx_count,
                   activity_tier, risk_flags_json, data_quality_score,
                   label_sources_json, source_attribution_json, observed_at
            FROM wallet_chain_state
            {where_sql}
            ORDER BY data_quality_score DESC, observed_at DESC, tx_count DESC
            """,
            params,
        ).fetchall()
    finally:
        conn.close()

    output_rows: list[dict[str, Any]] = []
    for row in rows:
        label_sources = _json_list(row[13])
        source_attribution = _json_object(row[14])
        attribution_chain: list[dict[str, Any]] = []
        label_seed_source = source_attribution.get("label_seed_source")
        if label_seed_source:
            attribution_chain.append({"stage": "label_seed", "source": label_seed_source})
        for source in label_sources[:8]:
            if isinstance(source, dict):
                attribution_chain.append(
                    {
                        "stage": "label_source",
                        "source": source.get("source") or source.get("type") or "unknown",
                        "url": source.get("url") or source.get("source_url"),
                        "confidence": source.get("confidence"),
                    }
                )
        if row[2] or source_attribution.get("rpc_source"):
            attribution_chain.append(
                {
                    "stage": "rpc_observation",
                    "source": source_attribution.get("rpc_source") or row[2],
                    "chain": source_attribution.get("rpc_chain") or row[0],
                }
            )
        if source_attribution.get("enrichment"):
            attribution_chain.append({"stage": "enrichment", "source": source_attribution.get("enrichment")})

        output_rows.append(
            {
                "chain": row[0],
                "address": row[1],
                "rpc_source": row[2],
                "label": row[3],
                "entity": row[4],
                "confidence": row[5],
                "address_kind": row[6],
                "is_contract": bool(row[7]),
                "native_value_usd": row[8],
                "tx_count": row[9],
                "activity_tier": row[10],
                "risk_flags": _json_list(row[11]),
                "data_quality_score": row[12],
                "label_sources": label_sources,
                "source_attribution": source_attribution,
                "attribution_chain": attribution_chain,
                "traceable": bool(source_attribution),
                "has_label_sources": bool(label_sources),
                "observed_at": row[15],
            }
        )

    return {
        "ok": True,
        "address": normalized_address,
        "chain": requested_chain or chain,
        "total": len(output_rows),
        "traceable_rows": sum(1 for row in output_rows if row["traceable"]),
        "rows": output_rows,
        "source_policy": "read-only wallet source trace; no RPC calls, labels, or wallet rows are changed",
    }


def get_rpc_wallet_quality_audit(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 20,
) -> dict[str, Any]:
    """Read-only quality distribution for RPC wallet state before more ingestion."""
    _init_db()
    requested_chain = _normalize_chain(chain or "") if chain else None
    max_rows = max(1, min(int(limit or 20), 100))
    where = []
    params: list[Any] = []
    if requested_chain:
        where.append("chain = ?")
        params.append(requested_chain)
    if entity:
        clause, clause_params = entity_in_clause("entity", entity)
        where.append(clause)
        params.extend(clause_params)
    where_sql = f"WHERE {' AND '.join(where)}" if where else ""
    high_expr = "data_quality_score >= 80"
    medium_expr = "data_quality_score >= 50 AND data_quality_score < 80"
    low_expr = "data_quality_score < 50"
    traceable_expr = "source_attribution_json IS NOT NULL AND TRIM(source_attribution_json) NOT IN ('', '{}')"
    label_sources_expr = "label_sources_json IS NOT NULL AND TRIM(label_sources_json) NOT IN ('', '[]')"
    rpc_source_expr = "rpc_source IS NOT NULL AND TRIM(rpc_source) != ''"
    conn = _get_db()
    try:
        totals = conn.execute(
            f"""
            SELECT COUNT(*),
                   SUM(CASE WHEN {high_expr} THEN 1 ELSE 0 END),
                   SUM(CASE WHEN {medium_expr} THEN 1 ELSE 0 END),
                   SUM(CASE WHEN {low_expr} THEN 1 ELSE 0 END),
                   AVG(data_quality_score),
                   SUM(CASE WHEN {traceable_expr} THEN 1 ELSE 0 END),
                   SUM(CASE WHEN {label_sources_expr} THEN 1 ELSE 0 END),
                   SUM(CASE WHEN {rpc_source_expr} THEN 1 ELSE 0 END)
            FROM wallet_chain_state
            {where_sql}
            """,
            params,
        ).fetchone()
        by_entity_chain = [
            {
                "entity": row[0] or "unknown",
                "chain": row[1],
                "wallets": int(row[2] or 0),
                "high_quality": int(row[3] or 0),
                "medium_quality": int(row[4] or 0),
                "low_quality": int(row[5] or 0),
                "avg_quality": round(float(row[6] or 0), 2),
                "recommended_action": "refresh_low_quality_or_review_sources" if int(row[5] or 0) else "monitor",
            }
            for row in conn.execute(
                f"""
                SELECT COALESCE(entity, 'unknown'), chain,
                       COUNT(*),
                       SUM(CASE WHEN {high_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {medium_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {low_expr} THEN 1 ELSE 0 END),
                       AVG(data_quality_score)
                FROM wallet_chain_state
                {where_sql}
                GROUP BY COALESCE(entity, 'unknown'), chain
                ORDER BY 6 DESC, 7 ASC, 3 DESC
                LIMIT ?
                """,
                [*params, max_rows],
            ).fetchall()
        ]
        by_chain = [
            {
                "chain": row[0],
                "wallets": int(row[1] or 0),
                "high_quality": int(row[2] or 0),
                "medium_quality": int(row[3] or 0),
                "low_quality": int(row[4] or 0),
                "avg_quality": round(float(row[5] or 0), 2),
            }
            for row in conn.execute(
                f"""
                SELECT chain,
                       COUNT(*),
                       SUM(CASE WHEN {high_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {medium_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {low_expr} THEN 1 ELSE 0 END),
                       AVG(data_quality_score)
                FROM wallet_chain_state
                {where_sql}
                GROUP BY chain
                ORDER BY 5 DESC, 6 ASC, 2 DESC
                LIMIT ?
                """,
                [*params, max_rows],
            ).fetchall()
        ]
        by_rpc_source = [
            {
                "rpc_source": row[0] or "unknown",
                "wallets": int(row[1] or 0),
                "low_quality": int(row[2] or 0),
                "avg_quality": round(float(row[3] or 0), 2),
                "traceable_rows": int(row[4] or 0),
                "with_label_sources": int(row[5] or 0),
                "traceability_pct": round((int(row[4] or 0) / int(row[1] or 1)) * 100, 2),
                "recommended_action": (
                    "backfill_source_attribution"
                    if int(row[4] or 0) < int(row[1] or 0)
                    else "monitor"
                ),
            }
            for row in conn.execute(
                f"""
                SELECT COALESCE(rpc_source, 'unknown'),
                       COUNT(*),
                       SUM(CASE WHEN {low_expr} THEN 1 ELSE 0 END),
                       AVG(data_quality_score),
                       SUM(CASE WHEN {traceable_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {label_sources_expr} THEN 1 ELSE 0 END)
                FROM wallet_chain_state
                {where_sql}
                GROUP BY COALESCE(rpc_source, 'unknown')
                ORDER BY 3 DESC, 5 ASC, 4 ASC, 2 DESC
                LIMIT ?
                """,
                [*params, max_rows],
            ).fetchall()
        ]
        weakest_wallets = [
            {
                "chain": row[0],
                "address": row[1],
                "label": row[2],
                "entity": row[3],
                "rpc_source": row[4],
                "data_quality_score": int(row[5] or 0),
                "risk_flags": _json_list(row[6]),
                "traceable": bool(_json_object(row[7])),
                "has_label_sources": bool(_json_list(row[9])),
                "source_attribution_quality": (
                    "label_and_rpc_traceable"
                    if _json_object(row[7]) and _json_list(row[9])
                    else "rpc_traceable_only"
                    if _json_object(row[7])
                    else "missing_source_attribution"
                ),
                "observed_at": int(row[8] or 0),
            }
            for row in conn.execute(
                f"""
                SELECT chain, address, label, entity, rpc_source, data_quality_score,
                       risk_flags_json, source_attribution_json, observed_at, label_sources_json
                FROM wallet_chain_state
                {where_sql}
                ORDER BY data_quality_score ASC, observed_at ASC
                LIMIT ?
                """,
                [*params, max_rows],
            ).fetchall()
        ]
    finally:
        conn.close()

    total = int(totals[0] or 0)
    high = int(totals[1] or 0)
    medium = int(totals[2] or 0)
    low = int(totals[3] or 0)
    traceable = int(totals[5] or 0)
    with_label_sources = int(totals[6] or 0)
    with_rpc_source = int(totals[7] or 0)
    return {
        "ok": True,
        "entity": entity,
        "chain": requested_chain or chain,
        "thresholds": {
            "high": "data_quality_score >= 80",
            "medium": "50 <= data_quality_score < 80",
            "low": "data_quality_score < 50",
        },
        "total_wallets": total,
        "quality_distribution": {
            "high": high,
            "medium": medium,
            "low": low,
        },
        "source_attribution": {
            "traceable_rows": traceable,
            "missing_traceability": max(0, total - traceable),
            "with_label_sources": with_label_sources,
            "with_rpc_source": with_rpc_source,
            "traceability_pct": round((traceable / total) * 100, 2) if total else 0,
            "label_source_pct": round((with_label_sources / total) * 100, 2) if total else 0,
            "rpc_source_pct": round((with_rpc_source / total) * 100, 2) if total else 0,
        },
        "low_quality_pct": round((low / total) * 100, 2) if total else 0,
        "avg_quality": round(float(totals[4] or 0), 2),
        "by_entity_chain": by_entity_chain,
        "by_chain": by_chain,
        "by_rpc_source": by_rpc_source,
        "weakest_wallets": weakest_wallets,
        "source_policy": "read-only wallet_chain_state quality audit; no RPC calls, labels, or wallet rows are changed",
    }


def backfill_rpc_wallet_source_attribution(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 100,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Backfill missing wallet_chain_state source_attribution_json from existing rows only."""
    _init_db()
    requested_chain = _normalize_chain(chain or "") if chain else None
    max_rows = max(1, min(int(limit or 100), 500))
    where = [
        "source_attribution_json IS NOT NULL",
        "TRIM(source_attribution_json) IN ('', '{}')",
        "(rpc_source IS NOT NULL AND TRIM(rpc_source) != '')",
    ]
    params: list[Any] = []
    if requested_chain:
        where.append("chain = ?")
        params.append(requested_chain)
    if entity:
        clause, clause_params = entity_in_clause("entity", entity)
        where.append(clause)
        params.extend(clause_params)
    where_sql = f"WHERE {' AND '.join(where)}"
    conn = _get_db()
    job_id: int | None = None
    backup_path = ""
    updated = 0
    now = int(time.time())
    rows_out: list[dict[str, Any]] = []
    try:
        rows = conn.execute(
            f"""
            SELECT chain, address, rpc_source, label, entity, confidence,
                   label_sources_json, observed_at
            FROM wallet_chain_state
            {where_sql}
            ORDER BY observed_at ASC, data_quality_score ASC
            LIMIT ?
            """,
            [*params, max_rows],
        ).fetchall()
        if not dry_run:
            if rows:
                backup_path = _backup_onchain_db("before_rpc_source_backfill")
            job_id = _start_data_job(
                "rpc_source_attribution_backfill",
                {
                    "entity": entity,
                    "chain": requested_chain or chain,
                    "limit": max_rows,
                    "dry_run": False,
                    "backup_path": backup_path,
                },
            )
        for row in rows:
            label_sources = _json_list(row[6])
            attribution = {
                "label_seed_source": "wallet_chain_state_existing_row" if row[3] or row[4] else None,
                "label_sources": label_sources,
                "rpc_source": row[2],
                "rpc_chain": row[0],
                "enrichment": "source_attribution_backfill",
                "backfilled_from_existing_row": True,
                "trusted_label_promotion": False,
                "observed_at": int(row[7] or 0),
                "backfilled_at": now,
            }
            rows_out.append(
                {
                    "chain": row[0],
                    "address": row[1],
                    "rpc_source": row[2],
                    "label": row[3],
                    "entity": row[4],
                    "confidence": row[5],
                    "has_label_sources": bool(label_sources),
                    "would_update": True,
                }
            )
            if not dry_run:
                conn.execute(
                    """
                    UPDATE wallet_chain_state
                    SET source_attribution_json = ?
                    WHERE chain = ? AND address = ?
                    """,
                    (json.dumps(attribution, default=str), row[0], row[1]),
                )
                updated += 1
        if not dry_run:
            conn.commit()
            _finish_data_job(
                job_id,
                "ok",
                {
                    "matched": len(rows_out),
                    "updated": updated,
                    "backup_path": backup_path,
                    "source_policy": (
                        "metadata-only backfill from existing wallet_chain_state rows; "
                        "no RPC calls, labels, or balances are changed"
                    ),
                },
            )
    except Exception as exc:
        conn.rollback()
        if job_id is not None:
            _finish_data_job(job_id, "error", {"updated": updated}, str(exc)[:500])
        raise
    finally:
        conn.close()

    return {
        "ok": True,
        "dry_run": dry_run,
        "entity": entity,
        "chain": requested_chain or chain,
        "matched": len(rows_out),
        "updated": updated,
        "job_id": job_id,
        "backup_path": backup_path,
        "rows": rows_out,
        "source_policy": (
            "metadata-only wallet_chain_state source attribution backfill; "
            "no RPC calls, labels, balances, or trusted label promotions are performed"
        ),
    }


def backfill_rpc_wallet_label_sources(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 100,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Backfill wallet_chain_state label_sources_json from trusted label ledger rows."""
    _init_db()
    requested_chain = _normalize_chain(chain or "") if chain else None
    max_rows = max(1, min(int(limit or 100), 500))
    if not LABEL_LEDGER_PATH.exists():
        return {
            "ok": False,
            "dry_run": dry_run,
            "entity": entity,
            "chain": requested_chain or chain,
            "matched": 0,
            "updated": 0,
            "job_id": None,
            "backup_path": "",
            "rows": [],
            "reason": "label_ledger_missing",
            "source_policy": "metadata-only backfill skipped; label ledger database is missing",
        }

    where = [
        "w.label_sources_json IS NOT NULL",
        "TRIM(w.label_sources_json) IN ('', '[]')",
        "l.sources_json IS NOT NULL",
        "TRIM(l.sources_json) NOT IN ('', '[]')",
    ]
    params: list[Any] = []
    if requested_chain:
        where.append("w.chain = ?")
        params.append(requested_chain)
    if entity:
        clause, clause_params = entity_in_clause("w.entity", entity)
        where.append(clause)
        params.extend(clause_params)
    where_sql = f"WHERE {' AND '.join(where)}"
    conn = _get_db()
    job_id: int | None = None
    backup_path = ""
    updated = 0
    now = int(time.time())
    rows_out: list[dict[str, Any]] = []
    try:
        conn.execute(f"ATTACH DATABASE ? AS labeldb", (str(LABEL_LEDGER_PATH),))
        rows = conn.execute(
            f"""
            SELECT w.chain, w.address, w.label, w.entity, w.confidence,
                   w.source_attribution_json, l.sources_json
            FROM wallet_chain_state w
            JOIN labeldb.labels l
              ON LOWER(l.address) = LOWER(w.address)
             AND LOWER(CASE WHEN l.chain = 'ethereum' THEN 'eth' ELSE l.chain END) = LOWER(w.chain)
            {where_sql}
            ORDER BY w.observed_at ASC, w.data_quality_score ASC
            LIMIT ?
            """,
            [*params, max_rows],
        ).fetchall()
        if not dry_run:
            if rows:
                backup_path = _backup_onchain_db("before_rpc_label_sources_backfill")
            job_id = _start_data_job(
                "rpc_label_sources_backfill",
                {
                    "entity": entity,
                    "chain": requested_chain or chain,
                    "limit": max_rows,
                    "dry_run": False,
                    "backup_path": backup_path,
                },
            )
        for row in rows:
            label_sources = _json_list(row[6])
            source_attribution = _json_object(row[5])
            source_attribution.update(
                {
                    "label_sources": label_sources,
                    "label_sources_backfilled_from": "label_ledger.sources_json",
                    "label_sources_backfilled_at": now,
                    "trusted_label_promotion": False,
                }
            )
            rows_out.append(
                {
                    "chain": row[0],
                    "address": row[1],
                    "label": row[2],
                    "entity": row[3],
                    "confidence": row[4],
                    "label_source_count": len(label_sources),
                    "would_update": True,
                }
            )
            if not dry_run:
                conn.execute(
                    """
                    UPDATE wallet_chain_state
                    SET label_sources_json = ?,
                        source_attribution_json = ?
                    WHERE chain = ? AND address = ?
                    """,
                    (
                        json.dumps(label_sources, default=str),
                        json.dumps(source_attribution, default=str),
                        row[0],
                        row[1],
                    ),
                )
                updated += 1
        if not dry_run:
            conn.commit()
            _finish_data_job(
                job_id,
                "ok",
                {
                    "matched": len(rows_out),
                    "updated": updated,
                    "backup_path": backup_path,
                    "source_policy": (
                        "metadata-only backfill from label_ledger.sources_json; "
                        "no RPC calls, labels, balances, or promotions are changed"
                    ),
                },
            )
    except Exception as exc:
        conn.rollback()
        if job_id is not None:
            _finish_data_job(job_id, "error", {"updated": updated}, str(exc)[:500])
        raise
    finally:
        try:
            conn.execute("DETACH DATABASE labeldb")
        except Exception:
            pass
        conn.close()

    return {
        "ok": True,
        "dry_run": dry_run,
        "entity": entity,
        "chain": requested_chain or chain,
        "matched": len(rows_out),
        "updated": updated,
        "job_id": job_id,
        "backup_path": backup_path,
        "rows": rows_out,
        "source_policy": (
            "metadata-only wallet_chain_state label source backfill from existing label ledger; "
            "no RPC calls, labels, balances, or trusted label promotions are performed"
        ),
    }


def get_rpc_label_source_gap_report(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 50,
) -> dict[str, Any]:
    """Read-only queue of RPC wallet rows that still lack public label sources."""
    _init_db()
    requested_chain = _normalize_chain(chain or "") if chain else None
    max_rows = max(1, min(int(limit or 50), 200))
    where = [
        "w.label_sources_json IS NOT NULL",
        "TRIM(w.label_sources_json) IN ('', '[]')",
    ]
    params: list[Any] = []
    if requested_chain:
        where.append("w.chain = ?")
        params.append(requested_chain)
    if entity:
        clause, clause_params = entity_in_clause("w.entity", entity)
        where.append(clause)
        params.extend(clause_params)
    where_sql = f"WHERE {' AND '.join(where)}"
    conn = _get_db()
    rows_out: list[dict[str, Any]] = []
    summary = {
        "total_missing_label_sources": 0,
        "labelled_without_ledger_match": 0,
        "ledger_match_without_sources": 0,
        "unlabelled_client_or_observed": 0,
        "stage_for_public_corroboration": 0,
        "skip_unlabelled_observation": 0,
    }
    try:
        if LABEL_LEDGER_PATH.exists():
            conn.execute("ATTACH DATABASE ? AS labeldb", (str(LABEL_LEDGER_PATH),))
            label_join = """
                LEFT JOIN labeldb.labels l
                  ON LOWER(l.address) = LOWER(w.address)
                 AND LOWER(CASE WHEN l.chain = 'ethereum' THEN 'eth' ELSE l.chain END) = LOWER(w.chain)
            """
            label_select = "l.address IS NOT NULL, COALESCE(l.sources_json, '')"
        else:
            label_join = ""
            label_select = "0, ''"
        rows = conn.execute(
            f"""
            SELECT w.chain, w.address, w.label, w.entity, w.confidence, w.rpc_source,
                   w.data_quality_score, w.source_attribution_json, w.observed_at,
                   {label_select}
            FROM wallet_chain_state w
            {label_join}
            {where_sql}
            ORDER BY
                CASE WHEN w.entity IS NULL OR w.entity = '' OR w.label IS NULL OR w.label = '' THEN 1 ELSE 0 END,
                w.entity,
                w.chain,
                w.data_quality_score ASC,
                w.observed_at ASC
            LIMIT ?
            """,
            [*params, max_rows],
        ).fetchall()
        total = conn.execute(
            f"""
            SELECT COUNT(*)
            FROM wallet_chain_state w
            {where_sql}
            """,
            params,
        ).fetchone()[0]
    finally:
        try:
            conn.execute("DETACH DATABASE labeldb")
        except Exception:
            pass
        conn.close()

    summary["total_missing_label_sources"] = int(total or 0)
    for row in rows:
        label = str(row[2] or "").strip()
        row_entity = str(row[3] or "").strip()
        has_label_match = bool(row[9])
        ledger_sources = _json_list(row[10])
        if not label or not row_entity:
            action = "skip_unlabelled_observation"
            reason = "client_or_observed_wallet_without_label"
            summary["unlabelled_client_or_observed"] += 1
            summary["skip_unlabelled_observation"] += 1
        elif has_label_match and not ledger_sources:
            action = "refresh_ledger_sources"
            reason = "trusted_label_exists_but_has_no_sources_json"
            summary["ledger_match_without_sources"] += 1
        else:
            action = "stage_for_public_corroboration"
            reason = "wallet_state_label_has_no_matching_public_label_source"
            summary["labelled_without_ledger_match"] += 1
            summary["stage_for_public_corroboration"] += 1
        rows_out.append(
            {
                "chain": row[0],
                "address": row[1],
                "label": label or None,
                "entity": row_entity or None,
                "confidence": row[4],
                "rpc_source": row[5],
                "data_quality_score": int(row[6] or 0),
                "traceable": bool(_json_object(row[7])),
                "observed_at": int(row[8] or 0),
                "has_label_ledger_match": has_label_match,
                "candidate_action": action,
                "reason": reason,
            }
        )

    return {
        "ok": True,
        "entity": entity,
        "chain": requested_chain or chain,
        "summary": summary,
        "rows": rows_out,
        "source_policy": (
            "read-only RPC label-source gap report; no RPC calls, labels, candidates, "
            "balances, or trusted label promotions are changed"
        ),
    }


def stage_rpc_label_source_gap_candidates(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 25,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Stage labelled source gaps as candidates for public corroboration only."""
    safe_limit = max(1, min(int(limit or 25), 100))
    report = get_rpc_label_source_gap_report(entity=entity, chain=chain, limit=safe_limit)
    stage_rows = [
        row for row in report.get("rows", [])
        if row.get("candidate_action") == "stage_for_public_corroboration"
    ]
    candidate_rows: list[dict[str, Any]] = []
    for row in stage_rows:
        candidate_rows.append(
            {
                "chain": row.get("chain"),
                "address": row.get("address"),
                "label": row.get("label"),
                "entity": row.get("entity"),
                "wallet_type": str(row.get("label") or "").split(":", 1)[-1].strip().replace("_", " ") or None,
                "confidence": "low",
                "source": "rpc_label_source_gap",
                "source_url": None,
                "evidence": {
                    "source": "wallet_chain_state",
                    "reason": row.get("reason"),
                    "rpc_source": row.get("rpc_source"),
                    "data_quality_score": row.get("data_quality_score"),
                    "traceable": row.get("traceable"),
                    "observed_at": row.get("observed_at"),
                    "candidate_action": row.get("candidate_action"),
                    "trusted_label_promotion": False,
                },
                "tags": ["label_source_gap", "requires_public_corroboration"],
            }
        )

    job_id: int | None = None
    staging: dict[str, Any] = {
        "ok": True,
        "rows_observed": len(candidate_rows),
        "candidates_inserted": 0,
        "candidates_merged": 0,
        "source_policy": "dry-run candidate staging preview; no rows are changed",
    }
    if not dry_run:
        job_id = _start_data_job(
            "rpc_label_source_gap_candidate_staging",
            {
                "entity": entity,
                "chain": chain,
                "limit": safe_limit,
                "dry_run": False,
                "candidate_rows": len(candidate_rows),
            },
        )
        try:
            from services.label_ledger import stage_label_candidates_from_rows

            staging = stage_label_candidates_from_rows(candidate_rows)
            _finish_data_job(
                job_id,
                "ok",
                {
                    "candidate_rows": len(candidate_rows),
                    "candidates_inserted": staging.get("candidates_inserted", 0),
                    "candidates_merged": staging.get("candidates_merged", 0),
                    "skipped_unlabelled": report.get("summary", {}).get("skip_unlabelled_observation", 0),
                    "source_policy": (
                        "candidate-only staging from RPC label-source gaps; "
                        "no trusted labels, RPC rows, balances, or promotions are changed"
                    ),
                },
            )
        except Exception as exc:
            _finish_data_job(job_id, "error", {"candidate_rows": len(candidate_rows)}, str(exc)[:500])
            raise

    return {
        "ok": True,
        "dry_run": dry_run,
        "entity": entity,
        "chain": chain,
        "limit": safe_limit,
        "job_id": job_id,
        "gap_summary": report.get("summary", {}),
        "candidate_rows": len(candidate_rows),
        "staging": staging,
        "rows": candidate_rows,
        "source_policy": (
            "candidate-only staging from RPC label-source gaps; client/unlabelled observations are skipped, "
            "trusted labels are never changed"
        ),
    }


def corroborate_rpc_label_source_gap_candidates(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 10,
    dry_run: bool = True,
    timeout: int = 12,
    allow_external: bool = False,
    confirm: str | None = None,
) -> dict[str, Any]:
    """Corroborate only RPC label-source-gap candidates with public evidence.

    This is intentionally evidence-only: it may persist candidate evidence bundles
    when dry_run is false, but it never promotes trusted labels.
    """
    safe_limit = max(1, min(int(limit or 10), 25))
    safe_timeout = max(2, min(int(timeout or 12), 20))
    if not allow_external:
        preview = get_label_source_gap_candidate_corroboration_preview(
            entity=entity,
            chain=chain,
            limit=safe_limit,
            dry_run=True,
        )
        return {
            "ok": True,
            "dry_run": bool(dry_run),
            "job_id": None,
            "external_access_enabled": False,
            "would_call_external": False,
            "would_persist_evidence": False,
            "writes_performed": 0,
            "result": {
                "candidate_source": "rpc_label_source_gap",
                "corroboration_status": "external_disabled",
                "external_access_enabled": False,
                "would_call_external": False,
                "would_persist_evidence": False,
                "candidates_selected": 0,
                "rows_reviewed": 0,
                "evidence_bundles_written": 0,
                "writes_performed": 0,
                "verified_source_ready": 0,
                "needs_more_evidence": 0,
                "blocked_by_reason": [
                    {
                        "reason": "allow_external_true_required_for_public_source_corroboration",
                        "count": 1,
                    }
                ],
                "trusted_labels_changed": False,
                "preview": preview,
                "source_policy": (
                    "external source corroboration disabled by default; returned local-only preview, "
                    "no Blockscout/Etherscan/provider/scraping calls, no evidence writes, no label promotion"
                ),
            },
        }
    if not dry_run and confirm != "CORROBORATE_LABEL_SOURCE_GAP_CANDIDATES":
        preview = get_label_source_gap_candidate_corroboration_preview(
            entity=entity,
            chain=chain,
            limit=safe_limit,
            dry_run=True,
        )
        return {
            "ok": False,
            "dry_run": False,
            "job_id": None,
            "external_access_enabled": True,
            "would_call_external": False,
            "would_persist_evidence": False,
            "writes_performed": 0,
            "result": {
                "candidate_source": "rpc_label_source_gap",
                "corroboration_status": "blocked",
                "external_access_enabled": True,
                "would_call_external": False,
                "would_persist_evidence": False,
                "candidates_selected": 0,
                "rows_reviewed": 0,
                "evidence_bundles_written": 0,
                "writes_performed": 0,
                "trusted_labels_changed": False,
                "blockers": ["confirm_CORROBORATE_LABEL_SOURCE_GAP_CANDIDATES_required"],
                "preview": preview,
                "source_policy": (
                    "real source-gap corroboration evidence persistence requires explicit confirm; "
                    "no external calls or evidence writes were performed"
                ),
            },
        }
    if not LABEL_LEDGER_PATH.exists():
        return {
            "ok": False,
            "dry_run": dry_run,
            "error": "label_ledger_missing",
            "db_path": str(LABEL_LEDGER_PATH),
            "source_policy": "no corroboration ran; trusted labels are unchanged",
        }

    where = ["status = 'candidate'", "source = 'rpc_label_source_gap'"]
    params: list[Any] = []
    if entity:
        where.append("LOWER(proposed_entity) LIKE ?")
        params.append(f"%{entity.lower()}%")
    if chain:
        normalized_chain = _normalize_chain(chain)
        label_chain = "ethereum" if normalized_chain == "eth" else normalized_chain
        chain_values = sorted({normalized_chain, label_chain})
        where.append(f"chain IN ({','.join('?' for _ in chain_values)})")
        params.extend(chain_values)

    conn = sqlite3.connect(str(LABEL_LEDGER_PATH))
    try:
        rows = conn.execute(
            f"""
            SELECT id, chain, address, proposed_label, proposed_entity, seen_count
            FROM label_candidates
            WHERE {' AND '.join(where)}
            ORDER BY seen_count DESC, last_seen_at DESC, id ASC
            LIMIT ?
            """,
            [*params, safe_limit],
        ).fetchall()
    finally:
        conn.close()

    selected_ids = [int(row[0]) for row in rows]
    selected_preview = [
        {
            "id": int(row[0]),
            "chain": row[1],
            "address": row[2],
            "label": row[3],
            "entity": row[4],
            "seen_count": int(row[5] or 0),
        }
        for row in rows
    ]

    job_id: int | None = None
    if not dry_run:
        job_id = _start_data_job(
            "rpc_label_source_gap_candidate_corroboration",
            {
                "entity": entity,
                "chain": chain,
                "limit": safe_limit,
                "timeout": safe_timeout,
                "dry_run": False,
                "candidate_ids": selected_ids,
            },
        )

    try:
        from services.label_ledger import corroborate_label_candidates, get_label_ledger_summary

        labels_before = int(get_label_ledger_summary().get("labels") or 0)
        if selected_ids:
            result = corroborate_label_candidates(
                limit=len(selected_ids),
                timeout=safe_timeout,
                persist=not dry_run,
                candidate_ids=selected_ids,
            )
        else:
            result = {
                "ok": True,
                "persist": not dry_run,
                "rows_reviewed": 0,
                "evidence_bundles_written": 0,
                "verified_source_ready": 0,
                "needs_more_evidence": 0,
                "blocked_by_reason": [],
                "rows": [],
            }
        labels_after = int(get_label_ledger_summary().get("labels") or 0)
        writes_performed = 0 if dry_run else int(result.get("evidence_bundles_written") or 0) + (1 if job_id is not None else 0)
        payload = {
            "candidate_source": "rpc_label_source_gap",
            "corroboration_status": "external_authorized",
            "external_access_enabled": True,
            "would_call_external": True,
            "would_persist_evidence": not dry_run,
            "candidate_ids": selected_ids,
            "candidates_selected": len(selected_ids),
            "selected_preview": selected_preview,
            "rows_reviewed": result.get("rows_reviewed", 0),
            "evidence_bundles_written": result.get("evidence_bundles_written", 0),
            "writes_performed": writes_performed,
            "verified_source_ready": result.get("verified_source_ready", 0),
            "needs_more_evidence": result.get("needs_more_evidence", 0),
            "blocked_by_reason": result.get("blocked_by_reason", []),
            "labels_before": labels_before,
            "labels_after": labels_after,
            "trusted_labels_changed": labels_after != labels_before,
            "rows": [
                {
                    "id": row.get("id"),
                    "chain": row.get("chain"),
                    "address": row.get("address"),
                    "entity": row.get("entity"),
                    "label": row.get("label"),
                    "status": (row.get("corroboration") or {}).get("status"),
                    "score": (row.get("corroboration") or {}).get("score"),
                    "evidence_count": len((row.get("corroboration") or {}).get("evidence") or []),
                    "blockers": (row.get("corroboration") or {}).get("blockers") or [],
                }
                for row in result.get("rows", [])[:safe_limit]
            ],
        "source_policy": (
                "explicitly authorized targeted RPC label-source-gap corroboration; dry-run may call external "
                "public sources when allow_external=true, real mode persists evidence bundles only after confirm; "
                "no candidates are promoted and no trusted labels are changed"
            ),
        }
        if job_id is not None:
            _finish_data_job(job_id, "ok", result=payload)
        return {
            "ok": True,
            "dry_run": dry_run,
            "job_id": job_id,
            "external_access_enabled": True,
            "would_call_external": True,
            "would_persist_evidence": not dry_run,
            "writes_performed": writes_performed,
            "result": payload,
        }
    except Exception as exc:
        if job_id is not None:
            _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


def backfill_rpc_label_source_gap_candidate_urls(
    entity: str | None = None,
    chain: str | None = None,
    limit: int = 25,
    dry_run: bool = True,
) -> dict[str, Any]:
    """Backfill canonical entity source URLs for RPC gap candidates only."""
    safe_limit = max(1, min(int(limit or 25), 100))
    job_id: int | None = None
    if not dry_run:
        job_id = _start_data_job(
            "rpc_label_source_gap_candidate_source_url_backfill",
            {
                "entity": entity,
                "chain": chain,
                "limit": safe_limit,
                "dry_run": False,
            },
        )
    try:
        from services.label_ledger import backfill_candidate_entity_source_urls, get_label_ledger_summary

        labels_before = int(get_label_ledger_summary().get("labels") or 0)
        result = backfill_candidate_entity_source_urls(
            source="rpc_label_source_gap",
            limit=safe_limit,
            entity=entity,
            chain=chain,
            dry_run=dry_run,
        )
        labels_after = int(get_label_ledger_summary().get("labels") or 0)
        payload = {
            **result,
            "labels_before": labels_before,
            "labels_after": labels_after,
            "trusted_labels_changed": labels_after != labels_before,
            "source_policy": (
                "targeted RPC label-source-gap source_url backfill updates candidates only; "
                "no trusted labels are changed and no candidates are promoted"
            ),
        }
        if job_id is not None:
            _finish_data_job(job_id, "ok", result=payload)
        return {"ok": True, "dry_run": dry_run, "job_id": job_id, "result": payload}
    except Exception as exc:
        if job_id is not None:
            _finish_data_job(job_id, "failed", error=str(exc)[:500])
        raise


def get_rpc_wallet_state_audit(
    entity: str | None = None,
    chain: str | None = None,
    stale_after_hours: int = 24,
    limit: int = 20,
) -> dict[str, Any]:
    """Read-only audit for RPC wallet state traceability and refresh safety."""
    _init_db()
    requested_chain = _normalize_chain(chain or "") if chain else None
    max_rows = max(1, min(int(limit or 20), 100))
    stale_seconds = max(1, min(int(stale_after_hours or 24), 24 * 30)) * 3600
    stale_before = int(time.time()) - stale_seconds
    where = []
    params: list[Any] = []
    if requested_chain:
        where.append("chain = ?")
        params.append(requested_chain)
    if entity:
        clause, clause_params = entity_in_clause("entity", entity)
        where.append(clause)
        params.extend(clause_params)
    where_sql = f"WHERE {' AND '.join(where)}" if where else ""
    missing_attribution_expr = (
        "source_attribution_json IS NULL OR source_attribution_json = '' OR source_attribution_json = '{}'"
    )
    missing_label_sources_expr = (
        "label_sources_json IS NULL OR label_sources_json = '' OR label_sources_json = '[]'"
    )
    conn = _get_db()
    try:
        totals = conn.execute(
            f"""
            SELECT COUNT(*),
                   SUM(CASE WHEN rpc_source IS NULL OR rpc_source = '' THEN 1 ELSE 0 END),
                   SUM(CASE WHEN label IS NULL OR label = '' THEN 1 ELSE 0 END),
                   SUM(CASE WHEN entity IS NULL OR entity = '' THEN 1 ELSE 0 END),
                   SUM(CASE WHEN {missing_label_sources_expr} THEN 1 ELSE 0 END),
                   SUM(CASE WHEN {missing_attribution_expr} THEN 1 ELSE 0 END),
                   SUM(CASE WHEN observed_at < ? THEN 1 ELSE 0 END),
                   SUM(CASE WHEN data_quality_score < 50 THEN 1 ELSE 0 END),
                   AVG(data_quality_score)
            FROM wallet_chain_state
            {where_sql}
            """,
            [stale_before, *params],
        ).fetchone()
        by_chain = [
            {
                "chain": row[0],
                "wallets": int(row[1] or 0),
                "missing_source_attribution": int(row[2] or 0),
                "missing_label_sources": int(row[3] or 0),
                "stale_rows": int(row[4] or 0),
                "avg_quality": round(float(row[5] or 0), 2),
            }
            for row in conn.execute(
                f"""
                SELECT chain,
                       COUNT(*),
                       SUM(CASE WHEN {missing_attribution_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {missing_label_sources_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN observed_at < ? THEN 1 ELSE 0 END),
                       AVG(data_quality_score)
                FROM wallet_chain_state
                {where_sql}
                GROUP BY chain
                ORDER BY COUNT(*) DESC
                """,
                [stale_before, *params],
            ).fetchall()
        ]
        by_rpc_source = [
            {"rpc_source": row[0] or "unknown", "wallets": int(row[1] or 0)}
            for row in conn.execute(
                f"""
                SELECT COALESCE(rpc_source, 'unknown'), COUNT(*)
                FROM wallet_chain_state
                {where_sql}
                GROUP BY COALESCE(rpc_source, 'unknown')
                ORDER BY COUNT(*) DESC
                LIMIT ?
                """,
                [*params, max_rows],
            ).fetchall()
        ]
        refresh_targets = [
            {
                "entity": row[0] or "unknown",
                "chain": row[1],
                "wallets": int(row[2] or 0),
                "missing_source_attribution": int(row[3] or 0),
                "missing_label_sources": int(row[4] or 0),
                "stale_rows": int(row[5] or 0),
                "low_quality_rows": int(row[6] or 0),
                "avg_quality": round(float(row[7] or 0), 2),
                "recommended_action": "refresh_rpc_state_with_source_attribution",
            }
            for row in conn.execute(
                f"""
                SELECT COALESCE(entity, 'unknown'), chain,
                       COUNT(*),
                       SUM(CASE WHEN {missing_attribution_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN {missing_label_sources_expr} THEN 1 ELSE 0 END),
                       SUM(CASE WHEN observed_at < ? THEN 1 ELSE 0 END),
                       SUM(CASE WHEN data_quality_score < 50 THEN 1 ELSE 0 END),
                       AVG(data_quality_score)
                FROM wallet_chain_state
                {where_sql}
                GROUP BY COALESCE(entity, 'unknown'), chain
                HAVING SUM(CASE WHEN {missing_attribution_expr} THEN 1 ELSE 0 END) > 0
                    OR SUM(CASE WHEN {missing_label_sources_expr} THEN 1 ELSE 0 END) > 0
                    OR SUM(CASE WHEN observed_at < ? THEN 1 ELSE 0 END) > 0
                    OR SUM(CASE WHEN data_quality_score < 50 THEN 1 ELSE 0 END) > 0
                ORDER BY 4 DESC, 6 DESC, 7 DESC, 3 DESC
                LIMIT ?
                """,
                [stale_before, *params, stale_before, max_rows],
            ).fetchall()
        ]
    finally:
        conn.close()

    total = int(totals[0] or 0)
    missing_source_attribution = int(totals[5] or 0)
    missing_label_sources = int(totals[4] or 0)
    stale_rows = int(totals[6] or 0)
    low_quality_rows = int(totals[7] or 0)
    return {
        "ok": True,
        "entity": entity,
        "chain": requested_chain or chain,
        "stale_after_hours": stale_seconds // 3600,
        "total_wallets": total,
        "traceable_wallets": max(0, total - missing_source_attribution),
        "traceability_pct": round(((total - missing_source_attribution) / total) * 100, 2) if total else 0,
        "missing_rpc_source": int(totals[1] or 0),
        "missing_label": int(totals[2] or 0),
        "missing_entity": int(totals[3] or 0),
        "missing_label_sources": missing_label_sources,
        "missing_source_attribution": missing_source_attribution,
        "stale_rows": stale_rows,
        "low_quality_rows": low_quality_rows,
        "avg_quality": round(float(totals[8] or 0), 2),
        "by_chain": by_chain,
        "by_rpc_source": by_rpc_source,
        "refresh_targets": refresh_targets,
        "source_policy": "read-only wallet_chain_state audit; no RPC calls, labels, or wallet rows are changed",
    }


