# Wallet Analyzer
def analyze_wallet(address: str) -> dict[str, Any]:
    address = address.strip().lower()
    cache_key = f"wallet:{address}"
    return _cached(cache_key, _analyze_wallet_inner, address)


def _analyze_wallet_inner(address: str) -> dict[str, Any]:
    _init_db()
    conn = _get_db()
    chain_errors: list[dict[str, str]] = []

    if address.startswith("0x") and len(address) == 42:
        # Multi-chain: bounded first-party RPC scan across supported EVM chains.
        chains: list[dict[str, Any]] = []
        for chain in SUPPORTED_EVM_CHAINS:
            try:
                balance = get_evm_balance(chain, address)
                tx_count = get_evm_tx_count(chain, address)
            except Exception as exc:
                chain_errors.append({"chain": chain, "error": str(exc)[:160]})
                continue
            if balance > 0 or tx_count > 0:
                chains.append({
                    "chain": chain,
                    "balance": round(balance, 6),
                    "tx_count": tx_count,
                    "unit": NATIVE_UNITS.get(chain, chain.upper()),
                })

        # If no activity found, keep the known supported chain surface visible.
        if not chains:
            chains = [
                {
                    "chain": chain,
                    "balance": 0.0,
                    "tx_count": 0,
                    "unit": NATIVE_UNITS.get(chain, chain.upper()),
                }
                for chain in SUPPORTED_EVM_CHAINS
            ]

        primary_row = max(chains, key=lambda row: (row.get("tx_count") or 0, row.get("balance") or 0))
        primary_chain = str(primary_row.get("chain") or "eth")
        total_tx = sum(int(row.get("tx_count") or 0) for row in chains)

    elif len(address) >= 32 and len(address) <= 44:
        primary_chain = "solana"
        result = _rpc_sol("getBalance", [address])
        sol_balance = (result.get("value", 0) / 1e9) if result else 0.0
        chains = [{"chain": "solana", "balance": round(sol_balance, 6), "tx_count": 0, "unit": "SOL"}]
        total_tx = 0
    else:
        return {"ok": False, "error": "unsupported_address_format"}

    # DB stats (from ingestion)
    cursor = conn.execute(
        "SELECT total_tx, total_swaps, total_volume, labels FROM wallets WHERE wallet = ?",
        (address,)
    )
    row = cursor.fetchone()
    if row:
        db_tx, db_swaps, db_volume, db_labels = row
    else:
        db_tx, db_swaps, db_volume, db_labels = 0, 0, 0.0, ""

    total_tx = max(total_tx, db_tx or 0)
    total_swaps = db_swaps or 0
    total_volume = db_volume or 0.0

    label = db_labels.split(",")[0] if db_labels else "unknown"
    if label in ("", "unknown", "new_wallet"):
        if total_tx < 10:
            label = "new_wallet"
        elif total_volume > 100000:
            label = "whale"
        elif total_swaps > 100:
            label = "smart_money"
        elif total_swaps > 20:
            label = "active_trader"
        elif total_tx > 500:
            label = "high_frequency"
        else:
            label = "regular"

    conn.close()

    # Token balances + Net Worth
    token_balances: list[dict[str, Any]] = []
    net_worth_usd: float | None = None
    try:
        for ch in chains:
            ch_name = ch["chain"]
            if ch_name in SUPPORTED_EVM_CHAINS:
                tokens = get_token_balances(ch_name, address)
                token_balances.extend(tokens)
        
        # Calculate net worth
        coin_ids = set()
        for ch in chains:
            native_coin_id = _NATIVE_COIN_IDS.get(ch["chain"])
            if native_coin_id:
                coin_ids.add(native_coin_id)
        for t in token_balances:
            coin_ids.add(t["coin_id"])
        
        prices = _get_coin_prices(coin_ids)
        net_worth = 0.0
        for ch in chains:
            cid = _NATIVE_COIN_IDS.get(ch["chain"])
            if cid and cid in prices:
                net_worth += ch["balance"] * prices[cid]
        for t in token_balances:
            if t["coin_id"] in prices:
                net_worth += t["balance"] * prices[t["coin_id"]]
        
        net_worth_usd = round(net_worth, 2) if net_worth >= 0 else None
    except Exception:
        pass

    return {
        "ok": True,
        "wallet": address,
        "chain": primary_chain,
        "chains": chains,
        "tx_count": total_tx,
        "swap_count": total_swaps,
        "volume": round(total_volume, 2),
        "label": label,
        "token_balances": token_balances,
        "net_worth_usd": net_worth_usd,
        "chain_errors": chain_errors[:5],
    }


